// ════════════════════════════════════════
//  デモシーン ▸ 力学
// ════════════════════════════════════════
//  ★共通の見せ方と実装関数の約束は js/app/demo-kit.js にある（先に読むこと）。
//    どのデモがどの単元に並ぶかは目録 js/app/demos.js の側で決まる。
//
//  ★この分野の動く物体は、既定で回転を止める（fixedRotation:true）。新しく足す物体にも付ける。
//    力学で読ませたいのはどれも重心の運動（速度・加速度・運動量・エネルギー）で、自転は
//    題材の外にある。放っておくと、生徒が物をつかんで置き直しただけで斜めに転がり出し、
//    そこから先のグラフが読めなくなる。
//    ★「見た目は何も変わらない」ではない。摩擦のある面を滑る物体や、走る台車のように
//      倒れうる物体では、外すと転がり出して運動そのものが変わる（実測：回転を戻して
//      15秒まわすと、走る台車からの投射で 103px、ばね→摩擦→位置で 144px ずれる）。
//      止めたうえで各デモの主張が成り立つことを確かめてある（走る台車の球は台車へ
//      横ずれ 0px で戻り、位置→運動→ばね の球は出発と同じ高さ（差 0px）まで戻る）。
//    ★計測の落とし穴：b.fixedRotation を書き換えただけでは外したことにならない。
//      invInertia は setMass() の中で決まるので、そのあとに setMass() の呼び直しが要る。これを忘れて
//      「差 0px」という誤った結論を一度出している。
//  ★ただし「力の矢印を出す物体（showForces）には付けない」。平らな面に置いた箱の垂直抗力は、
//    接触点2つへの配分そのものが不定で、それを1つに決めているのは重心まわりのトルクの
//    つりあいだけ。回転を止めるとそのつりあいが消え、ソルバは先に見つけた接触点へ全部を
//    載せてしまう ＝ 矢印が角から生える（実測：箱の中心から 32px＝ちょうど半幅ぶん左へ。
//    回転を戻すと 0px）。矢印を読むための物体でこれが起きると、題材そのものが壊れる。
//  ★そのほかの例外は3つ。理由をその場に書いてある：
//      ・浮力の3ブロック   … 傾いて浮くのも浮力の姿（回転を止めると別物になる）
//      ・射影デモの棒     … モーターで回す当人
//      ・単振り子デモの棒 … 同上

// ════════════════════════════════════════
//  力学 ▸ 物体の運動
// ════════════════════════════════════════
// ── 等加速度直線運動（正の加速度／負の加速度）─────────────────────
//   ★斜面ではなく「水平なレール＋動力」で見せる。速度グラフの「大きさ」は符号を持たない
//     （距離・速さ・|a|）ので、斜面のように運動が斜めだと加速度の正負がグラフから読めない。
//     運動をx方向に固定すれば、変位・速度・加速度のどれもx成分がそのまま符号付きで読める。
//     ＝ グラフは x 成分だけを出す（y と大きさは畳む。y方向は動かないので出しても 0 の線）。
//   ★摩擦は 0（物体・地面とも）。a = F/m がそのまま出るようにするため。
//   ★重力は既定のまま働かせる。ガイドレールが鉛直成分を受け持つ＝水平な線路の上の力学台車。
//     重力を切ってしまうと「浮いた箱」になり、垂直抗力のある実験と別物になる。
//   ★数値は「1画面で往復が収まり、記録開始のしきい値（|a|≧0.9 m/s²）に余裕がある」で決めた：
//     m=2kg・F=4N → a=2m/s²。3秒で 9m 進み、v は 6m/s に達する。
const DEMO_CART_MASS  = 2;    // [kg]
const DEMO_CART_FORCE = 4;    // [N]  → a = 2 m/s²
const DEMO_CART_X0    = -450; // [px] 出発点（+450 が3秒後の位置）
function _demoAccelCart(vx0, dirRad, title, note) {
  const cart = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'box', x:DEMO_CART_X0, y:ground.y - 28, w:90, h:56, mass:DEMO_CART_MASS,
    vx: toPx(vx0),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5,
    label:'台車',
    guideEnabled:true, guideAngle:0,          // 水平のレールに拘束＝運動はx方向だけ
    thrusters:[{ force:DEMO_CART_FORCE, dir:dirRad }],
  });
  objects.push(cart);
  resetDemoWorld();
  updateGroundTerrain(true);   // 台車は地面の上を走る（落下のデモが消したままにしないよう明示）
  setDemoCam(0, 0.65);   // 走る範囲 ±4.5m が画面（±8m）に収まる倍率
  // 変位・速度・加速度の3段を出し、成分は x だけ（符号がそのまま加速度の正負になる）
  moveDemoGraphTop(velGraphNew(cart, { showPos:true, showVel:true, showAcc:true,
                                       showX:true, showY:false, showMag:false }));
  // 説明書き。グラフの符号を読む題材なので、＋の向きを画面にも描いておく
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y,      title);
  demoNote (p.x, p.y + 54, note);
  demoArrow(DEMO_CART_X0 - 30, ground.y - 190, 200, 1, '#ffd54f');
  demoLabel(DEMO_CART_X0 - 30, ground.y - 250, '＋の向き', '#ffd54f');
  return cart;
}
// 静止 → 右向きの動力。速度が右向きに増える＝加速度は正
function demoAccelPositive() {
  _demoAccelCart(0, 0, '正の加速度の運動',
    '台車 2 kg を、右向きの動力 4 N で押す（摩擦なし・静止から出発）\n'
  + '　→ a = F/m = ＋2 m/s² の等加速度直線運動\n'
  + '\n'
  + '【手順】▶実行 を押して、右うえのグラフを上から見る\n'
  + '・変位：下に凸の放物線（同じ時間で進む距離が増えていく）\n'
  + '・速度：右上がりの直線。この傾きが加速度\n'
  + '・加速度：0 より上で一定 ＝ 正の加速度\n'
  + '・ストロボ：台車を選んでから押すと、残像の間隔が\n'
  + '　　だんだん開く（間隔の差 = aT²）');
}
// 右向きに走らせて → 左向きの動力。速度が減り、0 を通って負へ入る＝加速度は負
// （3秒で止まり、6秒で出発点へ戻る。加速度は最初から最後まで -2 m/s² のまま）
function demoAccelNegative() {
  _demoAccelCart(6, Math.PI, '負の加速度の運動',
    '右へ 6 m/s で走る台車 2 kg を、左向きの動力 4 N で押す（摩擦なし）\n'
  + '　→ a = F/m = −2 m/s² の等加速度直線運動\n'
  + '\n'
  + '【手順】▶実行 を押して、右うえのグラフを上から見る\n'
  + '・変位：山なりの放物線。6秒で出発点（0 m）へ戻る\n'
  + '・速度：右下がりの直線。3秒で 0 を通り、そのまま負へ入る\n'
  + '・加速度：0 より下で一定 ＝ 負の加速度（向きは最後まで変わらない）\n'
  + '・ストロボ：台車を選んでから押すと、残像の間隔が\n'
  + '　　詰まっていき、折り返してまた開く');
}

// ── 落下と投射 ──────────────────────────────────────
//   ★働く力は重力だけ。空気抵抗は既定で切れており（抗力係数 Cd=0）、摩擦も 0 にしてある。
//     ＝ 加速度は落下中ずっと -9.8 m/s²（画面の上向きを正としたとき）。
//     ★例外は「（空気抵抗）」の2つだけで、そちらは o.drag で Cd を入れる。
//       この節の他のデモの主張（a が一定・水平は等速）は、抵抗が無いことに依っている。
//   ★地面を消す（world.terrain=false）。落下・投射で見せたいのは飛んでいる間だけで、
//     着地は題材の外にある。地面があると衝突の瞬間に加速度が跳ね、そのスパイクが
//     加速度の縦軸を持っていってしまう（実測：着地直後は軸が −9.8〜89.8 まで伸びる）。
//     ★world.terrain は描画だけでなく地面との衝突そのものを切る（js/physics/ground.js:58）
//     ので、ボールはそのまま画面の下へ落ちていく。
//   ★グラフの成分は運動の向きで決める：鉛直だけの運動は Y（赤）だけ、投射は X（青）と Y（赤）。
//     投射で2成分を並べると「水平は等速・鉛直は等加速度」がそのまま2段の形の違いになる。
//   ★初速は利用者が速度ツールで与える（自由落下・投げ下ろし・投げ上げ・水平投射・斜方投射の
//     5つは、この節では2つのデモに畳んである。理由は demoVerticalFall の★）。o.vx / o.vyUp は
//     空気抵抗つきの3つが使う＝そちらは「同じ初速で抵抗の有無を見くらべる」のが題材なので、
//     初速を利用者に委ねられない。
const DEMO_BALL_R = 20;         // [px] ボールの半径
function _demoProjectile(o) {
  const ball = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x:o.x, y:o.y, radius:DEMO_BALL_R,
    mass: o.mass || 1,
    drag: o.drag || 0,                             // ★抗力係数 Cd。0＝空気抵抗なし（既定）
    vx: toPx(o.vx || 0), vy: -toPx(o.vyUp || 0),   // ★vyUp は画面の上向きが正（内部の y は下向きが正）
    friction:0, frictionStatic:0, restitution:0,
    // ★鉛直のデモだけレール（動きの制限）に乗せる。速度ツールが初速を与えた直後に
    //   projectGuideVelocity が呼ばれる（js/input/mouse.js の velocity 解放処理）ので、
    //   斜めに引いてもレール方向＝鉛直の成分だけが残る。＝「鉛直の運動」の図が壊れない。
    guideEnabled: !!o.guideVertical, guideAngle: Math.PI / 2,
    fillColor: o.fillColor || '#eceff1', strokeColor:'#b0bec5', strokeWidth:1.5,
    label:'ボール',
  });
  if (o.tracer) {                    // 軌跡（道すじそのものが読みどころのデモだけ）
    ball.tracerEnabled  = true;
    ball.tracerColor    = o.tracer;
    ball.tracerDuration = 60;        // 飛び終わるまで消さない
  }
  objects.push(ball);
  // ★留め具（速度ツールで解放される溶接＝緑のナット）。bodyB を null にすると
  //   ワールドに打つ杭になる（溶接ツールで物体を1つだけ掴んだときと同じ形。
  //   js/input/mouse.js:862 の hits.length===1 の枝）。
  //   ★これが要るのは「実行しながら投げられる」ようにするため。留めていないと、▶を押した
  //     瞬間からボールが落ち始めるので、狙って引く時間が無い（初速は止めている間にしか
  //     与えられず、リセットのたびに同じ初速が戻ってくる）。留めておけば、▶のあとで
  //     好きなときに投げられて、投げるまで画面は静止したままになる。
  //   ★解放は速度ツールの離した瞬間に起きる（releaseFixjointsFor。js/input/mouse.js:993）。
  //     引かずにクリックしただけでも外れる＝初速 0 のまま落とせる（＝自由落下）。
  //   ★代償：実行中に初速を与えるので、その1瞬が加速度のスパイクになる。加速度の段は
  //     移動平均 6 フレーム（VG_ACC_SMOOTH_N）で均されるため、スパイクはきっかり6点に広がる。
  //     縦軸はこの幅を物差しにしてスパイクを枠の外へ出すので（vgAccAxisRange の★）、
  //     投げた直後から −9.81 の平らな線が正しく読める（実測：上へ 9 m/s で、4秒でも
  //     20秒でも軸は −10.59〜0.78。以前は上下 2% を切る作りで、2秒で軸の上端 170 m/s²、
  //     4秒で 80 と、投げた直後の数秒だけ縦に潰れていた）。
  //     止めたまま初速を与えれば（＝留め具なしの昔の作り）スパイクは出ないが、そのかわり
  //     実行しながら投げられなくなる。ここは「実行しながら投げられる」を採った。
  if (o.hold) joints.push(new Joint({ type:'fixjoint', bodyA:ball, bodyB:null,
                                      anchorAx:0, anchorAy:0,
                                      anchorBx:ball.x, anchorBy:ball.y, releasable:true }));
  resetDemoWorld();
  updateGroundTerrain(false);   // 地面なし（チェック欄も一緒に戻る）
  setDemoCam(o.camX || 0, 0.65);
  const g = velGraphNew(ball, { showPos:true, showVel:true, showAcc:true,
                                showX:!!o.showX, showY:true, showMag:false });
  // ★窓の置き場所。既定は右うえだが、鉛直のデモだけ左下へ逃がす（demoVerticalFall の★）。
  if (o.graphLeft) { moveDemoGraphLeft(g); moveDemoGraphBottom(g); } else moveDemoGraphTop(g);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y,      o.title);
  demoNote (p.x, p.y + 54, o.note);
  return ball;
}
// ── 落下運動（鉛直）── 自由落下・鉛直投げ下ろし・鉛直投げ上げ ────────
//   ★もとは3つのデモだった（demoFreeFall / demoThrowDown / demoThrowUp）。畳んだ理由：
//     ① 3つとも初期の絵が同じ。demoFreeFall と demoThrowDown は座標まで同一で、
//        ▶を押すまで見分けがつかなかった＝目録に3行あることが情報になっていない。
//     ② 3つを分けていたのは初速だけで、それは利用者が速度ツールで与えられる。
//        引く向きを変えることが、そのまま「運動がどう始まるか」を手でつかむ練習になる。
//     ③ 3つの読みどころ（傾きは同じ・最高点でも a は変わらない）は、初速を変えて
//        投げ直すほうがよく出る。1つの画面で続けて見くらべられるため。
//     ★教科書の見出し（自由落下・鉛直投げ下ろし・鉛直投げ上げ）は目録の説明文に残す。
//       デモの数は減らすが、その名前で探しに来た人が辿り着けなくなってはいけない。
//   ★レール（動きの制限・90°）に乗せる。速度ツールは斜めに引かれても、初速を与えた
//     直後の projectGuideVelocity でレール方向の成分だけを残す（js/physics/ground.js:364）。
//     ＝ 少し斜めに引いても「鉛直の運動」の図が崩れない。グラフを Y だけにしてあることにも
//     これで理由がつく（X は構造的に 0）。レールは右パネルのチェックと 90° のプリセットで
//     作れる普通の設定で、デモ専用の仕掛けではない。
//   ★グラフの窓は左下へ逃がす。ボールを画面の右寄り（x=350）に置くため：本文は1行 40 字で
//     画面の左半分を使い、既定の右うえに窓を置くとボールの居場所が残らない（実測：もとの
//     自由落下はボールと本文の下端が 27px しか離れていなかった）。左下なら本文の下が空く。
//   ★ボールの高さは ground.y-430。上へ 9 m/s ほど（画面上 100px 引いた強さ）で投げると
//     実測 411px 昇り、ボールの上端と画面の上端（ground.y-906）のあいだに 25px 残る。
//     ★ここは 460 から詰めた値。460 だと最高点でボールが画面の上を 5px はみ出した
//       （実測。球の半径 20px を勘定に入れ忘れていた）。下へは 676px ＝ 1.2 秒ぶん見える。
//   ★開いた直後の道具を速度ツールにしておく（runDemo は編集ツールに戻してから
//     デモを呼ぶので、ここで上書きすると残る）。初速を与えることが手順そのものなので、
//     左のツールバーから道具を探すところから始めさせない。
function demoVerticalFall() {
  setTool('velocity');
  _demoProjectile({ x:350, y:ground.y - 430 - DEMO_BALL_R, guideVertical:true, graphLeft:true,
    hold:true,
    title:'落下運動（鉛直）',
    note:'働くのは重力だけ（空気抵抗なし）。加速度はいつも下向きに一定。\n'
       + 'ボールは点線のレールに乗っていて、上下にしか動けない。\n'
       + '\n'
       + '【やってみよう】▶実行 を押す。ボールは緑の留め具で止まったまま\n'
       + '・速度ツールで掴んで引き、離すと飛び出す（引く長さが速さ）\n'
       + '・引かずにクリックだけ … 自由落下／下へ引く … 鉛直投げ下ろし\n'
       + '・上へ引く … 鉛直投げ上げ。リセットで留め具ごと元へ戻る\n'
       + '\n'
       + '【注目】左下のグラフの 速度Y\n'
       + '・始まりの高さは投げ方で変わるが、直線の傾きはどれも同じ\n'
       + '・上へ投げたときだけ 0 を横切る。そこが最高点で、加速度は変わらない\n'
       + '　＝ 止まっているのは速度だけ' });
}
// ── 落下運動（平面）── 水平投射・斜方投射 ─────────────────────
//   ★もとは demoHorizontalThrow / demoProjectileMotion の2つ。分けていたのは初速の向きだけで、
//     読みどころ（水平は等速・鉛直は落下・重ねると放物線）は共通。上の鉛直と同じ理由で畳んだ。
//   ★レールは付けない。好きな向きへ投げられることがこちらの題材だから。
//   ★軌跡を出す（もとの2つは出していなかった）。初速を利用者が決めるので、放物線が
//     その場で残らないと「重ねると放物線」を目で確かめられない。もとの本文が
//     ◍ストロボを勧めていたのはこのためだが、速度ツールで投げた直後はボールが選択済み
//     なので、ストロボも一手で押せる（軌跡と併せて、どちらでも道すじが残る）。
//   ★投げ出す点は画面のいちばん下・左（x=-620・高さはボールの半径だけ）。もとの
//     demoProjectileMotion と同じ場所で、理由も同じ＝斜方投射の山を本文の下に通すため。
//     ここを上げると山が本文へ食い込む（実測：高さ 300px から 10 m/s・60° で投げたら、
//     最高点が画面の 146px ＝ 本文の3行目の高さまで昇り、軌跡が文字の上を横切った）。
//     この位置なら 10 m/s・60° の最高点は地面の 401px 上で、本文の下端まで 88px 空く。
//     右うえのグラフの窓（ワールドで x 260〜752・地面の 174〜820px 上）にも入らない：
//     同じ高さへ戻るのが x=260 で、そこでのボールの上端は窓の下端の 134px 下（すべて実測）。
//   ★そのぶん水平投射は画面から出るのが速い（画面の下端まで 246px ＝ 約 0.7 秒）。
//     グラフは物体が画面の外にいても記録が続くので、X が等速・Y が等加速度という
//     読みどころは残る。ここは山を優先した。
//   ★道具は鉛直と同じ理由で速度ツールにしておく。
function demoPlanarProjectile() {
  setTool('velocity');
  _demoProjectile({ x:-620, y:ground.y - DEMO_BALL_R, showX:true, tracer:'#4fc3f7',
    hold:true,
    title:'落下運動（平面）',
    note:'働くのは重力だけ（空気抵抗なし）。水平には力が働かない。\n'
       + 'レールなし。好きな向きへ投げられる。\n'
       + '\n'
       + '【やってみよう】▶実行 を押す。ボールは緑の留め具で止まったまま\n'
       + '・速度ツールで掴んで引き、離すと飛び出す\n'
       + '・水平に引く … 水平投射（Shift で角度がそろう）\n'
       + '・斜め上へ引く … 斜方投射。リセットで何度でも投げ直せる\n'
       + '\n'
       + '【注目】グラフの X（青）は等速、Y（赤）は落下と同じ\n'
       + '・この2つを重ねたものが、画面に残る放物線の道すじ\n'
       + '・落ちる時間は、横へ投げても投げなくても変わらない' });
}

// ── 空気抵抗つき ────────────────────────────────────
//   ★抵抗の式は v²則（F = ½·ρ·Cd·A·v²、js/physics/body.js:414）。エンジンはこれしか
//     持たない。教科書が「抵抗は速さに比例する」とおく場合とは v-t の形が少し違う
//     （tanh 型 と 指数型）が、終端速度が現れること・そこへ近づくほど加速度が 0 に
//     なることは同じで、実在の球の抵抗は v² 側に近い。説明の本文にもその旨を書く。
//   ★球は「軽くて大きい」ものにする。数値はどこも誇張していない：直径 0.4 m・20 g・
//     Cd 0.47 ＝ 風船くらいの球で、Cd は球の実測値そのもの。
//     他の投射デモと同じ 1 kg のままだと終端速度が 41.7 m/s になり、デモの時間内に
//     抵抗の効果が見えない（＝ Cd を実在しない値まで上げるしかなくなる）。
//   ★断面は 直径 × world.depth = 0.4 × 0.05 = 0.02 m²（この系は2Dなので奥行きは world 側が持つ）。
//     終端速度 v_t = √(2mg / ρ·Cd·A) = 5.90 m/s。実測 5.86 m/s（60Hz の離散化で 0.7% 低い）。
//   ★world.airDensity(1.2) と world.depth(0.05) は既定のまま触らない。ここを動かすと
//     resetDemoWorld() が戻さないので、次に開いたデモまで抵抗が残る。
//   ★抵抗つきの運動を決めるのは「断面/質量」の比だけ（a = ½ρ·Cd·(A/m)·v²）。球の大きさを
//     変えても、この比さえ保てば軌道はまったく同じになる＝どの抵抗デモも「同じ球」として読める。
//     17球を並べる比較デモは球を小さくする必要があるので、質量はここから逆算する。
//     実測：直径 0.4 m・20 g と 直径 0.22 m・11 g は、60°で最高点 1.85 m・到達 2.98 m・
//     上り 0.55 秒／下り 0.68 秒 まですべて一致した。比較デモの球を 直径 0.22 m・11 g から
//     直径 0.10 m・5.1 g へ縮めたときも、17球の到達距離と最高点は 4e-16 m まで同じだった
//     （＝丸め誤差だけ。半径から質量を逆算しているので比が動いていない）。
const DEMO_DRAG_AM = 1.0;       // [m²/kg] 断面/質量。この比が終端速度 5.90 m/s を決めている
const DEMO_DRAG_CD = 0.47;      // 球の抗力係数（実物の値）
//     ★呼ばれるたびに計算する（load 時の const にしない）。world.depth を変えた状態で
//       デモを開いても、断面/質量の比＝終端速度のほうが保たれる。
function demoDragMass(radiusPx) {              // 断面 = 直径 × world.depth
  return 2 * radiusPx * PX2M * world.depth / DEMO_DRAG_AM;
}
// 静かに落とす。重力と抵抗がつり合うところで速度が頭打ちになる（終端速度）
//   ★落とす高さは自由落下・投げ下ろしと同じ 5 m。同じ高さにしておくと、デモを
//     行き来するだけで「5 m 落ちるのにかかる時間」が直に比べられる。
//   ★本文は9行まで。10行にすると最後の行が、落とし始めのボール（x=130px）の高さまで
//     下りてきて右端が重なる（実測：文字の下端が画面 242px、ボールの上端が 238px）。
function demoFallDrag() {
  _demoProjectile({ x:130, y:ground.y - 500 - DEMO_BALL_R,
    mass:demoDragMass(DEMO_BALL_R), drag:DEMO_DRAG_CD, title:'落下（空気抵抗）',
    note:'風船くらいの軽い球（直径 0.4 m・20 g）を、自由落下と同じ高さから静かに落とす\n'
       + '　→ 速くなるほど空気抵抗が強くなり、5.9 m/s で頭打ちになる（終端速度）\n'
       + '\n'
       + '【手順】▶実行 を押して、右うえのグラフを上から見る\n'
       + '・速度Y（赤）：はじめは自由落下と同じ傾きで、だんだん寝て水平に近づく\n'
       + '　　0.88 秒（2.9 m）で終端速度の 90%、1.6 秒（6.9 m）で 99%\n'
       + '・加速度Y：−9.8 から始まり 0 へ近づく ＝ 重力と抵抗がつり合っていく\n'
       + '・5 m 落ちるのに 1.27 秒・5.7 m/s（自由落下 1.02 秒・10.0 m/s）\n'
       + '・抵抗は速さの2乗に比例するとしている（球の空気抵抗は実際こちらに近い）' });
}
// 抵抗ありの斜方投射。抵抗が無かった場合の放物線を薄く重ねて見くらべる。
//   ★初速は「斜方投射」デモとまったく同じ 10 m/s・60°。2つのデモを行き来するだけで
//     比較になるようにしてある（片方だけ投げ方を変えると比較そのものが成り立たない）。
//   ★基準の放物線は お絵描きの線（注釈）で置く。物体を2つにしない指定なので、
//     「抵抗なしの球」は置けない。注釈は物理に一切参加しないので、重ねても軌道は変わらない。
//   ★点は等時間刻みで打つ。等間隔の x 刻みで打つと、頂点付近だけ点が粗くなって折れる。
function demoProjectileDrag() {
  const x0 = -620, y0 = ground.y - DEMO_BALL_R, v0x = 5.0, v0yUp = 8.66;
  _demoProjectile({ x:x0, y:y0, vx:v0x, vyUp:v0yUp, showX:true,
    mass:demoDragMass(DEMO_BALL_R), drag:DEMO_DRAG_CD, tracer:'#ffd54f',
    title:'斜方投射（空気抵抗）',
    note:'同じ球を、「斜方投射」デモとまったく同じ 10 m/s・60° で投げ出す\n'
       + '　→ 最高点 1.85 m（抵抗なし 3.81 m）、戻ってくるのは 2.98 m 先（同 8.83 m）\n'
       + '\n'
       + '【手順】▶実行 を押して、黄色い軌跡と、薄く重ねた放物線を見くらべる\n'
       + '・薄い線 ＝ 抵抗が無かった場合の道すじ。実際の軌跡は途中から内側へ落ちる\n'
       + '・軌跡は左右非対称：上りに 0.55 秒・下りに 0.68 秒かかり、下りのほうが急\n'
       + '・速度X（青）：5.0 → 1.2 m/s へ減る。水平にも力（抵抗）が働くので等速ではない\n'
       + '・加速度：X も 0 ではなくなる（抵抗の向きは、いつでも速度と真逆）\n'
       + '・投げ出した瞬間がいちばん速い ＝ 抵抗もいちばん強く、軌跡の曲がりも大きい' });
  // 抵抗が無かった場合の放物線（x = v₀ₓt、y = v₀ᵧt + ½gt²）を、戻ってくる高さまで
  const g = toPx(G_EARTH), vx = toPx(v0x), vy = toPx(v0yUp);
  const pts = [];
  for (let t = 0; t <= 2 * vy / g + 1e-9; t += 1 / 60) {
    pts.push({ x: x0 + vx * t, y: y0 - vy * t + 0.5 * g * t * t });
  }
  demoPath(pts, 'rgba(255,255,255,0.35)', 2);
}
// 速さは同じで角度だけ違う17球を、同じ点から同時に投げ出す。
//   ★重なった位置から始まるので衝突レイヤーを 0（ゴースト）にする。1 のままだと
//     出発の瞬間に球が互いを押しのけ、初速が壊れて比較にならない。
//   ★グラフの窓は開かない（1窓=1物体なので17枚出すことになる）。
//     この題材の主役は軌跡そのものなので、球ごとに色を変えた軌跡で見せる。
//   ★地面は他の投射デモと同じく消してあるので、到達点の基準は自分で描く（demoFakeGround）。
//   ★抵抗なし版と抵抗あり版は同じ関数（_demoCompare）で組む。角度・色・見かけの地面・
//     球の作り方まで全部そろえておかないと、2つを見くらべる題材そのものが成り立たない。
const DEMO_COMPARE_V0 = 10;                        // [m/s] 全球に共通の速さ
const DEMO_COMPARE_R  = 11;                        // [px] ★17球ぶん重なるので球は小さめ
//   ★倍率は2つのデモで違う（抵抗ありは扇が縮むので寄る。demoProjectileDragCompare の★）。
//     球の半径をそのままにすると、画面に映る球の大きさまで倍率の比で変わってしまう
//     （実測：抵抗なしは画面半径 7.2px、抵抗ありは 15.4px ＝ 2.15 倍）。この2つは扇の
//     大きさを目で見くらべる題材なので、球だけ大きいと「縮んだ量」の物差しが狂う。
//     ＝ 抵抗あり側の半径を倍率の比で縮め、画面上の見かけをそろえる。
const DEMO_COMPARE_ZOOM      = 0.65;               // 抵抗なし版の倍率
const DEMO_COMPARE_DRAG_ZOOM = 1.4;                // 抵抗あり版の倍率
//   ★5°刻み・5°〜85°の17球。45°を必ず含む刻みにする（最遠になる角度が列に無いと
//     この題材は成り立たない）。0°と90°は入れない：0°は水平投射そのもの、90°は
//     投げ上げそのもので、どちらも別のデモが受け持っている。
const DEMO_COMPARE_ANGLES = [];
for (let _d = 5; _d <= 85; _d += 5) DEMO_COMPARE_ANGLES.push(_d);
//   ★色は「足して 90° になる組」でそろえる。同じ色の2本が同じ点へ落ちる ＝ 組の関係が、
//     説明を読む前に画面の色だけで読める。17本を角度順のグラデーションにすると、
//     隣どうしの色が近すぎてどの2本が対なのか追えなくなる（刻みを細かくして
//     いちばん失われるのがこの対応なので、そこを色で立て直す）。
//   ★45°だけは相手がいない。単独の色（黄）にして、いちばん遠くへ行く1本を目立たせる。
//   ★8色は黄の帯を空けて選ぶ。橙（#ffa726）を混ぜたら 45°の黄と見分けがつかず、
//     「いちばん遠くへ行く1本」を目で拾えなかった（実測：17本を並べた画面で確認）。
const DEMO_PAIR_COLORS  = ['#ef5350', '#ff7043', '#ec407a', '#ba68c8',
                           '#7e57c2', '#42a5f5', '#26c6da', '#66bb6a'];
const DEMO_COMPARE_BEST = '#ffd54f';               // 45°
function demoCompareColor(deg) {
  if (deg === 45) return DEMO_COMPARE_BEST;
  const lo = Math.min(deg, 90 - deg);              // 組の小さいほう（5,10,…,40）
  return DEMO_PAIR_COLORS[lo / 5 - 1];
}
// 見かけの地面（お絵描きの細い白線＋テキストの「地面」）。
//   ★線そのものを投げた高さ y に置く。読ませたいのは軌跡＝球の中心の道すじで、それが
//     線を切る点が到達点になる。球の下端（y＋半径）へ下げると軌跡はそのぶん深く潜ってから
//     線に達し、浅い角度ほど到達点が右へずれる（半径 11px の抵抗なし版で、5°で 1.26 m ＝
//     その球の飛距離 1.77 m の 7割ぶん）。代わりに球は線に半分かかって見えるが、それは「中心が地面の高さにある」姿そのもの。
//   ★左右は画面の端まで通す。長さを決め打ちにすると端が途切れて「宙に浮いた棒」に見え、
//     地面として読めない。見える幅は窓の大きさで変わるのでカメラから測る
//     ＝ setDemoCam のあとで呼ぶこと。
//   ★「地面」の札は 投げ出し点のすぐ左・線の上 に置く。ここは球が通らない唯一の場所
//     （球は右へしか飛ばない）。線の下は目盛りの数字が並ぶ帯なので置けない。
//     ★右端を投げ出し点に寄せる（左端を画面の左端にそろえない）。線は端から端まで
//       通っているので、札が離れているとどちらの線を指しているのか読めなくなる。
//     ★大きさは本文の 0.75 倍。地面はこの図の主役ではないので、本文と同じ大きさだと
//       軌跡より先に目へ入ってしまう。
//   ★衝突はしない（注釈は物理に一切参加しない）。球は線を突き抜けて下へ落ちていくので、
//     そのことを必ず説明の本文に書く。書かないと「地面をすり抜けるバグ」に見える。
const DEMO_GROUND_LABEL_GAP = 24;   // [px] 札の右端と投げ出し点のあいだ
function demoFakeGround(y, x0, textSize) {
  const half = canvas.width / 2 / cam.zoom;
  demoPath([{ x:cam.x - half - 20, y }, { x:cam.x + half + 20, y }], 'rgba(255,255,255,0.55)', 2);
  const size = (textSize || DEMO_NOTE_SIZE) * 0.75;
  const m = annotMeasure('地面', size, undefined, true);
  annotations.push(new Annotation({ type:'text', x:x0 - m.w - DEMO_GROUND_LABEL_GAP, y:y - m.h - 6,
                                    text:'地面', size, bold:true, color:'#eceff1' }));
}
// 速さは同じで角度だけ違う17球を、同じ点から同時に投げ出す（抵抗なし／抵抗あり 共通）。
//   o.drag   … 抗力係数 Cd（0＝抵抗なし）
//   o.zoom   … 倍率。抵抗ありは扇が 1/3 に縮むので寄る。本文の大きさもその比で戻す
//   o.radius … [px] 球の半径。倍率のぶん縮めて画面上の見かけをそろえる（上の★）
//   o.x0     … 投げ出し点
function _demoCompare(o) {
  const r = o.radius, x0 = o.x0, y0 = ground.y - r;
  resetDemoWorld();
  updateGroundTerrain(false);
  for (const deg of DEMO_COMPARE_ANGLES) {
    const th = deg * Math.PI / 180, col = demoCompareColor(deg);
    const b = new Body({
        fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
      type:'circle', x:x0, y:y0, radius:r,
      // ★抵抗ありは断面/質量の比を他の抵抗デモとそろえる（demoDragMass の★）。
      //   半径から質量を逆算するので、球を小さくしても軌道は変わらない。
      //   抵抗なしのほうは質量が運動に効かないので 1 kg のままでよい。
      mass: o.drag ? demoDragMass(r) : 1,
      drag: o.drag || 0,
      vx:  toPx(DEMO_COMPARE_V0 * Math.cos(th)),
      vy: -toPx(DEMO_COMPARE_V0 * Math.sin(th)),   // ★内部の y は下向きが正
      friction:0, frictionStatic:0, restitution:0,
      layers:0,                                    // ★ゴースト＝重なっていてもぶつからない
      fillColor:col, strokeColor:'#ffffff', strokeWidth:1,
      label: deg + '°',
    });
    b.tracerEnabled  = true;
    b.tracerColor    = col;
    b.tracerDuration = 60;                         // 17球ぶんが出そろうまで消さない
    objects.push(b);
  }
  setDemoCam(o.camX || 0, o.zoom);
  const s = demoTextScale(o.zoom);                 // 倍率を上げたぶん文字を小さくする
  demoFakeGround(y0, x0, DEMO_NOTE_SIZE * s);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, o.title, DEMO_TITLE_SIZE * s);
  demoNote (p.x, p.y + 54 * s, o.note, DEMO_NOTE_SIZE * s);
}
function demoProjectileCompare() {
  _demoCompare({ drag:0, zoom:DEMO_COMPARE_ZOOM, radius:DEMO_COMPARE_R,
    x0:-600, title:'斜方投射（比較）',
    note:'同じ 10 m/s で、角度だけ 5°ずつ変えた17球（5°〜85°）を同じ点から同時に投げ出す\n'
       + '　（重なった位置から出発するので、ぶつからないよう衝突レイヤーは切ってある）\n'
       + '\n'
       + '【手順】▶実行 を押して、17本の軌跡を見くらべる\n'
       + '・白い線 ＝ 投げた高さに引いた「地面」。軌跡がこの線を切る点が到達点\n'
       + '　（お絵描きの線なので物理には参加しない。球はぶつからず突き抜けて落ちていく）\n'
       + '・いちばん遠くへ行くのは黄色の 45°（投げた高さへ戻るまで 10.2 m）\n'
       + '・同じ色の2本は足して 90° になる組（5°と85°、20°と70° …）。到達点がぴったり重なる\n'
       + '・角度が大きいほど高く上がり、空中にいる時間も長い\n'
       + '　　→ 高さと飛距離は両立しない（45°がその折り合いの点）' });
}
// 同じ17本を空気抵抗つきで。45°が最遠でなくなり、足して90°の組も重ならなくなる。
//   ★倍率を上げてある。抵抗ありの扇は 3.7 m × 2.4 m で、抵抗なし（10.3 m × 5.0 m）の
//     3分の1しかない。同じ 0.65 で置くと画面上 241×153px の切手大になり、17本を見分けられない。
//     ★倍率が違うことは本文に書く。書かないと、隣のデモと扇の大きさを目で比べた人が
//       「思ったほど縮んでいない」と読み違える（縮んだ量そのものが読みどころなので致命的）。
//     ★1.4 は「空の高さに対する扇の高さ」を抵抗なし版とそろえた値（どちらも約 0.65）。
//       これ以上寄せると本文の置き場所がなくなる（2.0 では空 247px に対し扇が 236px）。
function demoProjectileDragCompare() {
  _demoCompare({ drag:DEMO_DRAG_CD, zoom:DEMO_COMPARE_DRAG_ZOOM,
    radius:DEMO_COMPARE_R * DEMO_COMPARE_ZOOM / DEMO_COMPARE_DRAG_ZOOM,
    x0:-300, title:'斜方投射（空気抵抗比較）',
    note:'風船くらいの軽い球（終端速度 5.9 m/s）を、同じ 10 m/s で 5°ずつ 17本\n'
       + '　→ 最遠は 45°ではなく 35°。しかも 3.71 m で、抵抗なしの 10.25 m の3分の1\n'
       + '\n'
       + '【手順】▶実行 を押して、「斜方投射（比較）」の扇と見くらべる\n'
       + '・白い線 ＝ 投げた高さに引いた「地面」。軌跡がこの線を切る点が到達点\n'
       + '　（お絵描きの線なので物理には参加しない。球はぶつからず突き抜けて落ちていく）\n'
       + '・黄色の 45°（3.63 m）はもう一番ではない。35°（3.71 m）と 40°（3.70 m）が上\n'
       + '・同じ色の2本（足して 90°）はもう重ならず、低いほうの角がいつでも遠い\n'
       + '　　例：30°は 3.61 m に対し 60°は 2.98 m。高く上げるほど抵抗に削られる\n'
       + '・扇が小さいので、この画面だけ倍率を上げてある（目盛りの数字で確かめられる）' });
}

// 落とし始める球Bへ、その初めの位置を真っすぐ向いて球Aを投げ出すと必ず当たる。
//   ★教科書では狩りの喩えで呼ばれることがあるが、この題材で要るのは「同時に出発した
//     2物体が同じだけ落ちる」ことだけなので、球A・球B で通す（生き物に見立てない）。
//   ★球Aも球Bも、力が働かなかった場合の位置から同じ ½gt² だけ落ちる。だから
//     「向けた瞬間の位置関係」のまま出会う＝向きが合っていれば速さによらず当たる。
//   ★速度ツールの予測は2本描かれる（js/render/preview.js:537）：
//       白い点線 …「まっすぐ進んだ場合」＝力が働かないときの線。時刻をそろえた点つき
//       緑の実線 … 重力込みの本当の軌道
//     当たるかどうかを決めるのは前者。ここが授業で見せたい一点なので、説明でも
//     「白い点線が球Bを通るように向ける」と書いている。
//   ★予測は他の物体も一緒に動かす（predict.js は全物体を積分する）。つまり球Bも
//     予測の中で落ちるので、向きが合っていれば緑の線はぶつかる点で止まり、
//     そこに橙色の×が出る（preview.js:581）。向きの正しさをドラッグ中に確かめられる。
//     実測：白い点線の終点は球Bの初期位置から 22px（＝2球が触れ合う 28px とほぼ同じ）。
//   ★初速は向きから計算して入れる（角度を手で書かない）。位置を動かしても
//     向きがずれないので、数値を変えて試すときに壊れない。
function demoAirCollision() {
  const aX = -500, aY = ground.y - 100;          // 球A（左下・投げ出す）
  const bX =  400, bY = ground.y - 500;          // 球B（右上・落とす）
  const dx = bX - aX, dy = bY - aY, L = Math.hypot(dx, dy);
  const v0 = 14;                                 // [m/s] 球Aの速さ（速さは当たり外れに効かない）
  const ballA = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x:aX, y:aY, radius:14, mass:1,
    vx: toPx(v0 * dx / L), vy: toPx(v0 * dy / L),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'球A',
  });
  const ballB = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x:bX, y:bY, radius:14, mass:1,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#4dd0e1', strokeColor:'#b2ebf2', strokeWidth:1.5, label:'球B',
  });
  objects.push(ballA, ballB);
  resetDemoWorld();
  updateGroundTerrain(false);
  setDemoCam(0, 0.65);
  // ── 当たった瞬間で止めるプログラム ───────────────────────
  //   ★このデモの結論は「出会う」という出来事そのもので、当たったあとには何も無い
  //     （地面が無いので2球はそのまま画面の下へ落ちていく）。止めておけば、出会った点と
  //     速度ツールが出す橙色の×（予測した出会いの点）を、同じ画で見くらべられる。
  //   ★相手は「物体だけ」。地面は無いので今は同じだが、意味として球どうしの衝突を指す。
  const pg = addProgram(ballA);
  pg.trigger = 'hit'; pg.hitWhat = 'body'; pg.action = 'pause';
  pg.collapsed = true; pg.fx = 0.735; pg.fy = 0.17;
  pg.reset(); syncProgramState(pg); syncProgramPanel(pg); placeProgramPanel(pg);
  demoLabel(bX - 40, bY - 70, '球B', '#b2ebf2');
  demoLabel(aX - 30, aY + 30, '球A', '#ffcdd2');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '2物体の空中衝突');
  demoNote (p.x, p.y + 54,
    '右上の球Bは ▶実行 と同時に手をはなして自由落下する。\n'
  + '左下の球Aは、その瞬間の球Bの位置へ真っすぐ向けて同時に投げ出される。\n'
  + '\n'
  + '【手順】\n'
  + '1. ▶実行 → 落ちてくる球Bに球Aが当たる（約 0.70 秒後）。\n'
  + '　　当たった瞬間に自動で止まる（右上のプログラム）ので出会う点が読める\n'
  + '2. ↩ で戻し、速度ツールで球Aからドラッグして向きを変えてみる\n'
  + '　・白い点線「まっすぐ進んだ場合」＝重力が無ければ進む線。\n'
  + '　　この点線の先が球Bを通るように向ければ、速さをいくつにしても当たる\n'
  + '　・当たる向きなら、緑の予測線はぶつかる点で止まり橙色の×が出る\n'
  + '　　（×は球Bの初めの位置より下＝落ちてきた球Bと出会う点）\n'
  + '　・点線が球Bから外れると×は出ない（向きだけが効く）\n'
  + '\n'
  + 'なぜ当たるか：球Aも球Bも、力が働かなければ進んだはずの位置から\n'
  + '同じ ½gt² だけ落ちる。落ちる量が同じなので、向けた瞬間の\n'
  + '位置関係のまま出会う。');
}

// 走る台車からの投射。荷台のばね式発射台が、走行中に球を真上へ打ち出す。
//   ★時間で引き金を引く仕掛けは無い（タイマー・スイッチの類はどのツールにも無い）。
//     そこで「押さえレール」で作る：球はレールの下面に押さえられてばねを縮めたまま走り、
//     レールの端を抜けた瞬間に解放される。台車は等速なので 走った距離 ÷ 速さ ＝ 遅れ時間 で、
//     レールの長さがそのまま待ち時間になる（3m/s × 1.0秒 ＝ 300px）。
//   ★押さえレールは球だけを止めたい。衝突レイヤーで分ける：
//       台車・皿 …… レイヤー1
//       レール …… レイヤー2
//       球 …… レイヤー1＋2
//     マスク方式で推移的でないから、レールは球だけを押さえ、円筒の壁は素通りする。
//   ★ばねは「皿（円筒の中を上下する板）」につなぎ、球は皿の上に載せるだけにする。
//     球に直接ばねを付けると、自然長を越えた先で引き戻されてしまい打ち出しにならない
//     （押すだけのばねは無い）。皿はばねが自然長に達したところで減速し、球だけが離れる。
//   ★横向きの力はどこにも無い（摩擦0・抗力0）。台車も球も皿も同じ初速で走り出すので、
//     球は空中でも台車と同じ速さで進み、そのまま円筒へ戻ってくる。
const DEMO_TROLLEY_V   = 3;      // [m/s] 台車の速さ
const DEMO_TROLLEY_WAIT = 1.0;   // [s]   発射までの待ち時間（＝押さえレールの長さで決まる）
function demoTrolleyLaunch() {
  // ★高く飛ばすなら、ばねを強くするより「縮み幅」を伸ばすほうが得。
  //   ためられるエネルギーは ½kx² ＝ 幅の2乗で効くのに、押さえに要る力（＝解放の瞬間に
  //   横へ蹴られる量）は kx ＝ 幅の1乗でしか増えない。
  //   実測：k を 100→220 に上げると 1.10→2.41m・横ずれ +0.039→+0.104 m/s（2.7倍）。
  //         k=80 のまま幅を 40→85px にすると 3.3m まで上がって横ずれは +0.066 m/s に収まる。
  //   ★縮み幅は「おもりの丈 − 円筒の縁から出ている10px」まで。これを超えると、
  //     自然長のとき皿が縁より上へ出てしまい、戻ってきたおもりが円筒に入らない。
  //     だからおもりを縦長（44×100px）にして、その丈ぶんの縮みしろを稼いでいる。
  //   ★それでも、解放の瞬間には「1サブステップぶんの接触力積」が横向きに残る。
  //     押さえレールの端では、おもりが上へ食い込むぶんの重なりが横の重なりより深くなり、
  //     めり込みを解く向き（法線）が1回だけ横を向くため。大きさは
  //       Δv ≒ dt·g·(h/x + 1)   （h=打ち上げ高さ・x=縮み幅・dt=SIM_DT/substeps）
  //     で、刻みに比例する。実測：substeps=4 で +0.177 m/s、16 で +0.046 m/s。
  //     この題材は物体4つ・関節1つしかないので、刻みを細かくしても速さは落ちない。
  resetDemoWorld();
  world.substeps = 16;
  const x0 = -600;                       // 台車の出発点[px]
  const cartY = ground.y - 66;           // 荷台の中心（下面が地面）
  // U字の一体成形。★壁を別の物体にして溶接すると、ばねの反力で継ぎ目が震える。
  //   凹ポリゴンはそのまま置ける（js/physics/convex.js が凸パーツへ分解する）。
  //   内寸 128×102px の筒（縁 -50／内床 +52）に、皿・おもり・ばねが収まる。
  const cart = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'polygon', x:x0, y:cartY, mass:3,
    verts:[{x:-106,y:-50},{x:-90,y:-50},{x:-90,y:52},{x:90,y:52},
           {x:90,y:-50},{x:106,y:-50},{x:106,y:66},{x:-106,y:66}],
    vx: toPx(DEMO_TROLLEY_V),
    friction:0, frictionStatic:0, restitution:0,
    guideEnabled:true, guideAngle:0,     // 水平のレールに拘束＝ばねの反力で浮き沈みしない
    fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5, label:'台車',
  });
  // ばねの上に載る皿。円筒の内側（幅128px）を上下するだけなので回転は止める
  const plate = new Body({
    type:'box', x:x0, y:cartY + 46, w:172, h:12, mass:0.2,
    vx: toPx(DEMO_TROLLEY_V), fixedRotation:true,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1, label:'皿',
  });
  // 打ち出される「おもり」。★丸ではなく角にしてある。丸だと、押さえレールの端を
  //   抜けるとき接触が角（点）に移り、法線が斜めを向いて横向きの力積が入る
  //   （実測：丸で 3.00→3.81 m/s と横に蹴られ、壁にぶつかって台車まで減速した）。
  //   平らな上面どうしなら、最後まで法線は鉛直のままで横に蹴られない。
  const proj = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'box', x:x0, y:cartY - 10, w:90, h:100, mass:0.5,
    vx: toPx(DEMO_TROLLEY_V),
    friction:0, frictionStatic:0, restitution:0,
    layers:0b0011,                       // ★台車（1）とも押さえレール（2）とも当たる
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'おもり',
  });
  // 押さえレール。おもりの頭に触れる高さに置く。
  //   ★端の位置は「おもりの後ろ端」で決める。押さえが外れるのは前端ではなく後ろ端が
  //     レールを抜けた瞬間なので、前端で測ると半幅ぶん遅れる。
  const railL = x0 - 400;
  const railR = x0 - 45 + toPx(DEMO_TROLLEY_V) * DEMO_TROLLEY_WAIT;
  const rail = new Body({
    type:'box', x:(railL + railR)/2, y:cartY - 66, w:railR - railL, h:12,
    isStatic:true, mass:0, layers:0b0010,   // ★おもりだけを押さえる（円筒の壁は素通り）
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1, label:'押さえレール',
  });
  objects.push(cart, plate, proj, rail);
  // ばね：台車の内床 ↔ 皿。自然長 51px に対していまは 11px＝40px 縮んでいる
  demoSpring({
    bodyA:cart, bodyB:plate, anchorAx:0, anchorAy:52, anchorBx:0, anchorBy:0,
    // 自然長 91px に対していまは 6px＝85px 縮んでいる（縮み幅は上の★の制約いっぱい）
    restLength:91, stiffness:70, damping:0.2, radius:8,
  });
  updateGroundTerrain(true);
  setDemoCam(0, 0.65);
  demoLabel(railR - 300, rail.y - 50, '押さえレール', '#b0bec5');   // 右端寄せ（左端は画面外）
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '走る台車からの投射');
  demoNote (p.x, p.y + 54,
    '台車は 3 m/s の等速直線運動（摩擦なし）。荷台の円筒にばね式の発射台があり、\n'
  + 'おもりは灰色の押さえレールに押さえられて、ばねを縮めたまま走っている。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '1. 台車がレールの端を抜けた瞬間（約 1.0 秒後）、ばねが伸びておもりが真上へ飛び出す\n'
  + '2. おもりは空中でも横向きには 3 m/s のまま（横向きの力が働かないから）\n'
  + '3. 台車も同じ 3 m/s で走り続けるので、おもりはもとの円筒へ戻ってくる\n'
  + '\n'
  + '・台車から見れば「真上に投げ上げて、真下に落ちてきた」だけ\n'
  + '・地面から見れば放物線。同じ運動を、どこから見るかが違うだけ\n'
  + '・ストロボ：おもりを選んでから押すと、押さえレールの下を等間隔で進み、\n'
  + '　　そのあと放物線になる様子が像で残る');
}

// 川を渡る船。流れの場（速度の合成モード）の中を、岸に垂直な向きのまま船が横切る。
//   ★真上から見下ろした図にする（world.gravY = 0・地面なし）。「等速直線運動で流れに
//     垂直に突っ込む」は横から見た画面では作れない（重力が縦向きの運動を加速してしまう）。
//     state.js が背景を「真上から見たテーブル」とみなす設定（bgFriction / bgGravPerp）を
//     持っているのはこの見方のためで、摩擦は 0 のまま＝水面を滑る船として扱う。
//   ★流れの場は 'advect'（速度の合成）。抗力モードではないので、船の質量にも抗力係数にも
//     依らずに v + u になる（flow-field.js の①）。教科書の速度の合成そのもの。
//   ★数値は 3-4-5 の直角三角形にとる：船 4 m/s（岸に垂直）・流れ 3 m/s → 合成 5 m/s。
//     川幅 4 m なら渡るのに 1.0 秒ちょうど、流される距離は 3.0 m ちょうど。
//     グラフの目盛りも 3・4・5 で読めるので、合成の計算をその場で確かめられる。
//   ★グラフは速度だけ（変位と加速度は畳む）。加速度を出すと、川に入る瞬間と出る瞬間に
//     見かけの巨大なスパイクが立つ：速度の合成は力ではなく「媒質に乗り移った」ぶんの
//     下駄なので、v の階段を dv/dt で微分した数字に物理的な意味がない。
//   ★流速はリモコンのつまみで変えられる（流れの場の「流速」。船の速さは変えない）。
//     変えて渡り直すと「流される距離は流速に比例して変わるが、渡る時間 1.0 秒と
//     速度Y の 4 m/s は変わらない」＝ 2つの向きの運動が互いに独立なことを手で確かめられる。
//     渡っている最中に回しても、速度X だけがその場で段になって変わる（flow-field.js の
//     applyFlowAdvection は下駄を差し替えるだけ）。
//     ★↩ で戻ると流速は ▶ を押した時点の値に戻る（履歴の控えが流れの場ごと持つ）。
//       つまみで決めた値のまま何度でも渡り直せる。
//     ★画面の注釈（黄色の矢印・着く点）は開いたときの 3 m/s の値として残し、
//       そう読めるように「3.0 m/s なら」と書く。変えた先は水色の軌跡が示す。
const DEMO_RIVER_FLOW  = 3;     // [m/s] 川の流れ（右向き）
const DEMO_BOAT_SPEED  = 4;     // [m/s] 船が水に対して進む速さ（岸に垂直）
const DEMO_RIVER_W     = 400;   // [px]  川幅 4 m（渡るのに 1.0 秒）
const DEMO_RIVER_DRIFT = 300;   // [px]  流される距離 3 m（＝川幅 ÷ 船の速さ × 流速）
function demoRiverCrossing() {
  resetDemoWorld();
  setDemoGravity(0);            // ★真上から見た図。重力は画面に垂直な向きなので画面内には現れない
  world.velVizScale = 20;       // [px per (m/s)] 既定 5 では 5 m/s が 25px にしかならず向きが読めない
  updateGroundTerrain(false);   // 岸は注釈の線で描く（物理には参加させない＝ぶつけて止めない）
  const bankNear = ground.y;                    // 手前の岸
  const bankFar  = ground.y - DEMO_RIVER_W;     // 向こう岸
  const x0 = -DEMO_RIVER_DRIFT;                 // 出発点。ここから 3 m 流されて x=0 に着く
  const y0 = ground.y + 180;                    // 岸まで 1.8 m 手前（0.45 秒ぶんの助走）
  // 川。★左右は画面の外まで伸ばす（幅を画面に合わせると、川が途中で切れて池に見える）
  flowFields.push(new FlowField({
    x: 0, y: (bankNear + bankFar) / 2, w: 2600, h: DEMO_RIVER_W,
    speed: DEMO_RIVER_FLOW, angle: 0,      // 角度 0 ＝ 右向き
    mode: 'advect',                        // ★速度の合成（抗力ではない）
  }));
  // 船。舳先を向こう岸へ向けたまま進む＝回転は止める（水の流れは船を回さない）
  const boat = new Body({
    type:'polygon', x:x0, y:y0, mass:2,
    verts:[{x:0,y:-34},{x:16,y:-8},{x:14,y:26},{x:-14,y:26},{x:-16,y:-8}],
    vy: -toPx(DEMO_BOAT_SPEED),            // ★内部の y は下向きが正。向こう岸＝画面の上
    friction:0, frictionStatic:0, restitution:0,
    fixedRotation:true,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5, label:'船',
    showVelocity:true,                     // 合成された速度（斜め 5 m/s）を矢印で見せる
  });
  boat.tracerEnabled  = true;
  boat.tracerColor    = '#4dd0e1';
  boat.tracerDuration = 60;                // 渡り終わるまで消さない（折れ曲がりが要点）
  objects.push(boat);
  setDemoCam(0, 0.65);
  // ── 岸と基準線 ────────────────────────────────
  const line = (x, y, pts, color, width) =>
    annotations.push(new Annotation({ type:'path', x, y, color, width, pts }));
  const bankColor = '#8d6e63';
  line(-1300, bankNear, [{x:0,y:0},{x:2600,y:0}], bankColor, 4);
  line(-1300, bankFar,  [{x:0,y:0},{x:2600,y:0}], bankColor, 4);
  demoLabel(420,  bankNear + 14, '手前の岸', '#bcaaa4');
  demoLabel(-740, bankFar  - 40, '向こう岸', '#bcaaa4');   // ★右うえはグラフの窓が占める
  // 流れが無ければ進んだはずの道すじ（出発点から真っすぐ向こう岸へ）
  line(x0, bankFar, [{x:0,y:0},{x:0,y:y0 - bankFar}], 'rgba(255,255,255,0.30)', 2);
  // 流された 3 m の目印。★向こう岸の少し手前（川の中）に置く。岸より上は説明文の場所。
  //   ★色は軌跡（水色）と変える。同じ色だと、寸法の矢印が船の通った跡に見える
  demoArrow(x0, bankFar + 34, DEMO_RIVER_DRIFT, 1, '#ffd54f');
  //   ★流速はつまみで変わるので、寸法と着く点は「開いたときの 3 m/s なら」と書く
  //   ★文字は矢印より左から書き出す。x0+30 からだと末尾が縦の目盛り（x=0 の「3m」）に重なる
  demoLabel(x0 - 60, bankFar + 76, '3.0 m/s なら 3.0 m 流される', '#ffd54f');
  demoLabel(x0 - 30, bankFar - 40, '流れが無ければ着く点', 'rgba(255,255,255,0.75)');
  demoLabel(30,      bankFar - 40, '3.0 m/s で着く点', '#4dd0e1');
  // 流れの向き。★左下（川の中）に置く。右半分はグラフの窓と船の通り道
  demoArrow(-700, bankNear - 120, 200, 1, '#7986cb');
  demoLabel(-700, bankNear - 175, '川の流れ（はじめ 3.0 m/s）', '#9fa8da');
  // ── 流速のつまみ ───────────────────────────────────
  //   ★範囲は 0〜5 m/s。5 m/s で着く点は x=+200px（船の右端 +216px）で、右うえの
  //     グラフの窓の左端（ワールドで約 +260px）より手前に収まる。これより速くすると
  //     向こう岸に着くところが窓の下に隠れる。0 まで下げれば「流れが無ければ」の線の上を渡る。
  //   ★窓は左下・手前の岸より下。船（x=-300）より左で、本文とも川とも重ならない。
  const knob = addRemote('prop', flowFields[0], 'flowfield');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'speed'; knob.lo = 0; knob.hi = 5;
    knob.fx = 0.055; knob.fy = 0.80;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  // ── グラフ ────────────────────────────────────
  // ★autoStart：記録開始トリガー（|a|≥0.9 m/s²）を待たずに、実行と同時に記録する。
  //   川に入るまで加速度はどこにも生じないので、待たせると t=0 が「川に入った瞬間」になり、
  //   合成する前の 4 m/s が1点も残らない。Y が入水の前後で変わらないこと（＝渡る時間は
  //   流れに依らない）がこの題材の要点なので、川に入る前の平らな区間が要る。
  //   ★リセットしても待機へ戻らない。startVelGraphNow() で開けると
  //     リセットのたびに待機へ落ち、2回目の実行から入水後だけのグラフになる。
  moveDemoGraphTop(velGraphNew(boat, { showPos:false, showVel:true, showAcc:false,
                                       showX:true, showY:true, showMag:true,
                                       autoStart:true }));
  // ★本文は1行 40 文字までに収める。右うえのグラフの窓が画面の右 1/3 を覆うので、
  //   43 文字を超えると行末が窓の下へ潜って読めなくなる（実測：44 文字で切れた）。
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '速度の合成（川を渡る船）');
  demoNote (p.x, p.y + 54,
    'これは川を真上から見た図（重力は画面に垂直な向きなので、画面の中には現れない）。\n'
  + '川は右へ 3 m/s で流れ、船は水に対して 4 m/s で岸に垂直に進む。川幅は 4 m。\n'
  + '\n'
  + '【手順1】▶実行 を押して、右うえの速度グラフを見る\n'
  + '・X（青）：川に入ると 0 → 3 m/s、出ると 0 に戻る ＝ 川の流れそのもの\n'
  + '・Y（赤）：ずっと 4 m/s のまま。渡る時間 1.0 秒は流れがあってもなくても同じ\n'
  + '・大きさ（白）：4 → 5 m/s。3 と 4 を直角に足して 5 ＝ 速度の合成\n'
  + '・水色の軌跡：川の中だけ斜めに折れ曲がり、3.0 m 下流に着く\n'
  + '・緑の矢印＝地面から見た速度。舳先は向こう岸を向いたまま、進む向きだけ斜め\n'
  + '【手順2】↩ で戻し、左下のつまみで流速を変えて渡り直す（0〜5 m/s）\n'
  + '・流される距離は流速に比例して変わるが、渡る時間と Y の 4 m/s は変わらない\n'
  + '・渡っている最中に回すと、X だけがその場で変わり、軌跡がそこで折れる');
}

// ════════════════════════════════════════
//  力学 ▸ いろいろな力
// ════════════════════════════════════════
// ── いろいろな力（重力・垂直抗力・張力・弾性力）──────────────────
//   ★1画面に5つの「遊具」を並べ、おもりを掴んで置き換えながら力の矢印を読む題材。
//     運動を見せるデモではないので、初期配置はすべて釣り合った状態から始める
//     （実行を押しても何も動かない＝生徒が触ったところだけが変わる）。
//   ★このデモだけは摩擦を働かせる（他の力学デモは既定で 0 にしてある）。
//     見せたい力は重力・垂直抗力・張力・弾性力の4つで摩擦は入っていないが、摩擦を 0 に
//     すると「置く」操作そのものが成立しない：箱を 20px ずらして重ねただけで、着地の
//     瞬間の傾きを止めるものが無く、2個とも横へ滑って画面外まで飛んだ（実測：15tick
//     ごとに横向きの速さが約3倍に育ち、A は x=-1334 まで流れた）。
//     釣り合っている間の摩擦力は 0 なので黄色い矢印は出ない＝見る力は4つのまま。
//     ★斜面（②）だけは静的な三角形側の摩擦を 0 にして「なめらかな斜面」を保つ。
//       合成は積なので、面が 0 ならその接触は 0 になる。
//   ★world.sleeping = false。これが要（既定は true）。
//     眠った物体はソルバを通らないので _forces が空になり、代わりに liveForcesFor()
//     （重力＋地面の垂直抗力だけ）が使われる。＝ 静止して眠った瞬間に、
//     ロープの張力もばねの弾性力も台の垂直抗力も矢印が消える。釣り合いを眺める
//     題材でそれが起きると「力が無くなった」に見えるので、眠らせない。
//   ★forceVizScale = 8 [px/N]。標準のおもり 1 kg の重力 9.8 N が 78 px になる長さ。
//     既定の 1 では 9.8 px＝最小長 12px に潰れて、力の大小がまったく読めない。
//     2段重ね（19.6 N＝157 px）でも上限 260px に当たらない。
const PG_MASS      = 1;    // [kg]  標準のおもり。mg = 9.8 N
const PG_SPRING_K  = 20;   // [N/m] つり下げばね。1 kg で 49 px（0.49 m）伸びる
const PG_PLATE_K   = 25;   // [N/m] 踏み台のばね。1 kg 載せると 39 px 縮む
//   ★④のつり下げばねは減衰 0＝止まらない単振動にする。以前は ζ≈0.3 相当（c=3.8）を
//     入れて釣り合いの位置へ早く落ち着かせていたが、それだと「引いて放すと単振動する」
//     という、ばねのいちばん見せたい姿が数往復で消えてしまう。
//     ★釣り合いの伸び（1kg で 49px）を読みたいときは、おもりをそっと置けばよい。
//       振れるのは引いて放したときだけで、勝手には振れない。
//   ★⑤の踏み台は減衰を残す。あちらは「載せると縮む・弾性力が増える」を読む台で、
//     載せるたびに揺れ続けると皿の上のおもりが跳ねて落ちる。
const PG_SPRING_C  = 0;    // [N·s/m] ④つり下げばね（減衰なし＝単振動）
const PG_PLATE_C   = 4.0;  // [N·s/m] 踏み台のばね（m=1.5kg, k=25）
function demoForcePlayground() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;         // ★冒頭の★を参照（眠ると拘束力の矢印が消える）
  world.forceVizScale = 8;        // [px per N]
  updateGroundTerrain(true);
  // 共通の作り。反発は 0（置いた箱が跳ねない）、力ベクトルは動く物体すべてで ON。
  // 摩擦は冒頭の★のとおり普通に効かせる（釣り合っている間は 0 なので矢印は出ない）
  const solid  = { friction:0.6, frictionStatic:0.8, restitution:0 };
  const fixed  = o => Object.assign({ isStatic:true, mass:0,
                                      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5 },
                                    solid, o);
  const weight = o => Object.assign({ type:'box', w:64, h:64, mass:PG_MASS,
                                      fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5,
                                      showForces:true }, solid, o);
  // 遊具の立て札。★見出し（何をする所か）と本文（どの力が出るか）を1組で置く。
  //   全体の説明は左うえに1つだけ置き、ここは「その遊具の前で読む短い説明」に徹する。
  //   ★5枚とも同じ高さ（SIGN_Y）に並べる。遊具のすぐ横に散らすと、ロープやばねや
  //     力の矢印と必ずどこかで重なる（実測：初版は5枚のうち4枚が遊具に掛かった）。
  //     上に1列そろえれば、説明文の帯と遊具の帯が上下に分かれて両方読める。
  //   ★1行の字数は「その遊具に割り当てた幅 ÷ 18px」まで。はみ出すと隣の札に食い込む。
  //   ★列の高さは本文の下端から決める（決め打ちの y にすると本文と重なる。
  //     demoNoteBelow の★）。そのため本文はここで先に置く。
  setDemoCam(0, 0.55);            // 遊具5つ（±900px＝18m）が1画面に収まる倍率
  const p = demoTextTopLeft();
  const NOTE =
    '5つの遊具で、力の向きと大きさを見くらべる。\n'
  + '矢印の色： 重力＝赤　垂直抗力＝青　張力・弾性力＝緑\n'
  + '\n'
  + '開いた直後は一時停止。矢印はつりあった状態のまま。\n'
  + '【手順】▶実行 を押してから、編集ツールでおもりを\n'
  + '運ぶ（止めたままだと矢印が更新されない）。';
  demoTitle(p.x, p.y, 'いろいろな力');
  demoNote (p.x, p.y + 54, NOTE);
  const SIGN_Y = demoNoteBelow(p.y + 54, NOTE);
  const sign = (x, head, body) => {
    annotations.push(new Annotation({ type:'text', x, y:SIGN_Y, text:head,
                                      size:22, bold:true, color:'#4fc3f7' }));
    annotations.push(new Annotation({ type:'text', x, y:SIGN_Y + 33, text:body,
                                      size:18, color:'#cfd8dc' }));
  };

  // ── ① 床とすべり台（重力・垂直抗力）　持ち場 x = -900 〜 -520 ──────────
  //   ★床（つりあう）とすべり台（つりあわない）を同じ持ち場に並べる。同じ2力でも、
  //     面の向きが変わると打ち消し合わなくなる ＝ ①の箱をそのまま滑らせて確かめられる。
  //   ★すべり台は②と同じ 30°・摩擦0。②との違いは「ロープで支えていない」ことだけで、
  //     ②の札に書いた「ロープを外すと滑り落ちる」を、②を壊さずにその場で試せる。
  //   ★丈は 104px（1.04m）に抑える。もとは倒れ込みを避けるための値だった（丈 127px では
  //     四角い箱が斜面の裾を抜ける瞬間に前のめりに倒れて転がり、仕切りに寄りかかったまま
  //     54° で止まった。実測）。いまは回転を止めてある（ファイル冒頭の★）ので倒れないが、
  //     丈はこのままにする：高くすると重心が上がり、斜面に置いた瞬間の見た目が不安定になる。
  //   ★仕切りの壁を置く。摩擦0の斜面を滑り降りた箱は 3.4 m/s まで加速し、床の摩擦
  //     （合成 μ=0.55）では止まるのに 1m 以上要る。壁が無いと②の斜面へ乗り上げて、
  //     ロープで支えてある②の箱に当たり、隣の遊具の釣り合いを壊してしまう。
  const SLIDE_X = -800, SLIDE_W =  90, SLIDE_H = 104;   // tan30° × 180px ≒ 104px
  objects.push(new Body(fixed({ type:'polygon', x:SLIDE_X, y:gy,
    friction:0, frictionStatic:0,          // ★②と同じ「なめらかな斜面」
    verts:[{x:-SLIDE_W,y:-SLIDE_H},{x:SLIDE_W,y:0},{x:-SLIDE_W,y:0}] })));
  objects.push(new Body(fixed({ type:'box', x:-548, y:gy - 50, w:16, h:100 })));   // 仕切り
  objects.push(new Body(weight({ x:-610, y:gy - 32, label:'1kg' })));
  sign(-890, '① 床とすべり台',
    '持ち上げると重力（赤）だけ。\n'
  + '床に置くと垂直抗力（青）が上向きに\n'
  + '同じ長さで出て、つりあう。\n'
  + 'すべり台（②と同じなめらかな面）に置くと\n'
  + '2力はつりあわず、滑り出す。');

  // ── ② なめらかな斜面（3力のつりあい）　持ち場 x = -510 〜 -260 ────────
  //   ★30°の直角三角形。摩擦が 0 なので、支えなければ必ず滑り落ちる（①のすべり台）。
  //     斜面に沿ったロープで支えると、重力（鉛直）・垂直抗力（面に垂直）・張力（斜面に
  //     沿う）の3本が別々の向きに、しかも別々の長さで出る。＝「垂直抗力は重力の逆向きで
  //     同じ大きさ」という思い込みが、絵のうえで崩れる。
  //     1 kg・30° なら 張力 = mg/2 = 4.9 N（39px）、垂直抗力 = mg·cos30° = 8.5 N（68px）。
  const RAMP_X = -390, RAMP_W = 130, RAMP_H = 150;   // tan30° × 260px ≒ 150px
  objects.push(new Body(fixed({ type:'polygon', x:RAMP_X, y:gy,
    friction:0, frictionStatic:0,          // ★ここも「なめらかな斜面」（合成は積）
    verts:[{x:RAMP_W,y:-RAMP_H},{x:RAMP_W,y:0},{x:-RAMP_W,y:0}] })));
  // 斜面の中ほどに置いた 1kg。傾きは画面で右上がり＝内部の角度では負
  const rampBlock = new Body(weight({ type:'box', w:76, h:44,
    x:RAMP_X - 11, y:gy - 94, angle:-Math.PI/6, label:'1kg' }));
  objects.push(rampBlock);
  // 斜面の上に立てた杭。★ロープが斜面と平行になる位置に置く（平行でないと張力に
  //   面から浮かせる成分が入り、垂直抗力が mg·cos30° からずれる）
  const rampPost = new Body(fixed({ type:'box', w:14, h:52, x:-281, y:gy - 163 }));
  objects.push(rampPost);
  joints.push(new Joint({
    type:'rope', bodyA:rampPost, bodyB:rampBlock,
    anchorAx:0, anchorAy:0, anchorBx:38, anchorBy:0,
    restLength:100, maxLength:100,
    linDensity:0.02,      // ★ほぼ軽いロープ（既定 0.2 kg/m だと自重が張力に混ざる）
    color:'#a5d6a7',
  }));
  sign(-510, '② なめらかな斜面',
    'ロープを外すと滑り落ちる。\n'
  + '垂直抗力（青）は面に垂直で、\n'
  + '重力の矢印より短い。\n'
  + '重力・垂直抗力・張力の\n'
  + '3力がつりあっている。');

  // ── ③④の支持体（梁だけ）──────────────────────────────
  //   ★横の柱は置かない。ロープもばねも取り付け点は「世界に固定した座標」（bodyA:null）
  //     なので、柱は物理的には何の役にも立たず、③の振り子が振れる範囲を削るだけだった
  //     （左の柱は振り子から 33px の位置にあり、少し揺らすとすぐ当たった）。
  //     梁は取り付け点の目印として残す。
  const BEAM_Y = gy - 630, HANG_Y = BEAM_Y + 11;   // 梁の下面＝つり下げ点
  objects.push(new Body(fixed({ type:'box', x: 135, y:BEAM_Y, w:850, h:22 })));

  // ── ③ ロープでつるす（張力）　持ち場 x = -250 〜 190 ────────────────
  //   ★1本と2本を並べるのが要点。同じ 1 kg でも、斜めに張った2本の張力は mg/2 にならない
  //     （つりあうのは鉛直成分だけなので、1本あたりは mg/(2cosθ) まで大きくなる）。
  //     θ = 46.7°（横 120px・縦 113px）で 7.1 N。2本の和は 14.3 N ＞ 9.8 N になる。
  //   ★1本のほう（振り子）は左右に振らせる遊具でもあるので、両隣を空けてある。
  //     左は斜面の頂点（gy-190）の上を通るだけ、右は 2本づりの左のロープに 80°付近で
  //     やっと届く＝実用上は振り放題。振ると張力が重力より長くなる（円運動の向心力）。
  const ball1 = new Body(weight({ type:'circle', radius:26, x:-230, y:gy - 320, label:'1kg' }));
  objects.push(ball1);
  joints.push(new Joint({
    type:'rope', bodyA:null, anchorAx:-230, anchorAy:HANG_Y, bodyB:ball1,
    anchorBx:0, anchorBy:-26, restLength:273, maxLength:273,
    linDensity:0.02, color:'#a5d6a7',
  }));
  const ball2 = new Body(weight({ type:'circle', radius:26, x:110, y:gy - 480, label:'1kg' }));
  objects.push(ball2);
  for (const ax of [-10, 230])
    joints.push(new Joint({
      type:'rope', bodyA:null, anchorAx:ax, anchorAy:HANG_Y, bodyB:ball2,
      anchorBx:0, anchorBy:-26, restLength:165, maxLength:165,
      linDensity:0.02, color:'#a5d6a7',
    }));
  sign(-250, '③ ロープでつるす（1本／2本）',
    '1本のとき張力（緑）＝重力。横に振ってもよい。\n'
  + '2本に分けても半分にはならない。開くほど長い\n'
  + '（つりあうのは上下の成分だけだから）。');

  // ── ④ ばねにつるす（弾性力・のび）　持ち場 x = 200 〜 545 ─────────────
  //   ★自然長 120px に対し 1kg で 49px のびた位置から始める（＝最初から釣り合っている）。
  //   ★つかんでいる間はばねの拘束が外れる（joint.js の jointLengthSuspended）ので、
  //     引いている最中ではなく「離したあとの往復」で、のびに比例して緑の矢印が
  //     伸び縮みするのを見る。札にもその断りを書く。
  const SP_REST = 120;
  const SP_EXT  = PG_MASS * G_EARTH / PG_SPRING_K * PPM;    // = 49px
  const hung = new Body(weight({ x:380, y:HANG_Y + SP_REST + SP_EXT + 32, label:'1kg' }));
  objects.push(hung);
  demoSpring({
    anchorAx:380, anchorAy:HANG_Y, bodyB:hung, anchorBx:0, anchorBy:-32,
    restLength:SP_REST, stiffness:PG_SPRING_K, damping:PG_SPRING_C,
  });
  sign(210, '④ ばねにつるす（のびる）',
    '弾性力（緑）は自然長へ戻る向き。\n'
  + '下へ引いて離すと、のびが大きいほど\n'
  + '矢印も長い（フックの法則 F = kx）。\n'
  + '※つかんでいる間だけばねを外している。');

  // ── ⑤ ばねの上にのせる（弾性力・ちぢみ ＋ 垂直抗力）　持ち場 x = 560 〜 900 ──
  //   ★体重計。おもりを載せると、ばねの縮みと弾性力、皿と箱の間の垂直抗力が同時に増える。
  //     ここだけは「つかんだままゆっくり載せる」ができる（おもりはばねに繋がっていないので、
  //     ④と違って掴んでいる間もばねが生きている）＝ 増え方を手で追える唯一の遊具。
  //   ★皿は鉛直のレールに拘束する（guideAngle = π/2）。ばね1本では横に倒れてしまい、
  //     おもりを少しでも端に置くと皿ごと滑り落ちる。
  //   ★皿は平板ではなく縁のある「受け皿」にする。摩擦0の平板に載せると、ばねの上下動の
  //     あいだ接触点の法線がわずかに傾き、横向きの速さが正のフィードバックで育つ
  //     （実測：0.1 → 0.4 → 3.1 → 23 → 64 → 135 px/s と 15tick ごとに約3倍になり、
  //      4秒で皿から飛び出して画面外の x=2900 まで飛んだ）。止めるものが要る。
  //     縁は反発0なので、寄っていったおもりは縁で速さを失ってそこに落ち着く。
  const PLATE_X = 700, PL_REST = 160, PL_MASS = 0.5;
  const PL_COMP = PL_MASS * G_EARTH / PG_PLATE_K * PPM;     // 皿だけで 19.6px 縮む
  objects.push(new Body(fixed({ type:'box', x:PLATE_X, y:gy - 20, w:150, h:40 })));
  const plate = new Body(weight({
    type:'polygon', x:PLATE_X, y:gy - 40 - PL_REST + PL_COMP - 8, mass:PL_MASS,
    // 底 170×16、両端に高さ 32 の縁。原点は底板の中心（ばねの取り付けは (0,+8)）
    verts:[{x:-85,y:-40},{x:-73,y:-40},{x:-73,y:-8},{x:73,y:-8},
           {x:73,y:-40},{x:85,y:-40},{x:85,y:8},{x:-85,y:8}],
    // ★動滑車は鉛直のレールに乗せる（プロパティ欄の「ガイド」。手でも設定できる）。
    //   横に自由なままだと、引き手が床に着いた衝撃で縄が一瞬ゆるみ、その隙に巻き付きの
    //   接触点が滑車の反対側へ回り込んで縄が交差し、動滑車が 190→250px 横へ流れて
    //   戻らなかった（実測）。上限のストッパーで受け止める案も試したが、今度は縦に
    //   振れ続けた（-423〜-457px を12秒たっても往復）。横を止めると縦の往復も消える
    //   （実測：3秒で -470px に静止）。滑車が鉛直にしか動かないのは実物どおりでもある。
    guideEnabled:true, guideAngle:Math.PI/2,       // 鉛直のレール（横には動かない）
    // ★回転も止める。レールが止めるのは並進だけなので、おもりを中央から 15px ずらして
    //   置いただけで皿が傾き出し、40tick で 49° 回って中身を投げ出した（実測）。
    //   体重計の皿は上下にしか動かない部品なので、1自由度に縛るのが正しい。
    fixedRotation:true,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', label:'皿 0.5kg',
  }));
  objects.push(plate);
  demoSpring({
    anchorAx:PLATE_X, anchorAy:gy - 40, bodyB:plate, anchorBx:0, anchorBy:8,
    restLength:PL_REST, stiffness:PG_PLATE_K, damping:PG_PLATE_C, radius:14,
  });
  objects.push(new Body(weight({ x:830, y:gy - 32, label:'1kg' })));
  sign(560, '⑤ ばねの上にのせる',
    '横の 1kg を皿へ運ぶ。\n'
  + 'ばねが縮んで弾性力（緑）が\n'
  + '増え、皿と箱の間には\n'
  + '垂直抗力（青）が出る。\n'
  + '※これは持ったまま載せられる。');

  // ── 一時停止で開く ──────────────────────────────────
  //   ★止めたまま開くと、力の矢印が重力と床の垂直抗力しか出ない。止まっている物体の
  //     矢印は liveForcesFor()（js/render/vectors.js）が毎フレーム作り直すが、あれが
  //     live で出せるのは重力・推力・地面の垂直抗力だけで、ロープの張力もばねの弾性力も
  //     物体どうしの垂直抗力も「ソルバが解いた結果」なので作れないため。
  //     矢印を読むための題材でそれが起きると、開いた瞬間の画面が空っぽに見える。
  //   ★そこで、止める前に 60tick だけ回して釣り合いの力を _forces に入れておく。
  //     _forces は次の simTick() の頭（Body.clearForces）まで残るので、止めている間は
  //     その値がそのまま描かれ続ける。初期配置はもともと釣り合っているので、この
  //     60tick で物体は動かない（実測：全7個が 1px 以内・|v| < 0.05 m/s）。
  //   ★ただし止めたままおもりを掴んで動かしても、矢印はこの値のまま固まる（誰も
  //     解き直さないため）。だから説明文で「▶実行 を押してから運ぶ」と断ってある。
  for (let i = 0; i < 60; i++) simTick();
  stepCount = 0; world.simTime = 0;    // 経過時間は 0 から見せる（回したのは矢印のためだけ）
}

// ════════════════════════════════════════
//  力学 ▸ いろいろな力 ▸ 滑車・動滑車
// ════════════════════════════════════════
// ── 縄を経路に沿って掛ける ────────────────────────────────
//   ★ロープの節点は既定では「両端を結ぶ直線」に並ぶ（ensureRopeNodes）。滑車に掛けた形は
//     直線ではないので、そのまま置くと縄が滑車を貫いた状態から始まって暴れる。
//     シーン読込が巻き付き形状を復元するのに使う restoreRopeNodes へ、経路上に等間隔で
//     並べた節点を渡せば、最初から掛かった形で始められる。
//   ★maxLength は経路の実長にする。これが縄の全長＝張力が立つ基準になる。
//   pts は折れ線（両端はロープの端点と一致させること）。円弧は pulleyArc() で作る。
function ropeAlongPath(j, pts) {
  let total = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) {
    const d = Math.hypot(pts[i].x - pts[i-1].x, pts[i].y - pts[i-1].y);
    seg.push(d); total += d;
  }
  const n = ropeSegCountFor(total), step = total / n, saved = [];
  for (let k = 1; k < n; k++) {
    let s = k * step, i = 0;
    while (i < seg.length - 1 && s > seg[i]) { s -= seg[i]; i++; }
    const t = seg[i] > 0 ? Math.min(1, s / seg[i]) : 0;
    saved.push({ x: pts[i].x + (pts[i+1].x - pts[i].x) * t,
                 y: pts[i].y + (pts[i+1].y - pts[i].y) * t });
  }
  j.maxLength = total; j.restLength = total;
  restoreRopeNodes(j, saved);
}
// 滑車に巻きつく円弧。半径は「滑車の半径＋縄の半径」＝縄の中心線が通る円。
//   a0→a1 は度。180→0 で上を越え、180→360 で下をくぐる（画面の y は下向き正）。
function pulleyArc(cx, cy, r, a0, a1) {
  const out = [], st = a1 > a0 ? 15 : -15;
  for (let a = a0; st > 0 ? a <= a1 : a >= a1; a += st)
    out.push({ x: cx + r * Math.cos(a * Math.PI/180), y: cy - r * Math.sin(a * Math.PI/180) });
  return out;
}
// ── 滑車・動滑車 ────────────────────────────────────────
//   ★引く力はリモコンのつまみ（設定を変える）。左右の引き手に下向きの動力を付け、1つの
//     つまみに2本ともつなぐ＝左右に必ず同じ力がかかる。0 N で開くので ▶実行 だけでは
//     何も起きず、つまみを 0 から少しずつ上げていくと、先に動滑車の荷が持ち上がり、
//     定滑車の荷はそのほぼ2倍まで上げないと床から離れない、が見どころ
//     （2026-09-30、ユーザーの指示。押しボタンで 7.0 N を一度に入れる形から変えた）。
//       定滑車：引く力 F ＋ 引き手の重さ 0.98 N ＞ 荷の重力 9.81 N → F ＞ 8.83 N
//       動滑車：2 ×（F ＋ 0.98）＞ 荷と動滑車の 10.8 N           → F ＞ 4.42 N
//     実測（2026-10-01。力を固定して 6 秒追う。上がり続けるか＝加速するかで判定）：
//       動滑車 4.3 N → 0.6 mm（床の上）／ 4.4 N → 2〜4 cm 浮いて戻る ／ 4.5 N → 6 秒で 2.0 m
//       定滑車 8.7 N → 1 mm ／ 8.8 N → 毎秒 14 mm 這う ／ 8.85 N → 加速
//       ＝ どちらも理論の境目どおり。画面の札の「約 4.4 N」「約 8.8 N」はこの値。
//     ☆以前は動滑車の荷が 4.0 N から 7〜8 cm 浮いて宙に留まっていた。縄の節点の鎖が
//       動滑車を接触で押し上げる力が、巻き付きの張力（joint.js の wrap）に重なっていた
//       二重計上が原因で、節点の質量に比例していた（F=4.2 N で 0.283 N、縄の質量 ×3 で
//       0.433 N）。rope.js の viaTension で直した（張力が引いている相手は節点の接触では
//       押さない）。直したあと F=4.2 N で荷の浮き 87 mm → 0.3 mm。
//       加速度（7 N・2次式の当てはめ）は理論 3.450 に対し 修正前 3.358／修正後 3.483 m/s²。
//     ★つまみの範囲は 0〜12 N（PU_FMAX）。200 等分で 0.06 N 刻み＝2つの境目のどちらも
//       飛ばさずに通れる。上限は定滑車の境目 8.8 N に余裕を持たせた値。
//     ★以前は動力を付けず、つかむツールで引かせていた。動力を付けっぱなしにすると
//       ▶実行 だけで右側が上がってしまったため（下の引き手の★）。0 N で開けばその問題は
//       起きず、マウスで引く強さのばらつきも消える。つかむツールの上限 7.0 N も残してある
//       （手で引いても、動滑車だけが上がる）。
//   ★色は役割で決める：持ち上げる荷＝赤、動滑車＝黄、引き手＝青、支える構造（天井・
//     定滑車）＝灰。左右で同じ役には同じ色を使う。
//   ★定滑車は天井から縄で吊る（宙に浮いた静的物体にしない）。吊ってあるので定滑車自身も
//     動く物体で、巻き付いた縄から 2T を下向きに受け、その反力を吊り縄が持つ。
//     ＝ 滑車も「摩擦0の円い物体に縄を掛けただけ」で、生徒が同じものを手で組める。
//   ★引き手は荷の 1/10（0.1 kg）。ここを軽くしないと、引き手が自分の重さで縄を引いて
//     勝手に動き出す（動力を付けっぱなしにしていた頃は ▶実行 だけで右側が上がってしまった。
//     いまは動力を 0 N で開き、つまみで上げていく）。
//     ただし 0 にはできない：動滑車（0.1 kg）を吊っておくには張力が半分だけ要るので、
//     引き手の重さが動滑車の重さの半分（0.05 kg 相当）を下回ると動滑車が沈む。
//     0.1 kg なら張力 0.98 N が立ち、必要な 0.49 N に対して倍の余裕がある。
//   ★つかむツールの最大力は 7.0 N（grabMaxForce）。手で引き手を引いたときの下向きの力は
//     これに引き手の重さ 0.98 N を足した 7.98 N が上限で、定滑車の境目 8.83 N に届かず、
//     動滑車の境目 4.42 N は超える＝手で引いても動滑車だけが上がる。
//     荷を直接つかんで持ち上げようとしても上がらないのも同じ理由。
//   ★ストロボはデモ側で入れない（2026-09-30、ユーザーの指示）。デモを開いた時点では
//     ストロボは切れている、をどのデモでも揃える。入れれば（対象「動いている物体すべて」）
//     動滑車の側で引き手の像が荷の像の2倍の間隔で並ぶが、それは使う人が選ぶこと。
const PU_FMAX  = 12;     // [N]  引く力のつまみの上限（冒頭の★）
const PU_GRAB  = 7;      // [N]  つかむツールの最大力
const PU_LOAD  = 1;      // [kg] 荷。重力 9.81 N。左右で同じ物体
const PU_MOV   = 0.1;    // [kg] 動滑車そのもの
const PU_HAND  = 0.1;    // [kg] 引き手（荷の1/10）
const PU_FIX   = 0.5;    // [kg] 定滑車（天井から吊るので動く物体）
const PU_R     = 36;     // [px] 滑車の半径
function demoPulley() {
  const gy = ground.y;
  resetDemoWorld();
  // ★力ベクトルは出さない。この題材の要点は「同じ力で上がる／上がらない」という結果で、
  //   矢印を出すと動滑車には 巻き付きの張力（上）・荷を吊る縄の張力（下）・重力 の3本が
  //   重なって、かえって読みにくい。見たい人はプロパティ欄の「力」で個別に出せる。
  world.forceVizScale = 8;     // ★出したときに読める長さ（1kg の重力 9.81 N が 78px）
  // ★眠らせない。荷は床に置いた状態から始まるので、縄が張る前に眠ると起きそこねる
  world.sleeping = false;
  grabMaxForce = PU_GRAB;      // ★冒頭の★を参照
  updateGroundTerrain(true);
  const RR = PU_R + ROPE_CFG.radius;      // 縄の中心線が通る半径
  const CEIL_Y = gy - 650, CEIL_B = CEIL_Y + 12;   // 天井の中心と下面
  const PY = gy - 560;                             // 定滑車の中心の高さ
  const slip = { friction:0, frictionStatic:0, restitution:0 };
  const rope = o => Object.assign({ type:'rope', linDensity:0.02, color:'#a5d6a7' }, o);
  const load = (x, y) => new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'box', w:64, h:64, x, y, mass:PU_LOAD,
    friction:0.6, frictionStatic:0.8, restitution:0,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'荷 1kg' });
  const hand = (x, y) => new Body(Object.assign({
    type:'box', w:40, h:40, x, y, mass:PU_HAND, fixedRotation:true,
    fillColor:'#7986cb', strokeColor:'#c5cae9', strokeWidth:1.5,
    label:'引き手 0.1kg',
    // ★下向きの動力。0 N で開き、大きさはつまみで左右そろえて上げていく（冒頭の★）
    thrusters:[{ force:0, dir:Math.PI/2 }] }, slip));
  // 天井から縄で吊った定滑車。滑車自身も動く物体なので、巻き付いた縄の 2T を受け取る。
  //   ★吊り縄は2本のV字にする。1本で吊ると横に振れる自由が残り、引き手が着地した衝撃で
  //     定滑車が 268→281px 振れ、その幾何のずれに引きずられて動滑車まで 190→250px
  //     流れた（実測）。2本で三角に張れば横は決まる＝実物の滑車ブロックの吊り方と同じ。
  const HANG_SPREAD = 34;      // [px] 天井側の2点の間隔（片側）
  const hangPulley = (ceil, x) => {
    const p = new Body(Object.assign({
      type:'circle', radius:PU_R, x, y:PY, mass:PU_FIX, fixedRotation:true,
      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5 }, slip));
    objects.push(p);
    for (const dx of [-HANG_SPREAD, HANG_SPREAD]) {
      const h = new Joint(rope({ bodyA:ceil, bodyB:p, anchorAx:x + dx - ceil.x, anchorAy:12,
                                 anchorBx:0, anchorBy:0 }));
      ropeAlongPath(h, [{ x: x + dx, y:CEIL_B }, { x, y:PY }]);
      joints.push(h);
    }
    return p;
  };
  // ── 全体の説明と、その下に並べる立て札の高さ ────────────────────
  //   ★本文を先に置いて、札の列（SIGN_Y）はその下端から決める。決め打ちの y にすると
  //     本文と重なる（本文の位置は画面の大きさと倍率で動くため。demoNoteBelow の★）。
  setDemoCam(0, 0.55);
  const p = demoTextTopLeft();
  const NOTE =
    '▶実行 を押し、下のつまみで「引く力」を 0 から\n'
  + '少しずつ上げる（左右の引き手に同じ力がかかる）。\n'
  + '荷はどちらも 1 kg（重力 9.81 N）。\n'
  + '先に持ち上がるのは動滑車の荷。定滑車の荷は\n'
  + 'その倍ちかく引かないと床から離れない。';
  demoTitle(p.x, p.y, '滑車・動滑車');
  demoNote (p.x, p.y + 54, NOTE);
  const SIGN_Y = demoNoteBelow(p.y + 54, NOTE);
  const sign = (x, head, body) => {
    annotations.push(new Annotation({ type:'text', x, y:SIGN_Y, text:head,
                                      size:22, bold:true, color:'#4fc3f7' }));
    annotations.push(new Annotation({ type:'text', x, y:SIGN_Y + 33, text:body,
                                      size:18, color:'#cfd8dc' }));
  };
  // ── 天井 ─────────────────────────────────────────
  const ceil = new Body(Object.assign({
    type:'box', x:-40, y:CEIL_Y, w:980, h:24, isStatic:true, mass:0,
    fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'天井（固定）' }, slip));
  objects.push(ceil);

  // ── ① 定滑車 ───────────────────────────────────────
  //   縄の向きを変えるだけ。張力は縄のどこでも同じなので、荷を引く力は動力そのまま。
  const P1X = -450;
  hangPulley(ceil, P1X);
  const ld1 = load(P1X - RR, gy - 32);            // 床に置いた状態から始める
  const hd1 = hand(P1X + RR, gy - 440);
  objects.push(ld1, hd1);
  const j1 = new Joint(rope({ bodyA:ld1, bodyB:hd1,
                              anchorAx:0, anchorAy:-32, anchorBx:0, anchorBy:-20 }));
  ropeAlongPath(j1, [{ x:P1X - RR, y:gy - 64 },
                     ...pulleyArc(P1X, PY, RR, 180, 0),
                     { x:P1X + RR, y:gy - 460 }]);
  joints.push(j1);
  sign(-720, '① 定滑車（向きを変えるだけ）',
    '引く力がそのまま縄の張力になる。\n'
  + '引く力＋引き手の重さ 0.98 N が荷の\n'
  + '重力 9.81 N を超えるまで上がらない\n'
  + '＝ 引く力 約 8.8 N で床から離れる。');

  // ── ② 動滑車 ───────────────────────────────────────
  //   縄の一端を天井に留め、動滑車の下をくぐらせ、定滑車で向きを変えて引く。
  //   荷は動滑車から縄で吊る＝①とまったく同じ 1kg の箱を、同じように床から持ち上げる。
  const MX = 290, MY = gy - 260;                   // 動滑車の中心
  const AX = MX - RR, BX = MX + RR;                // 左右の縄が通る線
  const FX = BX + RR, HX = FX + RR;                // 定滑車の中心／引き手の線
  hangPulley(ceil, FX);
  const mov = new Body(Object.assign({
    type:'circle', radius:PU_R, x:MX, y:MY, mass:PU_MOV, fixedRotation:true,
    guideEnabled:true, guideAngle:Math.PI/2,
    fillColor:'#ffca28', strokeColor:'#ffe082', strokeWidth:1.5, label:'動滑車' }, slip));
  const ld2 = load(MX, gy - 32);                   // ①と同じ荷。床に置いた状態から始める
  const hd2 = hand(HX, gy - 440);
  objects.push(mov, ld2, hd2);
  // 動滑車の下から荷を吊る縄
  const jl = new Joint(rope({ bodyA:mov, bodyB:ld2,
                              anchorAx:0, anchorAy:PU_R, anchorBx:0, anchorBy:-32 }));
  ropeAlongPath(jl, [{ x:MX, y:MY + PU_R }, { x:MX, y:gy - 64 }]);
  joints.push(jl);
  // 天井 → 動滑車の下 → 定滑車の上 → 引き手
  const j2 = new Joint(rope({ bodyA:ceil, bodyB:hd2,
                              anchorAx:AX - ceil.x, anchorAy:12, anchorBx:0, anchorBy:-20 }));
  ropeAlongPath(j2, [{ x:AX, y:CEIL_B }, { x:AX, y:MY },
                     ...pulleyArc(MX, MY, RR, 180, 360),
                     { x:BX, y:PY },
                     ...pulleyArc(FX, PY, RR, 180, 0),
                     { x:HX, y:gy - 460 }]);
  joints.push(j2);
  sign(60, '② 動滑車（力が半分で済む）',
    '荷は同じ縄の2本で支えられるので、\n'
  + '2 ×（引く力 ＋ 0.98）が荷と動滑車の\n'
  + '重さ 10.8 N を超えれば上がる\n'
  + '＝ 引く力 約 4.4 N で持ち上がる。');
  // ── 引く力のつまみ（リモコン）─────────────────────────────
  //   ★1つの窓に左右2本の動力をつなぐ＝つまみ1本で、両方の引き手に同じ力を入れる
  //     （冒頭の★。範囲 0〜PU_FMAX）。
  //   ★窓は①と②のちょうど真ん中の下（ワールドで x≈−80。①の引き手の縄 x≈−410 と
  //     ②の天井側の縄 x≈250 の中点）。左下（既定の場所）だと①の荷（床の上）に重なり、
  //     0.285 に寄せた版は①の引き手が床へ落ちてくる所（窓の左端のすぐ外）に掛かった（実測）。
  //   ★本文は5行まで。6行にすると下に並ぶ立て札が天井の帯に食い込む（実測）。
  const rem = addRemote('prop', hd1.thrusters[0], 'thruster',
                        [hd1.thrusters[0].id, hd2.thrusters[0].id]);
  if (rem) {
    rem.kind = 'prop'; rem.prop = 'force'; rem.lo = 0; rem.hi = PU_FMAX;
    rem.fx = 0.37; rem.fy = 0.62;
    placeRemotePanel(rem); syncRemotePanel(rem);
  }
}

// ── 摩擦力（静止摩擦 → 最大静止摩擦 → 動摩擦）───────────────────────
//   ★このデモの主張は「静止摩擦は決まった大きさを持たない」。引く力とつり合うだけの
//     大きさが出てきて、上限（最大静止摩擦 μs N）に届いた瞬間に動き出し、そこから先は
//     引く力によらない一定値（動摩擦 μk N）に落ちる。
//   ★エンジンはこの区別を持っている（js/core/geometry.js の frictionCoef）。
//     必要な接線力が jn·μs 以下なら μs、超えたら μk へ切り替わる ＝ 教科書の図そのもの。
//     デモ側で場合分けをしていないことが大事なので、係数を2つ与えるだけにしてある。
//   ★箱は1つだけ置き、引く力はつまみ（リモコン）で 0 から上げていく。以前は同じ箱を
//     5つ並べて引く力だけを変えていたが、並べる形では原理的に出せないものが2つある：
//     　・同じ箱の上で、黄色い矢印が橙色に合わせて伸び、上限で動摩擦へ「落ちる」瞬間
//     　・下げ戻したときの履歴。動き出した箱は 5.88 N を割るまで止まらず、止めたあと
//     　　もう一度動かすにはまた 9.81 N 要る ＝「動かし始めのほうが重い」
//     並べる形の利点だった「一時停止のままでも矢印がそろって出る」は、つまみを回すのが
//     実行中の操作なので要らなくなった（解いた値がそのまま毎 tick 出る）。
//   ★つまみの範囲は 0〜12 N。remotePropTicks が範囲を 200 等分するので 0.06 N 刻みになり、
//     上限 9.81 N をまたぐ 9.8 と 9.9 を打ち分けられる（表の既定 0〜500 N のままだと
//     2.5 N 刻みで、またぐ瞬間が飛ぶ）。
//   ★下限は 0 にする。「引いていない」状態へいつでも戻せることが要る（動き出した箱を
//     止めるのも、履歴を見るのも、つまみを下げる操作でやる）。
//   ★摩擦の矢印は「引く力とぴったり同じ長さ」で伸びていくのが読みどころなので、
//     地面側の係数は 1.0 にして箱側の値がそのまま効くようにする（合成は積）。
//   ★μs=0.5 / μk=0.3 は「金属」（0.55/0.4）と「木材」（0.7/0.6）の中間あたりで、
//     比 μk/μs=0.6 は矢印の長さの差（画面 88px → 53px）が目で分かる開き。
//   ★μs はこれ以上は上げられない。引く力は重心の高さに掛かるので、箱が傾き出す力は
//     F_tip = mg·W/H（垂直抗力の作用点が底面の端まで寄る力）＝ 箱の縦横比だけで決まる。
//     すべり出す力 μs·N がこれを超えると、箱はすべる前に前へ倒れる ⇔ μs > W/H = 0.81。
//     実測：μs=0.9 にすると 15.95 N で傾き 90°（＝転倒）、すべり出しには届かなかった。
//     いまの 0.5 は 9.81 N ですべり出し、F_tip = 15.9 N まで 6 割の余裕がある。
const FRI_M    = 2;     // [kg] 箱。重力 19.6 N ＝ 垂直抗力 N
const FRI_MUS  = 0.5;   // 静止摩擦係数 → 最大静止摩擦 μs·N = 9.81 N
const FRI_MUK  = 0.3;   // 動摩擦係数   → 動摩擦     μk·N = 5.88 N
const FRI_FMAX = 12;    // [N] つまみの上限（上の★）
const FRI_X    = 40;    // [px] 箱の置き場所（下の★。つまみの窓の右、走る余地のある側）
//   ★箱・矢印・札は「1つの装置」としてまとめて FRI_K 倍する。箱だけ大きくすると、
//     このデモの主役である矢印（黄と橙が同じ長さ／上限で黄が落ちる）が箱に対して
//     細く短くなり、かえって読みにくい。倍率で寄る手もあるが、それだと本文まで
//     一緒に拡大され、幅 500px の置き場所の予算が崩れる（デモ共通の約束）。
//     ＝ 世界の側の寸法だけを揃えて大きくし、カメラと本文はそのままにする。
const FRI_K = 1.8;      // 装置全体の拡大率（下の各★の数値はすべて FRI_K 倍したあとの値）
const FRI_W = 130 * FRI_K, FRI_H = 160 * FRI_K;   // [px] 箱の大きさ（2.34 × 2.88 m）
//   ★縦横比 130:160 は変えない。すべり出す前に倒れない条件 μs < W/H = 0.81 が
//     これだけで決まっているため（上の★）。拡大しても比が同じなら余裕も同じ
//     （実測：F_tip は拡大前後とも 15.94 N）。
//   ★背が高いのは、重心から下向きに伸びる重力の矢印が箱の下へはみ出す量を減らすため。
//     ★矢印は画面px・箱は世界px なので、はみ出す量は拡大で相殺されない：
//       19.6·forceVizScale − (H/2)·zoom で、拡大前 98−40 = 58px、いま 177−72 = 105px。
//       ＝ 装置を大きくすると赤い矢印だけは地面の帯へ深く刺さる（実測。目盛りの数字の
//       列を縦に横切るが、どのパネルにも掛からず画面の下端までは 43px 残る）。
//       ここを詰めたいなら FRI_K を下げるより、縦横比を 130:160 から縦長へ寄せること
//       （倒れる余裕を食うので、μs·N ＜ F_tip = mg·W/H を必ず確かめる）。
function demoFrictionThreshold() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;      // ★眠ると拘束力の矢印が消える（いろいろな力のデモの★）
  // ★[画面px per N]。箱と同じ FRI_K 倍で伸ばす＝装置ごと大きくなる（箱の★）。
  //   重力 19.6 N が 177px、最大静止摩擦 9.81 N が 88px、動摩擦 5.88 N が 53px。
  //   ★横向きの矢印は箱の外へ出ていないと読めない。箱の半幅は画面 58px なので、
  //     88px なら 30px はみ出す。ここを 5 のままにすると矢印は 49px ＝ 半幅より短く、
  //     黄と橙が箱の中に隠れてこのデモの読みどころが消える（だから箱と一緒に伸ばす）。
  world.forceVizScale = 5 * FRI_K;
  // ★既定の4でよい。ここは以前 16 にしてあった（「止まっている箱の這いを抑える」）が、
  //   這いの原因は接触ソルバが速度だけを消して位置のずれを戻していなかったことで、
  //   collision.js の correctContactTangentialDrift で直した。実測（当時の5つ並べ）：
  //   substeps 4 と 16 で結果は同じ（1/1/1/1/25661px と 1/1/1/1/25572px）で、4 が 3倍速い。
  //   ★つまみにした今も確かめた：9.8 N（上限 9.807 N のすぐ下）を 5 秒かけても動いた距離
  //   0.000 m・静止率 0.96、動き出すのは 9.85 N から。刻み 4 のままで境目が濁らない
  //   （静止率は箱を大きくする前は 0.99 だった。動いた距離は前後とも 0.000 m）。
  updateGroundTerrain(true);
  ground.friction = 1; ground.frictionStatic = 1;   // ★合成は積。箱側の値がそのまま効く
  // ★箱は画面 x 366〜483 に置く。左うえの本文（幅500px）は上半分で終わるので下では
  //   ぶつからず、つまみの窓（画面 x 56〜225）の右で、右へ 10.3 m 走る余地がある位置。
  //   （箱を大きくして左右へ 26px ずつ広がったので、走る余地は 10.8 → 10.3 m に減った）
  setDemoCam(190, 0.5);
  // ★回転は止めない（力の矢印を出す物体には付けない。ファイル冒頭の★）。
  //   引く力は重心の高さに掛ける＝底面の摩擦との偶力が最小になり、箱は傾かない。
  //   止まっているあいだ摩擦は引く力 F と同じ大きさなので、垂直抗力の作用点は
  //   d = F·(H/2)/mg だけ前へ寄る。すべり出す 9.81 N でも d = 0.72 m ＜ 半幅 1.17 m。
  //   すべり出したあとは摩擦が μk·N = 5.88 N に落ちるので d = 0.43 m まで戻る
  //   （＝つまみを上限まで一気に上げても倒れない。実測の傾き 0°）。
  //   ★この余裕は箱を大きくしても変わらない。d/半幅 = μs·H/W ＝ 縦横比だけで決まるため
  const box = new Body({ type:'box', x:FRI_X, y: gy - FRI_H/2, w:FRI_W, h:FRI_H, mass:FRI_M,
    friction:FRI_MUK, frictionStatic:FRI_MUS, restitution:0,
    thrusters:[{ force:0, dir:0 }],               // 右向きに引く。大きさはつまみで決める
    showForces:true, label:'2 kg',
    fillColor:'#5c6bc0', strokeColor:'#c5cae9', strokeWidth:2 });
  objects.push(box);
  // ★止めたまま矢印を出すための空回し（demo-kit の★）。F = 0 で開くので箱は動かず、
  //   開いた時点で重力（赤）と垂直抗力（青）がつり合って出ている。
  demoWarmForces(30);
  // ── 引く力のつまみ ───────────────────────────────────
  //   ★このデモの操作はこれ1つ。窓は左下（addRemote の既定の積み場所）で、本文の下・
  //     箱の左。範囲の理由はファイル冒頭の★（0〜12 N ＝ 0.06 N 刻み）。
  const knob = addRemote('prop', box.thrusters[0], 'thruster');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'force'; knob.lo = 0; knob.hi = FRI_FMAX;
    knob.fx = 0.055; knob.fy = 0.62;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  // ── すべり出した瞬間に止めるプログラム ─────────────────────────
  //   ★静止摩擦 → 動摩擦 の切り替わりは実行中の一瞬で過ぎる。「速さが 0.1 m/s 以上に
  //     なったら → 実行を止める」を箱につなぎ、すべり出した直後で画面を止める。
  //     止まった画面で、つまみの値（μs·N をわずかに超えた値）と、縮んだ黄色の矢印
  //     （μk·N）を並べて読める。止めている間も矢印の平滑化は回るので、黄色は 5.88 N へ落ち着く。
  //   ★速さのきっかけは「範囲に入った瞬間」だけ発火する（program.js の speed の★）。
  //     箱は速さ 0 で開くので ▶ の直後には発火しない。止まった箱をもう一度動かしたときにも
  //     また止まる（【もう一手】の「動かし始めのほうが重い」もそこで読める）。
  //   ★下限は 0.1 m/s。すべっているかどうかは FRICTION_SLIP_V（0.05 m/s。geometry.js）で
  //     決まり、それ以下では μs·N のまま這うように加速する。0.01 にすると這っている最中に
  //     止まり、黄色は 9.81 N のまま（実測）＝切り替わる前の画になる。
  //     0.1 なら止まった tick の摩擦は 5.88 N、引く力は 10.14 N（つまみを 0.06 N ずつ
  //     5 tick おきに上げたとき）／10.56 N（毎 tick 上げたとき）、動いた距離は 7mm／5mm（実測）。
  const pg = addProgram(box);
  if (pg) {
    pg.trigger = 'speed'; pg.spdMin = 0.1; pg.spdMax = 100; pg.action = 'pause';
    pg.collapsed = true; pg.fx = 0.055; pg.fy = 0.55;
    pg.reset(); syncProgramState(pg); syncProgramPanel(pg); placeProgramPanel(pg);
  }
  // 立て札は箱の上。★矢印（重力は下・引く力と摩擦は横）とぶつからない場所はここだけ。
  //   ★左端は箱の右端より右にする。箱を大きくしたぶん札も上へ動くので、箱の真上に
  //     置くと縦の目盛り（世界の x=0 の線）の数字の列に入り込む（実測：拡大前は
  //     「3m」の札と 17px 空いていたが、拡大後は「4.5m」の上に重なった）。
  //     箱の右へ出せば数字の列より右になり、上下どこへ動いてもぶつからない。
  annotations.push(new Annotation({ type:'text', x:FRI_X + FRI_W/2 + 60, y: gy - FRI_H - 190,
    text:'最大静止摩擦 μs·N = 9.81 N\n動摩擦　　　 μk·N = 5.88 N', size:20, bold:true,
    color:'#cfd8dc' }));
  // ★グラフは加速度Xを出す。動き出す前は 0、動き出したあとは (F − 5.88)/2 ＝ つまみを
  //   上げたぶんだけ増える。摩擦が「引く力によらない一定値」であることの数の裏づけ。
  moveDemoGraphTop(velGraphNew(box, { showPos:false, showVel:true, showAcc:true,
                                      showX:true, showY:false, showMag:false }));
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '摩擦力（静止摩擦と動摩擦）');
  demoNote (p.x, p.y + 54,
    '箱は 2 kg・μs = 0.5・μk = 0.3。垂直抗力は N = mg = 19.6 N。\n'
  + '矢印の色： 重力＝赤　垂直抗力＝青　摩擦＝黄　引く力＝橙\n'
  + '\n'
  + '【手順】▶実行 を押し、左下のつまみで「引く力」を 0 から少しずつ上げる\n'
  + '・箱が止まっているあいだ、黄色い矢印（摩擦）は橙色の矢印（引く力）と\n'
  + '　　ぴったり同じ長さで伸びる。静止摩擦は決まった大きさを持たず、\n'
  + '　　「動かないために必要なだけ」出てくる（つり合っているので合力は 0）\n'
  + '・出せる上限が最大静止摩擦 μs·N（箱の上の札）。そこを超えると動き出し、\n'
  + '　　黄色い矢印は動摩擦 μk·N まで縮む。ここから先はいくら引いても摩擦は増えない\n'
  + '　　（すべり出すと自動で一時停止する＝左のプログラム。読んだら ▶ で続きへ）\n'
  + '・余った力がそのまま加速に回る。引く力を上げたぶんだけ加速度が増えるのが\n'
  + '　　右うえのグラフ（加速度X）で見える。摩擦のほうは増えない\n'
  + '\n'
  + '【もう一手】一時停止したところでつまみを下げ、▶ で続ける\n'
  + '・少し下げたくらいではまだ加速し続ける。動摩擦 μk·N を割ってはじめて減速し、\n'
  + '　　やがて止まる\n'
  + '・止まった箱をもう一度動かすには、また最大静止摩擦まで上げなければならない\n'
  + '　　＝ 動かし始めのほうが重い。これが μk < μs ということ\n'
  + '　　（右へ走り去ったら、上の ↺ステップリセット で最初の位置に戻せる）');
}

// ════════════════════════════════════════
//  力学 ▸ いろいろな力 ▸ 浮力
// ════════════════════════════════════════
//   ★コップの水に、密度だけが違う同じ大きさのブロックを落とす。浮くか沈むかは
//     「水より軽い物質でできているか」だけで決まる＝重さでも大きさでもない、を見せる。
//   ★浮力は式で与えていない。水は SPH の粒子（js/physics/particles.js）で、粒子が
//     物体を押す力の合計がそのまま浮力になる（二方向連成）。だから沈み具合も
//     こちらで指定していない。実測で密度の比とほぼ一致することを確かめてある
//     （2026-09-27、水面の見積もりを直したあと。tools/measure-buoyancy.js）：
//       密度  200 → 22.2% ／ 400 → 41.3% ／ 600 → 61.2% ／ 800 → 81.5%
//       密度 1000 → 97.9%（水中に漂う＝中性浮力）／ 1200・1500 → 100%
//       （同じ日に重力の積分も直したあとの値。body.js の integrate の★）
//     （箱1個ずつ・900tick 落ち着かせたあと 400tick の時間平均。水面はブロックから離れた
//       列ごとの最上点の平均で測る。1tick 読みだと水面が σ3〜7px 波打っていて結論が暴れる）
//     このデモの3つ同時は 39.9% / 97.8% / 100%（理論 40/100/100）、コップの外へ出た
//     粒子は 0 個。重力を直す前は密度400 だけ 34.9% と浮いていた（particles.js _buoyancy の☆）。
//     ☆直す前は 71.1% / 100% / 100% で、下の「26%→29%」の頃とも向きが逆になっていた。
//     ☆壁の鏡像（particles.js の _measureWalls）を入れてから理論値へ寄った。
//       それまでは 26% / 78% / 100% で、とくに「水と同じ密度」が 78% と浮きすぎていた
//       （理論は 100%＝ちょうど中性浮力）。壁ぎわの水が毎tick震えていたぶん、
//       物体を下から叩く力が過大に出ていたためである。揺れも収まった
//       （ブロックの y のばらつき σ 1.67→1.10px）。
//   ★粒子の間隔は 11.2px。PARTICLE_TYPES.fluid.restArea = 126px² の平方根で、
//     静止時に1粒子が占める面積からくる値。これより詰めて置くと初期の圧力で弾ける。
const BU_IW    = 240;   // [px] コップの内半幅
const BU_IH    = 260;   // [px] 内側の高さ
const BU_T     = 22;    // [px] 肉厚
const BU_WATER = 170;   // [px] 水深（1.7 m）。上に 90px の余裕＝落とした飛沫が外へ出ない
const BU_W     = 76;    // [px] ブロックの幅
const BU_H     = 40;    // [px] ブロックの高さ。★平たくする：立方体だと密度 400 の木が
                        //   45°傾いた姿で安定してしまい（低密度の角柱は斜めが安定な向き）、
                        //   沈み具合が読めなくなった。平たい板なら水平のまま浮く
const BU_STEP  = 11.2;  // [px] 粒子の間隔（restArea = 126px² の平方根）
function demoBuoyancy() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;
  updateGroundTerrain(true);
  // ── コップ（U字の静的ポリゴン。原点は内底の中心）───────────────────
  objects.push(new Body({
    type:'polygon', x:0, y:gy - BU_T, isStatic:true, mass:0,
    friction:0.4, frictionStatic:0.5, restitution:0,
    verts:[{ x:-(BU_IW+BU_T), y:-BU_IH }, { x:-BU_IW, y:-BU_IH }, { x:-BU_IW, y:0 },
           { x:BU_IW, y:0 }, { x:BU_IW, y:-BU_IH }, { x:(BU_IW+BU_T), y:-BU_IH },
           { x:(BU_IW+BU_T), y:BU_T }, { x:-(BU_IW+BU_T), y:BU_T }],
    fillColor:'#37474f', strokeColor:'#b0bec5', strokeWidth:2.5, label:'コップ' }));
  // ── 水（粒子を格子で流し込む）──────────────────────────────
  const floorY = gy - BU_T;
  for (let y = floorY - BU_STEP*0.5; y > floorY - BU_WATER; y -= BU_STEP)
    for (let x = -BU_IW + BU_STEP*0.6; x < BU_IW - BU_STEP*0.6; x += BU_STEP)
      particles.push(new Particle(x, y, 'fluid'));
  // ── 密度だけが違う3つのブロック ────────────────────────────
  //   ★大きさは全部同じ。違うのは密度だけ＝重さの違いは密度の違いそのもの。
  //   ★fixedRotation にはしない（傾いて浮くのも浮力の姿）。
  const CUBES = [
    { d:400,  x:-150, fill:'#8d6e63', stroke:'#d7ccc8', name:'木' },
    { d:1000, x:   0, fill:'#4dd0e1', stroke:'#b2ebf2', name:'水と同じ' },
    { d:2000, x: 150, fill:'#546e7a', stroke:'#cfd8dc', name:'石' },
  ];
  const made = [];
  for (const c of CUBES) {
    const b = new Body({
      type:'box', w:BU_W, h:BU_H, x:c.x, y:floorY - BU_WATER - 90, density:c.d,
      friction:0.3, frictionStatic:0.4, restitution:0,
      fillColor:c.fill, strokeColor:c.stroke, strokeWidth:1.5,
      label:c.name + ' ' + c.d });
    b.setMass(b.massFromDensity());     // ★密度から質量を出し直す（既定は木材相当の 600）
    objects.push(b);
    made.push(b);
  }
  // ── 木の密度のつまみ ─────────────────────────────────────
  //   ★3つを見くらべたあと、1つの物体の密度だけを連続して変えて「沈む割合 ＝ ρ/ρ水」を
  //     手で追う。つなぐのは木（浮いている＝変化がいちばん見える）。書き込みは右パネルの
  //     密度と同じ applyBodyProp（質量＝密度×面積×奥行き を出し直す）。
  //   ★範囲は 100〜2100 kg/m³。リモコンは範囲を 200 等分する（remotePropTicks）ので
  //     ちょうど 10 kg/m³ 刻みになり、400・1000 などの切りのよい値に止まる。
  //   ★落ち着いた水の中で密度を変えても、落として測った値（冒頭の★）と同じ所へ落ち着く。
  //     実測（tools/measure-buoyancy.js knob。1段ごとに 600tick 待って 400tick の時間平均）：
  //       上り 200→18.9% ／ 400→39.1% ／ 600→64.3% ／ 800→83.7% ／ 1000→99.5% ／ 1200→100%
  //       下り 800→77.1% ／ 400→39.5%（1200 で底へ沈めたあとでも、下げれば浮き上がって戻る）
  //     理論とのずれは平均 1.7 ポイント・最大 4.3 ポイント。木の y の揺れは σ 0.3〜1.0px。
  //     ★時間平均で読むこと。1 tick で読むと水面の波で数ポイント〜十数ポイント暴れる（CLAUDE.md）。
  const knob = addRemote('prop', made[0], 'body');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'density'; knob.lo = 100; knob.hi = 2100;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  // ── 説明 ─────────────────────────────────────────
  setDemoCam(0, 0.75);       // コップ（幅 5.1m）と落とす高さが収まる倍率
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '浮力');
  demoNote (p.x, p.y + 54,
    'コップの水へ、大きさが同じで密度だけ違う\n'
  + '3つのブロックを落とす。水の密度は 1000 kg/m³。\n'
  + '\n'
  + '【手順】▶実行 を押す。\n'
  + '・木 400：水より軽い → 大きく水面から出て浮く\n'
  + '・水と同じ 1000：水中に漂う（浮きも沈みもしない）\n'
  + '・石 2000：水より重い → 底まで沈む\n'
  + '\n'
  + '【もう一手】左下のつまみで木の密度を変える\n'
  + '・重くするほど深く沈む（沈む割合 ＝ 密度 ÷ 1000）\n'
  + '・1000 を超えると底へ。下げればまた浮いてくる\n'
  + '\n'
  + '浮力は式で与えていない。水の粒子が物体を押す\n'
  + '力の合計がそのまま浮力になっている。');
}

// ════════════════════════════════════════
//  力学 ▸ 力学的エネルギー保存 ▸ 位置 → 運動 → ばね
// ════════════════════════════════════════
//   ★高いところから滑り降り（位置→運動）、水平面を走り、ばねを縮めて（運動→弾性）、
//     押し返されて同じ高さまで戻る。摩擦は 0 なので、3つの形の合計が一定に保たれる。
//   ★走路の高さは「水平面を走る間の物体の中心が y=0 を通る」ように決める（関数の先頭の★）。
//     位置エネルギーの基準は原点を通る水平面なので、こうすると走っている間の
//     位置エネルギーがちょうど 0 になり、グラフが読みやすい。
//   ★滑る物体は円にして回転を止める（fixedRotation）。四角い箱を回転オフのまま斜面に置くと
//     角の1点でしか当たらず、姿勢が斜面と合わない。円なら接触は常に1点で法線が中心を通り、
//     曲がった面の上でも姿勢の問題が起きない＝教科書の「なめらかな面を滑る物体」そのもの。
//   ★斜面と地面のつなぎは円弧（フィレット）で、しかもその区間を「真円」として解かせる
//     （detectArcs／js/physics/arc.js）。多角形のままだと継ぎ目ごとに法線が折れ、
//     そのたびに速度の面直成分が吸われて sin²(折れ角) ぶんの運動エネルギーが消える。
//     実測（1往復して戻る高さ。出発点を100%）：
//       角のまま … 66.9%  ／  円弧・折れ線12分割 … 88.1%  ／  同40分割 … 92.6%
//       円弧を真円として解く … 97.6%
//     片道の損失の内訳（substeps 16）：直線斜面 0.29% ／ 円弧まわり 0.18% ／ 水平面 0.00%。
//     ばねでの損失は 0.25%（うち減衰ぶんが 0.4ポイント相当）で、いちばん大きいのは斜面。
//     1往復して戻る高さは 98.4%（2往復目 97.2%、3往復目 95.9%、4往復目 94.6%）。
//   ★ばねは「壁 ─ ばね ─ 受け板」で、物体は受け板にぶつかるだけ（つながっていない）。
//     つないでしまうと伸びるときに引き戻され、離れて戻っていく動きにならない。
//   ★受け板は地面から浮かせる（下端を 4px 上げる）。地面にちょうど接していると、
//     水平レール（guide）が y を固定しようとするのと地面の接触が毎tick 押し合って、
//     板が止まっているときもずっと細かく震え続けた。
const EN_MASS   = 1;      // [kg] 滑る物体
const EN_R      = 30;     // [px] その半径
const EN_K      = 40;     // [N/m] ばね定数。位置エネルギー 15.7J を 0.89m の縮みで受け止める
const EN_PLATE  = 0.001;  // [kg] 受け板（軽いほど戻る高さが出発点に近づく）
// ★ばねの減衰。0 にすると、物体が離れたあと受け板が鳴り続ける：分離の瞬間に受け板が
//   持っている運動エネルギー ½m·v² が、減衰の無いばねでは永久に往復するため。
//   振幅は A = v√(m/k) なので板を軽くすると小さくなるが、軽くしすぎると数値的に不安定
//   （ω=√(k/m) がサブステップの刻みに対して大きくなりすぎる。0.001kg で ω·dt=0.83）。
//   板 0.001kg・substeps 16 での実測（振れ幅／1往復して戻る高さ）：
//     減衰 0 … 5.61px／98.9%   0.005 … 0.26px／98.7%
//     減衰 0.01 … 0.01px／98.4%   0.02 … 0.00px／97.9%
//   0.01 なら板は完全に止まり、戻る高さの代償は 0.5 ポイントで済む。
//   ★接触している間もこの減衰は効く（そのぶんが上の代償）。0 に戻すと保存は良くなるが
//     板が震え続け、板も系に入っているので運動エネルギーのグラフまで波打つ。
const EN_DAMP   = 0.01;   // [N·s/m] ばねの減衰
const EN_FIL_R  = 220;    // [px] 斜面と地面をつなぐ円弧の半径
const EN_FIL_N  = 16;     // 円弧を何本の辺で描くか（当たりは真円なので、これは見た目だけ）
const EN_SLOPE  = 35;     // [deg] 斜面の角度
const EN_H      = 200;    // [px] 斜面のてっぺんの高さ
function demoEnergySpring() {
  // ★走行面は原点より EN_Rpx 下げる。位置エネルギーの基準は「原点を通る水平面」なので、
  //   面を y=0 に置くと、物体の中心が半径ぶん上に来て最下点でも位置エネルギーが 0 に
  //   ならない（実測：1kg・半径30px で 2.94 J 残っていた）。面を半径ぶん下げれば、
  //   水平面を走る間の中心がちょうど y=0 を通る。以下 gy は「走行面の高さ」の意味。
  const gy = ground.y + EN_R;
  // ★刻みを 16 にする。斜面を滑る間に失われるエネルギーは substeps に比例して減る
  //   （実測：直線斜面＋円弧の片道 substeps 4 で 0.97%／8 で 0.63%／16 で 0.47%。
  //     ソルバの反復回数 iterations・positionIterations を増やしても一切変わらないので、
  //     収束の問題ではなく時間の刻みの問題）。1往復して戻る高さは 97.3% → 98.4% になる。
  //   物体4個・関節1個しかないので、刻みを4倍にしても 1tick 0.25→0.60ms（60fps の
  //   予算 16.7ms の 3.6%）で済む。
  resetDemoWorld();
  world.substeps = 16;
  world.sleeping = false;
  // ★世界の地面は使わない。コース1枚で斜面から水平面までを作る。地面を併用すると、
  //   円弧から地面へ乗り移る継ぎ目で 1.1% のエネルギーが消えた（別のコライダーへ
  //   渡るため）。1枚にすれば継ぎ目が無くなり、片道の損失が 1.72% → 0.75% になる。
  updateGroundTerrain(false);
  const slip = { friction:0, frictionStatic:0, restitution:0 };   // ★摩擦0＝力学的エネルギーが保存する条件
  const th = EN_SLOPE * Math.PI / 180;
  const filW = EN_FIL_R * Math.sin(th);          // 円弧の水平の広がり
  const filH = EN_FIL_R * (1 - Math.cos(th));    // 円弧ぶんの高さ
  const runX = (EN_H - filH) / Math.tan(th);     // 直線部分の水平の長さ
  const xA = -650, xB = xA + runX, xC = xB + filW;   // てっぺん／直線の下端／地面に接する点
  // ── 斜面（1枚の静的ポリゴン。上面は 直線 → 円弧、下面は地面の下に埋める）───────
  const top = [{ x:xA, y:gy - EN_H }, { x:xB, y:gy - filH }];
  const cx = xC, cy = gy - EN_FIL_R;             // 円弧の中心（最下点が (xC, gy)＝地面に接する）
  for (let i = 1; i <= EN_FIL_N; i++) {
    const p = th * (1 - i / EN_FIL_N);
    top.push({ x: cx - EN_FIL_R * Math.sin(p), y: cy + EN_FIL_R * Math.cos(p) });
  }
  top.push({ x:600, y:gy });                     // 円弧のあとは水平面（壁の向こうまで）
  const trackVerts = [...top, { x:600, y:gy + 80 }, { x:xA, y:gy + 80 }];
  const track = new Body(Object.assign({
    type:'polygon', x:0, y:0, isStatic:true, mass:0,
    verts: trackVerts, arcs: detectArcs(trackVerts, [], [{ cx, cy, r: EN_FIL_R }]),
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 }, slip));
  // ── 壁とばねと受け板 ────────────────────────────────
  const wallX = 560, REST = 160, PLY = gy - 34;   // 壁の位置／ばねの自然長／ばねの高さ
  const wall = new Body(Object.assign({
    type:'box', x:wallX, y:gy - 60, w:40, h:120, isStatic:true, mass:0,
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 }, slip));
  // ★走路と壁を図形和で1つにする（demo-kit.js の demoUnion）。性質は同じなので合成できる。
  //   壁のラベル「壁」は失う（図形和はラベルも最初の1つに揃えるため）。
  //   ★このデモはエネルギー保存の実測値が上の★に載っているので、合成の前後で測った。
  //     系＝滑る物体＋受け板、乱数固定、900tick の時間平均と最小値：
  //       合成前 力学的E 15.707J・平均比 0.9516・最小比 0.8996・最高到達 y −160.1
  //       合成後 力学的E 15.707J・平均比 0.9515・最小比 0.8993・最高到達 y −160.1
  //     差は平均比 0.01%・最小比 0.03% で、最高到達点は動かない＝円弧は図形和を通っても
  //     復元されている（detectArcs が既存の円弧を種に拾い直す。js/app/clipper.js の★）。
  //     ここが崩れたら detectArcs が円弧を拾えていない＝多角形の角でエネルギーが
  //     削られている（js/physics/arc.js の★。角1つで sin²7.5°≒1.7%）。
  demoUnion([track, wall]);
  const plate = new Body(Object.assign({
    // ★x はばねの取り付け点（板の中心から 8px 右）が自然長になる位置。ここを板の中心で
    //   置くと、開始時点でばねが 8px 縮んだ状態になり、減衰0なので板が永久に振動し続ける
    //   （実測：待機中に 16px 揺れ、水平面での運動エネルギーのグラフが 1.6% 波打った）。
    type:'box', x:wallX - 20 - REST - 8, y:PLY, w:16, h:60, mass:EN_PLATE,
    guideEnabled:true, guideAngle:0,             // 水平のレール（受け板は横にしか動かない）
    fixedRotation:true,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5, label:'受け板' }, slip));
  objects.push(plate);
  demoSpring({
    anchorAx:wallX - 20, anchorAy:PLY, bodyB:plate, anchorBx:8, anchorBy:0,
    restLength:REST, stiffness:EN_K, damping:EN_DAMP,  // ★減衰 0：ばねでエネルギーを捨てない
    radius:14 });
  // ── 滑る物体（斜面の上に置く）──────────────────────────
  //   ★てっぺんぴったりではなく、斜面に沿って 60px 下へ置く（角に乗せない）
  const dirx = Math.cos(th), diry = Math.sin(th);       // 斜面を下る向き
  const nx = diry, ny = -dirx;                          // 面の外向き法線
  const slider = new Body(Object.assign({
    type:'circle', radius:EN_R, mass:EN_MASS,
    x: xA + dirx * 60 + nx * EN_R,
    y: (gy - EN_H) + diry * 60 + ny * EN_R,
    fixedRotation:true,                          // ★回転オフ：転がらずに滑る
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'1kg' }, slip));
  objects.push(slider);
  // ── グラフ ────────────────────────────────────────
  //   ★系は「滑る物体＋受け板」。ばねの弾性エネルギーは両端の動く側が系に入って初めて
  //     数えられる（energy.js の springCounts）ので、受け板を外すと弾性の山が出ない。
  moveDemoGraphTop(eneGraphNew([slider.id, plate.id], {
    showKt:true, showUg:true, showUs:true, showMech:true,
    showKr:false, showUgg:false, showUe:false }));       // 回転・万有引力・静電気は使わない
  // ── 説明 ─────────────────────────────────────────
  setDemoCam(0, 0.65);   // コース（-650〜600px）が左右に余白を残して収まる倍率
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '力学的エネルギー保存');
  demoNote (p.x, p.y + 54,
    '摩擦なし。1 kg の物体が高さ 1.6 m から滑り出す。\n'
  + '\n'
  + '【手順】▶実行 を押して、右うえのグラフを見る\n'
  + '・位置エネルギー（緑）が減り、運動エネルギー（青）が増える\n'
  + '・ばねに当たると運動が弾性エネルギー（橙）へ移る\n'
  + '・押し返されて逆再生のように戻り、同じ高さまで上がる\n'
  + '・合計（黄）は平ら＝力学的エネルギーは保存している\n'
  + '\n'
  + '走路は、水平面を走る間の物体の中心が高さ 0 を通るように\n'
  + '置いてある。だから走っている間の位置エネルギーは 0。');
}

// ════════════════════════════════════════
//  力学 ▸ 力学的エネルギー保存 ▸ 位置 → 位置 + 運動
// ════════════════════════════════════════
//   ★同じ「位置エネルギーが運動エネルギーに変わる」話でも、こちらは戻ってこない。
//     高いところから滑り降りてジャンプ台から斜めに飛び出すと、いちばん高く上がった点でも
//     横向きには動いたままなので、そのぶんの運動エネルギーが位置エネルギーに戻らない。
//     ＝ 最初の高さには届かない。力学的エネルギーは減っていない（位置と運動に分かれただけ）。
//   ★飛び出し角 40°・出発 3.0m・踏切 0.5m。実測（物体の中心の高さで測る）：
//       出発 2.49m（E=24.40 J はすべて位置）→ 最高点 1.26m ＝ 最初の高さの 51%
//       最高点での内訳 位置 12.39 J（51%）／運動 11.72 J（49%）、合計は出発時の 99.0%
//     最高点でも横向きに 4.84 m/s で動いていて、その運動エネルギーは位置に戻らない。
//     角度を上げるほど高く上がるが、真上（90°）にしない限り必ず届かない、が要点。
//   ★着地でエネルギーが段になって落ちるのは本当（反発0の非弾性衝突で、下向きの
//     運動エネルギーがそこで失われる）。隠さずに説明文へ書いてある。
//   ★摩擦は 0、滑る物体は円＋回転オフ。斜面と水平面のつなぎも踏切も円弧にして、
//     その区間を真円として解かせる（detectArcs／js/physics/arc.js）。
//     多角形のままだと継ぎ目ごとに速度の面直成分が吸われる。
//   ★substeps は 16。斜面で失うエネルギーは刻みに反比例する（位置→運動→ばね の★を参照）。
const JP_MASS  = 1;      // [kg] 滑る物体
const JP_R     = 30;     // [px] その半径
const JP_H     = 300;    // [px] 出発の高さ（3.0 m）
const JP_SLOPE = 45;     // [deg] 斜面の角度。★35°だと斜面が左へ 107px 長く張り出し、
                         //   装置を左へ寄せると出発点が画面から切れた（軌跡をグラフ窓から
                         //   逃がすために左へ寄せる必要がある）。角度を変えても飛び方は
                         //   変わらない（飛び出しの速さは踏切までの落差だけで決まる）
const JP_FIL_R = 220;    // [px] 斜面と水平面をつなぐ円弧の半径
const JP_TAKE  = 40;     // [deg] 飛び出し角
const JP_TK_R  = 214;    // [px] 踏切の円弧の半径。R(1-cos40°) = 50px＝踏切の高さ 0.5m
const JP_RUNOUT = 12000; // [px] 着地後の走路の長さ（120 m）。★摩擦0で減速しないので、
                         //   見ている間に端へ届かない長さが要る（40m だと 8 秒で落ちた）
const JP_ARC_N = 16;     // 円弧を何本の辺で描くか（当たりは真円なので、これは見た目だけ）
function demoJumpHill() {
  // ★走行面は原点より JP_Rpx 下げる。位置エネルギーの基準は「原点を通る水平面」なので、
  //   面を y=0 に置くと、物体の中心が半径ぶん上に来て最下点でも位置エネルギーが 0 に
  //   ならない（実測：1kg・半径30px で 2.94 J 残っていた）。面を半径ぶん下げれば、
  //   水平面を走る間の中心がちょうど y=0 を通る。以下 gy は「走行面の高さ」の意味。
  const gy = ground.y + JP_R;
  resetDemoWorld();
  world.substeps = 16;
  world.sleeping = false;
  updateGroundTerrain(false);        // ★コース1枚で作る（別コライダーへの継ぎ目を作らない）
  const slip = { friction:0, frictionStatic:0, restitution:0 };
  const th = JP_SLOPE * Math.PI / 180, tk = JP_TAKE * Math.PI / 180;
  const filW = JP_FIL_R * Math.sin(th), filH = JP_FIL_R * (1 - Math.cos(th));
  const runX = (JP_H - filH) / Math.tan(th);
  // ★水平面の始まり xC を基準にして、斜面のてっぺん xA を逆算する。こうすると角度を
  //   変えても踏切から先（＝飛び方）はまったく動かず、左の張り出しだけが変わる。
  const xC = -202, xB = xC - filW, xA = xB - runX;      // 水平面の始まり／直線の下端／てっぺん
  const xT = 100;                                       // 踏切の始まり（ここから登り）
  const lipX = xT + JP_TK_R * Math.sin(tk);             // 飛び出す縁
  const lipY = gy - JP_TK_R * (1 - Math.cos(tk));
  // ── コース（1枚の静的ポリゴン）────────────────────────────
  const top = [{ x:xA, y:gy - JP_H }, { x:xB, y:gy - filH }];
  const c1x = xC, c1y = gy - JP_FIL_R;                  // 斜面→水平面の円弧の中心
  for (let i = 1; i <= JP_ARC_N; i++) {
    const p = th * (1 - i / JP_ARC_N);
    top.push({ x: c1x - JP_FIL_R * Math.sin(p), y: c1y + JP_FIL_R * Math.cos(p) });
  }
  const c2x = xT, c2y = gy - JP_TK_R;                   // 踏切の円弧の中心
  for (let i = 1; i <= JP_ARC_N; i++) {
    const p = tk * (i / JP_ARC_N);
    top.push({ x: c2x + JP_TK_R * Math.sin(p), y: c2y + JP_TK_R * Math.cos(p) });
  }
  top.push({ x:lipX, y:gy });                           // 踏切の裏（垂直に切り落とす）
  // 着地する水平面。★摩擦0なので着地したあと 5 m/s で走り続ける。端で切ると、そこから
  //   落ちてグラフが発散する（実測：x=1200 で切ったら 4.5 秒後に落下して ±370J まで振り切れた）。
  //   画面（右端 x≒1000）のはるか先まで伸ばして、見ている間に端へ届かないようにする。
  top.push({ x:JP_RUNOUT, y:gy });
  top.push({ x:JP_RUNOUT, y:gy - 200 });                // ★走路の突き当たりの壁（画面外）。
  //   これが無いと端から落ちて、位置エネルギーが下限なく減りグラフが振り切れる
  const verts = [...top, { x:JP_RUNOUT + 40, y:gy - 200 }, { x:JP_RUNOUT + 40, y:gy + 80 }, { x:xA, y:gy + 80 }];
  objects.push(new Body(Object.assign({
    type:'polygon', x:0, y:0, isStatic:true, mass:0, verts,
    arcs: detectArcs(verts, [], [{ cx:c1x, cy:c1y, r:JP_FIL_R }, { cx:c2x, cy:c2y, r:JP_TK_R }]),
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 }, slip)));
  // ── 滑る物体 ────────────────────────────────────
  const dirx = Math.cos(th), diry = Math.sin(th), nx = diry, ny = -dirx;
  const slider = new Body(Object.assign({
    type:'circle', radius:JP_R, mass:JP_MASS,
    x: xA + dirx * 60 + nx * JP_R,
    y: (gy - JP_H) + diry * 60 + ny * JP_R,
    fixedRotation:true,                                 // ★回転オフ：転がらずに滑る
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'1kg' }, slip));
  objects.push(slider);
  slider.tracerEnabled  = true;                         // 飛んだ跡を残す（届かないことが一目で分かる）
  slider.tracerColor    = '#4dd0e1';
  slider.tracerDuration = 12;
  // ── 「最初の高さ」の線 ───────────────────────────────
  //   ★物体の中心の高さで引く（面の高さではなく重心の高さが位置エネルギーを決める）
  const lineY = slider.y;
  // ★太さ5px（倍率 0.5 では画面 2.5px）。3px だと飛んでいるあたりで背景に紛れて見えない
  annotations.push(new Annotation({ type:'path', x:xA, y:lineY, color:'#ffd54f', width:5,
                                    pts:[{ x:0, y:0 }, { x:1620, y:0 }] }));
  annotations.push(new Annotation({ type:'text', x:xA + 20, y:lineY - 40,
                                    text:'最初の高さ', size:26, bold:true, color:'#ffd54f' }));
  // ── グラフ ────────────────────────────────────────
  moveDemoGraphTop(eneGraphNew([slider.id], {
    showKt:true, showUg:true, showUs:false, showMech:true,
    showKr:false, showUgg:false, showUe:false }));
  // ── 説明 ─────────────────────────────────────────
  // ★カメラは装置を左寄せにする。右うえのグラフ窓（画面 x 568〜988・y 56〜506）に
  //   飛んだ軌跡の頂点が入ってしまうため（実測：ずらす前は頂点が画面 680,500 ＝窓の中）。
  setDemoCam(360, 0.5);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '力学的エネルギー保存（位置 → 位置 + 運動）');
  demoNote (p.x, p.y + 54,
    '摩擦なし。1 kg の物体が中心の高さ 2.5 m から滑り出し、\n'
  + '踏切から 40° に飛び出す。\n'
  + '\n'
  + '【手順】▶実行 を押す。\n'
  + '・いちばん高く上がった点でも、黄色い線（最初の高さ）\n'
  + '　には届かない\n'
  + '・そこでも横向きに動いている＝運動エネルギーが残って\n'
  + '　いるから。その分が位置エネルギーに戻らない\n'
  + '・実測：最高点は最初の高さの 51%。内訳は 位置 51% ／ 運動 49%\n'
  + '・グラフの合計（黄）は飛んでいる間ずっと平ら＝減っていない\n'
  + '・着地でぶつかると下向きの運動エネルギーはそこで失われる\n'
  + '　（グラフが段になるのはそのため）');
}

// ════════════════════════════════════════
//  力学 ▸ 力学的エネルギー保存 ▸ ばね → 摩擦 → 位置
// ════════════════════════════════════════
//   ★ばねに押されて走り出し、ざらざらの面で少し減り、なめらかな坂を上って戻ってくる。
//     戻るたびに「ばねの縮み・坂を上る高さ」が小さくなる＝減った分だけ摩擦が奪っている。
//   ★摩擦は面ごとに変える。摩擦は接触する2つの物体の値の積なので、物体側を 0.5 にして
//     ざらざらの面だけ SF_MU（合成 0.075）、なめらかな走路は 0（合成 0）にしてある。
//     ＝ 継ぎ目のない走路1枚の上に、ざらざらの薄い板を重ねる（関数の中の★。突き合わせた
//     3枚にすると継ぎ目で1割強のエネルギーを失っていた）。
//   ★滑る物体は円＋回転オフ。摩擦で転がってしまうと、失われるはずのエネルギーが
//     回転の運動エネルギーとして残り、「摩擦で減った分」が読めなくなる。
//   ★ばねは「壁 ─ ばね ─ 受け板」で、物体は受け板にぶつかるだけ（つながっていない）。
//     つないだままだと自然長を過ぎたところで引き戻され、離れて走っていかない。
//     受け板は 0.001kg・減衰 0.01（位置→運動→ばね の★を参照。0 だと離れたあと鳴り続ける）。
//   ★坂は円弧でつなぎ、その区間を真円として解かせる（detectArcs／js/physics/arc.js）。
const SF_MASS  = 1;      // [kg] 走る物体
const SF_R     = 30;     // [px] その半径
const SF_K     = 40;     // [N/m] ばね定数
const SF_PUSH  = 80;     // [px] 最初の縮み（0.8 m）。弾性エネルギー ½kx² = 12.8 J
const SF_MU    = 0.15;   // ざらざらの面の摩擦係数（物体の 0.5 と掛けて合成 0.075）。
                         //   ★実測（2026-10-01、継ぎ目を直したあと）：坂を 0.94 m → 0.26 m と2回上り、
                         //     10.5 秒で茶色の板の上（x=−3.65 m）で止まる
const SF_MU_MAX = 0.4;   // つまみの上限（合成 0.2）。下の★（つまみ）
                         //   ★0 まで下げた対照（実測）：坂の高さ 1.25→1.20→1.15→1.10… m と往復ごとに
                         //     約 4% ずつしか減らず、60 秒たっても止まらない。残る減りはばねの受け板との
                         //     受け渡し（位置→運動→ばね と同じ 2% ほど）とくさび・円弧のぶん。
                         //     1秒平均の E：μ=0 で 12.43→11.98→11.32 J（5秒ごと）、既定で 11.43→5.61→0.33 J
const SF_ROUGH = [-450, -50];   // [px] ざらざらの面の平らな上面の範囲（長さ 4.0 m）
const SF_TAPER = 40;     // [px] ざらざらの板の両端のくさびの長さ（傾き atan((LIFT+DIP)/TAPER)≈2°）
const SF_LIFT  = 0.5;    // [px] 板の上面が走路より高い量（物体のめり込み 0.1〜0.2px より大きく）
const SF_DIP   = 1;      // [px] くさびの先端を走路の面より沈める量（先端に物体が当たらないように）
const SF_HILL_X0 = -10;  // [px] 坂の円弧が始まる x（右のくさびの先 r1+TAPER と一致させる）
const SF_HILL  = 150;    // [px] 坂のてっぺんの高さ（1.5 m）
const SF_FIL_R = 180;    // [px] 坂の付け根の円弧の半径
const SF_SLOPE = 40;     // [deg] 坂の角度
const SF_ARC_N = 16;     // 円弧を何本の辺で描くか（当たりは真円なので見た目だけ）
function demoSpringFrictionHill() {
  // ★走行面は原点より SF_Rpx 下げる。位置エネルギーの基準は「原点を通る水平面」なので、
  //   面を y=0 に置くと、物体の中心が半径ぶん上に来て最下点でも位置エネルギーが 0 に
  //   ならない（実測：1kg・半径30px で 2.94 J 残っていた）。面を半径ぶん下げれば、
  //   水平面を走る間の中心がちょうど y=0 を通る。以下 gy は「走行面の高さ」の意味。
  const gy = ground.y + SF_R;
  resetDemoWorld();
  world.substeps = 16;   // ★斜面で失うエネルギーは刻みに反比例する（位置→運動→ばね の★）
  world.sleeping = false;
  updateGroundTerrain(false);
  // ── 走路：なめらかな1枚（平ら＋円弧＋坂）と、その上に重ねたざらざらの板 ──────────
  //   ★走路は継ぎ目のない1枚にする。以前は「なめらか／ざらざら／なめらか＋坂」の3枚の
  //     静的物体を突き合わせていたが、高さが同じでも継ぎ目の角に物体が引っかかり、通るたびに
  //     上へ 0.3〜0.7 m/s 弾かれてエネルギーを失っていた（2026-10-01 実測。摩擦を全部 0 に
  //     しても1往復で 1.3〜1.8 J＝1割強。4秒ごとの平均 E：3枚のまま 10.59→8.83→7.43 J、
  //     1枚にまとめると 12.33→12.04→11.77 J）。つまり「茶色の面で段になる」の一部は摩擦では
  //     なく継ぎ目の損失だった。★の「同一平面なので損失はほぼ無い」は誤りだったので消した。
  //   ★ざらざらの面は、走路の上に重ねた薄い板（上面は走路より SF_LIFT だけ高い）。
  //     板の両端は走路の面より下（SF_DIP）から長さ SF_TAPER かけて立ち上がる浅いくさびにして、
  //     物体が角に当たらず乗り移れるようにする（傾き約 2°。損失は sin² で 0.1% ほど）。
  //     板の上では物体は走路から浮くので、摩擦は板の値だけが効く。
  //     ★代わりに、板の上では物体の中心が SF_LIFT ぶん高い＝位置エネルギーが 0.05 J（12.8 J の
  //       0.4%）だけ 0 から浮く。グラフでは読み取れない大きさ。
  const th = SF_SLOPE * Math.PI / 180;
  const xL = -720;
  const filW = SF_FIL_R * Math.sin(th), filH = SF_FIL_R * (1 - Math.cos(th));
  const xC = SF_HILL_X0, cx = xC, cy = gy - SF_FIL_R;
  const top = [{ x:xL, y:gy }, { x:xC, y:gy }];
  for (let i = 1; i <= SF_ARC_N; i++) {
    const p = th * (i / SF_ARC_N);
    top.push({ x: cx + SF_FIL_R * Math.sin(p), y: cy + SF_FIL_R * Math.cos(p) });
  }
  const runX = (SF_HILL - filH) / Math.tan(th);
  top.push({ x: xC + filW + runX, y: gy - SF_HILL });
  const xR = xC + filW + runX + 40;
  const verts = [...top, { x:xR, y:gy - SF_HILL }, { x:xR, y:gy + 80 }, { x:xL, y:gy + 80 }];
  const track = new Body({
    type:'polygon', x:0, y:0, isStatic:true, mass:0, verts,
    arcs: detectArcs(verts, [], [{ cx, cy, r:SF_FIL_R }]),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 });
  // ── 壁・ばね・受け板 ────────────────────────────────
  const wallX = xL + 20, REST = 180, PLY = gy - 34;
  // ★壁は走路と図形和で1つにする（demo-kit.js の demoUnion。円弧は検出し直される）。
  demoUnion([track, new Body({
    type:'box', x:wallX, y:gy - 60, w:40, h:120, isStatic:true, mass:0,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 })]);
  // ざらざらの板（走路より後に置く＝手前に描かれて茶色が見える）
  const [r0, r1] = SF_ROUGH;
  const rough = new Body({
    type:'polygon', x:0, y:0, isStatic:true, mass:0,
    verts:[{ x:r0 - SF_TAPER, y:gy + SF_DIP }, { x:r0, y:gy - SF_LIFT },
           { x:r1, y:gy - SF_LIFT }, { x:r1 + SF_TAPER, y:gy + SF_DIP },
           { x:r1 + SF_TAPER, y:gy + 80 }, { x:r0 - SF_TAPER, y:gy + 80 }],
    friction:SF_MU, frictionStatic:SF_MU * 1.25, restitution:0,
    fillColor:'#6d4c41', strokeColor:'#90a4ae', strokeWidth:2 });
  objects.push(rough);
  const natural = wallX + 20 + REST;                 // ばねが自然長のときの取り付け点
  const plate = new Body({
    type:'box', x:natural - SF_PUSH - 8, y:PLY, w:16, h:60, mass:0.001,
    guideEnabled:true, guideAngle:0, fixedRotation:true,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5, label:'受け板' });
  objects.push(plate);
  demoSpring({
    anchorAx:wallX + 20, anchorAy:PLY, bodyB:plate, anchorBx:8, anchorBy:0,
    restLength:REST, stiffness:SF_K, damping:0.01, radius:14 });
  // ── 走る物体（受け板に押し当てた位置に置く）──────────────────
  const slider = new Body({
    type:'circle', radius:SF_R, x: natural - SF_PUSH + SF_R, y: gy - SF_R, mass:SF_MASS,
    fixedRotation:true,                                // ★回転オフ：転がらずに滑る
    friction:0.5, frictionStatic:0.625, restitution:0,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:'1kg' });
  objects.push(slider);
  // ── ざらざらの面の目印 ───────────────────────────────
  // ★面の上（y = gy+24）へ置くと板の塗りに隠れる。物体（半径30px）の通り道より上へ出す
  annotations.push(new Annotation({ type:'text', x:SF_ROUGH[0] + 20, y:gy - 112,
    text:'ざらざらの面（摩擦あり・4.0 m）', size:22, bold:true, color:'#bcaaa4' }));
  // ── ざらざらの面の摩擦のつまみ ───────────────────────────
  //   ★面の動摩擦係数 μk をつまみにする（物体の 0.5 と掛けたものが効く）。0 まで下げると
  //     合計（黄）の段が消えて平らになる＝減っていたのは摩擦のせい、を対照で確かめられる。
  //     書き込みは applyBodyProp（μs ≧ μk を保つ）。
  const knob = addRemote('prop', rough, 'body');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'friction'; knob.lo = 0; knob.hi = SF_MU_MAX;
    // ★窓は坂の右・グラフの窓の下。左下（既定の場所）だと、ばね・物体・「ざらざらの面」の
    //   札に重なって隠れた（実測）。
    knob.fx = 0.62; knob.fy = 0.72;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  // ── グラフ ────────────────────────────────────────
  moveDemoGraphTop(eneGraphNew([slider.id, plate.id], {
    showKt:true, showUg:true, showUs:true, showMech:true,
    showKr:false, showUgg:false, showUe:false }));
  // ── 説明 ─────────────────────────────────────────
  setDemoCam(125, 0.55);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'ばね → 摩擦 → 位置');
  demoNote (p.x, p.y + 54,
    '1 kg の物体を、ばねを 0.8 m 縮めて押し当ててある。\n'
  + '茶色の面だけ摩擦がある（合成 μ = 0.075・長さ 4.0 m）。\n'
  + '\n'
  + '【手順】▶実行 を押して、右うえのグラフを見る\n'
  + '・弾性（橙）→ 運動（青）→ 位置（緑）と移り変わる\n'
  + '・茶色の面を通るたびに合計（黄）が階段状に下がる\n'
  + '　＝その分を摩擦が熱に変えて系の外へ持ち出している\n'
  + '・坂を上る高さも、ばねの縮みも、往復のたびに小さくなる\n'
  // ★坂の高さは 2026-09-27 に 0.89→0.16 から直し、2026-10-01 に走路の継ぎ目を直して
  //   0.94→0.26 になった。1回目の理論の上限は 1.0 m
  + '　（実測：坂は 0.94 m → 0.26 m。最後は茶色の面の途中で止まり、\n'
  + '　　力学的エネルギーはほぼ 0 になる）\n'
  + '\n'
  + '【もう一手】右下のつまみで茶色の面の摩擦を変える\n'
  + '・0 にすると茶色の面での段が消える ＝ 減っていたのは摩擦のせい\n'
  + '　（それでも往復ごとに少しずつ減るのは、ばねの受け板とのやりとりのぶん）');
}

// ════════════════════════════════════════
//  力学 ▸ 力学的エネルギー保存 ▸ アトウッドの機械（エネルギーの持ち主は系）
// ════════════════════════════════════════
//   ★滑車に掛けた 1.5 kg と 1.0 kg。2つをまとめた「系」の力学的エネルギーは保存するが、
//     片方だけを見ると保存しない（縄の張力がその物体に仕事をするから）。エネルギーの持ち主は
//     物体ではなく系、という見方（CLAUDE.md 第6章）をそのまま2枚のグラフにする。
//       重いほう：張力が上向き・動きは下向き → 負の仕事を受けて減る
//       軽いほう：張力が上向き・動きも上向き → 正の仕事を受けて増える
//       系：縄が両方にする仕事は打ち消し合う（張力は同じ・動く距離も同じ）→ 合計は一定
//   ★滑車は固定した摩擦0の円（静的物体）。縄の張力は joint.js の巻き付きで伝わり、
//     静的な支点は力を受け取っても動かないので、系のエネルギーに出入りしない。
//   ★理論：a = (m1−m2)g/(m1+m2) = 1.96 m/s²、張力 T = 2·m1·m2·g/(m1+m2) = 11.77 N。
//     重いほうが d 下がると、重いほうの E は −T·d、軽いほうは +T·d、系は 0。
//     実測（2026-10-01。0.25 秒ごと）：重いほうの ΔE は −T·d と 0.01 J 以内で一致
//     （1.00 s：d=0.966 m・−11.380 J／理論 −11.372 J）。系は動き出しの数 tick で縄が張るときに
//     0.06 J 減るだけで、そのあとは平ら。床に着くと重いほうの運動 5.85 J が消える。
const AT_M1 = 1.5, AT_M2 = 1.0;   // [kg] 重いほう（左・赤）／軽いほう（右・青）
const AT_R  = 40;                 // [px] 滑車の半径
function demoAtwoodEnergy() {
  const gy = ground.y;
  resetDemoWorld();
  world.substeps = 8;
  world.sleeping = false;
  updateGroundTerrain(true);
  const slip = { friction:0, frictionStatic:0, restitution:0 };
  // ★装置は本文（左うえ）と2枚のグラフ（右）のあいだの下に収める。滑車を gy−620 に置いた版は
  //   天井と縄が本文の行に重なった（実測）。
  const PX = -60, PY = gy - 440;                    // 滑車の中心
  const RR = AT_R + ROPE_CFG.radius;                // 縄の中心線が通る半径
  // 天井と滑車の支柱（見た目）＋ 滑車
  objects.push(new Body(Object.assign({ type:'box', x:PX, y:PY - 90, w:200, h:20,
    isStatic:true, mass:0, fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5,
    label:'天井（固定）' }, slip)));
  objects.push(new Body(Object.assign({ type:'circle', radius:AT_R, x:PX, y:PY,
    isStatic:true, mass:0, fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5,
    label:'滑車（固定・摩擦なし）' }, slip)));
  annotations.push(new Annotation({ type:'path', x:PX, y:PY - 80, color:'#90a4ae', width:4,
    pts:[{ x:0, y:0 }, { x:0, y:80 - AT_R }] }));
  // おもり（同じ高さから）
  // ★重いほうは床まで 1.4 m 下がって着く。そのとき軽いほうの上端と滑車の下端は 0.6 m 空く
  //   （軽いほうが先に滑車へぶつかると、系のエネルギーがそこで欠けて題材が濁る）。
  const Y0 = gy - 170;
  const weight = (x, m, fill, stroke, label) => new Body(Object.assign({
    type:'box', w:60, h:60, x, y:Y0, mass:m, fixedRotation:true,
    fillColor:fill, strokeColor:stroke, strokeWidth:1.5, label }, slip));
  const A = weight(PX - RR, AT_M1, '#ef5350', '#ffcdd2', '1.5 kg');
  const B = weight(PX + RR, AT_M2, '#42a5f5', '#bbdefb', '1.0 kg');
  objects.push(A, B);
  const j = new Joint({ type:'rope', bodyA:A, bodyB:B, linDensity:0.02, color:'#a5d6a7',
                        anchorAx:0, anchorAy:-30, anchorBx:0, anchorBy:-30 });
  ropeAlongPath(j, [{ x:PX - RR, y:Y0 - 30 }, ...pulleyArc(PX, PY, RR, 180, 0), { x:PX + RR, y:Y0 - 30 }]);
  joints.push(j);
  // ── グラフ：系（上）と、重いほうだけ（下）──────────────────────
  //   ★同じ時間軸で縦に並べる。上の合計（黄）は平ら、下の合計は下がり続ける。
  const gSys = eneGraphNew([A.id, B.id], {
    showKt:true, showUg:true, showMech:true,
    showKr:false, showUs:false, showUgg:false, showUe:false });
  const gOne = eneGraphNew([A.id], {
    showKt:true, showUg:true, showMech:true,
    showKr:false, showUs:false, showUgg:false, showUe:false });
  sizeDemoGraph(gSys, 420, 330); moveDemoGraphTop(gSys);
  sizeDemoGraph(gOne, 420, 330); moveDemoGraphBottom(gOne);
  setDemoCam(0, 0.6);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'アトウッドの機械（エネルギーの持ち主）');
  demoNote (p.x, p.y + 54,
    '摩擦なし。固定した滑車に 1.5 kg と 1.0 kg を掛け、\n'
  + '同じ高さから放す。重いほうが下がり、軽いほうが上がる。\n'
  + '\n'
  + '【手順】▶実行 を押して、右の2枚のグラフを見くらべる\n'
  + '・上＝2つをまとめた系：合計（黄）は平ら ＝ 保存する\n'
  + '・下＝重いほう（1.5 kg）だけ：合計が下がり続ける\n'
  + '　＝ 縄の張力が上向き、動きは下向き → 負の仕事をされる\n'
  + '・軽いほうは同じだけ正の仕事をされて増える。\n'
  + '　2つ合わせると打ち消し合う\n'
  + '・重いほうが床に着くと、運動のぶんが失われる\n'
  + '\n'
  + 'エネルギーは物体1つが持つものではなく、\n'
  + '力をおよぼし合う相手を含めた「系」が持つ。');
}

// ════════════════════════════════════════
//  力学 ▸ 剛体
// ════════════════════════════════════════
// ── 上皿天秤（力のモーメントのつりあい）──────────────────────
//   ★見せたいのは m₁d₁ = m₂d₂ の1本だけ。だから「重さ」と「支点からの距離」の両方を
//     触れるようにする：おもりは編集ツールで皿へ運べ、皿はつり下げ棒の端をつまんで
//     さおの上を左右へ動かせる（ジョイントの端点のドラッグ）。
//     ＝ 同じおもりでも、置く場所を変えればつりあう。それが目で分かる形にする。
//   ★さおは支点が重心より上にないと「はかり」にならない。支点＝重心だと、どの角度でも
//     つりあう（中立）ので、つりあったのか偶然その角度なのかが区別できない。
//     支点を重心の上 e だけ離すと、傾いたときに mg·e·sinθ の戻す力が生まれ、
//     つりあえば水平、片方が重ければ決まった角度で止まる ＝ 本物の天秤と同じ。
//   ★この物理エンジンは「物体のローカル原点＝重心」として扱う（多角形の重心を
//     図形から計算し直したりはしない）。だからさおを三角形に描いても重心は原点のままで、
//     ヒンジをローカル (0,-100) に取れば e はちょうど 100px ＝ 1.0 m になる。
//   ★戻す力と感度は裏返しの関係にある。mg·e を大きくすると、少しの差では傾かない
//     （鈍い）が、大きく傾いても倒れきらない。ここは さお 16 kg・e = 1.0 m にしてある：
//     戻す力 157 N·m/rad に対し、1 kg を 2.0 m に載せた差 19.6 N·m で 6°ほど傾く。
//     読める傾きで、かつ端が地面に着くほどは倒れない値。
//   ★さおを短くしてある（半分の長さ 4.0 m）。長いほど支点まわりの慣性が長さの2乗で
//     効き、振れがゆっくりになって落ち着くまでが長い。7.0 m のときは周期が 8 秒を超え、
//     ★★実測を 20 秒おきに読んでいたせいで、−8°と−15°を行き来する「ゆっくりした揺れ」
//     に見えていた（周期 8 秒の振動を 20 秒間隔で読んだ折り返し＝ただの見誤り。
//     プロジェクトメモリ physbox-benchmarking-must-be-seeded と同じ罠）。
//   ★大きく傾きすぎるのは空中のストッパーで受け止める（下の★）。
const BAL_ARM     = 400;   // [px] さおの半分の長さ（4.0 m）
const BAL_E       = 100;   // [px] 支点と重心のへだたり（1.0 m）。上の★
const BAL_BEAM_M  = 16;    // [kg] さお
// ★皿は軽くする。皿にも重さがあるので、皿を左右で違う距離へ動かすと皿の重さぶんの
//   モーメントが残り、m₁d₁ = m₂d₂ がそのままでは合わなくなる。実測：皿 0.6kg のとき
//   「2kg を 2.0m、1kg を 4.0m」はつりあわず 11° 右へ傾いた（皿だけで 0.6×4.0 − 0.6×2.0
//   ＝ 1.2 kg·m の差が出るため）。0.15kg なら残る差は 0.3 kg·m ＝ 傾き 1.1° に収まる。
const BAL_PAN_M   = 0.15;  // [kg] 皿（左右まったく同じ物にすること）
const BAL_PAN_WALL = 90;   // [px] 皿の壁の高さ。★4kg（一辺79px）まで壁の中に収まる高さ。
//   ★皿は fixedRotation で水平に保たれるので、つり下げ点の高さは皿の傾きに効かない。
//     だから壁は「おもりが収まる高さ」だけで決めてよく、低くしたぶんを床との間隔に回せる。
const BAL_ROD     = 260;   // [px] つり下げ棒の長さ（さおと皿のあいだ）
const BAL_DASHPOT_EACH = 120;  // [N·s/m] 制動器1本ぶんの摩擦。左右2本で 240
const BAL_DASH_BORE   = 26;    // [px] 制動器の内径（見た目の太さ。通気なので力には効かない）
// ★制動器は支点の近く（0.8 m）に付ける。理由は2つ。
//   ①行程が短くて済む：傾きの上限 8.7° での上下動は 80·sin8.7° = ±12px。3.0 m に付けると
//     ±45px 要り、器がさおの下へ 2.4 m ぶら下がって、つり下げ棒と重なる。
//   ②**行程を使い切らせない**。ピストンの行き止まりは硬い拘束で、しかも
//     enforcePistonVessels は接触の位置補正の**後**に走る。実測：3.0 m・行程 140px で
//     左右が同時に行き止まりへ当たり、さおが 11.6° で固まった（振れ止めの 8.7° すら
//     突き抜けた＝拘束がストッパーの接触を上書きした）。
const BAL_DASH_X      = 80;    // [px] 制動器の取り付け位置（支点から 0.8 m）
const BAL_DASH_LEN    = 90;    // [px] 制動器の行程（±33px。要る ±12px の 2.7 倍）
// ★蓋を軽くしすぎない。器と蓋の質量比が開くと、器と蓋の拘束（solveVesselConstraint）が
//   位置を直すときに軽いほうが大きく動かされ、それがヒンジ越しにさおへ返って**発振する**。
//   実測（さお4kg・支点は重心の1.0m上・制動器を±0.8mに2本、10秒後の傾き）：
//     蓋 0.2kg → 18.1°（叩かなくても勝手に増える）／0.4kg → 0.11°／0.6kg → 0.04°／1.0kg → 0.01°
//     蓋 0.2kg のままでも、器の密度を 600→60 に落とせば 0.000°（＝犯人は器と蓋の質量比）
//   左右同じ重さなので、つりあいの角度そのものは動かない。
const BAL_DASH_PIST_M = 0.5;   // [kg] 蓋の質量
const BAL_DASH_CYL_D  = 150;   // [kg/m³] 器の密度。蓋と釣り合う程度に軽くする
const BAL_D0      = 200;   // [px] 皿の初期位置（支点から 2.0 m）
// ── さおの断面と、中に刻んだ窪み ───────────────────────────
//   ★さおは中空。空洞の床にくし歯を刻み、その窪みに〇を落として皿の位置を決める。
//   ★下の壁を薄く（窪みの床 +25 に対し下面 +32 ＝ 7px）してあるのは、つり下げ棒が
//     ここを抜けるため。厚くすると棒が材料の中を長く貫いて見える。
//   ★窪みは 0.5 m ごとに6か所。目分量ではなく「支点から何 m か」を数えて置ける。
const BAL_TOP     = 40;    // [px] さおの上面（重心＝ローカル原点から上へ）
const BAL_BOT     = 32;    // [px] さおの下面
const BAL_SLOT_TOP   = -25;  // [px] 空洞の天井
const BAL_SLOT_FLOOR =  25;  // [px] 窪みの床
const BAL_TOOTH_TOP  =   0;  // [px] 歯の頂（ここを越えて隣の窪みへ移す）
const BAL_POCKET  = 30;    // [px] 窪みの幅（〇の直径 20 より広く）
const BAL_SLOTS   = [100, 150, 200, 250, 300, 350];  // 窪みの中心（支点から 1.0〜3.5 m）
const BAL_BALL_R  = 10;    // [px] 位置ぎめの〇
const BAL_BALL_M  = 0.1;   // [kg] ★軽くする。左右で違う距離に置くと、〇自身の
                           //   モーメントの差が m₁d₁ = m₂d₂ のずれになるため（皿と同じ理屈）
// 片側ぶんの空洞（穴）の輪郭。sign=+1 で右、-1 で左。
//   ★左右で1つずつ、別々の穴にする（ひと続きにしない）。つながっていると〇が支点を
//     またいで反対側へ転がり、「左腕の距離」という量そのものが消える。
//   ★鏡像にすると巻き方向が裏返るので、並びも反転して戻す。慣性モーメントの計算は
//     巻き方向をそろえてあるので（js/physics/body.js の★）どちらでも壊れないが、
//     凸分解に余計な仕事をさせない。
function balSlotHole(sign) {
  const h = BAL_POCKET / 2, c = BAL_SLOTS, last = c.length - 1;
  const pts = [{ x:c[0] - h,    y:BAL_SLOT_TOP },      // 天井を左から右へ
               { x:c[last] + h, y:BAL_SLOT_TOP },
               { x:c[last] + h, y:BAL_SLOT_FLOOR }];   // 右の壁を下りる
  for (let k = last; k >= 0; k--) {                    // 床を右から左へ、歯を越えながら
    pts.push({ x:c[k] - h, y:BAL_SLOT_FLOOR });
    if (k > 0) {
      pts.push({ x:c[k] - h,     y:BAL_TOOTH_TOP });
      pts.push({ x:c[k-1] + h,   y:BAL_TOOTH_TOP });
      pts.push({ x:c[k-1] + h,   y:BAL_SLOT_FLOOR });
    }
  }
  return sign > 0 ? pts : pts.map(p => ({ x:-p.x, y:p.y })).reverse();
}
// 衝突レイヤー。★さおと〇だけを別のレイヤーに置く。さおは皿・おもり・支柱と重なる
//   場所を通るのでぶつけたくないが、〇だけはさおの窪みで受け止めてほしい。
//   マスク方式なので、この2枚だけが共通ビットを持てばよい。
const BAL_LAYER_BEAM = 0b0010;   // さおと〇
const BAL_LAYER_DASH = 0b1000;   // 制動器（このビットは他の誰も持たない＝何とも当たらない）
const BAL_DRAG    = 1.2;   // 抗力係数（空気抵抗。振れ止めの主役はストッパーのほう）
// 振れ止め（空中のストッパー）。★さおの両端の上に置き、傾きをここで受け止める。
//   BAL_STOP_GAP は「さおの上面とストッパーの下面のすきま」。傾きの上限は
//   asin(すきま / BAL_STOP_X) で決まる：56px / 370px → 8.7°。
//   ★8〜9° は「読める傾き」より少し外に取ってある。普通の不つりあい（1kg の差を
//     2.0m で ＝ 実測 −3.8°）はストッパーに触れず、大きく傾いたときだけ受け止める。
const BAL_STOP_X   = 370;  // [px] ストッパーの位置（支点から 3.7 m）
const BAL_STOP_GAP = 56;   // [px] さおの上面とのすきま
// 置いてあるおもり。★一辺は質量の3乗根に比例させる（見た目の大きさと重さが食い違わない）
const BAL_WEIGHTS = [
  { m:0.5, color:'#90a4ae' }, { m:0.5, color:'#90a4ae' }, { m:0.5, color:'#90a4ae' },
  { m:1,   color:'#ffb300' }, { m:1,   color:'#ffb300' }, { m:1,   color:'#ffb300' },
  { m:2,   color:'#ef5350' }, { m:2,   color:'#ef5350' },
  { m:3,   color:'#7e57c2' }, { m:4,   color:'#26a69a' },
];
function demoBalanceScale() {
  const gy = ground.y;
  resetDemoWorld();
  world.substeps = 8;          // ★さお・皿・おもりが棒でつながるので、既定の4だと皿が震える
  // ★眠らせない。天秤はほとんど動かないので、眠りが入っているとさおが寝入ってしまい、
  //   皿へおもりを載せても傾かない（実測：左2kg・右1kg にしても 0.0°のまま動かなかった）。
  //   代わりに空気抵抗で振れを止める（BAL_DRAG）。
  world.sleeping = false;
  updateGroundTerrain(true);
  ground.friction = 1; ground.frictionStatic = 1;   // おもりが床を滑って散らない
  setDemoCam(0, 0.60);
  // ★支点を高くする（つり下げ棒を 2.6 m に延ばしたぶん）。5.2 m のままだと皿の底が
  //   床の 5px 上まで下りてきて、さおが傾いた側の皿が床に当たる。6.2 m で 1.05 m 空く。
  //   ★上限は本文の下端（この倍率で 地面の 6.56 m 上）。さおは本文と横に重なる位置に
  //     あるので、山の頂がそれより上へ出ると文字に掛かる。
  const pivotY = gy - 640;                     // 支点の高さ（6.4 m）
  const beamY  = pivotY + BAL_E;               // さおの重心の高さ
  const solid  = { friction:0.7, frictionStatic:0.9, restitution:0 };
  // ★支柱は置かない。ヒンジは地面のローカル座標に直接つないである（下の hinge）ので、
  //   柱は物理には一切関わっていなかった＝見た目だけの物。置かないほうが、さおの下を
  //   通る皿とつり下げ棒の邪魔にもならない。
  // さお。★中を空洞にし、その床にくし歯の窪みを刻む。窪みに置いた〇を掴んで動かすと、
  //   皿をつるす位置＝支点からの距離が段階的に変わる。
  //   ★空洞は左右で分断する（中央 ±70px は中まで詰まったまま）。ひと続きにすると
  //     〇が支点をまたいで反対側へ転がってしまい、「左腕の距離」という量が消える。
  //   ★窪みは 0.5 m ごと。〇は ±1.0 / 1.5 / 2.0 / 2.5 / 3.0 / 3.5 m の6か所に座る。
  //     刻んであるので、目分量ではなく「何 m か」を数えて置ける。
  //   ★頂点は「符号つき面積が正」になる向きに並べる。逆に並べると慣性モーメントが負になり、
  //     さおがヒンジのまわりで発散した（実測：角度が 10¹⁹ 度）。
  const beam = new Body(Object.assign({ type:'polygon', x:0, y:beamY, mass:BAL_BEAM_M,
    verts:[{x:0,y:-BAL_E},{x:60,y:-BAL_TOP},{x:BAL_ARM,y:-BAL_TOP},{x:BAL_ARM,y:BAL_BOT},
           {x:-BAL_ARM,y:BAL_BOT},{x:-BAL_ARM,y:-BAL_TOP},{x:-60,y:-BAL_TOP}],
    holes:[balSlotHole(+1), balSlotHole(-1)],
    drag:BAL_DRAG, layers:BAL_LAYER_BEAM,     // ★〇だけを受け止める（上の★）
    fillColor:'#8d6e63', strokeColor:'#d7ccc8', strokeWidth:2,
    label:`さお ${BAL_BEAM_M}kg` }, solid));
  objects.push(beam);
  // ★支点は背景に留める（ヒンジは画鋲：さおと背景を1点で刺す。手のヒンジツールで宙を
  //   クリックしたときと同じ）。以前は地面に留めていたが、宙の点を地面に留めることは
  //   手ではできず、地面を傾けると支点が地面と一緒に回った（2026-10-02 に直した）。
  //   ★打つのは手のツールと同じ入口（demo-kit.js の demoPin）。支点にはさおしか無いので背景に留まる
  const pivotW = getWorldAnchor(beam, 0, -BAL_E);
  demoPin('hinge', pivotW.x, pivotW.y, 'pair', { expect:[beam, null], opts:{ color:'#ffd54f' } });
  // 皿（左右で同じ物）。★U字の受け皿にする。平らな板だと、おもりを端に置いた瞬間に
  //   傾いて転がり落ちる。つり下げ点を壁の上端の中央に取ると、重心がその下に来て安定する。
  const pan = (d) => {
    // ★皿は回らないようにする（fixedRotation）。「上皿天秤」の皿は、平行四辺形のリンクで
    //   さおの傾きによらず水平に保たれている道具で、それをそのまま写したもの。
    //   ★これが無いと軽い皿は使いものにならない：皿 0.15kg に 2kg を載せると、
    //     おもりが少し中心からずれただけで皿ごと回り、実測では 45°まで傾いて
    //     おもりがこぼれかけた。皿を重くすれば回りにくくなるが、こんどは皿自身の
    //     モーメントが効いて m₁d₁ = m₂d₂ が合わなくなる（BAL_PAN_M の★）。
    //     水平に保つのは、重さを増やさずに回転だけ止められる唯一の手。
    // 窪みに座った〇。★これを掴んで隣の窪みへ移すと、皿ごと距離が変わる。
    //   〇はさおと同じレイヤーなので窪みで受け止められ、皿やおもりとはすり抜ける。
    const ballY = beamY + BAL_SLOT_FLOOR - BAL_BALL_R;
    const ball = new Body(Object.assign({ type:'circle', x:d, y:ballY, radius:BAL_BALL_R,
      mass:BAL_BALL_M, drag:BAL_DRAG, layers:BAL_LAYER_BEAM,
      fillColor:'#ffd54f', strokeColor:'#fff59d', strokeWidth:1.5,
      label:'位置ぎめの〇' }, solid));
    objects.push(ball);
    const p = new Body(Object.assign({ type:'polygon', x:d, y:ballY + BAL_ROD + BAL_PAN_WALL,
      mass:BAL_PAN_M, drag:BAL_DRAG, fixedRotation:true,
      // ★U字（凹）。凹ポリゴンは凸パーツへ自動で分解される（js/physics/convex.js）。
      //   ここも符号つき面積が正になる向きで並べること（さおの★と同じ）。
      // ★壁は高くする。理由は2つ：
      //   ① さおが傾く途中で皿が振れ、浅い皿（34px）だとおもりが外へこぼれた
      //      （実測：18°傾いたときに 2kg が皿の 273px 下まで落ちた）。
      //   ② つり下げ点を壁の上端＝おもりの重心よりずっと上に取るため。皿は軽いので、
      //      つり下げ点が低いと、おもりを端に寄せただけで皿がぐらりと回る。
      //      壁 120px なら、2kg を 0.3 m 端へ寄せても傾きは 16° に収まる。
      //   ★横から見た図なので、壁は左右の縦棒として描かれる。おもり（一辺 40〜72px）は
      //     その間に見えたままで、高い壁に隠れることはない。
      verts:[{x:-90,y:-BAL_PAN_WALL},{x:-74,y:-BAL_PAN_WALL},{x:-74,y:4},{x:74,y:4},
             {x:74,y:-BAL_PAN_WALL},{x:90,y:-BAL_PAN_WALL},{x:90,y:20},{x:-90,y:20}],
      fillColor:'#455a64', strokeColor:'#b0bec5', strokeWidth:2, label:'皿' }, solid));
    objects.push(p);
    // ★皿は「さお」ではなく「〇」からつるす。だから〇を動かせば皿も付いてくる。
    //   ★棒はレイヤー 0（すり抜け）。さおの下の壁を貫いて出るので、当てると跳ねる。
    //   ★つり下げ点は皿の壁の上端。おもりの重心より上でないと、おもりを端に置いた
    //     ときに皿がひっくり返る（重心が支点より上になるため）。
    joints.push(new Joint({ type:'rod', bodyA:ball, anchorAx:0, anchorAy:0,
                            bodyB:p, anchorBx:0, anchorBy:-BAL_PAN_WALL,
                            restLength:BAL_ROD, maxLength:BAL_ROD,
                            layers:0, color:'#b0bec5' }));
    return p;
  };
  pan(-BAL_D0); pan(BAL_D0);
  // ── 振れ止め（空中のストッパー）─────────────────────────
  //   ★支点の摩擦（モーターの保持トルク）で止めるのは不可。動き出すのに要るトルクに
  //     下限ができ、小さな重さの差では傾かない天秤になってしまう。
  //   ★以前はばねの制動器（ばね定数0・減衰のみ）を使っていた。こちらのほうが
  //     小さな振れまで止まる（実測：つりあったあと 20〜30 秒で振れ幅 0.2°）。
  //     それをやめてストッパーに替えた。ばね（ばね定数0・減衰のみ）でも
  //     振れは止まるが、天秤にばねが下がっている絵は「引っぱっている」と読まれやすい。
  //     本物の天秤にも振れ止めは付いていて、そちらは当たって止める形をしている。
  //   ★さおの両端の「下」に1つずつ置く。さおは支点で結ばれた1本の剛体なので、
  //     左端が下がるのを止めれば右端が上がるのも止まる ＝ 2つで両向きを抑えられる。
  //   ★上ではなく下なのは場所の都合。上に置くと本文の下端と高さを取り合い、
  //     実測（倍率 0.60）では左のストッパーが本文の最終行に重なった。下は空いている。
  //   ★止まるのは当たった衝撃で角速度が消えるから（反発 0）。よく効く：
  //     さおに av = 0.5 rad/s を与えて叩いても、20 秒後には振れ幅 0.36° で止まっている。
  //     大きな不つりあい（左の皿に 2kg+3kg）でも −7.5° で受け止められ、振れ幅 0.34°。
  //   ★ただし「ストッパーに届かない小さな振れ」は止められない。それを消すのが下の制動器で、
  //     制動器を通気シリンダーに替えてからは**振れが本当に止まる**。実測（av = 0.5 で叩く）：
  //       振れ幅 0〜5秒／5〜15秒／20〜30秒 ＝ 4.37°／0.18°／0.00°
  //       （ばね定数0のばねジョイントだった頃は 8.15°／7.68°／6.43°、制動器なしなら
  //         8.17°／7.88°／7.06°。つまり以前の制動器はほとんど効いていなかった）
  //     ★つりあいの角度は動かさない：左の皿に 0.3kg を足したときの落ち着き先は
  //       −4.74°（振れ幅 0.01°）で、制動器を外した同じ場面が 60 秒かけて −4.04° まで
  //       近づいていく先と同じ値。粘性の制動なので静止摩擦を持たず、途中で止まれない
  //       ＝**手前で止まって嘘の値を指すことがない**（読みは 10 秒で出る）。
  //   ★空気抵抗を上げても効かないので上げない（実測：抗力 1.2／3／6 で 20〜40 秒の
  //     振れ幅は 8.61°／8.54°／8.01°）。効きもしない値で Cd だけ大きくするのは嘘になる。
  //   ★レイヤーはさおと同じ。皿・おもり（レイヤー1）とはすり抜けるので、
  //     おもりを運ぶ手が引っかかることはない。〇は空洞の中なので届かない。
  for (const sx of [-1, 1]) {
    objects.push(new Body(Object.assign({ type:'box',
      x: sx * BAL_STOP_X, y: beamY + BAL_BOT + BAL_STOP_GAP + 10, w:70, h:20,
      isStatic:true, mass:0, layers:BAL_LAYER_BEAM,
      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5,
      label:'振れ止め' }, solid)));
    // ★制動器を左右に1本ずつ。ストッパーは「当たって止める」ので、当たらない小さな振れは
    //   残る。制動器は動く速さにだけ逆らうので、つりあいの角度には効かず振れだけを消す。
    //   ストッパーとは役割が違うので両方いる。
    //   ★色は暗い灰にして目立たせない。この部品は題材ではなく、装置の裏方。
    //   ★中身は「通気にしたピストン容器」。中は外気に開放されているので気体ばねが無く、
    //     残るのはピストンとシリンダーの摩擦だけ＝速さにだけ逆らう本物のダッシュポット。
    //     ばね定数0のばねジョイントで作っていたのをやめた理由は、あれが制動器として
    //     働いていなかったため：相対速度を**重心**の速度から作るのに力積は取り付け点へ
    //     与えるので、回る物体では向きが揃わず正の仕事をしうる（実測：支点を重心の上に
    //     置いたさおで、減衰 0 なら振れ幅 6.83°→6.66° と減るのに、120 で 6.83°→8.60°、
    //     400 では 29.9°→48.1° と**振れが育った**）。
    //   ★器は地面まで伸ばさない。閉端を背景へヒンジで留めれば、必要なのは行程ぶんの
    //     長さだけで済む（さおの下面は地面から 5.08 m あるので、地面に立てると 5 m の
    //     塔になる）。傾きの上限 8.7° に対し、取り付け点 3.0 m での上下動は ±45px。
    //   ★器も蓋もレイヤー 0（すり抜け）。つり下げ棒と同じ扱いで、皿・おもり・さおの
    //     どれとも当たらない。装置の裏方が主役の邪魔をしてはいけない。
    // ★閉端の高さは「蓋がちょうどさおの下面に来る」ように決める（ずらすとヒンジが
    //   その差だけさおを引っぱる）。蓋の初期位置は閉端から innerLen/2 + 蓋の厚みの半分。
    const dashCE = { x: sx * BAL_DASH_X, y: beamY + BAL_BOT + BAL_DASH_LEN / 2 + 6 };
    const dv = createPistonVessel({
      x: dashCE.x, y: dashCE.y - BAL_DASH_LEN / 2, bore: BAL_DASH_BORE,
      innerLen: BAL_DASH_LEN, fill: 0.5, pistonMass: BAL_DASH_PIST_M, pistonThick: 12,
      damp: BAL_DASHPOT_EACH, cylinderDensity: BAL_DASH_CYL_D,
      cylinderColor: '#37474f', pistonColor: '#546e7a', label: '制動器' });
    const dCyl = dv.cylinder(), dPis = dv.piston(), dCh = dv.chamber();
    dCh.vent = true;                       // ★通気＝気体ばねを持たない（上の★）
    // ★レイヤーは 0（すり抜け）にしない。0 は「ゴースト」として黄色い破線で描かれる
    //   仕掛けで、実測では制動器2本が破線の箱になって本文より目立った。誰とも重ならない
    //   専用のビットを与えれば、当たらないのは同じで見た目はふつうの物体のままになる。
    dCyl.layers = BAL_LAYER_DASH; dPis.layers = BAL_LAYER_DASH;
    dCyl.label = '制動器'; dPis.label = '';
    // ★さおより後ろに描く。器は蓋の上端より上まで伸びている（蓋が中を動くのだから
    //   当然そうなる）ので、そのままだとさおの上に重なって主役の邪魔をする。
    //   objects の並び順がそのまま描く順なので、先頭へ移して奥に置く。
    for (const b of [dCyl, dPis]) objects.splice(objects.indexOf(b), 1);
    objects.unshift(dCyl, dPis);
    // 閉端を背景へ、蓋をさおの下面へ。どちらもヒンジ＝器は傾いてさおに追従する
    const ce = dv.closedEnd();
    joints.push(new Joint({ type:'hinge', bodyA:null, anchorAx:ce.x, anchorAy:ce.y,
                            bodyB:dCyl, anchorBx:0, anchorBy:BAL_DASH_LEN / 2,
                            color:'#607d8b' }));
    joints.push(new Joint({ type:'hinge', bodyA:beam, anchorAx:sx*BAL_DASH_X, anchorAy:BAL_BOT,
                            bodyB:dPis, anchorBx:0, anchorBy:0, color:'#607d8b' }));
  }
  // 置いてあるおもり。★床の上、皿の真下を避けた中央付近に並べる
  //   さおの外側の床に3個ずつ。真下に置くと、皿を動かしたときに皿がおもりに乗る
  BAL_WEIGHTS.forEach((w, i) => {
    const s = 50 * Math.cbrt(w.m);
    // ★皿の真下（±3.5m まで動く）を避け、さおの外側の床に5個ずつ。
    const slot = [-780, -688, -596, -504, -412, 412, 504, 596, 688, 780][i];
    objects.push(new Body(Object.assign({ type:'box', x:slot, y:gy - s/2, w:s, h:s,
      mass:w.m, fillColor:w.color, strokeColor:'#ffffff', strokeWidth:1.5,
      label:`${w.m}kg` }, solid)));
    // ★床のおもりに、そのおもりと同じ色で質量を書く。物体の label は画面には出ない
    //   ので（js/render/body.js に描く処理が無い）、注釈で置くしかない。
    //   ★色をおもりと合わせるのが肝。皿へ運んだあとも「床のどれを持っていったか」が
    //     色で辿れる。数字だけ白で書くと、どの札がどのおもりのものか分からなくなる。
    //   ★札はおもりの「上」に置く。床の下に置くと、座標軸の目盛り（−7.5m などの数字が
    //     地面のすぐ下に並ぶ）と重なって、どちらも読めなくなった（実測）。
    annotations.push(new Annotation({ type:'text', x:slot - 26, y:gy - s - 34,
      text:`${w.m} kg`, size:22, bold:true, color:w.color }));
  });
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '上皿天秤 ― 支点からの距離で決まる');
  demoNote (p.x, p.y + 54,
  // ★本文は 8 行まで。さおは本文と横に重なる位置にあるので、縦に逃がすしかなく、
  //   1行増やすごとにさおを 0.3 m 下げる＝皿と床のすきまが 0.3 m 減る、という関係になる。
  //   おもりが皿の下を通れる高さを確保するため、説明は削って短く保つ
  //   （実測：12 行にすると、すきまが 1.55 m から 0.65 m まで詰まった）。
    'さお（16 kg）を支点で支え、左右に同じ皿をつり下げてある。\n'
  + '支点は重心の 1.0 m 上なので、つりあえば水平に戻る。\n'
  + '\n'
  + '【手順】▶実行 を押してから、編集ツールで\n'
  + '① 床のおもりを皿へ運ぶ（皿の下は通り抜けられる）。重いほうが下がる\n'
  + '② さおの中の黄色い〇を隣の窪みへ移すと、皿ごと位置が変わる\n'
  + '　　窪みは 0.5 m ごと、支点から 1.0〜3.5 m の6か所。左右の空洞は別々\n'
  + '\n'
  + '【読みどころ】つりあうのは「重さ × 支点からの距離」が等しいとき\n'
  + '　例：2 kg を 1.0 m なら、1 kg は 2.0 m（2×1.0 = 1×2.0）');
}

// ── 壁に立てかけたはしご ────────────────────────────────
//   ★見せたいのは「おもりを高く掛けるほど滑りやすい」の1点。
//     壁からの垂直抗力は N_壁 = [W_はしご/2 + W_おもり × s/L] × cot θ で、掛ける高さ s が
//     上がるほど増える。床が出せる摩擦は μ(W_はしご + W_おもり) で s によらないので、
//     どこかの高さで足りなくなる ＝ そこが滑り出す点。
//   ★はしごの上の面を凸凹にして、窪みへおもりを「置く」。横桟がそのまま上へ突き出た形で、
//     隣の窪みとのあいだに歯が1本立つ。おもりは斜面を滑り落ちて下側の歯に当たって止まる
//     ＝ 実物どおり「桟にひっかける」操作になる。掴んで隣の窪みへずらすだけで掛け替わる。
//     ★以前は中空の枠の中に〇を入れ、そこからロープでおもりを吊るしていた（上皿天秤の
//       さおと同じ作り）。部品が3つ（枠の空洞・〇・ロープ）要るうえ、低い桟ではおもりが
//       床に着いてロープがたるみ、そのぶん荷重が抜けていた。窪みに置く形なら部品は
//       おもり1つで、どの窪みでも 10kg がまるごとはしごに載る。
//   ★はしごの中身は詰まっている（穴を開けない）。枠に見せるための空洞を残していたが、
//     おもりが載るのは上の面の窪みのほうで、空洞は何の役にも立っていなかった。
//     ★穴を取っても静止の話は 1 つも動かない。N_壁 も滑り出す窪みも実測で完全に同じ
//       （43.3 / 51.4 / 59.5 / 67.6 / 75.7 / 83.8 N、下4つが静止率 1.00）。
//       つりあいを決めているのは接地点の位置と重心の位置だけで、そのどちらも
//       穴の有無で変わらないため（変わるのは慣性モーメントだが、静止した図には効かない）。
//   ★歯は「引っかかりの仕事」をしていること。はしごとおもりの接触の摩擦は合成が積で
//     0.25×0.6 = 0.15 しかなく、tan60°= 1.73 に遠く及ばない ＝ 摩擦だけでは必ず滑り落ちる。
//     止めているのは歯の側面だけで、歯を取れば（＝平らな上面なら）おもりは床まで落ちる。
//   ★歯はおもりの重心より高くする（歯 34px ＞ おもりの半分の高さ 24px）。低いと接触の
//     合力がおもりの重心より下に来て、歯を乗り越える向きのトルクが立つ。
//   ★はしごを重くする（20kg）。おもり 10kg との比が 2:1（js/physics/body.js の質量比の
//     実測。0.1kg の板に 30kg を載せたときは完全に貫通した）。
//   ★壁の摩擦は 0（教科書の前提）。摩擦の合成は積なので、壁側を 0 にすれば
//     はしご側の値によらずその接触は 0 になる。床だけが滑りを止めている図になる。
//   ── 数値の根拠（すべて実測。窪みは根元から 1〜6 m の6か所）────────────────
//   ★N_壁 の実測 [N]：43.3 / 51.4 / 59.5 / 67.6 / 75.7 / 83.8（1〜6 m）。
//     ★測るときは μ を 0.32 まで上げて、6か所とも滑らせずに測ること。μ=0.25 のままだと
//       5 m・6 m は測っているあいだに滑り出し、動いたあとの値（80.6 / 93.2）が混ざる。
//     完全に直線で、傾きは 1 m あたり 8.08 N ＝ 教科書の W_おもり×cotθ/L（98×0.5774/7
//     ＝ 8.083）とぴたり合う。デモが読ませたいのはこの傾きなので、そこは理論どおり。
//   ★ただし切片は教科書の細い棒の式より小さい（2 m で実測 51.4 N ／式は 72.8 N）。
//     幅のある板だからで、理由は2つ。どちらも腕を短くする向きに効く：
//       ・床に着いているのは軸の先ではなく根元の「角」で、軸より 26px 右にある
//       ・おもりの重心は上の面のさらに 24px 外、軸から 54px 離れて左へずれる
//     ＝ この系で N_壁 を見積もるときは、細い棒の式ではなく根元の角まわりのモーメント
//       N_壁×606 ＝ 196.1×(175−26) + 98×(x_おもり−26) を使うこと（px と N の混在に注意）。
//   ★μ = 0.25 の根拠。床の摩擦の上限は μ(W_はしご+W_おもり) ＝ 73.6 N で、
//     上の列と見くらべると 4 m（67.6）で持ちこたえ 5 m（75.7）で足りない。
//     実測（300 tick の静止率）：1m 1.00／2m 1.00／3m 1.00／4m 1.00／5m 0.53／6m 0.63。
//     滑ったほうは 300 tick で 175px（1.75 m）下がる。
//   ★「おもりを外しても立つ」ことを条件にすると、これ以上 μ を下げられない。
//     おもり無しの N_壁 は 48.2 N、上限は 0.25×196.1 ＝ 49.0 N ＝ 余裕は 1.6% しかない
//     （実測：μ=0.25 で静止率 1.00・変位 0px、μ=0.24 では滑る）。
//     ★これは調整の失敗ではなく物理の性質。おもりを「はしご自身の重心と同じ高さ」に
//       置いた状態は、おもりが無い状態とちょうど同じ安定度になる（分子と分母が同じ比で
//       増えるため）。この系ではその釣り合いの高さが 4.6 m なので、
//       「おもり無しでも立つ」を保つ限り、滑り出す窪みは 5 m 以上の2つに限られる。
//       ＝ 4つ持ちこたえて2つ滑る、が取りうる中でいちばん均等な分かれ方。
const LAD_L      = 700;   // [px] はしごの長さ（7.0 m）
const LAD_W      = 60;    // [px] はしごの幅
const LAD_DEG    = 60;    // [°] 床からの角度
const LAD_M      = 20;    // [kg] はしご
const LAD_LOAD   = 10;    // [kg] 窪みに置くおもり
const LAD_MU     = 0.25;  // 床とはしごの静止摩擦係数 μs（床側を 1 にしてあるのでこれが実効値）。つまみの初期値
const LAD_MU_K   = 0.10;  // 動摩擦係数 μk。★μs のつまみの下限と同じ値にする（μs ≧ μk の決まりがあり、
                          //   μk より下へは μs を下げられないため）。滑り出すかどうかは μs だけで決まる
const LAD_MU_LO  = 0.10, LAD_MU_HI = 0.40;   // つまみの範囲（下の★）
const LAD_RUNGS  = [-300, -200, -100, 0, 100, 200, 300];  // 横桟のローカル x
const LAD_TOOTH_W = 14;   // [px] 歯（横桟）の幅
const LAD_TOOTH_H = 34;   // [px] 上の面からの歯の高さ。★おもりの重心（24px）より高くする
const LAD_LOAD_W  = 56;   // [px] おもり。窪みの幅 86px に収まり、掴んで隣へ移せる
const LAD_LOAD_H  = 48;   // [px] おもりの高さ。★歯（34px）が重心（24px）より高いこと
// はしごの外周。上の面（ローカル −y 側）に、横桟の位置で歯を1本ずつ立てる。
//   ★頂点は「下の辺を左→右、上の辺を右→左」の1周で作る。上の辺を戻る途中で歯を
//     差し込むので、歯は必ず外向きに立ち、自己交差しない。
function ladOutline() {
  const hw = LAD_L/2, hh = LAD_W/2, tw = LAD_TOOTH_W/2, top = -hh - LAD_TOOTH_H;
  const v = [{x:-hw,y:hh},{x:hw,y:hh},{x:hw,y:-hh}];
  for (let i = LAD_RUNGS.length - 1; i >= 0; i--) {
    const xc = LAD_RUNGS[i];
    v.push({x:xc+tw,y:-hh},{x:xc+tw,y:top},{x:xc-tw,y:top},{x:xc-tw,y:-hh});
  }
  v.push({x:-hw,y:-hh});
  return v;
}
// 窪み（歯と歯のあいだ）の中心のローカル x。根元から数えて i 番目（0 起点）
function ladNotchX(i) { return (LAD_RUNGS[i] + LAD_RUNGS[i+1]) / 2; }
// おもりを i 番目の窪みへ置く。★下側の歯に当たった位置（窪みの中心から
//   (窪みの幅 − おもりの幅)/2 だけ根元寄り）に直接置く。中心に置くと、おもりが
//   歯まで滑り落ちる 15px ぶんの助走が付き、その勢いで歯を乗り越えることがある。
function ladPutLoad(lad, load, i) {
  const slide = ((100 - LAD_TOOTH_W) - LAD_LOAD_W) / 2;
  const p = getWorldAnchor(lad, ladNotchX(i) - slide, -LAD_W/2 - LAD_LOAD_H/2);
  load.x = p.x; load.y = p.y; load.angle = lad.angle;
  load.vx = load.vy = load.av = 0;
  load._invalidateShape(); load._updateAABB();
}
function demoLadder() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;      // ★眠ると拘束力の矢印が消える（いろいろな力のデモの★）
  world.forceVizScale = 1;     // [画面px per N] はしごの重力 196 N が 196px
  // ★ここは 16 のまま。接触の這い（collision.js の correctContactTangentialDrift で
  //   直した分）とは別の残差で、壁と床の2点で支える静定問題の収束が足りない。
  //   実測：substeps 4 では 900tick で 19/23px 動き 3.3° 傾くが、16 なら 5/5px・0.8°。
  world.substeps = 16;
  updateGroundTerrain(true);
  ground.friction = 1; ground.frictionStatic = 1;   // ★合成は積。はしご側の値が実効値
  setDemoCam(0, 0.55);
  const th = LAD_DEG * Math.PI / 180;
  const dx = Math.cos(th), dy = -Math.sin(th);      // 根元から先端への向き（yは下が正）
  // はしご本体（中身の詰まった板。上の面だけ横桟が突き出た凸凹）
  const lad = new Body({ type:'polygon', x: LAD_L/2 * dx, y: gy + LAD_L/2 * dy, angle:-th,
    mass:LAD_M, verts: ladOutline(),
    friction:LAD_MU_K, frictionStatic:LAD_MU, restitution:0, showForces:true,
    fillColor:'#8d6e63', strokeColor:'#d7ccc8', strokeWidth:2, label:`はしご ${LAD_M}kg` });
  // ★はしごの「角」が床と壁にちょうど触れる位置まで平行移動する。傾けた長方形の中心を
  //   軸の中点に置くと、根元の角が床へ 15px、先端の角が壁へ 26px めり込んだ状態で始まる。
  //   そのめり込みをソルバが押し返す最初の数 tick で、はしごが 26px 跳ねて滑り出しの
  //   判定が壊れていた（実測：どの窪みに置いても最初の 5 tick で x が −25.7px 動き、
  //   おもりが歯を1つ乗り越えることもあった）。角の座標から出すので、歯を足しても崩れない。
  let maxX = -Infinity, maxY = -Infinity;
  for (const v of lad._worldVerts()) { if (v.x > maxX) maxX = v.x; if (v.y > maxY) maxY = v.y; }
  lad.y -= (maxY - gy); lad._invalidateShape(); lad._updateAABB();
  objects.push(lad);
  // 壁（静的・摩擦0）。★はしごの先端の角がちょうど当たる位置に立てる
  objects.push(new Body({ type:'box', x: maxX + 40, y: gy - 400, w:80, h:800,
    isStatic:true, mass:0, friction:0, frictionStatic:0, restitution:0,
    fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'壁（なめらか）' }));
  // おもり。★根元から2つ目の窪み（2 m）から始める＝持ちこたえる高さ
  const load = new Body({ type:'box', angle:-th, w:LAD_LOAD_W, h:LAD_LOAD_H,
    // ★矢印を出すのははしごだけ。読みどころは「はしごが受ける力」＝壁の垂直抗力と
    //   床の摩擦のせめぎ合いで、おもり自身が受ける力（重力と、はしごからの抗力・摩擦）は
    //   その話に出てこない。両方に出すと、はしごの根元でおもりの矢印4本が重なって
    //   肝心の黄色い摩擦の矢印が埋まる。
    mass:LAD_LOAD, friction:0.6, frictionStatic:0.6, restitution:0,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5, label:`おもり ${LAD_LOAD}kg` });
  ladPutLoad(lad, load, 1);
  objects.push(load);
  // ── 滑り出したら止めるプログラム ─────────────────────────────
  //   ★「速さが 0.2 m/s 以上になったら → 実行を止める」。滑り出すとすぐ倒れてしまうので、
  //     滑り出した直後の画面で止めて、どの窪み・どの μs で滑ったかを落ち着いて読ませる。
  //   ★しきい値は 0.2 m/s（2026-10-01。止まった時点で動摩擦に落ちていてよい、はユーザーの判断）。
  //     止まった時点で床の摩擦はもう動摩擦 μk·N に落ちている（実測 f/N = 0.100）。
  //     0.1 では、おもりを持ち上げた瞬間のはしごの跳ね返り（はしごは 1px しか動かないのに速さが
  //     一瞬 0.185 m/s）で止まった。0.2 ならそれを越え、本当に滑ったときは 6〜43 tick・傾き 0.3°
  //     以内（まだ立っている）で止まる（実測：μs 0.25 の 5 m・6 m、μs 0.20 の 3 m・4 m）。
  //     ★運ぶおもりをはしごの桟にぶつけると、はしごは本当に押されて滑る（実測 −254px 倒れた）。
  //       これは誤停止ではなく、止まって正しい。上限 μs·N に張りついた瞬間で止めるには
  //     切り替わり（0.05 m/s）より手前の 0.02 m/s が要るが（そこで止めると f/N = 0.200／0.250）、
  //     0.02 ではおもりを運ぶ・置くときの揺れで止まってしまった（実測：手の速さ 1 m/s で運ぶと
  //     はしごの速さ 0.020〜0.040、一時停止中に 10px 上へ置いて ▶ で 0.021〜0.077 m/s）。
  //     本文にも「止まったときは、すでに動摩擦に変わっている」と書く。
  const pg = addProgram(lad);
  if (pg) {
    pg.trigger = 'speed'; pg.spdMin = 0.2; pg.spdMax = 100; pg.action = 'pause';
    pg.collapsed = true; pg.fx = 0.055; pg.fy = 0.55;
    pg.reset(); syncProgramState(pg); syncProgramPanel(pg); placeProgramPanel(pg);
  }
  // ── 床の静止摩擦係数のつまみ ──────────────────────────────
  //   ★床側は 1 にしてあるので、はしご側の μs がそのまま床の静止摩擦係数になる。
  //   ★範囲 0.10〜0.40。滑らずに立つのに要る μs は、床の摩擦 ÷ 全体の重さ ＝ N_壁 ÷ 294 N で、
  //     窪み 1〜6 m で 0.147／0.175／0.202／0.230／0.257／0.285、おもり無しで 0.246（上の N_壁 の実測から）。
  //     この範囲なら「どの窪みでも滑る」から「どの窪みでも立つ」までを回せる。
  //     実測（2026-10-01。二分法・300 tick で 5px 以上動いたら滑り）：なし 0.246／1 m 0.147／2 m 0.175／
  //     3 m 0.202／4 m 0.230／5 m 0.257／6 m 0.285 ＝ 上の理論値と小数第3位まで一致。
  const knob = addRemote('prop', lad, 'body');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'frictionStatic'; knob.lo = LAD_MU_LO; knob.hi = LAD_MU_HI;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '壁に立てかけたはしご');
  demoNote (p.x, p.y + 54,
    'なめらかな壁（摩擦 0）に 60°で立てかけた 7 m・20 kg のはしご。\n'
  + '倒れないように支えているのは、床の摩擦だけ。\n'
  + '上の面は桟が突き出た凸凹で、窪みにおもりを置くとそこへひっかかる。\n'
  + '矢印の色： 重力＝赤　垂直抗力＝青　摩擦＝黄\n'
  + '\n'
  + '【手順】▶実行 を押してから、編集ツールで\n'
  + '　おもりをつまんで、上下の窪みへ置き替える（窪みは根元から 1〜6 m の6か所）\n'
  + '\n'
  + '【読みどころ】高い窪みに置くほど滑りやすい\n'
  + '・おもりを 1 m 高い窪みへ移すごとに、壁が押し返す力は 8.1 N ずつ増える\n'
  + '　（＝ おもりの重さ × cot60° ÷ はしごの長さ）。置く高さだけで決まる\n'
  + '・床が出せる摩擦の上限は μ(20+10)g ＝ 73.6 N。どこに置いても変わらない\n'
  + '・実測：1〜4 m の窪みなら立ったまま。5 m（75.7 N）で上限を超えて滑り出す\n'
  + '・滑り出すと自動で止まる（左のプログラム）。止まったときの床の摩擦は、\n'
  + '　もう動摩擦に変わっている。おもりを桟にぶつけて押しても滑って止まる\n'
  + '\n'
  + '【もう一手】左下のつまみで床の静止摩擦係数 μs を変える（↩ で戻してから）\n'
  + '・立つのに要る μs：1 m 0.15 ／ 3 m 0.20 ／ 5 m 0.26 ／ 6 m 0.29\n'
  + '　＝ 高い窪みほど大きな μs が要る。0.29 以上ならどこに置いても立つ');
}

// ── 物体が傾く条件 ─────────────────────────────────────
//   ★見せたいのは「垂直抗力の作用点が動く」こと。垂直抗力は面のどこか1点に働く量では
//     なく、底面ぜんぶに分布した圧力の合力で、その合力の作用点は力のつりあいで決まる。
//     引く力が強いほど前へ寄り、底面のかどに届いたところで行き場を失う ＝ そこが傾く条件。
//   ★これはこちらで描く絵ではなく、ソルバが実際に出している値をそのまま見ている。
//     地面の接触は底面の2つのかどで別々に解かれ（js/physics/ground.js:257）、
//     どちらも同じキー 'ground0' で recordForce される。recordForce は同じキーの力を
//     大きさで重みづけした位置に集約する（js/physics/body.js:344）ので、
//     矢印の足もとが2つのかどの荷重の重心 ＝ 垂直抗力の作用点そのものになる。
//   ★箱は1つだけ置き、引く力はつまみ（リモコン）で 0 から上げていく（摩擦のデモと同じ）。
//     並べる形では「作用点がじりじり前へ寄っていく」が飛び飛びの5枚の絵にしかならず、
//     かどに届いて傾き出す瞬間そのものが見えない。つまみなら、傾く直前で手を止めて
//     かどで支えたまま眺めることも、そこから 0.03 N ずつ上げて越えることもできる。
//   ★つまみの範囲は 0〜6 N（0.03 N 刻み）。傾き出す力 4.9 N の少し上までで、
//     この箱が滑り出す力 μmg = 13.7 N には決して届かない ＝ つまみを端まで回しても
//     「滑る」ほうは起きない（このデモで見せたいのは傾くほうなので、そこは塞いでおく）。
//     下限は 0（摩擦のデモと同じ。引いていない状態へいつでも戻せること）。
//   ★実測：垂直抗力の作用点は 1.5／3.0／4.5 N で 0.245／0.490／0.734 m ＝ 理論 F·H/(mg)
//     と小数第3位まで一致する。傾きかけてから 0 へ戻すと、12° までなら起き上がる
//     （勢いで 20° まで行って戻る）。15° まで待つと重心がかど（26.57°）を越えて倒れ切る。
//   ★理論値：高さ H のところを F で引くと、垂直抗力の作用点は中心から
//       x_N = F·H / (mg)
//     だけ前へ寄る（重心まわりの力のモーメントのつりあい。引く力と摩擦力がどちらも
//     重心から H/2 ずれていて、同じ向きのモーメントを作るので H/2 が2つ分で H になる）。
//     x_N が底面の半分 W/2 に届くのが傾く条件で、そのときの力は F = mg·W/(2H)。
//   ★寸法は「傾く力と重力が同じ桁になる」ように選んだ。F_tip/mg = W/(2H) なので、
//     細長くするほど小さい力で傾くが、矢印の長さの比が開いて短いほうが最小長に潰れる。
//     W=160px・H=320px なら比が 1/4 で、mg 19.6N の矢印 196px に対し傾く力 4.9N が 49px。
//   ★摩擦は μ = W/(2H) = 0.25 より大きくないと、傾く前に滑る。この箱は 0.7 にして傾かせる。
//     地面側は 1.0 にしてある（合成は積なので、そのとき箱側の値がそのまま効く）。
//   ★「μ が 0.25 より小さいと滑るほうが先」は本文に書くだけにして、箱を並べない。
//     つまみ1つで見せられないため：摩擦のつまみは μk しか動かせず（applyBodyProp は
//     μs ≧ μk を保つので μs を下げ切れない）、滑り出す力を決めるのは μs のほう。
// ── 右半分：モーターで傾く板 ──────────────────────────────
//   ★同じ箱を「立てて置く」と「寝かせて置く」で板に載せ、板を傾けていく。倒れ出す角は
//     tanθ = 幅/高さ、滑り出す角は tanθ = μ。小さいほうが先に起きるので、立てた箱
//     （幅/高さ = 0.5 → 26.6°）は倒れ、寝かせた箱（2.0 → 63.4°）は先に滑る（35.0°）。
//     質量も摩擦も同じで、置く向きだけが違う。
//   ★板は**軸（モーター）で回す**。角度を書き換える方式は使えない：テレポートでは接触に
//     回転が伝わらず、箱が板についてこない（板だけ傾いて箱は水平のまま板のかどで立ち、
//     26.6° に届く前に転倒した。実測 0→25° でずれ −281〜−674px・傾き −92〜−245°。
//     支点からの距離を 40〜300px、刻みを 0.225° まで振っても変わらない）。駆動（constVel）も
//     不可：回転は普通に受ける（body.js:363 の★）ので荷重で板が勝手に回る。
//     モーターならトルクで回る＝回転がソルバを通るので、接触が箱をきちんと運ぶ。
//   ★リモコンを放したら止める（joint.js の motorBrake）。放して軸が自由になると、支点より
//     重心が上にあるので板は倒れ切る（実測：20° で放すと 1秒で +7.3°、5秒で 112°）。
//     止める側にすると 15秒たっても 20.05°。
//   ★**押しては放す**で読む。押しっぱなしで連続に回すと読みが遅れる（実測：立てた箱が
//     倒れる角は 1.5°/s で 28.2°、3°/s で 29.4°、6°/s で 31.2°。逆に 0.5°/s まで落とすと
//     時間がかかりすぎて両方とも這いが溜まり 23° で崩れた）。1°ずつ押しては放す形なら
//     立てた箱 26.1°／寝かせた箱 34.0°（理論 26.57°／34.99°）で、どちらも 1° 以内に入る。
//     回す速さ 3°/s がその値。手順にも「少し傾けて、放して見る」と書く。
//   ★倒れるほうの箱を谷側に置く。山側だと、倒れた箱が滑り落ちて相手を突き、相手が
//     29.5° で「滑り出した」ように見えた（実際は 35.0° まで滑らない）。
const TIP_RAMP_W = 760, TIP_RAMP_H = 30;   // [px] 板
const TIP_RAMP_X = 680, TIP_RAMP_Y = -310; // [px] 板の中心＝支点（中央で支えた板）
const TIP_RAMP_W_DEG = 3;                  // [°/s] 板を回す速さ（上の★）
const TIP_W = 160;      // [px] 箱の幅（1.6 m）
const TIP_H = 320;      // [px] 箱の高さ（3.2 m）
const TIP_M = 2;        // [kg]
const TIP_MU = 0.7;     // 箱と床の摩擦（地面側が 1.0 なのでこれがそのまま効く）
const TIP_FMAX = 6;     // [N] つまみの上限（上の★。傾き出す 4.9 N の少し上）
const TIP_X = -420;     // [px] 平らな床の箱（左半分。右へ倒れ込む余地を空ける）
function demoTipping() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;      // ★眠ると拘束力の矢印が消える（いろいろな力のデモの★）
  // ★[画面px per N]。重力 19.6 N が 157px、引く力 0〜6 N が 0〜48px。
  //   10 にすると重力の矢印が 196px になり、重心から下向きに伸びて画面の下端を割る。
  world.forceVizScale = 8;
  // ★刻みを 4 → 16 に上げる。傾かないはずの箱が、引かれている向きと逆（左）へ
  //   ゆっくり這っていくため。這う速さは引く力に比例し、刻みに反比例する
  //   （実測、30秒の移動：刻み4 … −12.6／−25.8／−39px、刻み8 … その半分、
  //     刻み16 … −2.8／−6.1／−9.4px。反復回数は 8→60 まで振っても1桁も変わらない
  //     ＝ ソルバの収束ではなく、1サブステップの離散化そのものが出している）。
  //   刻み16 なら 30 秒で 9.4px＝画面上 4px で、静止して見える。
  //   ★つまみにした今の実測：傾く直前の 4.8 N で 10 秒たっても這いは 0.4px。
  //     傾き出すのは 4.9 N から（理論 4.903 N）で、境目はつまみの1目盛（0.03 N）に収まる。
  world.substeps = 16;
  updateGroundTerrain(true);
  ground.friction = 1; ground.frictionStatic = 1;   // ★合成は積。箱側の値がそのまま効く
  setDemoCam(60, 0.45);
  const box = new Body({ type:'box', x:TIP_X, y: gy - TIP_H/2, w:TIP_W, h:TIP_H, mass:TIP_M,
    friction:TIP_MU, frictionStatic:TIP_MU, restitution:0,
    // 右向き。大きさはつまみで。力点は★引く側の上のかど
    thrusters:[{ force:0, dir:0, localX: TIP_W/2, localY: -TIP_H/2 }],
    showForces:true, label:`2 kg・μ=${TIP_MU}`,
    fillColor:'#5c6bc0', strokeColor:'#c5cae9', strokeWidth:2 });
  objects.push(box);
  // ── 右半分：中央で支えた板を、モーターで傾ける ──────────────
  const ramp = new Body({ type:'box', x:TIP_RAMP_X, y:TIP_RAMP_Y, w:TIP_RAMP_W, h:TIP_RAMP_H,
    mass:20, friction:1, frictionStatic:1, restitution:0,   // ★合成は積。箱側の値が効く
    label:'板', fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:2 });
  objects.push(ramp);
  //   ★軸は板の中心＝支点。放したら止める（上の★）。回す速さは 3°/s。
  const axle = new Joint({ type:'axle', bodyA:null, bodyB:ramp,
    anchorAx:TIP_RAMP_X, anchorAy:TIP_RAMP_Y, anchorBx:0, anchorBy:0,
    motorSpeed: TIP_RAMP_W_DEG * Math.PI / 180, motorTorque:288, motorBrake:true });
  joints.push(axle);
  //   ★モーターを正に回すと右端が下がる（内部の y は下向きが正）。倒れるほうの箱＝
  //     立てた箱を谷側＝右に置く。
  const onRamp = (u, w, h, label) => objects.push(new Body({
    type:'box', x:TIP_RAMP_X + u, y:TIP_RAMP_Y - TIP_RAMP_H/2 - h/2, w, h, mass:TIP_M,
    friction:TIP_MU, frictionStatic:TIP_MU, restitution:0, label, showForces:true,
    fillColor:'#5c6bc0', strokeColor:'#c5cae9', strokeWidth:2 }));
  onRamp(-190, TIP_H, TIP_W, '寝かせて置く');   // 山側。幅3.2m×高さ1.6m → 滑るほうが先
  onRamp( 180, TIP_W, TIP_H, '立てて置く');     // 谷側。幅1.6m×高さ3.2m → 倒れるほうが先
  // ── リモコン3つ ──────────────────────────────────────
  //   ★それぞれの題材のそばに置く（画面の対角に離すと、動かしながら見るのがつらい）。
  //     引く力のつまみは左下（箱の左）、板の2つは右上（板の見出しの上）。
  //   ★板の2つを板の下に置くと、板の上の箱から下へ伸びる重力の矢印（赤）に被って
  //     見えなかった（2026-10-02、ユーザーの指摘で上へ移した）。上は見出しまでの
  //     高さしか空いていないので、畳んで置く（畳んでも「押す」ボタンとキーは残る）。
  //   ★板は「傾ける」と「戻す」の2つ。1つのリモコン＝1つのキー＝1つの向き（remote.js の★）
  //     なので、逆回転は〈逆に効く〉にしたリモコンをもう1つ置く形になる。
  const knob = addRemote('prop', box.thrusters[0], 'thruster');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'force'; knob.lo = 0; knob.hi = TIP_FMAX;
    knob.fx = 0.055; knob.fy = 0.62;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  const rmMotor = (mode, key, fx) => {
    const r = addRemote('motor', axle);
    if (!r) return;
    r.kind = 'motor'; r.mode = mode; r.key = key; r.fx = fx; r.fy = 0.10; r.collapsed = true;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  rmMotor('on',  'ArrowDown', 0.52);   // 傾ける
  rmMotor('rev', 'ArrowUp',   0.70);   // 戻す
  // ★止めたまま矢印を出すための空回し。①は F = 0 で開くので垂直抗力は底面の中央に立ち、
  //   ②の2つは水平な板の上なので青（垂直抗力）が真上、黄（摩擦）は 0 で出ない。
  //   ★板とリモコンを作った「あと」に呼ぶこと。前に置くと②の2つはまだ存在せず、
  //     ▶実行 を押すまで矢印が出ない（①だけ矢印がある画面で開くことになる）。
  //     リモコンより後ろなのは、放している状態（motorBrake で角度を保つ）で空回しさせるため。
  //   ★demoWarmForces は全物体の位置・角度・速度を控えて戻すので、空回しのあいだに
  //     板が 1.5° ほど回っても元へ戻る（demo-kit.js:123）。
  demoWarmForces(30);
  // 見出しは題材の上に1つずつ。★②の高さは、板がいちばん傾いたときに山側の箱が
  //   上がってくる先（画面 y 273）より上。①は倒れたあとの垂直抗力の矢印が届かない高さ。
  //   ★②の箱にも矢印を出したので、青い矢印の先端も見出しの下でなければならない。
  //     0〜45° を1°ずつ通して測った最高点は画面 y 275（板 14.1°のとき）で、見出しの
  //     y 233 まで 42px 空いている。ここは箱そのものの高さ（y 273）とほぼ同じ：
  //     垂直抗力の矢印は 19.6 N × 8 = 157px だが板に垂直なので、板が傾くほど
  //     真上への伸びが cos θ で縮み、箱が上がるぶんと打ち消し合うため。
  demoLabel(TIP_X - 120,      gy - TIP_H - 210,   '① 平らな床で引く');
  demoLabel(TIP_RAMP_X - 120, TIP_RAMP_Y - 480,   '② 板を傾ける');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '物体が傾く条件');
  demoNote (p.x, p.y + 54,
  // ★本文の1行は 38 文字（画面の 400px）まで。それを超えると右上のツールヒントの
  //   帯（画面の 420px から右）の下へ潜る（実測：44 文字の1行目が帯に掛かった）。
    '同じ箱（2 kg・μ = 0.7）を2通りの向きで見る。\n'
  + '矢印の色： 重力＝赤　垂直抗力＝青　摩擦＝黄　引く力＝橙\n'
  + '\n'
  + '【① 平らな床】左下のつまみで、上のかどを引く力を少しずつ大きくする\n'
  + '・青い矢印（垂直抗力）の足もとを見る。引く力が強いほど前（右）へ寄っていく。\n'
  + '　重力とつりあうために大きさは変わらないのに、働く場所だけが動く\n'
  + '・作用点は底面のかどより前へは出られない。そこに届いたところで傾く\n'
  + '　　傾き出す力 F ＝ mg × 幅 ÷ (2 × 高さ)\n'
  + '・かどに届く直前で手を止めると、かどで支えたまま釣り合って止まる\n'
  + '・傾き始めてすぐならつまみを 0 に戻せば起き上がる。重心が底面のかどの真上を\n'
  + '　越えてしまうと、もう戻らない\n'
  + '\n'
  + '【② 板を傾ける】↓キー（右上のリモコン）を短く押しては放し、少しずつ傾ける\n'
  + '　（放すと板はその角度で止まる。↑キーで戻せる。押しっぱなしにせず、\n'
  + '　　止めた状態で見ること）\n'
  + '・立てた箱は倒れ、寝かせた箱は滑る。同じ箱・同じ摩擦で、置く向きが違うだけ\n'
  + '　　倒れ出す角 tanθ ＝ 幅 ÷ 高さ　　　滑り出す角 tanθ ＝ μ\n'
  + '・板の上の2つにも矢印が出る。青は板に垂直で mg cosθ、黄は板に沿って\n'
  + '　上向きで mg sinθ ＝ 赤い矢印1本を2つの向きに分けたものが出ている\n'
  + '・小さいほうが先に起きる。立てた箱は幅÷高さが小さいので倒れるほうが先、\n'
  + '　寝かせた箱は大きいので滑るほうが先になる');
}

// ── 回転エネルギー（中実の円・中空の円・滑る箱を斜面で競走させる）──────────
//   ★見せたいのは「同じ高さから出発しても、回転にエネルギーを取られるぶん遅い」の1点。
//     斜面を転がる物体の加速度は a = g sinθ / (1 + I/mR²) で、質量にも半径にもよらず
//     「質量がどれだけ軸から離れて分布しているか」だけで決まる。
//     　滑る箱（回らない）… I/mR² = 0    → a = g sinθ
//     　中実の円         … I/mR² = 1/2  → a = (2/3) g sinθ
//     　中空の円         … I/mR² → 1     → a = (1/2) g sinθ
//   ★中空の円は「大きい円から小さい円を型抜きした形」そのもの。手で作れる：
//     円を2つ描いて両方選び、［型抜き (A−B)］。ブーリアンの結果は多角形だが、
//     js/physics/arc.js が「元は円だった区間」を円弧として復元するので、外周も内周も
//     真円のまま接触が解かれる（多角形のままだと角のたびにエネルギーが抜けて転がらない）。
//     慣性モーメントも穴を差し引いて計算される（js/physics/body.js の _calcInertiaPolygon）。
//   ★質量は3つとも 2 kg に揃える。型抜きしたリングは面積が減るぶん密度から決まる質量が
//     軽くなるので、プロパティ欄で 2 kg に直す（＝手順としても「質量を揃える」1手だけ）。
//     どうせ a は質量によらないが、揃えないと「軽いから速いのでは」と読まれてしまう。
//   ★摩擦は転がる2つだけ 1（滑らずに転がる条件）。箱は 0 にする。合成は積なので、
//     箱側を 0 にすれば斜面の値によらずその接触は摩擦 0 になる。
//   ★3本の走路は「真横にずらすだけ」にする。斜面に垂直な向きへ ROT_LANE ずらすと同時に
//     斜面に沿って ROT_LANE/tanθ だけ上へ戻すと、差し引きがちょうど真横 ROT_LANE/sinθ の
//     平行移動になり、3本の出発点も終点もそれぞれ1本の水平線に乗る。
//     ★これは見た目の都合ではない。単に垂直方向へ積むと、走路1本ぶん（1.75 m）高さが
//       違ってしまい、位置エネルギーの初期値が 2×9.8×1.75 ＝ 34 J ずれる（実測：
//       垂直に積んだときは 中実 30.6 J ／ 中空 60.1 J だった）。2枚のエネルギーグラフを
//       見くらべるデモなので、この差が入ると「中空のほうがエネルギーが多い」と読める。
//       真横にずらした今は、3枚とも E(0) が同じ 85.1 J から始まる（下の高さの基準の★）。
//     ★横に広くなるが、そのぶん縦は斜面の落差だけで済む。説明文（左うえ）と
//       グラフ2枚（右）の場所がそのぶん確保できる。
//   ★走路の間隔は「2R ＋ 板の厚み」より広く取る。狭いと物体の頭が1つ上の走路の裏に
//     当たって止まる（実測：間隔 150・R 75・厚み 44 では、中実と箱が 0.7 秒で急停止した。
//     頭は 150px あるのに、上の走路の裏は 106px しかなかった）。
//     いまは 175 ＞ 130 + 30 ＝ 160 で、余裕 15px。
//   ★実測（40°・7 m・2 kg。6.0 m 通過を「ゴール」として 180 tick）：
//       ゴール到達  滑る箱 1.383 s（理論 1.380）／中実 1.700（1.690）／中空 1.883（1.873）
//       滑りゼロ    転がる2つの接触点の速度 |v − ωR| は全 tick で 0.001 px/s 以下
//       中実がゴールした瞬間、中空はまだ 4.95 m ＝ 1.13 m 後ろにいる
//       ゴール時のエネルギー内訳 [J]  中実 並進 51.0 ／ 回転 25.5（回転が 33%）
//                                     中空 並進 41.5 ／ 回転 35.0（回転が 46%）
//                                     合計は 76.6 と 76.5 ＝ 減った位置エネルギーと同じ
//   ★中空の円の内径は 54px（外径 65px）。I/mR² = (1 + (54/65)²)/2 = 0.843 で、
//     教科書の薄い輪（1.0）ではない。壁を薄くするほど 1 に近づくが、画面上（既定倍率
//     0.44）で 5px を切ると輪に見えなくなる。11px は折り合い。説明文にも 0.84 と書く。
const ROT_DEG   = 40;    // [°] 斜面の傾き
const ROT_LEN   = 700;   // [px] 斜面の長さ（7.0 m）
const ROT_LANE  = 175;   // [px] 走路どうしの間隔（斜面に垂直に測る）
const ROT_R     = 65;    // [px] 円の外径
const ROT_RIN   = 54;    // [px] 中空の円の内径
const ROT_BOXW  = 110;   // [px] 滑る箱の長さ（斜面に沿う向き）
const ROT_M     = 2;     // [kg] 3つとも同じ
// 中空の円（型抜きした輪）のローカル頂点。★ブーリアンと同じ 48 角形近似で作り、
//   detectArcs で外周・内周の両方を円弧として持たせる（角でエネルギーを失わないため）
const ROT_SEG = 48;
function rotRingBody(opts) {
  const outer = [], hole = [];
  for (let i = 0; i < ROT_SEG; i++) {
    const a = i / ROT_SEG * Math.PI * 2;
    outer.push({ x: ROT_R   * Math.cos(a),  y: ROT_R   * Math.sin(a)  });
    hole .push({ x: ROT_RIN * Math.cos(-a), y: ROT_RIN * Math.sin(-a) });   // 穴は逆巻き
  }
  return new Body(Object.assign({
    type:'polygon', verts:outer, holes:[hole],
    arcs: detectArcs(outer, [hole], [{cx:0,cy:0,r:ROT_R},{cx:0,cy:0,r:ROT_RIN}]) }, opts));
}
function demoRollingEnergy() {
  resetDemoWorld();
  world.substeps = 16;         // ★斜面を転がるあいだの取りこぼしを減らす（保存のデモの★）
  world.sleeping = false;
  updateGroundTerrain(false);  // ★走路そのものが地面。世界の地面は使わない
  const th = ROT_DEG * Math.PI / 180;
  const dx = Math.cos(th), dy = Math.sin(th);      // 斜面を下る向き（yは下が正）
  const nx = dy, ny = -dx;                         // 走路の上向き法線
  const HALF = 15;                                 // 走路の板の厚みの半分
  const SHIFT = ROT_LANE / Math.sin(th);           // 走路1本ぶんの真横のずれ（上の★）
  // ★高さの基準。位置エネルギーの U=0 面は「原点を通り重力に垂直な面」に固定されていて
  //   （js/physics/energy.js）動かせないので、走路の側を上下させて基準に合わせる。
  //   合わせる先は「走り終えて止まったときの重心」＝ゴールの壁に着いた位置。こうすると
  //   下りきったところで U=0、走っているあいだは U>0 になり、力学的エネルギーの線が
  //   並進・回転より必ず上に来る（＝グラフの上端が保存量、その内訳が下の2本、と読める）。
  //   ★実測（中空の円）：合わせる前は U が +41.1 J → −42.8 J と符号を変え、
  //     K は最大 83.4 J ＝ 力学的エネルギー 41.1 J の線を追い越して見えていた。
  //     合わせた後は E = 85.1 J のまま、K は最大 83.4 J でその下に収まる（3つとも
  //     走行中ずっと K < E(0)。U の最小は 中空・中実 +1.12 J／箱 −0.08 J ＝めり込み分）。
  //   ★止まる位置がいちばん深いのは滑る箱（半分の長さ 55px が円の半径 65px より短いぶん
  //     壁に近づける）。そちらに合わせて、3つとも U が負にならないようにする。
  //   ★x は据え置き。3本ぶんの広がり（−778〜+739px）が原点まわりに揃う値。
  const STOP_S = ROT_LEN + 45 - 15 - ROT_BOXW/2;   // ゴールの壁（中心 s=+45／厚み30）の手前
  const START = { x: 20, y: -(dy*STOP_S + ny*ROT_R) };
  // 走路の上の位置。s＝斜面に沿って下った距離、h＝面からの高さ。
  //   i = 0:中空 / 1:中実 / 2:滑る箱（速い順に左へ並ぶ）
  const laneAt = (i, s, h) => ({
    x: START.x + dx*s + nx*h - SHIFT*i,
    y: START.y + dy*s + ny*h });
  for (let i = 0; i < 3; i++) {
    const c = laneAt(i, ROT_LEN/2, -HALF);
    objects.push(new Body({ type:'box', x:c.x, y:c.y, w:ROT_LEN + 130, h:HALF*2, angle:th,
      isStatic:true, mass:0, friction:1, frictionStatic:1, restitution:0,
      fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2 }));
    // ゴールの壁（走路の下端に垂直に立てる）。★これが無いと画面の外まで走り去る
    //   ★摩擦 0 にする。摩擦があると、当たったあとも回り続けている円が壁を「登る」。
    //     実測：中空の円は 661px/s・10.2rad/s で当たったあと、斜面に沿った位置は
    //     止まったまま速さ 220px/s で 15 tick かけて壁を駆け上がった。
    //   ★壁は円の直径（130px）より高くする。120px では壁のてっぺんの角が、
    //     中空の円の穴の口（面から 11〜119px）にちょうど並ぶ。登ってきた円がその角を
    //     穴に飲み込んで壁に「串刺し」になり、行き過ぎた位置（+57px）からソルバの
    //     位置補正で 67px 引き戻される ＝ 画面ではワープに見えた。
    //     160px なら角は円より上に出る。上の走路の裏（175px）にも当たらない。
    const g = laneAt(i, ROT_LEN + 45, 80);
    objects.push(new Body({ type:'box', x:g.x, y:g.y, w:30, h:160, angle:th,
      isStatic:true, mass:0, friction:0, frictionStatic:0, restitution:0,
      fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:2 }));
  }
  const put = (i, body) => { const p = laneAt(i, 0, ROT_R); body.x = p.x; body.y = p.y;
                             body._invalidateShape(); body._updateAABB(); objects.push(body); };
  // ① 中空の円（型抜きした輪）
  const ring = rotRingBody({ mass:ROT_M, friction:1, frictionStatic:1, restitution:0,
    fillColor:'#26a69a', strokeColor:'#b2dfdb', strokeWidth:2, label:'中空の円 2kg' });
  put(0, ring);
  // ② 中実の円
  const solid = new Body({ type:'circle', radius:ROT_R, mass:ROT_M,
    friction:1, frictionStatic:1, restitution:0,
    fillColor:'#ffa726', strokeColor:'#ffe0b2', strokeWidth:2, label:'中実の円 2kg' });
  put(1, solid);
  // ③ 滑る箱。★摩擦 0（＝回転を起こす力が無い）。念のため回転も止める
  const box = new Body({ type:'box', w:ROT_BOXW, h:ROT_R*2, mass:ROT_M, angle:th,
    friction:0, frictionStatic:0, restitution:0, fixedRotation:true,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:2, label:'滑る箱 2kg' });
  put(2, box);
  // ── グラフ（1窓 = 1系）。3つの内訳を縦に並べて見くらべる ────────────
  //   ★位置エネルギーの減りは3つとも同じなのに、その行き先が違う ＝ 読みどころ。
  //     滑る箱の窓は「運動(回転) が 0 のまま」を見せる係。3つ並べて初めて、
  //     0 → 33% → 46% と回転の取り分が増えていく並びになる。
  //   ★3枚を右の列へ等間隔に積む。エネルギーの窓は既定 420×450px なので、そのままでは
  //     1枚しか置けない。高さの内訳を測ると 見出し15 + グラフ155 + 操作15 + 操作17
  //     + 基準の説明45 + ボタン25 + 余白と隙間48 ＝ 320px で、このうち「基準の説明」は
  //     3枚に同じ文が並ぶだけなので畳む。グラフ自身の下限 150px も外して 80px にすると、
  //     1枚 218px まで詰まり 3枚が 736px に収まる（グラフ面は 100px 残る）。
  //   ★高さは画面から割り出す。決め打ちにすると、背の低い窓で3枚目が下に沈む。
  const opt = { showKt:true, showKr:true, showUg:true, showMech:true,
                showUs:false, showUgg:false, showUe:false };
  const GTOP = 56, GBOT = 10, GGAP = 8, GW = 400;
  const gh = Math.max(180, Math.floor((canvas.height - GTOP - GBOT - GGAP*2) / 3));
  [box, solid, ring].forEach((b, i) => {
    const g = eneGraphNew([b.id], opt);
    if (!g || !g.panel) return;
    const p = g.panel;
    p.style.top = (GTOP + i*(gh + GGAP)) + 'px'; p.style.bottom = 'auto';
    p.style.right = GBOT + 'px'; p.style.left = 'auto';
    p.style.minHeight = '0'; p.style.height = gh + 'px';
    p.style.minWidth  = '0'; p.style.width  = GW + 'px';
    const cv = p.querySelector('canvas'); if (cv) cv.style.minHeight = '80px';
    const ref = p.querySelector('.eg-ref-note'); if (ref) ref.style.display = 'none';
  });
  // ── カメラ ────────────────────────────────────────
  //   ★このデモは setDemoCam を使わない。地面を使わない（走路そのものが地面）ことに
  //     加えて、右の GW+GBOT がグラフ3枚で埋まるので「画面の中央に置く」が成り立たない。
  //     置き場所は左の帯だけなので、題材の実際の広がりからその帯へ合わせて決める。
  //   ★決め打ちの倍率にしないのは、グラフの列の幅が画面幅に対して一定でないため。
  //     幅の狭い窓ほど左の帯は細くなるので、倍率もそれに追従する必要がある。
  let mnX = Infinity, mxX = -Infinity, mnY = Infinity, mxY = -Infinity;
  for (const o of objects) {
    const a = o._aabb;
    if (a.minX < mnX) mnX = a.minX;  if (a.maxX > mxX) mxX = a.maxX;
    if (a.minY < mnY) mnY = a.minY;  if (a.maxY > mxY) mxY = a.maxY;
  }
  const availW = canvas.width - (GW + GBOT + 26);      // グラフの列を除いた幅
  const availH = canvas.height * 0.52;                 // 説明文の下に残る帯
  cam.zoom = Math.min(availW / (mxX - mnX + 60), availH / (mxY - mnY + 60));
  cam.x = (mnX + mxX)/2 - (availW/2 + 13 - canvas.width /2) / cam.zoom;
  cam.y = (mnY + mxY)/2 - (0.66*canvas.height - canvas.height/2) / cam.zoom;
  //   ★説明文の大きさは倍率から逆算する（画面上 14px 相当）。ここを決め打ちにすると、
  //     上で倍率を画面に合わせた意味が無くなり、窓の大きさで文字だけ大小する。
  const NS = Math.round(14 / cam.zoom);
  // ── 同じ高さであることを線で見せる ───────────────────────
  const hLine = (y, x0, x1) => annotations.push(new Annotation({
    type:'path', x:x0, y, color:'#78909c', width:2, pts:[{x:0,y:0},{x:x1-x0,y:0}] }));
  //   ★線は「走路2の端から走路0の端まで」。3本は真横にずれているだけなので、
  //     出発点どうし・ゴールどうしがそれぞれ1本の水平線に乗る（それがこの配置の主張）。
  const xs = i => laneAt(i, 0, 0).x, xg = i => laneAt(i, ROT_LEN, 0).x;
  hLine(START.y,              xs(2) - 90, xs(0) + 90);
  hLine(START.y + ROT_LEN*dy, xg(2) - 90, xg(0) + 90);
  //   ★札は1枚だけ、ゴールの線の下に置く。出発の線の上下は物体と走路の板で埋まっていて
  //     置く場所が無い（実測：線の 60px 上は箱の胴体の真ん中、130px 上は説明文の中。
  //     線の左外は画面の外だった）。空いているのはゴールの線より下だけ。
  //   ★大きさは説明文と同じ NS。demoLabel は既定 23px 固定で、この倍率では画面上 10px
  //     にしかならない（説明文だけ 34px に上げてあるので、札だけ取り残される）。
  annotations.push(new Annotation({ type:'text', size:NS, bold:true, color:'#b0bec5',
    x: xg(2) - 90, y: START.y + ROT_LEN*dy + 60,
    text: '↑ スタートもゴールも、3本とも同じ高さ' }));
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '回転エネルギー', 44);
  demoNote (p.x, p.y + 78,
    '同じ 2 kg・同じ高さから、40°の斜面を 7 m 下る3つ。\n'
  + '中空の円は、大きい円から小さい円を［型抜き］して作った輪。\n'
  + '走路は真横にずらしてあるだけで、出発もゴールも同じ高さ。\n'
  + '\n'
  + '【手順】▶実行 を押して、ゴールの線に着く順番を見る\n'
  + '\n'
  + '【読みどころ】減った位置エネルギーが 並進 と 回転 に分かれる\n'
  + '・a = g sinθ ÷ (1 + I/mR²)　質量にも半径にもよらない\n'
  + '　　I/mR² は 滑る箱 0（回らない）／中実 0.50／中空 0.84\n'
  + '・実測 6 m 地点：箱 1.38 秒 → 中実 1.70 秒 → 中空 1.88 秒\n'
  + '・そのときの内訳 [J]　中実 並進 51.0 / 回転 25.5（回転が 33%）\n'
  + '　　　　　　　　　　　中空 並進 41.5 / 回転 35.0（回転が 46%）\n'
  + '　合計はどちらも 76.5 J で同じ。行き先の割りふりだけが違う\n'
  + '・高さの基準はゴール。位置エネルギーは下りきって 0 になるので、\n'
  + '　　グラフのいちばん上の線がいつも 力学的エネルギー', NS);
}

// ── 剛体振り子（物理振り子）と 撃心 ───────────────────────────
//   ★この2つは「同じ式 I_O/(md) から出る同じ長さ 2L/3」でつながっている。
//     長さ L・一様な棒を端で吊るすと I_O = mL²/3、重心までの距離 d = L/2 なので
//       ・相当単振り子の長さ  l = I_O/(md) = 2L/3   … 同じ周期で振れる単振り子の長さ
//       ・撃心（打撃の中心）  q = I_O/(md) = 2L/3   … そこを叩くと支点に力がかからない点
//   ★つながっているのにデモを2つに分けてあるのは、読み方が正反対だから。
//     振り子は ▶実行 を押して何往復も見るもの。撃心は「押した瞬間」の図で、
//     止めたまま矢印を読むもの（下の★のとおり、動かすと成り立たない）。
//     1画面に同居させると手順が「①は止めたまま、②は動かして」と割れるうえ、
//     ▶のあと暴れる撃心側を押さえるための部品（支柱）が要る。その支柱は
//     一定の力で押され続ける棒を止めきれず、実測で 2 m の棒が毎秒 0.78°ずつ
//     めり込み、3 m の棒は 15 秒で貫通した（「物体が傾く条件」の★と同じ、
//     刻みに反比例して這う現象）。分ければその部品ごと要らなくなる。
//     つながりは、両方の説明文の最後の1行で互いを指すことで保つ。
//   ★天井の梁は置かない。支点はヒンジの印がその場所を示すので、梁があってもなくても
//     読めるものが変わらない。むしろ支点にかかる力の矢印（上向き）が梁の中へ入って
//     見えなくなる（実測：撃心の棒の矢印は真上を向く 34px で、20px の隙間では
//     梁に飲まれて「矢印が無い」ように見えた）。
const PP_L    = 300;   // [px] 棒の長さ（3.0 m）。振り子も撃心も同じ棒
const PP_W    = 18;    // [px] 棒の幅
const PP_M    = 1;     // [kg] 棒
const PP_DEG  = 20;    // [°]  振り子を放す角度
const PP_PIVY = -240;  // [px] 支点の高さ
const PP_EQ   = 200;   // [px] 2L/3 ＝ 相当単振り子の長さ ＝ 撃心の位置
const PP_F    = 19.6;  // [N]  撃心デモで棒に付ける動力（＝ 2mg。撃心デモの★）
// 上端でヒンジ留めした一様な棒。★回転を止めない（このファイルの既定の例外。
//   振り子として回る当人なので、止めると題材そのものが消える）
function _ppRod(px, deg, opts) {
  const th = deg * Math.PI / 180;
  const rod = new Body(Object.assign({
    type:'box', w:PP_W, h:PP_L, mass:PP_M, angle:th,
    x: px - PP_L/2 * Math.sin(th), y: PP_PIVY + PP_L/2 * Math.cos(th),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#8d6e63', strokeColor:'#d7ccc8', strokeWidth:1.5 }, opts || {}));
  objects.push(rod);
  joints.push(new Joint({ type:'hinge', bodyA:null, anchorAx:px, anchorAy:PP_PIVY,
                          bodyB:rod, anchorBx:0, anchorBy:-PP_L/2 }));
  return rod;
}
// 単振り子（質点＋質量0の連結棒）。単振り子デモと同じ作り
function _ppBob(px, len, color, label) {
  const th = PP_DEG * Math.PI / 180;
  const bob = new Body({ type:'circle', radius:14, mass:PP_M, fixedRotation:true,
    x: px - len * Math.sin(th), y: PP_PIVY + len * Math.cos(th),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5, label });
  objects.push(bob);
  joints.push(new Joint({ type:'rod', bodyA:null, anchorAx:px, anchorAy:PP_PIVY,
                          bodyB:bob, restLength:len, layers:0 }));
  return bob;
}
// 2L/3 の位置を示す水平線。両方のデモで同じ色・同じ意味で引く
//   ★base は支点の高さ。省略すると剛体振り子デモの支点（PP_PIVY）
function _ppEqLine(x0, x1, base) {
  annotations.push(new Annotation({ type:'path', x:x0,
    y:(base === undefined ? PP_PIVY : base) + PP_EQ,
    color:'#4fc3f7', width:2, pts:[{x:0,y:0},{x:x1-x0,y:0}] }));
}
// 指定した範囲が「説明文の下」に収まるようにカメラを決め、
// 説明文の大きさ（画面上 15px 相当のワールド px）を返す。
//   ★決め打ちの倍率にしない。窓の形が変わると題材の入り方が変わるので、ここで合わせる
//     （回転エネルギーのデモと同じ考え方）。
//   ★範囲は物体の AABB からではなく、呼ぶ側が明示する。注釈（2/3 の水平線と、棒の下に
//     並ぶ立て札）は objects に入らないので、AABB で測ると必ずはみ出す
//     （実測：立て札は棒の下端のさらに 70px 下にあり、画面の外へ切れていた）。
//   ★topFrac は画面の上から何割を説明文に空けるか。
function _ppFitCam(x0, x1, y0, y1, topFrac) {
  cam.zoom = Math.min((canvas.width - 40) / (x1 - x0),
                      (canvas.height * (1 - topFrac)) / (y1 - y0));
  cam.x = (x0 + x1) / 2;
  cam.y = (y0 + y1) / 2 - ((1 + topFrac)/2 * canvas.height - canvas.height/2) / cam.zoom;
  return Math.round(15 / cam.zoom);
}

// ── 剛体振り子（物理振り子）───────────────────────────────
//   ★見せたいのは「棒と同じ周期で振れるのは 2/3 の長さ」。それを言い切るには、
//     もっともらしい外れを両側に置く必要がある。4台を同じ角度から放す：
//       ① 3 m の棒  ② 1.5 m（棒の重心の高さ）  ③ 2 m（＝2L/3）  ④ 3 m（棒と同じ長さ）
//     ②と④が「筋は通っているのに外れる予想」で、③だけが棒とそろう。
//     ★②を置くのが要。「重心が 1.5 m にあるのだから、そこに全質量が集まった
//       単振り子と同じ周期のはず」は、物理を少しかじった人ほど立てる予想で、
//       しかも外れる（実測 2.476 s 対 棒 2.862 s ＝ 13.5% 違う）。
//       相当単振り子の長さを決めるのは重心までの距離 d ではなく I_O/(md)、という
//       このデモの主張は、②が無いと「3 m でないこと」しか言えていなかった。
//     ★並びは長さの昇順（棒・1.5・2・3）。外れ2つが正解を挟み、おもりの高さが
//       階段状に並ぶので「2 m はその間」も同時に読める。
//   ★実測（40 秒・最下点の通過で数える）：
//       棒 2.8615 s ／ 1.5 m 2.4756 s ／ 2 m 2.8603 s ／ 3 m 3.5015 s
//       棒と 2 m は差 0.04%、棒と 1.5 m は 13.5% 違う
//     ★どれも小さい角度の式（2.8375 / 2.4573 / 2.8375 / 3.4752 s）より 0.8% 長い。
//       振れ角 20°の有限振幅の効果（T ≒ T₀(1 + θ²/16) が +0.76%）で、計算の誤差ではない。
//       4台とも同じだけ長くなるので、そろって振れることは変わらない。
//     ★このずれは長さでは減らない。誤差は振れ角だけで決まるので、全部の長さを2倍にしても
//       +0.8% のまま（実測：1.5 m +0.74%／2 m +0.80%／3 m +0.76%）。しかもカメラは
//       題材の幅に合わせて詰めるので、2倍にしても画面の見た目は変わらず、周期が √2 倍
//       （2.86→4.04 秒）になって観察が遅くなるだけ。近似を良くしたいなら触るのは
//       振れ角のほうだが、20°を下げると「そろって振れる」ことのほうが見えにくくなる。
//   ── 長く振らせると棒と 2 m がずれていく件（切り分けの記録）─────────────
//   ★原因は「単振り子の腕（連結棒ジョイント）が振幅を抜いている」こと。振幅が減ると
//     有限振幅の効果ぶん周期が短くなるので、単振り子だけ先へ進む。実測（120 秒）：
//       棒（ヒンジ）の振幅 20.0°→19.8°／単振り子（連結棒）の振幅 20.0°→14.8°
//     ★棒の幅のせいではない。幅を 18px→2px にしても差は 0.242%→0.199% しか動かず、
//       残りはそのまま残った（幅の寄与 0.043% は下の l の補正で消してある）。
//   ★連結棒ジョイントの位置補正は 1 サブステップにつき 1 回・緩和率 0.5（joint.js:307）
//     なので、刻みを細かくするほど漏れが減る。実測の周期差（棒 対 2 m）：
//       刻み16 … 0.242%／32 … 0.114%／64 … 0.057%／96 … 0.043%
//       120 秒（約42往復）で 1/10 周期 → 1/40 周期。振幅も 14.8°→18.5°(64) と保つ。
//     ★刻み 64 を採る。1 tick 0.30ms → 0.92ms で、60fps の予算 16.7ms の 5.5%。
//       96 にしても差は 0.057%→0.043% しか縮まらないので、そこで打ち切る。
//     ★ゼロにはできない。漏れは刻みに反比例して減るだけで消えないので、何時間も
//       振らせれば必ずずれる。これは物理ではなく離散化の性質なので、説明文にも書く。
//   ★単振り子の長さは 2.00 m 決め打ちにせず、棒の慣性モーメントから l = I_O/(md) を
//     計算して使う。棒は幅 18px あるので厳密な細い棒ではなく、
//     l = 2L/3 + 幅²/(6L) = 2.0018 m（2L/3 から 0.09%）。この 0.09% が周期差の
//     0.043% にあたる。計算で出せる差をわざわざ残す理由がない。
function demoPhysicalPendulum() {
  resetDemoWorld();
  world.substeps = 64;         // ★連結棒ジョイントの漏れを抑えるため（上の★）
  updateGroundTerrain(false);  // 地面なし（吊るしてあるだけ）
  // ★4台の間隔。3台のときの 330px から詰めた（4台を 330 で並べると幅が 1/4 増え、
  //   カメラが引くぶん説明文が小さくなる）。290 なら 3台のときとほぼ同じ大きさで収まる。
  const XP = [-435, -145, 145, 435];
  const rod = _ppRod(XP[0], PP_DEG, { label:'剛体振り子 3 m' });
  // 相当単振り子の長さ l = I_O/(m·d)。★支点まわりの I_O は平行軸の定理で
  //   I_重心 + m·d²（d は支点から重心まで＝ L/2）
  const d = PP_L / 2;
  const lEq = (rod.inertia + rod.mass * d * d) / (rod.mass * d);
  // ★色は「外れ＝暖色／一致＝緑」。1.5 m と 3 m はどちらも筋の通った外れなので暖色でそろえ、
  //   棒とそろう 2 m だけを緑にする。長さの違いではなく当たり外れで塗り分ける。
  _ppBob(XP[1], d,    '#ffa726', '単振り子 1.5 m');
  _ppBob(XP[2], lEq,  '#66bb6a', '単振り子 2 m');
  _ppBob(XP[3], PP_L, '#ef5350', '単振り子 3 m');
  _ppEqLine(XP[0] - 190, XP[3] + 190);
  //   ★範囲は「水平線の左端〜右端」×「支点の少し上〜立て札の下」。
  //     上に空ける割合が撃心デモより大きいのは、説明文が2行ぶん長いため
  //     （0.42 では最終行が棒の支点に掛かった）。
  const NS = _ppFitCam(XP[0] - 210, XP[3] + 210, PP_PIVY - 60, PP_PIVY + PP_L + 210, 0.47);
  demoLabel(XP[0] - 190, PP_PIVY + PP_EQ + 16, '2 m ＝ 棒の長さの 2/3', '#4fc3f7');
  demoLabel(XP[0] -  95, PP_PIVY + PP_L + 70, '棒\n(剛体振り子)', '#d7ccc8');
  demoLabel(XP[1] -  80, PP_PIVY + PP_L + 70, '単振り子\n1.5 m',    '#ffa726');
  demoLabel(XP[2] -  70, PP_PIVY + PP_L + 70, '単振り子\n2 m',      '#66bb6a');
  demoLabel(XP[3] -  70, PP_PIVY + PP_L + 70, '単振り子\n3 m',      '#ef5350');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '剛体振り子（物理振り子）', Math.round(NS * 1.3));
  demoNote (p.x, p.y + NS * 2.2,
  // ★1行は 34 文字まで。超えると右上のツールヒントの帯（画面の 420px から右）に
  //   1行目が潜る（「物体が傾く条件」の★と同じ制約）
    '長さ 3 m・1 kg の一様な棒（左）と、単振り子 3 台。\n'
  + '4台とも上端で留め、同じ 20°から放す。\n'
  + '青い線は棒の 2/3 の高さ（2 m）。\n'
  + '\n'
  + '【手順】▶実行 を押して、4台が最下点を通る瞬間を見くらべる\n'
  + '\n'
  + '【読みどころ】棒とそろうのは 2 m だけ。1.5 m でも 3 m でもない\n'
  + '・1.5 m は棒の重心の高さ。「重心に全質量が集まったのと同じ」と\n'
  + '　考えたくなるが外れる（棒より 13.5% 速い）\n'
  + '・3 m は棒と同じ長さ。これも外れる（棒より 22% 遅い）\n'
  + '・効くのは重心までの距離 d ではなく、回しにくさとの兼ね合い\n'
  + '　　相当単振り子の長さ l = I/(md) = (mL²/3)/(m・L/2) = 2L/3\n'
  + '・実測の周期：棒 2.8615 秒／1.5 m 2.4756／2 m 2.8603／3 m 3.5015\n'
  + '　棒と 2 m の差は 0.04%\n'
  + '・長く振らせると棒と 2 m は少しずつずれる（2 分で 1/40 周期ほど）。\n'
  + '　物理ではなく計算の刻みのせいで、糸の側だけ振幅がゆっくり減るため\n'
  + '・この 2L/3 は「撃心」と同じ点。デモ［撃心（打撃の中心）］を参照', NS);
}

// ── 撃心（打撃の中心）─────────────────────────────────
//   ★このデモが見せるべきものは3つ。
//       ① 「撃」＝叩くこと。撃心は力積の話で、押し続ける力の話ではない。
//          一定の力で押す図は「押した瞬間」でしか成り立たず、動かすと壊れる。
//       ② 支点は「手」であること。しかも自由に動ける手にすること。静的物体は
//          recordForce を通らない（joint.js:399）ので、支点反力の矢印が出ない。
//       ③ 同じ振り方で、当てる場所だけ変えた3本を並べること。
//     ＝ 「手」にバットをヒンジで留めて振り、置いてある球を打つ。手に出ている
//       支点反力の矢印が、打った瞬間に横へ倒れるか倒れないかを見る。
//   ★重力を切って真上から見下ろした図にする（速度の合成のデモと同じ）。バットは水平に
//     振るものなので、見下ろした図がそのまま題材の図になる。
//   ★支点反力の衝撃ぶんは、球へ渡した力積 J に対して
//       ΔP = J[1 − m·d(q−d)/I_cm] / [(m+M) + m·d²·M/I_cm]
//     分子が 0 になるのは q = d + I_cm/(m·d) = I_O/(m·d) = 2L/3 のときだけ。
//     ★分母（手の重さ M）は分子に入らない ＝ どんな重さの手でも、撃心は同じ場所。
//       支点を固定してもしなくても分子は同じなので、手を自由にしてかまわない。
//     ★バットが振られていても、この式は変わらない。撃心は力積の釣り合いの話で、
//       当たる直前にバットがどう動いていたかは入ってこない。振る動きは「なめらかな
//       背景」として重なるだけ。
//   ★実測（手に出る支点反力 [N]。振っている間 → 当たった tick）：
//       1 m（根元寄り）… 12.8 → 65（5.1倍。横向き成分 −64 ＝ 手は手前へ引かれる）
//       2 m（撃心）    … 12.8 →  7（倒れない。横向き成分 −0.1 ＝ ほぼ 0）★
//       3 m（先端）    … 12.8 → 70（5.4倍。横向き成分 +69 ＝ 手は先へ押される）
//     ★振っている間の 12.8 N は3列とも同じで、向きもバットの向き（＝求心力の反作用）。
//       読みどころは「その矢印が打った瞬間に横へ倒れるか」。撃心の列だけ倒れない。
//     ★3列とも同じ tick（39）で当たる。ここがずれると ⏭ のコマ送りで並べて読めない
//       ので、球は「当たる瞬間の支点の位置」から測って置く（下の★ PC_DX/PC_DY）。
//   ── ここを間違えると読めなくなる、という記録 ────────────────────
//   ★系の運動量を x も y も 0 にして振り出すこと。手を止めたままバットにだけ角速度を
//     与えると系に運動量が残り、振っている間じゅう手が流れ続ける。前の作りは振り出し角
//     25°で当たるまで 0.05 秒（3 コマ）しかなく、そのぶん流れが目立たなかっただけで、
//     「バットが球を打つ」という肝心の絵が写っていなかった。運動量を 0 にすると、
//     当たる瞬間（バットが真下＝手の速度が極値）で背景が平らになるので、振り出し角を
//     110°まで戻しても 3列が同じ 0.65 秒で狙った所に当たる
//     （実測：当たった位置 101／200／300 px）。
//     ★y も 0 にすること。x だけ 0 にしていたころは y に 423 kg·px/s が残っていて、
//       系ぜんぶが 20 px/s で沈み、当たるまでに手が 13px 下がっていた。支点が下がった
//       ぶん当たり位置は q より短くなり（実測 99／198／297 px）、撃心の列にも
//       横向きが −1.9 N 残っていた。y も 0 にすると −0.1 N まで落ちる。
//   ★振りはゆっくりにすること。衝撃/背景 ∝ 1/ω（背景の求心力 mω²d は ω²、球へ渡る
//     力積は ω に比例）。実測の比（1 m の列、球 2 kg）：
//       ω=−8 … 3.8倍／−6 … 3.8倍／−4 … 5.6倍／−3 … 7.3倍／−2 … 10.9倍
//     −3 rad/s（先端 9 m/s）を採る。−2 まで落とすと振りが 1 秒近くかかって間延びする。
//   ★球は 1 kg。衝撃は球へ渡る力積に比例し、背景（求心力）は球によらないので、
//     本物の球（0.15 kg）では矢印が倒れない。★これは縮尺の誇張で、説明文にも書く。
//     ★2 kg より 1 kg が良い。2 kg だと打った瞬間にバットがほとんど止まってしまい
//       （実測：ω −3 → −0.73 rad/s）、振り抜きが見えない。1 kg なら −1.22 で振り抜く。
//       倒れる大きさも 1 m と 3 m でそろう（1 kg 65／70 N。2 kg では 102／78 N）。
//   ★振り出す向きは球と反対側（+110°）から。球側から振り戻すと、長い距離（3 m）の
//     列では振り出した時点でバットが球を追い越していて、狙った所とは違う場所で当たる。
//   ★手をレールに乗せない。レールに乗せると、当たる瞬間（バットが真下）の求心力は
//     まるごとレールが受け止めるので、手に「バットが引く矢印」と「レールが押し返す
//     矢印」が同じ点から正反対に生えて、どちらを読むのか分からなくなる。
//     手が自由なら矢印は1本。バットが軽いので、手は共通重心のまわりを小さく回るだけで
//     済む（当たるまでのずれは (−6.7, −9.6)px ＝ 11.6px ＝ 手の箱 52px の 1/4.5）。
//   ★衝撃は 1 tick で終わる。矢印には描画のたびに 20% ずつ寄せる平滑化
//     （js/render/vectors.js:76 の alpha）が掛かっているので、走ったままではその 1 コマが
//     過ぎ去ってしまう。**当たった tick でプログラムに実行を止めさせる**のがこの demo の
//     見せ方の中心で、止めている間は _forces が残ったまま（次の simTick の頭まで）なので、
//     矢印はそこから 100% まで育って留まる。
//     ★実測（手に出る支点反力の矢印 [px]。3列を左から）：
//         ×0.25 で流す（前の作り）    … 131 ／ 39 ／ 139   ＝ 撃心は 1/3.4
//         当たった tick で止める（今） … 196 ／ 22 ／ 209   ＝ 撃心は 1/9
//       止めた直後は 115/31/122 で、そのまま 0.6 秒描き続けると上の値まで育つ。
//       ＝ 見分けが 3 倍はっきりする。再生速度を落とす必要も、手でコマ送りする必要もない。
//     ★3列とも同じ tick で当たる（当たる tick を揃えたため）ので、1枚のプログラムで
//       3列が同時に凍る。つなぐ先は真ん中の列の球1つでよい。
//     ★プログラムの窓は畳んで置く。デモの部品は手で作れるものだけで組む約束なので、
//       「どうやって止めているか」も画面に見えていること自体が説明になる。
const PC_HAND  = 20;    // [kg] 手（腕と体のつもり）
const PC_BAT   = 1;     // [kg] バット。長さは PP_L（3 m）＝剛体振り子と同じ棒
const PC_BALL  = 1;     // [kg] 球。★読めるようにするための誇張（上の★）
const PC_E     = 0.3;   // 球とバットの反発係数
const PC_W0    = -3;    // [rad/s] 振り出す角速度（先端 9 m/s）
const PC_DEG0  = 110;   // [°] 振り出す角度（球と反対側）
const PC_BALLR = 20;    // [px] 球の半径
const PC_LANE  = 700;   // [px] 列の間隔（バットが振り抜いても隣と重ならない幅）
const PC_FVS   = 3;     // [px per N] 力の矢印の倍率（振り中 38px・打撃 200px。上限は 260px）
// ★再生速度は ×1 のまま（前は ×0.25 に落としていた。上の★の実測）
function demoPercussionCenter() {
  resetDemoWorld();
  setDemoGravity(0);           // ★重力なし＝真上から見下ろした図
  world.substeps = 16;
  world.sleeping = false;
  world.forceVizScale = PC_FVS;
  updateGroundTerrain(false);
  const HY = -70, QS = [100, PP_EQ, PP_L];
  const XS = QS.map((q, i) => (i - 1) * PC_LANE);
  const th = PC_DEG0 * Math.PI / 180;
  // ★バットが真下を向く瞬間の支点（手）の位置。外力も系の運動量も 0 なので共通重心は
  //   その場に留まり、手はそのまわりを回る：
  //       手 − 重心 = (m/(M+m))(L/2)·(sinθ, −cosθ)      m:バット M:手
  //   θ=110° で始まり θ=0 で当たるので、当たる瞬間の手は振り出し位置より
  //   (PC_DX, PC_DY) = (−6.7, −9.6)px ずれている。★球はこの点から測って置く。
  //   ★揃えないと当たる tick が列ごとに違う。支点が球から PC_DX だけ逃げるぶん当たりは
  //     遅れ、遅れ角は θ ≒ |PC_DX|/q ＝ **q に反比例する**（腕が長い列ほど早く届く）。
  //     直す前は 1 m と 2 m が 40 tick 目、3 m だけ 39 tick 目に当たっていた
  //     （実測の当たり角 −4.42°／−3.08°／−1.46°）。3列を同じ振り方で比べるデモなので、
  //     ここがずれると衝撃の出る tick も揃わず、⏭ のコマ送りで並べて読めない。
  const PC_K  = (PC_BAT / (PC_HAND + PC_BAT)) * (PP_L / 2);
  const PC_DX = -PC_K * Math.sin(th), PC_DY = -PC_K * (1 - Math.cos(th));
  let pcBall = null;
  QS.forEach((q, i) => {
    // ★衝突レイヤーで「列どうし」と「手とバット」を切る。バットは振り抜くので、
    //   切らないと隣の列のバットや自分の手とぶつかる。
    //     列 i のバットと球 … ビット i（0,1,2）／手 … ビット3（何ともぶつからない）
    const layer = 1 << i;
    const hand = new Body({ type:'box', x:XS[i], y:HY, w:52, h:28, mass:PC_HAND,
      fixedRotation:true, layers:1 << 3, showForces:true,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:2, label:'手' });
    objects.push(hand);
    // バット。★支点（手）まわりに角速度を与えて振り出す。速度ツールと同じで、
    //   角速度はプロパティ欄（回転の速さ）から手で入れられる
    const cx = XS[i] + (PP_L/2) * Math.sin(-th), cy = HY + (PP_L/2) * Math.cos(th);
    const bat = new Body({ type:'box', x:cx, y:cy, w:PP_W, h:PP_L, mass:PC_BAT, angle:th,
      friction:0, frictionStatic:0, restitution:PC_E, layers:layer,
      fillColor:'#8d6e63', strokeColor:'#d7ccc8', strokeWidth:1.5, label:'バット 3 m' });
    bat.av = PC_W0;
    // ヒンジを満たす重心速度 v = ω×r。★そのうえで系の運動量が x も y も 0 になるように、
    //   手とバットへ同じ下駄 V0 を履かせる（上の★。これが「振っても手が流れない」の中身）
    const rvx = -PC_W0 * (cy - HY), rvy = PC_W0 * (cx - XS[i]);
    const V0x = -PC_BAT * rvx / (PC_HAND + PC_BAT);
    const V0y = -PC_BAT * rvy / (PC_HAND + PC_BAT);
    hand.vx = V0x; hand.vy = V0y;
    bat.vx = V0x + rvx; bat.vy = V0y + rvy;
    objects.push(bat);
    joints.push(new Joint({ type:'hinge', bodyA:hand, anchorAx:0, anchorAy:0,
                            bodyB:bat, anchorBx:0, anchorBy:-PP_L/2 }));
    // 球。★バットが真下を向いた瞬間に、支点から q の所へ当たる位置に置く
    //   （＝そのときの支点 XS[i]+PC_DX から測った位置。上の★）
    const ball = new Body({ type:'circle', x:XS[i] + PC_DX + PP_W/2 + PC_BALLR, y:HY + PC_DY + q,
      radius:PC_BALLR, mass:PC_BALL, layers:layer,
      friction:0, frictionStatic:0, restitution:PC_E,
      fillColor:'#42a5f5', strokeColor:'#bbdefb', strokeWidth:1.5,
      label:`球（${(q/100).toFixed(0)} m の所）` });
    objects.push(ball);
    if (i === 1) pcBall = ball;         // ★真ん中の列の球（下でプログラムをつなぐ）
  });
  // ── 打った瞬間で止めるプログラム ─────────────────────────
  //   ★「何かが当たったら → 実行を止める」を球1つにつなぐだけ（上の★）。相手は
  //     物体だけにする——真上から見た図なので地面は無いが、既定のままにしておく。
  if (pcBall) {
    const pg = addProgram(pcBall);
    pg.trigger = 'hit'; pg.hitWhat = 'body'; pg.action = 'pause';
    pg.collapsed = true; pg.fx = 0.735; pg.fy = 0.17;   // ★上の操作ヒント帯を避ける高さ
    pg.reset(); syncProgramState(pg); syncProgramPanel(pg); placeProgramPanel(pg);
  }
  // 手のはじめの位置を示す白い縦線
  XS.forEach(x => annotations.push(new Annotation({ type:'path', x, y:HY - 52,
    color:'#ffffff', width:2, pts:[{x:0,y:0},{x:0,y:104}] })));
  // 撃心の位置を示す水平線（剛体振り子のデモと同じ色・同じ意味）
  _ppEqLine(XS[0] - 300, XS[2] + 300, HY);
  // ── カメラ ────────────────────────────────────────
  //   ★上下は「振りかぶったバットの先」から「振り下ろしたバットの先」まで。振り出し
  //     110°では先端が手より 103px 上・282px 左に出るので、上にも場所が要る。
  //   ★左右の余白 360px は、はみ出す物のうちいちばん外まで届く物に合わせてある。
  //     左＝1 m の列の力の矢印（手前向き）、右＝3 m の列の力の矢印（先向き）と飛ぶ球。
  //     ★力の矢印の長さは「画面 px」で決まる（js/render/vectors.js:175 の alen）ので、
  //       ワールドでの長さは倍率で割った値になる。66 N × 3 ＝ 198 画面px は、この倍率
  //       (0.60) では 328 ワールドpx ＝ バットの長さの 1.1 倍。余白を物の大きさだけで
  //       見積もると必ず足りない（実測：320px では矢印の先が画面の左端に触れていた）。
  //   ★説明文の高さは倍率によらない（大きさを倍率から逆算しているため）ので、
  //     行数を削らないと題材の場所は増えない。いまは 14 行。
  const topFrac = 0.42;
  const x0 = XS[0] - 360, x1 = XS[2] + 360, y0 = HY - 150, y1 = HY + PP_L + 90;
  cam.zoom = Math.min((canvas.width - 40) / (x1 - x0),
                      (canvas.height * (1 - topFrac)) / (y1 - y0));
  cam.x = (x0 + x1) / 2;
  cam.y = (y0 + y1) / 2 - ((topFrac + (1 - topFrac)/2) * canvas.height - canvas.height/2) / cam.zoom;
  const NS = Math.round(14 / cam.zoom);
  // ★札は真ん中の列の右へ。置ける所は消去法で1か所しかない。
  //   ・左右の列の高さ＝打った瞬間に横へ長い矢印が生えるので必ず潰される
  //     （実測：右端に置いたら 3 m の列の矢印が札を貫いた）
  //   ・真ん中の列の上＝振りかぶったバットが左上へ 282px 伸びていて、その下敷きになる
  //   横向きの矢印が出ないのは撃心の列だけ、バットが伸びるのは左だけ ＝ 真ん中の右。
  demoLabel(XS[1] + 45, HY - 52, '← 手のはじめの位置', '#eceff1');
  QS.forEach((q, i) => demoLabel(XS[i] - 110, HY + PP_L + 50,
    (q/100).toFixed(0) + ' m の所で打つ' + (q === PP_EQ ? '\n★撃心' : ''),
    q === PP_EQ ? '#4fc3f7' : '#d7ccc8'));
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '撃心（打撃の中心）', Math.round(NS * 1.3));
  demoNote (p.x, p.y + NS * 2.2,
  // ★1行は 34 文字まで（剛体振り子デモの★と同じ制約）
    '真上から見下ろした図（重力なし）。バットを水平に振るのと同じ向き。\n'
  + '「手」に長さ 3 m・1 kg のバットを留め、同じ振り方で振って球を打つ。\n'
  + '当てる場所だけを、根元から 1 m / 2 m / 3 m と変えてある。\n'
  + '手から出ている矢印が、バットが手を押し引きする力（支点反力）。\n'
  + '\n'
  + '【手順】▶実行。当たった瞬間に自動で止まる（右上のプログラム）ので、\n'
  + '　　　　止まった画の矢印を読む。▶をもう一度押せば続きが動く\n'
  + '\n'
  + '【読みどころ】2 m で打ったときだけ、手に横向きの力が来ない\n'
  + '・振っている間は3列とも同じ 12.8 N で、向きもバットの向き（振り回すぶん）\n'
  + '・打った瞬間：1 m 65 N 手前へ／2 m 倒れない／3 m 70 N 先へ\n'
  + '・支点反力 ∝ 1 − m・d(q−d)/I。0 になるのは q = I/(md) = 2L/3 だけ\n'
  + '　＝ 手の重さにも振る速さにもよらず、撃心はいつも棒の 2/3 の所\n'
  + '・球は 1 kg に誇張（本物の球は軽く、手に来る衝撃もそのぶん小さい）\n'
  + '・この 2L/3 は相当単振り子の長さと同じ。デモ［剛体振り子］を参照', NS);
}

// ── 偶力（並進せずに回る）─────────────────────────────────
//   ★向きが逆で大きさの等しい2つの力（偶力）は、合力が 0 なので重心を動かさず、回転だけを
//     起こす。1本だけなら、重心が動き出しながら回る。リモコンを2つ置いて押し比べる。
//   ★真上から見た図（重力 0・背景の摩擦 0）。板の重心に印（comIds）を出し、中心の軌跡を残す。
//     偶力では重心の印がその場から動かず、軌跡が点のまま。1本だけでは軌跡が伸びる。
//   ★動力は物体基準の向きなので板と一緒に回る＝偶力はいつも板に垂直で、回っても偶力のまま。
//   ★理論（2 kg・3.0×0.6 m の板、力 2 N を中心から ±1.2 m）：
//       慣性モーメント I = m(a²+b²)/12 = 1.56 kg·m²
//       偶力：トルク 2·F·d = 4.8 N·m → 角加速度 3.08 rad/s²、重心の加速度 0
//       1本：トルク F·d = 2.4 N·m → 角加速度 1.54 rad/s²、重心の加速度 F/m = 1.0 m/s²
//     実測（2026-10-01、1 秒押す）：偶力 重心の移動 0.0000 m・角加速度 3.077 rad/s²／
//     1本 角加速度 1.538 rad/s²・重心の移動 0.496 m（力が板と一緒に回るので 0.5 m より少し短い）。
//   ★回転は止めない（この題材の主役。ファイル冒頭の★の例外）。
const CP_M = 2, CP_W = 300, CP_H = 60;   // [kg] [px] [px]
const CP_F = 2, CP_D = 120;              // [N] 1本の力／[px] 力点の中心からの距離
function demoCouple() {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  world.sleeping = false;
  updateGroundTerrain(false);
  setDemoCam(0, 0.65);
  // ★板（回ると半径 1.5 m の円を占める）がグラフの窓（右うえ）にも本文にも掛からない位置
  const cx = cam.x + 30, cy = cam.y + 60;
  const plate = new Body({ type:'box', x:cx, y:cy, w:CP_W, h:CP_H, mass:CP_M,
    friction:0, frictionStatic:0, restitution:0,
    thrusters:[{ force:CP_F, dir:-Math.PI / 2, localX: CP_D, localY:0 },    // 右端：画面の上向き
               { force:CP_F, dir: Math.PI / 2, localX:-CP_D, localY:0 }],   // 左端：画面の下向き
    fillColor:'#5c6bc0', strokeColor:'#c5cae9', strokeWidth:2, label:'板 2kg' });
  plate.tracerEnabled = true; plate.tracerColor = '#ffd54f'; plate.tracerDuration = 30;
  objects.push(plate);
  comIds = [plate.id];            // ★重心の印（表示メニューの「重心」と同じもの）
  // リモコン：右端の1本だけ ／ 2本同時（偶力）
  const r1 = addRemote('thruster', plate.thrusters[0], 'thruster');
  if (r1) { r1.key = 'KeyZ'; r1.mode = 'on'; r1.fx = 0.055; r1.fy = 0.68; placeRemotePanel(r1); syncRemotePanel(r1); }
  const r2 = addRemote('thruster', plate.thrusters[0], 'thruster',
                       [plate.thrusters[0].id, plate.thrusters[1].id]);
  if (r2) { r2.key = 'KeyX'; r2.mode = 'on'; r2.fx = 0.24; r2.fy = 0.68; placeRemotePanel(r2); syncRemotePanel(r2); }
  moveDemoGraphTop(velGraphNew(plate, { showPos:false, showVel:true, showAcc:false,
                                        showX:false, showY:false, showMag:true, autoStart:true }));
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '偶力（並進せずに回る）');
  // ★2つのリモコンは左下に横並び（縦に積むと下の窓が上の窓を隠した）。札はそのすぐ上
  demoLabel(p.x, p.y + 650, '左（Z）：右端の1本だけ　　右（X）：2本同時＝偶力', '#ffd54f');
  demoNote (p.x, p.y + 54,
    '真上から見た図（重力も摩擦もない）。2 kg の板の両端に、\n'
  + '逆向きの動力 2 N が1本ずつ付いている。白黒の印は重心。\n'
  + '\n'
  + '【手順】▶実行 を押し、左下のリモコンを押しくらべる\n'
  + '・2本同時（X）：板はその場で回るだけ。重心の印は動かず、\n'
  + '　右うえのグラフ（重心の速さ）も 0 のまま ＝ 偶力\n'
  + '・1本だけ（Z）：回りながら重心も動き出す\n'
  + '\n'
  + '【読みどころ】偶力は合力が 0 なので重心を動かさない。\n'
  + '回転だけを起こし、その強さ（モーメント）は 力 × 2本の間隔');
}

// ── 重心の求め方（吊り下げ法）──────────────────────────────
//   ★形が不規則な板でも、1点で吊って静止させると、重心は必ずその点の真下に来る
//     （重力のモーメントが 0 になる向きで止まるから）。だから「吊って鉛直線を板に引く」を
//     2か所でやれば、2本の線の交点が重心。
//   ★2026-10-01 板1枚を掛け替える形に作り直した。以前は L 字の板3枚を違う点で吊り、
//     支点の真下に背景の破線を引いていたが、線が板に乗らないので「交点を作る」ができず、
//     「重心は支点の真下」までしか見せられなかった（ユーザーの指摘）。いまは
//     ・お絵描きで板の上から引いた線は板に貼り付く（annotate.js の syncAttachedAnnotations）
//     ・穴1〜3のヒンジをリモコン（1〜3 キー）で外す・留め直す（joint.js の setHingeDetached）
//     の2つで、教科書の手順をそのまま踏める。
//   ★重心の印は小さな正方形の穴（答え合わせ用）。穴は重心を中心に対称なので、重心の位置は変わらない。
//   ★エンジンは物体の基準点 (x, y) を重心として扱う（回転の中心・重力の作用点）。図形の道具は
//     頂点を重心まわりに置き直して作るので、ここでも L 字の頂点を重心まわりに置き直す
//     （置き直さないと、見た目の板と力学上の重心がずれる）。
//   ★振れを収めるのは空気抵抗（上皿天秤と同じ。drag）。ヒンジには摩擦が無い。
//   ★この寸法（腕 2.4 m・太さ 0.8 m）の重心は外の角から (0.73, 0.73) m で、板の中にある。
//     「重心が物体の外にあっても」を言うなら、腕を細くする（太さ < 腕の長さの 1/3 程度）必要がある。
//   ★板は何とも当たらない（layers 0）。掛け替えの途中で地面に触れて引っかかると、
//     止まった向きが「重心が真下」からずれる。
const HG_ARM = 240, HG_THK = 80;   // [px] L 字の腕の長さ・太さ
const HG_HOLE = 10;                // [px] 重心の穴の一辺
const HG_DRAG = 2.5;               // 抗力係数
const HG_MASS = 0.05;              // [kg] 板。★つりあいの向きは質量によらないので、軽くして空気抵抗を
                                   //   相対的に効かせ、早く止める。実測（離れ方の最大）：1 kg・1.2 では 45 秒たっても
                                   //   ±20〜30px 揺れていた。0.05 kg・2.5 で 10 秒 5px・23 秒 2px・60 秒 0.3px
                                   //   （空気抵抗は速さの2乗なので、小さな揺れほど止めにくい）
const HG_ZOOM = 0.75;              // ★掛け替えて振れても板が画面に収まる倍率
function hangLVerts() {
  const L = HG_ARM, T = HG_THK;
  const raw = [{x:0,y:0},{x:L,y:0},{x:L,y:T},{x:T,y:T},{x:T,y:L},{x:0,y:L}];
  // 多角形の面積重心（靴ひも公式）
  let A = 0, cx = 0, cy = 0;
  for (let i = 0; i < raw.length; i++) {
    const p = raw[i], q = raw[(i + 1) % raw.length], c = p.x * q.y - q.x * p.y;
    A += c; cx += (p.x + q.x) * c; cy += (p.y + q.y) * c;
  }
  A /= 2; cx /= 6 * A; cy /= 6 * A;
  return { verts: raw.map(p => ({ x: p.x - cx, y: p.y - cy })), cx, cy };
}
function demoHangingCOM() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;
  updateGroundTerrain(true);
  setDemoCam(0, HG_ZOOM);
  const ts = demoTextScale(cam.zoom);
  const { verts, cx, cy } = hangLVerts();
  const h = HG_HOLE / 2;
  const hole = [{x:-h,y:-h},{x:-h,y:h},{x:h,y:h},{x:h,y:-h}];
  // 吊る穴（L 字の元の座標で）：1 外の角の近く／2 横の腕の先／3 縦の腕の先
  const pins = [{ x:20, y:20 }, { x:HG_ARM - 20, y:HG_THK / 2 }, { x:HG_THK / 2, y:HG_ARM - 20 }];
  // ★支点（穴1）は画面の右寄り・上寄り。穴2・3で吊り直すと板は支点の右下・左下へ振れるので、
  //   本文（左上）にかからない側に置く
  const toWX = sx => cam.x + (sx - canvas.width / 2) / cam.zoom;
  const toWY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  const PX = toWX(canvas.width * 0.66), PY = toWY(canvas.height * 0.2);
  const a1 = { x: pins[0].x - cx, y: pins[0].y - cy };   // 穴1の、重心から見た位置（板のローカル）
  // ★板は傾けずに置く（支点を真上に合わせない）＝放すと振れて、重心が支点の真下へ来て止まる
  const plate = new Body({ type:'polygon', x: PX - a1.x, y: PY - a1.y, mass:HG_MASS, verts, holes:[hole],
    drag:HG_DRAG, friction:0.3, frictionStatic:0.4, restitution:0,
    layers:0,                                       // ★何とも当たらない（冒頭の★）
    fillColor:'#7986cb', strokeColor:'#c5cae9', strokeWidth:2, label:'L 字の板' });
  objects.push(plate);
  const hinges = pins.map((pin, i) => {
    const ax = pin.x - cx, ay = pin.y - cy;
    const w = getWorldAnchor(plate, ax, ay);
    // ★釘は背景に打つ（ヒンジは画鋲。上皿天秤の支点の★と同じ。以前は地面に留めていた）
    //   ★打つのは手のツールと同じ入口（demoPin）。穴の点には板しか無いので背景に留まる
    const j = demoPin('hinge', w.x, w.y, 'pair',
                      { expect:[plate, null], opts:{ color:'#ffd54f', detached: i > 0 } });
    // 穴の番号は板に貼る（板と一緒に振れる）
    const lb = new Annotation({ type:'text', x: w.x + 9, y: w.y - 4, text: String(i + 1),
                                size: 26, bold: true, color:'#ffd54f' });
    annotations.push(lb);
    annotAttachToBody(lb, plate);
    return j;
  });
  const p = demoTextTopLeft();
  const NOTE =
      '1枚の L 字の板。黄色の 1〜3 は吊るための穴、小さな四角の穴が重心（答え）。\n'
    + '\n'
    + '【手順】\n'
    + '① ▶実行。穴1で吊られた板が揺れて止まる（10 秒ほど）\n'
    + '② お絵描き（左のツールバー）の直線で、穴1から真下へ線を引く\n'
    + '　 板の上から引き始めると、線は板に貼り付く（Shift で真下にそろう）\n'
    + '③ 2 キーで穴2をその場で留め、1 キーで穴1を外す → 穴2で吊り直し\n'
    + '④ 止まったら、穴2から真下へもう1本\n'
    + '・2本の線の交点が重心（四角い穴）に来る。3 キーで穴3でも確かめられる\n'
    + '\n'
    + '【読みどころ】1点で吊ると、重心はその点の真下で止まる\n'
    + '（重心が真下にないと、重力のモーメントが板を回す）。\n'
    + '形が不規則でも、2か所で吊って鉛直線を引けば交点が重心';
  const noteY = p.y + 54 * ts;
  demoNote(p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
  demoTitle(p.x, p.y, '重心の求め方（吊り下げ法）', DEMO_TITLE_SIZE * ts);
  // ── リモコン：穴ごとに1台（外す・留め直す）。本文の下に横1列 ──
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const rs = [];
  hinges.forEach((j, i) => {
    const r = addRemote('ghost', j, 'joint');
    if (!r) return;
    r.key = 'Digit' + (i + 1); r.collapsed = true;
    syncRemotePanel(r);          // ★幅を測る前に中身を入れる
    rs.push(r);
  });
  dcPlaceRow(rs, 56, noteBot + 8);
}

// ── 滑りから転がりへ ───────────────────────────────────────
//   ★回転させずに床へ滑り込ませた球は、床の動摩擦で並進が減り、同じ摩擦のモーメントで回転が
//     増える。速さと Rω がそろった瞬間に滑りが止まり（接点が止まる）、そこから先は摩擦 0 で
//     転がり続ける。教科書では式だけになりがちな「滑り → 転がり」の移り変わりを、
//     グラフ2枚（速さ／並進と回転の運動エネルギー）と摩擦の矢印で見せる。
//   ★理論（中実の球ではなく円板＝2D の円。I = ½mR²）：
//       滑っている間：a = −μg、角加速度 α = μmgR / I = 2μg/R
//       そろう時刻 t = v₀ / (3μg)、そのときの速さ v = (2/3)v₀
//     ★2D の円は円板なので 2/3。3D の中実球なら 5/7 になる（本文にもそう書く）。
//   ★床の摩擦：地面側 1、球側 0.3 → 合成 0.3。
//   ★実測（2026-10-01）：速さと Rω がそろうのは 0.567 s（理論 v₀/(3μg) = 0.567 s）、
//     そのあとの速さ 3.333 m/s（理論 2/3×5 = 3.333）。0.25 s ごとの v／ωR：4.265／1.471、
//     3.529／2.942、0.75 s 以降は 3.333／3.333 で一定。
const RL_V0 = 5, RL_MU = 0.3, RL_R = 30;   // [m/s] [-] [px]
function demoSlipToRoll() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 8;
  world.forceVizScale = 8;
  updateGroundTerrain(true);
  ground.friction = 1; ground.frictionStatic = 1;   // ★合成は積。球の値がそのまま効く
  setDemoCam(0, 0.65);
  const ball = new Body({ type:'circle', radius:RL_R, mass:1,
    x: cam.x - 620, y: gy - RL_R, vx: toPx(RL_V0), av: 0,
    friction:RL_MU, frictionStatic:RL_MU, restitution:0, showForces:true,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:2, label:'円板 1kg' });
  // ★縁の1点の軌跡。円には向きの目印が無いので回っているのが見えない。縁の点の道すじなら、
  //   滑っている間は引き伸ばされた曲線、転がりに移ると床に触れる所で止まるサイクロイドになる
  //   ＝「接点が止まる」が目で読める。始まりは真下（床に触れている点）。
  ball.tracerEnabled = true; ball.tracerColor = '#ffd54f'; ball.tracerDuration = 6;
  ball.tracerAnchorX = 0; ball.tracerAnchorY = RL_R;
  objects.push(ball);
  const gv = velGraphNew(ball, { showPos:false, showVel:true, showAcc:false,
                                 showX:true, showY:false, showMag:false, autoStart:true });
  const ge = eneGraphNew([ball.id], { showKt:true, showKr:true, showMech:true,
                                       showUg:false, showUs:false, showUgg:false, showUe:false });
  // ★2枚とも床より上に積む（下の窓を画面の下端に置くと、転がっていく円板が窓に隠れた）
  sizeDemoGraph(gv, 400, 260); moveDemoGraphTop(gv);
  sizeDemoGraph(ge, 400, 260); moveDemoGraphTop(ge);
  if (ge && ge.panel) ge.panel.style.top = '326px';
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '滑りから転がりへ');
  demoNote (p.x, p.y + 54,
    '回転していない円板（1 kg・半径 0.3 m）を、5 m/s で床へ\n'
  + '滑り込ませる。床との動摩擦係数は 0.3。\n'
  + '\n'
  + '【手順】▶実行 を押して、右の2枚のグラフ・矢印・縁の点の道すじを見る\n'
  + '・滑っている間：摩擦（黄）が後ろ向きに働き、速さは減り、\n'
  + '　回転は増える（運動エネルギーが 並進 → 回転 へ）\n'
  + '・速さ ＝ 半径 × 角速度 になった瞬間に滑りが止まる\n'
  + '　→ 摩擦の矢印が消え、速さも回転も一定の転がりになる\n'
  + '・黄色い道すじ：転がりになると床に触れる所で止まる（尖った形）\n'
  + '・そのときの速さは最初の 2/3（3.3 m/s）。0.57 秒後\n'
  + '\n'
  + '円板は I = ½mR² なので 2/3。3D の球（I = ⅖mR²）なら 5/7。\n'
  + '滑っている間は摩擦が熱を出すので、合計（黄）が減る');
}

// ════════════════════════════════════════
//  力学 ▸ 運動量
// ════════════════════════════════════════
// ── 衝突と合体・分裂（運動量が保存する見せ方）───────────────────
//   ★どちらも「真上から見下ろした図」で組む（重力0・地面なし）。運動量はベクトルで、
//     横から見た図では地面の法線力という外力が入るので py が保存しない
//     （js/ui/momgraph.js 冒頭の★）。真上から見た図なら x も y も外力が無く、
//     どちらの成分でも「まっすぐ一定」が読める。＝エアテーブルに乗せた力学台車。
//   ★摩擦0。運動量保存の条件（外力が無い）を満たすため。台車どうしの間だけ力が働く。
//   ★衝突と合体は1つのデモにまとめ、反発係数をつまみ（リモコン）にした（2026-10-01、
//     ユーザーの指示）。以前は e=1 と e=0 の2つのデモを並べていたが、つまみなら
//     0 と 1 の間も回せる＝「内訳は e で変わるのに、合計だけは変わらない」が連続で読める。
//   ★眠りを切る（world.sleeping=false）。止まって待っている台車は 0.6 秒で眠るので、
//     ぶつかられた瞬間の反応が遅れる。実測：眠らせたままだと衝突の前後で合計運動量が
//     3.000 → 2.947 kg·m/s と 1.8% 落ちた（眠りを切ると 3.000 のまま 15桁一致）。
//   ★4つの道具を重ねる（どれも生徒が手で出せるもの）：
//     ・運動量グラフ（右うえ）… 合計が動かない
//     ・エネルギーグラフ（その下）… 合計は動かないのにエネルギーは e しだいで減る。
//       この2枚を並べるのが momgraph.js 冒頭の★「本命の使い方」
//     ・重心の印（comIds）… 2台の重心は衝突の前もあとも同じ速さでまっすぐ進む
//       ＝ 運動量保存を「図」で読む（全運動量 ＝ 全質量 × 重心の速度）
//     ・当たった瞬間に止めるプログラム … 作用・反作用の矢印は 1/60 秒しか出ないので、
//       その tick で時計を止める（撃心のデモと同じ。止めた画では矢印が本当の大きさで残る）
const MOM_CART_W = 84, MOM_CART_H = 52;   // [px] 台車の見た目（0.84 m × 0.52 m）
// [px] 台車を置く高さ。★グラフの窓は右に縦2枚（運動量・エネルギー）で、下端は画面の
//   586px あたり。台車はその下を走らせる（右へ抜けていく台車が窓の裏に入らないように）。
//   真上から見た図には地面が無いので、座標原点の線より下へ置いてかまわない。
//   ★原点の線（x 軸）と目盛りの数字に台車・札が重ならない高さ。30 では台車が目盛りの
//     数字の列にちょうど載り、「重心」の札が「O (0, 0)」に重なった。
const MOM_TRACK_Y = 100;
const MOM_V0      = 3;                    // [m/s] ぶつけにいく台車の初速
const MOM_GRAPH_W = 300, MOM_GRAPH_H = 260;   // [画面px] グラフの窓（右に縦2枚）
// 台車1台。e は反発係数（合成は積。相手を e=1 にしておけば、こちらの値がそのまま e になる）
//   ★力の矢印を出す（showForces）。運動量が変わるのは力が働いている間だけなので、
//     矢印が出ている一瞬とグラフの折れ曲がりが同じ時刻に起きるのが見える。摩擦も重力も
//     0 なので、出る矢印は台車どうしが押し合う力（とばね）だけ＝作用・反作用がそのまま並ぶ。
//   ★y は省略すると走路の高さ（MOM_TRACK_Y）。走路を2本並べるデモ（力積）だけが渡す
function _momCart(x, mass, v, e, color, label, y) {
  const b = new Body({
    type:'box', x, y:(y !== undefined ? y : ground.y + MOM_TRACK_Y), w:MOM_CART_W, h:MOM_CART_H, mass,
    vx: toPx(v), friction:0, frictionStatic:0, restitution:e,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5, label, showForces:true,
  });
  objects.push(b);
  return b;
}
// 共通の下ごしらえ（真上から見た図・眠りなし・カメラ）
function _momSetup() {
  resetDemoWorld();
  setDemoGravity(0);          // ★真上から見下ろした図。重力は画面に垂直で画面内に現れない
  world.sleeping = false;     // ★冒頭の★を参照（待っている台車が眠ると衝突がずれる）
  updateGroundTerrain(false); // 地面なし（横から見た図ではないので、下は「床」ではない）
  setDemoCam(0, 0.65);
}
// 運動量とエネルギーのグラフを右に縦2枚。重心の印も出す（どれも同じ「系」＝ids）
//   ★エネルギーは並進の運動エネルギー（とばね）だけ。重力0なので重力の位置エネルギーは
//     出ても 0 の線で、回転は台車が回らないので 0。0 の線を並べると読む線が埋もれる。
function _momGraphs(ids, withSpring) {
  const gm = momGraphNew(ids, { comp:'x', showParts:true, showRef:true });
  const ge = eneGraphNew(ids, { showKt:true, showKr:false, showUg:false, showUs:!!withSpring,
                                showUgg:false, showUe:false, showMech:true });
  // ★右端をそろえる。窓は開いた順に少しずつずらして置かれる（graphCascadeOffset）ので、
  //   上下を決めるだけでは2枚目が左へずれる
  [gm, ge].forEach((g, i) => {
    if (!g || !g.panel) return;
    sizeDemoGraph(g, MOM_GRAPH_W, MOM_GRAPH_H);
    g.panel.style.right = '10px'; g.panel.style.left = 'auto';
    g.panel.style.top = (56 + i * (MOM_GRAPH_H + 10)) + 'px'; g.panel.style.bottom = 'auto';
  });
  comIds = ids.slice();
}
// プログラムの窓を1枚（畳んで）置く。fx・fy は画面の割合
function _momProgram(body, set, fx, fy) {
  const pg = addProgram(body);
  if (!pg) return null;
  Object.assign(pg, set);
  pg.collapsed = true; pg.fx = fx; pg.fy = fy;
  pg.reset(); syncProgramState(pg); syncProgramPanel(pg); placeProgramPanel(pg);
  return pg;
}
// ── ① 衝突と合体（反発係数のつまみ）─────────────────────────────
//   ★1kg が 2kg にぶつかる。一般の e で
//       v₁' = (m₁ − e·m₂)/(m₁+m₂)·v = (1 − 2e) m/s、 v₂' = (1+e)·m₁v/(m₁+m₂) = (1 + e) m/s
//       失う運動エネルギー = ½·μ·v²·(1 − e²) = 3(1 − e²) J（μ = m₁m₂/(m₁+m₂) = 2/3 kg、はじめ 4.5 J）
//     e=1 で 1kg は −1 m/s（跳ね返る）、e=0.5 でちょうど止まり、e=0 で 2台そろって 1 m/s（合体）。
//     軽いほうが跳ね返される配置にしたのは、内訳の線が符号をまたぐ（正 → 負）ので、
//     合計が動かないことがはっきり見えるため。
//   ★つまみは 1kg の台車の反発係数。2kg は e=1 に固定してあるので、合成（積）がつまみの値になる。
//   ★実測（2026-10-01、e を 1／0.5／0 に置いて 3 秒）：1kg −1.000／0.000／1.000 m/s、
//     2kg 2.000／1.500／1.000 m/s、合計 3.000 kg·m/s（3つとも）、運動エネルギー 4.50／2.25／1.50 J
//     ＝ 上の式どおり。当たるのは 81 tick 目（1.35 秒）で、力積はその 1 tick にまとまって出る
//     （矢印 240／180／120 N ＝ 受け渡した運動量 × 60）。だからその tick で止めれば矢印が残る。
function demoMomentumCollision() {
  _momSetup();
  const a = _momCart(-430, 1, MOM_V0, 1, '#42a5f5', '1kg');
  const b = _momCart(  60, 2, 0,      1, '#66bb6a', '2kg');
  _momGraphs([a.id, b.id]);
  // 反発係数のつまみ（左下・本文の下）
  const k = addRemote('prop', a, 'body');
  if (k) {
    k.prop = 'restitution'; k.lo = 0; k.hi = 1; k.collapsed = true;
    k.fx = 0.055; k.fy = 0.60;
    placeRemotePanel(k); syncRemotePanel(k);
  }
  // 当たった瞬間に止める（冒頭の★）
  _momProgram(a, { trigger:'hit', hitWhat:'body', action:'pause' }, 0.30, 0.60);
  const ly = ground.y + MOM_TRACK_Y - 70;
  demoLabel(-500, ly, '① 1kg・3 m/s →', '#42a5f5');
  demoLabel( 110, ly, '② 2kg・静止',    '#66bb6a');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '衝突と合体（運動量保存）');
  demoNote (p.x, p.y + 54,
    'エアテーブルの台車を真上から見た図（摩擦なし・画面内に重力は現れない）。\n'
  + '1 kg の台車を 3 m/s で、止まっている 2 kg の台車にぶつける。\n'
  + '\n'
  + '【手順】左下のつまみで反発係数 e を選び、▶実行。当たった瞬間に自動で止まる\n'
  + '　（矢印を読んだら ▶ でもう一度）。e を変えるときは ↩ で最初に戻してから\n'
  + '\n'
  + '【読みどころ】右うえの運動量グラフの合計（黄）は、どの e でも 3 kg·m/s のまま\n'
  + '・e = 1：1kg は −1、2kg は ＋4 kg·m/s（軽いほうが跳ね返される）\n'
  + '・e = 0.5：1kg はぴたりと止まる／e = 0：2台そろって 1 m/s（合体）\n'
  + '・止まった画：2台に同じ長さ・逆向きの矢印（作用・反作用）。これが運動量を渡す\n'
  + '・エネルギー（下のグラフ）は e < 1 だと減る（e = 0 で 4.5 → 1.5 J）。\n'
  + '　運動量は減らないのにエネルギーは減る＝この2つは別の量\n'
  + '・白黒の丸は2台の重心。衝突の前もあとも 1 m/s でまっすぐ進む\n'
  + '・ストロボ：▾ で「動いている物体すべて」にすると、残像の間隔で速さが読める');
}
// ── ② 分裂（ばねで押し合って別れる）──────────────────────────
//   ★「静止していた物体が2つに分かれる」を、手で置ける部品だけで作る。押し板を
//     縮んだばねで台車Aに付け、その押し板を台車Bに当てておく。▶実行 でばねが伸びて
//     Bを突き放し、自然長を過ぎたところで押し板はBから離れる（接触は押すことしか
//     できないため）。＝力学台車のばね発条の実験そのもの。
//   ★ばねの両端は系の中（AとBの間）なので、ばねが何 J 出そうと、減衰で何 J 失おうと
//     合計運動量は 0 のまま。「エネルギーは変わるのに運動量は変わらない」が同時に出る
//     （エネルギーグラフでは、ばねの位置エネルギーが運動エネルギーへ移る）。
//   ★押し板は軽く（0.1 kg）、ばねには減衰を入れる。入れないと別れたあとも押し板が
//     台車Aの上で振動し続け、内訳の線が最後までギザギザになる（合計は 0 のまま）。
//   ★プログラムで自動停止はしない（2026-10-01、ユーザーの指示で外した）。押し合いは
//     0.07 秒で終わるので、走ったままでは力の矢印は一瞬しか出ない。矢印を見せたいときは
//     上のバーの「1ステップ」で 1 tick ずつ進めてもらう（本文の手順に書く）。
const MOM_SPRING_K   = 300;   // [N/m] ばね定数（ばねツールの既定と同じ手応え）
const MOM_SPRING_L0  = 30;    // [px] 自然長
const MOM_SPRING_X   = 14;    // [px] 縮み。E = ½kx² = 2.9 J
// ★0.65 は「これまで実際に効いていた減衰」。以前は demo-kit が c を ζ に直して渡しており、
//   質量の見積もりのずれで、書いてある 3 ではなく 0.65 が効いていた（共振のデモの★と同じ話）。
//   c をそのまま渡すようになったので、数のほうを実効値へ合わせる。3 にすると別れる速さが
//   11% 落ち（実測 1kg 側が 1.70 → 1.52 m/s）、下の本文に書いた実測値が合わなくなる。
//   ☆2026-09-27 に理想ばねを半分ずつ効かせるよう直して（slinky.js の applyIdealSprings の★）、
//     1kg 側は 1.70 → 1.72 m/s になった。本文の 1.61 はそれ以前から合っていなかったので
//     いっしょに直した（減衰0なら理論 2.00 m/s）。
const MOM_SPRING_C   = 0.65;  // [N·s/m] 減衰。★運動量には効かない（内力なので必ず打ち消し合う）
// ★実測（2026-10-01）：1kg が押し板から受ける力は tick 1〜4 で 30・30・20・10 N、5 tick 目からは 0。
//   別れたあと 1kg ＋1.719 m/s・2kg と押し板 −0.819 m/s、合計運動量 0.000000。
function demoMomentumSplit() {
  _momSetup();
  const ax = -100;
  const pushX0 = ax + MOM_CART_W / 2 + (MOM_SPRING_L0 - MOM_SPRING_X);
  // ★作る順番＝グラフの内訳の色。momGraphNew は渡した並びではなく id 順（＝作った順）に
  //   並べ、色は青・緑・赤の順に振られる（js/ui/momgraph.js の MG_COLORS）。だから
  //   「青い台車 → 緑の台車 → 押し板」の順で作る。2kg を先に作ると、画面では緑の台車が
  //   グラフでは青い線になり、説明文の色と食い違う。
  const b = _momCart(pushX0 + 10 + MOM_CART_W / 2, 1, 0, 0, '#42a5f5', '1kg');  // 台車B（青）
  const a = _momCart(ax, 2, 0, 0, '#66bb6a', '2kg');                            // 台車A（緑）
  // 押し板。台車Aの右面（局所 +42）から、縮めた長さ 16px のところに置く。
  //   ★頭は丸くする（実物のばね発条の玉と同じ）。平らな面どうしで押すと接触点が2つ
  //     できて左右の力積がわずかに違い、突き放す一瞬に自転と横滑りをもらう。真上から
  //     見た図には止めるもの（摩擦・重力）が何も無いので、それが延々と続く。
  //     実測（10秒後）：箱16×40 … 押し板が 33.8px 横へずれ、台車Bが 11.6°回った。
  //                     箱16×52（面の高さを台車とそろえる）… ずれ 0・B は 0.53°。
  //                     丸い頭（半径10）… ずれ 0.00・B の自転 0.00（厳密に 0）。
  //     丸いと接触点が中心線上の1点だけになるので、横向きの力積が原理的に出ない。
  //     ＝ 回転を止める設定（ファイル冒頭の★）に頼らなくても、形の側で決まっている。
  const push = new Body({
    type:'circle', x:pushX0, y:ground.y + MOM_TRACK_Y, radius:10, mass:0.1,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5, label:'押し板',
    showForces:true,
  });
  objects.push(push);
  demoSpring({ bodyA:a, anchorAx:MOM_CART_W/2, anchorAy:0, bodyB:push, anchorBx:0, anchorBy:0,
               restLength:MOM_SPRING_L0, stiffness:MOM_SPRING_K, damping:MOM_SPRING_C,
               radius:8 });
  _momGraphs([b.id, a.id, push.id], true);
  // ★力の矢印だけ倍率を上げる（「1ステップ」で止めて見るときのため）。ばねが出す力は最大 40 N（実測）で、既定の 1 px/N では
  //   40px＝台車の半分しかなく、ばねと押し板の絵に埋もれて左右一対が読めない。
  //   3 px/N なら 120px＝台車 1.4 個ぶん。
  world.forceVizScale = 3;
  const ly = ground.y + MOM_TRACK_Y - 70;
  demoLabel(-190, ly, '2kg', '#66bb6a');
  demoLabel( -75, ground.y + MOM_TRACK_Y + 45, '縮めたばねと押し板', '#ffd54f');
  demoLabel( 30, ly, '1kg', '#42a5f5');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '分裂（運動量保存）');
  demoNote (p.x, p.y + 54,
    'エアテーブルの上（摩擦なし）。2 kg の台車に、縮めたばねの付いた押し板があり、\n'
  + 'その先に 1 kg の台車が接している。全部止まっていて、はじめの運動量は 0。\n'
  + '\n'
  + '【手順】▶実行。押し合う瞬間の力を見るなら、▶の前に「1ステップ」を数回\n'
  + '\n'
  + '【読みどころ】右うえの運動量グラフの合計（黄）は 0 のまま動かない\n'
  + '・1ステップで進めた画：左右に同じ長さで逆向きの力の矢印＝足すと 0\n'
  + '・2kg は左へ・1kg は右へ別れる（押し板は 2kg 側に残る）\n'
  + '　実測：1kg が ＋1.72 m/s、2kg 側（押し板ごと 2.1 kg）が −0.82 m/s\n'
  + '　　　　どちらも大きさ 1.72 kg·m/s で、足すと 0\n'
  + '・エネルギー（下のグラフ）：ばねの位置エネルギーが運動エネルギーへ移る。\n'
  + '　エネルギーは 0 から増えたのに、運動量の合計は 0 のまま\n'
  + '・白黒の丸は全体の重心。2台が別れても、その場から動かない\n'
  + '・ストロボ：▾ で「動いている物体すべて」にすると、残像の間隔が\n'
  + '　2kg 側は 1kg の約半分（速さは質量に反比例）');
}

// ════════════════════════════════════════
//  力学 ▸ 運動量（床との衝突・斜めの衝突）
// ════════════════════════════════════════
// ── ④⑤ 床に当てて跳ね返らせる ────────────────────────────
//   ★どちらも床（地面）のある図。跳ね返り方そのものが題材なので、運動量グラフは
//     開かない（床が与える法線力は系の外からの力なので、球の運動量は保存しない＝
//     この題材で合計を出しても保存の話にならない）。読むのは変位と速度。
//   ★重力の扱いが2つで違う。④は落とすこと自体が題材なので働かせる。⑤は重力を 0 に
//     する（真上から見下ろした図＝①②③と同じエアテーブルの見立てで、床は「縁の壁」）。
//     ⑤で重力を残すと軌道が放物線になり、当たる前と後の速度が刻々変わるので、
//     「衝突で変わったぶん」と「重力で変わったぶん」が混ざって読めない。0 にすると
//     行きも帰りも直線＝入射と反射の2本を、そのまま角度と長さで比べられる。
//   ★反発係数は球だけに入れる。合成は積で、地面の既定が 1.0 なので、球の値が
//     そのまま跳ね返り係数 e になる（e=0.6 なら跳ね返る高さは e²=0.36 倍）。
//   ★摩擦は 0。⑤で「面に平行な速度は変わらない」を成り立たせるため（摩擦があると
//     床をこすって平行な速さが減り、球も回り出す）。
//   ★変位の y は原点基準（posOriginY）にする。座標原点は床の高さ（ground.y = 0）なので、
//     縦軸がそのまま「床からの高さ」になり、0 の線が床、山の頂上が跳ね上がった高さに
//     なる。既定の「記録開始位置から測る」だと同じ形が上下反転した「落とした点からの
//     距離」になり、床がグラフのどこなのかが読めない。
//   ★④は横へ 1.5 m/s だけ滑らせる。真下に落とすと跳ね返りが同じ場所で重なり、軌跡も
//     ストロボの残像も1本の縦線に潰れて「何回目の山か」が読めない（残像は直径 44cm に
//     対して 0.1 秒あたり 0 cm 進む＝完全に重なる）。横に流すと放物線が並んで、山が
//     e² = 0.36 倍ずつ低くなるのがそのまま図になる。
//     ★縦の運動はこれで 1 ミリも変わらない。摩擦 0・fixedRotation・床は平ら なので
//       法線と接線が切れており、実測でも vx = 0.5〜3.0 m/s のどれでも 400 tick 全部で
//       y の差が 0.000 mm（山も 2.00 → 0.85 → 0.44 m のまま）。だから本文の数値も
//       グラフも触らずに済む。逆に速すぎると読む前に画面から出る（実測：2.5 m/s は
//       4 秒で右端の 9m へ到達。1.5 m/s なら 4.7m で、跳ね終わるまで画面に残る）。
//     ★グラフは y のままにする。同じ段の成分は軸を共有する（vgAccAxisRange）ので、
//       x を足すと 変位の段が 0〜8.8m まで伸び、肝心の y（0〜5.2m）が 6 割に潰れて
//       3回目以降の小さな山が読めなくなる。横は等速なので、足しても直線が1本増えるだけ。
const MOM_BALL_R  = 22;   // [px] 球の半径
const MOM_BALL_E  = 0.6;  // 反発係数
const MOM_DROP_VX = 1.5;  // [m/s] ④で横へ流す速さ（上の★）
function _momDropBall(x, y, vx, vy) {
  const b = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x, y, radius:MOM_BALL_R, mass:1, vx: toPx(vx), vy: toPx(vy || 0),
    friction:0, frictionStatic:0, restitution:MOM_BALL_E,
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5,
  });
  b.tracerEnabled = true; b.tracerColor = '#ef5350'; b.tracerDuration = 12;
  objects.push(b);
  return b;
}
function demoFloorBounce() {
  resetDemoWorld();
  updateGroundTerrain(true);
  // ★高さは「球の下端から床まで」を 5.00 m にとる（中心で測ると半径ぶん 0.22 m ずれ、
  //   落ちてくる速さ √(2gh) が説明文の 9.9 m/s と合わなくなる）
  const ball = _momDropBall(-120, ground.y - 500 - MOM_BALL_R, MOM_DROP_VX);
  // ★倍率 0.55。0.65 だと 5m の高さが画面で高くなりすぎて、球が説明文の最終行に掛かる
  //   （実測：本文の下端 233px に対して球の上端 235px）。0.55 なら 90px 空いていた。
  //   ★その余白は本文を 10 → 12 行に伸ばしたぶん使ってある（実測：下端 249px・球の上端
  //     290px で残り 40.6px）。これ以上行を足すなら、先に倍率か行数のどちらかを削ること。
  setDemoCam(0, 0.55);
  // 変位と速度だけ（加速度は出さない）。まっすぐ落ちるので成分は y だけでよく、
  // その y は原点基準＝床からの高さで読む（冒頭の★）。上下の段が同じ向きの符号で揃う
  moveDemoGraphTop(velGraphNew(ball, { showPos:true, showVel:true, showAcc:false,
                                       showX:false, showY:true, showMag:false,
                                       posOriginY:true }));
  demoLabel(-100, ground.y - 520, '5.0 m から落とす', '#ef5350');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '床との衝突');
  demoNote (p.x, p.y + 54,
    '1 kg の球を 5.0 m の高さから落とす。反発係数 e = 0.6。\n'
  + '横へすこし滑らせてあるが、摩擦が無いので横は等速。縦の運動は変わらない。\n'
  + '\n'
  + '【手順】▶実行 を押して、右うえのグラフを見る\n'
  + '・変位 y（上の段）は床から測った球の中心の高さ。5.2 m から下がって、\n'
  + '　半径ぶんの 0.22 m（＝床に触れている高さ）で跳ね返り、また上がる\n'
  + '　山の頂上は 2.00 → 0.85 → 0.44 m。触れている 0.22 m からの差が\n'
  + '　その回に上がった高さで、1.78 → 0.63 → 0.22 m と e² = 0.36 倍ずつ\n'
  + '・速度 y（下の段）は落ちる間まっすぐ下へ増え、床に触れた瞬間に符号が変わる\n'
  + '　＝ 跳ね返りは一瞬の出来事。−9.8 m/s で当たり ＋5.9 m/s で戻る（0.6 倍）\n'
  + '・跳ね返るたびに山と山の間隔も短くなる（高さの平方根に比例するため）\n'
  + '・ストロボ：▾ で「横線」を入れると、線の間隔が山の上ほど詰まって見える');
}
// ⑤ 斜めの衝突。★重力 0（冒頭の★）。落として当てるのではなく、斜め下向きの速度を
//   付けて滑らせる。初速 (3, 4)＝速さ 5 m/s は、床の法線から 36.9°で入る向き。
//   跳ね返ったあとは (3, −2.4)＝51.3°で、「平行はそのまま・垂直だけ e 倍」で角度が
//   開くことが、直線2本の傾きの違いとして軌跡にそのまま残る。
const MOM_OBL_VX = 3;    // [m/s] 床に平行な成分（衝突で変わらない）
const MOM_OBL_VY = 4;    // [m/s] 床に垂直な成分（衝突で e 倍になって反転）
function demoObliqueBounce() {
  resetDemoWorld();
  setDemoGravity(0);          // ★重力なし＝行きも帰りも直線（冒頭の★）
  updateGroundTerrain(true);
  const ball = _momDropBall(-560, ground.y - 400 - MOM_BALL_R, MOM_OBL_VX, MOM_OBL_VY);
  ball.showForces = true;     // 床が出す力（垂直抗力）を見せる。摩擦0なので床に垂直な1本だけ
  // ★倍率 0.55（床との衝突と同じ理由。0.65 では出発点の球が本文の最終行に掛かっていた）
  setDemoCam(0, 0.55);
  // 成分で読む（x は変わらない・y だけが反転して縮む、が読みどころ）。
  //   ★autoStart：重力が無いので当たるまで加速度が 0 ＝ 既定の「加速度が生じるまで待つ」
  //     では、当たる前のまっすぐな区間が1点も残らない（比べる相手が消えてしまう）。
  moveDemoGraphTop(velGraphNew(ball, { showPos:true, showVel:true, showAcc:false,
                                       showX:true, showY:true, showMag:false,
                                       posOriginY:true, autoStart:true }));
  // ★床に当たった瞬間に止める（2026-10-01）。床が出す力は 1 tick にしか出ないので、
  //   走ったままでは矢印が見えない（衝突と合体のデモと同じ）。相手は地面・壁（env）。
  //   ★窓は右下へ。右うえは速度のグラフ、左うえは本文が占める。
  _momProgram(ball, { trigger:'hit', hitWhat:'env', action:'pause' }, 0.72, 0.88);
  // ★短い札を、軌跡の左どなり・説明文の下に置く。説明文が下へ伸びるので高い位置は
  //   使えず（実測：40字の札を y=−470 に置いて本文の最終行に掛かった）、左端も
  //   画面の外（x < −750）になる。空いているのは軌跡の左下だけ
  demoLabel(-740, ground.y - 330, '5 m/s（横 3・縦 4）', '#ef5350');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '斜めの衝突');
  demoNote (p.x, p.y + 54,
    '1 kg の球を、斜め下向き 5 m/s（横 3・縦 4）で床へ滑らせる。e = 0.6。\n'
  + '★重力は 0（エアテーブルを真上から見た図で、床は「縁の壁」）。行きも帰りも直線に\n'
  + '　なるので、床で変わったぶんだけを取り出して読める。当たるのは 1 回だけ。\n'
  + '\n'
  + '【手順】▶実行 を押して、軌跡（赤い線）と右うえのグラフを見る\n'
  + '・x（床に平行）は変わらない。ずっと 3 m/s の水平線のまま\n'
  + '　＝ 床は面に垂直な向きにしか力を出さない（摩擦0なので平行な力は0）\n'
  + '・y（床に垂直）だけが符号を変え、大きさは 0.6 倍（−4.0 → ＋2.4 m/s）\n'
  + '・そのぶん出ていく向きは寝る：入射は法線から 36.9°、反射は 51.3°\n'
  + '　＝ e < 1 では「入射角＝反射角」にならない（e = 1 なら等しい）\n'
  + '・変位の y は床から測った中心の高さ。0.22 m（半径）で折れて戻る\n'
  + '・当たった瞬間に自動で止まる（▶ で続き）。床に垂直な力の矢印が1本だけ出る\n'
  + '　＝ 斜めの衝突は「平行な成分はそのまま・垂直な成分だけ e 倍」で解ける');
}

// ── ⑥ ニュートン振り子 ──────────────────────────────────
//   ★「弾性衝突では運動量とエネルギーの両方が成り立つ」を、式ではなく形で見せる題材。
//     1個ぶつければ1個だけ出る。2個が半分の速さで出れば運動量は合うのにエネルギーが
//     足りない、という消去法がそのまま目の前で起きる。
//   ★球のあいだを 4px（4cm）だけ空けてある。ここは「接して並べる」と「空けて並べる」で
//     題材の性格が変わるところなので、実測を並べて選んだ（**このすきまの比較だけは球7個の
//     ころに測ったもの**。衝突ごとに 0.25 秒待ってから読んだ「真ん中5個の最大の速さ」／
//     「端の球の速さ」）：
//       すきま 0 … 0.00 が5回続く（真ん中は厳密に止まったまま）／端 1.77 のまま
//       すきま 2px … 0.02 → 0.04 → 0.07 → 0.11 → 0.14   ／端 1.73（画面では 1.3px で見えない）
//       すきま 4px … 0.04 → 0.09 → 0.16 → 0.23 → 0.31   ／端 1.64  ← これを採る
//       すきま 8px … 0.07 → 0.18 → 0.34 → 0.49 → 0.56   ／端 1.45
//     ★この「真ん中がだんだん一緒に揺れ出す」は計算の誤差ではない。刻みを 48 → 96 → 192 と
//       上げても数値が1つも変わらないので確かめられる。すきまを渡る間に球が振り子として
//       少し落ち、次の衝突が毎回わずかに違う高さで起きることから来る実際の振る舞い。
//     すきまがある側の利点は、力が1個ずつ順に渡っていくのが見えること（15個の列を渡り切る
//     のに 250ms＝15コマ。0.1× に落とすと1個ずつ動くのが追える）。接して並べると、この
//     受け渡しは1回の同時衝突に潰れて見えなくなる。
//   ★球は 15 個。**増やすほど見えが悪くなる、ではない**：「端の球が振り切って止まった瞬間
//     （＝力が列を渡り終えた瞬間）の、真ん中の球の最大の速さ」を折り返し8回ぶん並べると、
//       7個  … 0.00 0.08 0.16 0.22 0.25 0.27 0.26 0.23   [m/s]
//       11個 … 0.00 0.08 0.15 0.18 0.17 0.13 0.05 0.04
//       15個 … 0.00 0.08 0.13 0.13 0.08 0.01 0.09 0.14   ← これを採る
//     ほどけ具合は増やすほど**小さい**（ばらけた運動が多くの球に分かれて載るため）。
//     端の球の出ていく速さは 2.08 m/s でどれも同じ。上限を決めているのは画面の幅のほうで、
//     既定の倍率 0.65・幅 1280 の窓では、持ち上げた球を含めて左端が -4.5m（表示の端は -7.5m）。
//     ★この指標は「走っている最中」に読んではいけない。すきまを渡っている球そのものが
//       2 m/s で動いているので、真ん中の最大速さを毎 tick 読むと 2.09 が出てしまう。
//   ★すきまを空けると同時衝突が無くなるので、刻みは軽くて済む。実測（15個・すきま4px、
//     上と同じ指標の4回目／30秒後の端の球の速さ）：刻み8 … 0.13/1.81、16 … 0.13/1.83、
//     32 … 0.13/1.85、48 … 0.13/1.85。真ん中の揺れは刻みで変わらず、端の速さの目減りだけが
//     少し違う。16 で 48 との差は 1%（1.83 対 1.85）なので 16 を採る（7個のころと同じ差）。
//     ★接して並べる作りに戻すなら刻みは 48 が要る（実測：7個・すきま0 では 16 で衝突2回、
//       32 で4回、48 で5回まで。同時に触れ合う接触を1つずつ順に解くため誤差が積み上がる）。
//   ★持ち上げる角度は 25°。**弱く当てるほど良い、ではない**：当たりが弱いと1回の衝突で
//     伝える速度が小さく、誤差との比が悪くなって真ん中の球がまとめて動き出す
//     （実測・すきま0：25°で衝突5回もつのに、20°と15°は1回でほどけた）。
//   ★眠りは切る。待っている 14 個は静止しているので、眠らせると当たった瞬間の反応が遅れる
//     （①〜③の台車と同じ理由）。
//   ★2個いっしょに持ち上げた場合は、この計算では正しく出ない（実測：2個が
//     1.39 と 2.42 m/s に分かれる。同時に起きる衝突を1つずつ順に解いているため）。
//     だから説明文では1個の場合だけを読ませ、そのことを断っておく。
//   ★天井も床も壁も置かない。棒の片方の端は**背景に固定**する（Joint の bodyA:null＝
//     世界に固定した座標。手で作るときは「棒ツールで空中を始点にする」のと同じ）。
//     支点を梁の物体に留めると、梁を叩いた反作用が支点を伝って隣へ回り、球どうしの
//     衝突より先に力が伝わる経路ができてしまう。この題材は球の列だけで閉じているのがよい。
const NC_N       = 15;   // 球の数。★上の★の実測で選んだ値（画面の幅が上限）
const NC_R       = 22;   // [px] 球の半径（0.44 m）
const NC_ARM     = 240;  // [px] 吊り棒の長さ（2.4 m）
const NC_GAP     = 4;    // [px] 球どうしのすきま（4cm）。★上の★の実測で選んだ値
const NC_MASS    = 1;    // [kg] 15個とも同じ
const NC_DEG     = 25;   // [°]  左端の球を持ち上げる角度
const NC_SUBSTEP = 16;   // 刻み（すきまがあるので 48 は要らない。上の★）
// [px] 支点の高さ。★地面が無いので画面の中ほどに吊るす。説明文（11行）の下端から
//   支点まで 0.5m ほど空き、球の列は画面の下半分の真ん中あたりに来る
const NC_PIVOT_Y = -420;
function demoNewtonCradle() {
  resetDemoWorld();
  world.substeps = NC_SUBSTEP;
  world.sleeping = false;
  updateGroundTerrain(false);   // ★地面なし（天井・床・壁のどれも要らない。上の★）
  const py = ground.y + NC_PIVOT_Y;
  const step = 2 * NC_R + NC_GAP;
  const x0 = -(NC_N - 1) * step / 2;
  const balls = [];
  for (let i = 0; i < NC_N; i++) {
    const px = x0 + i * step;
    // 端の2個だけ色を変える（説明文が「青が止まって緑が出る」と指せるように）
    const col = i === 0 ? '#42a5f5' : i === NC_N - 1 ? '#66bb6a' : '#b0bec5';
    const b = new Body({
        fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
      type:'circle', x:px, y:py + NC_ARM, radius:NC_R, mass:NC_MASS,
      friction:0, frictionStatic:0, restitution:1,      // ★弾性衝突（e=1）・摩擦0
      fillColor:col, strokeColor:'#ffffff', strokeWidth:1.5,
      label:'球' + (i + 1),
    });
    objects.push(b);
    // 吊り棒。★片方の端（bodyA:null）は背景に固定＝支点は物体ではなく世界の座標。
    //   ★当たり判定は切る（layers:0）。棒は太さを持つ棒として他とぶつかるので、
    //   既定のままだと隣の球が隣の棒に触れて、球どうしの衝突より先に力が伝わってしまう
    joints.push(new Joint({ type:'rod', bodyA:null, anchorAx:px, anchorAy:py,
                            bodyB:b, restLength:NC_ARM, layers:0 }));
    balls.push(b);
  }
  // 左端だけ持ち上げる。★支点まわりに回すだけ（速度は与えない）。落ちたぶんの
  //   位置エネルギーがそのまま速さになるので、当たる速さは角度だけで決まる
  const th = NC_DEG * Math.PI / 180;
  balls[0].x = x0 - NC_ARM * Math.sin(th);
  balls[0].y = py + NC_ARM * Math.cos(th);
  setDemoCam(0, 0.65);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'ニュートン振り子');
  demoNote (p.x, p.y + 54,
    '同じ重さの球を15個、同じ長さの棒で1列にぶら下げてある。となりとはわずかな\n'
  + 'すきま（4cm）だけ空いていて、球どうしの跳ね返りは完全な弾性衝突。摩擦は無い。\n'
  + '左端の球（青）だけを持ち上げた状態から始める。\n'
  + '\n'
  + '【手順】▶実行 を押して、真ん中の球と右端の球（緑）を見る\n'
  + '・真ん中の球はすきまのぶんだけ動いて隣へ渡すだけ。反対の端の1個だけが出ていく\n'
  + '　（渡り切るのに 0.25 秒。上の速度を 0.1× に落とすと、1個ずつ順に渡るのが見える）\n'
  + '・出ていった球が戻ってぶつかると、こんどは左端の1個が出ていく。これが続く\n'
  + '・「2個が半分の速さで出る」は起きない。それでは勢い（運動量）のつじつまは合っても、\n'
  + '　弾性衝突では減らないはずのエネルギーが足りなくなるから\n'
  + '※すきまがあるぶん、渡し終わった球も完全には止まらない。衝突を重ねるほど真ん中も\n'
  + '　ゆっくり一緒に揺れ出す。読みどころは最初の数回');
}

// ════════════════════════════════════════
//  力学 ▸ 運動量（力積・衝撃振り子・反動・2次元の衝突・台車の上の車）
//  2026-10-01 追加。どれも「真上から見た図」か「水平方向に外力が無い図」で組み、
//  運動量グラフの合計が読めるようにしてある（冒頭の衝突と合体の★と同じ考え）。
// ════════════════════════════════════════
// 右に縦2枚の窓を置く（衝突と合体と同じ並び）。★渡した窓の右端をそろえる
function _momStackRight(list) {
  list.forEach((g, i) => {
    if (!g || !g.panel) return;
    sizeDemoGraph(g, MOM_GRAPH_W, MOM_GRAPH_H);
    g.panel.style.right = '10px'; g.panel.style.left = 'auto';
    g.panel.style.top = (56 + i * (MOM_GRAPH_H + 10)) + 'px'; g.panel.style.bottom = 'auto';
  });
}
// 窓のリモコン（つまみ・押しボタン）を1台置く
function _momRemote(kind, target, type, set, fx, fy) {
  const r = addRemote(kind, target, type);
  if (!r) return null;
  Object.assign(r, set);
  r.fx = fx; r.fy = fy;
  placeRemotePanel(r); syncRemotePanel(r);
  return r;
}

// ── 力積（かたいばね・やわらかいばね）───────────────────────────
//   ★同じ台車を同じ速さで壁にぶつける。違うのは台車の先に付けたばねの硬さだけ
//     （50 N/m と 2000 N/m）。受ける力の大きさと続く時間はまるで違うのに、
//     運動量の変化（＝力積）は同じになる。エアバッグ・受け身・グローブの話。
//   ★真上から見た図（重力0・摩擦0）。壁が与える力だけが外力なので、
//     運動量グラフの合計の変化がそのまま「壁から受けた力積」になる。グラフの傾きが力。
//   ★ばねは押し板（0.2 kg の丸い頭）を介して壁に当てる（分裂のデモの押し板と同じ作り）。
//     押し板と壁は e=0 で、押し板は縮む間ずっと壁に押しつけられて止まっている。
//     台車はばねに押し返されて逆向きに走り出し、ばねが自然長に戻ったところで押し板を
//     引きはがす。＝ 2本とも「押し板が壁で止まる」ぶんの損は同じで、違いは硬さだけ。
//   ★減衰は硬さに比例した割合（ζ = 0.02）にそろえる。ζ が同じなら跳ね返りの速さの比は
//     硬さによらない（減衰振動の半周期で残る割合は ζ だけで決まる）。減衰を 0 にすると
//     別れたあと押し板が台車の先で震え続け、硬いばねでは 1 tick より速く震える。
//       c = 2ζ√(k·M)（M ＝ 縮む間に動く台車 1 kg）
//   ★理論（減衰を無視）：最大の力 F = v√(kM)、続く時間 = π√(M/k)
//       やわらかい 50 N/m … 21 N・0.44 s　／　かたい 2000 N/m … 134 N・0.070 s
//     力 × 時間 の形は違っても、面積（力積）は同じ。
//   ★実測（2026-10-01、5秒）：運動量（台車＋押し板）の変化は やわらかい 6.420／かたい 6.385 N·s
//     （+3.600 → −2.820／−2.785。差 0.5%。かたい側は押し合いが 4 tick しかなく刻みの粗さが出る）。
//     変化にかかった時間 0.417／0.067 s、矢印の最大 20.6／123.7 N（かたい側は最大の瞬間が
//     tick の間に落ちるので理論の 134 N より低く出る）。止まるのは 116 tick と 127 tick。
//   ★押している最中で2回止める（プログラム〈何かが当たったら〉＋〈遅らせる〉）。
//     押し板が壁に当たった時刻から数えて、それぞれのばねがいちばん縮む時刻
//     （π/2·√(M/k)：かたい 0.035 s ＝ 2 tick、やわらかい 0.22 s ＝ 13 tick）。
//     1回目はかたい側の矢印が最大、2回目はやわらかい側の矢印が最大の画になる。
const IMP_KS     = [50, 2000];    // [N/m] やわらかい・かたい
const IMP_ZETA   = 0.02;          // 減衰の割合（上の★）
const IMP_L0     = 60;            // [px] ばねの自然長（やわらかい側が 42px 縮むので余裕を見る）
const IMP_PLATE  = 0.2;           // [kg] 押し板
const IMP_V0     = 3;             // [m/s]
const IMP_LANE_Y = [-230, 100];   // [px] 2本の走路の高さ（上：やわらかい・下：かたい）
const IMP_WALL_X = 250;           // [px] 壁の中心
function demoImpulseCushion() {
  _momSetup();
  world.forceVizScale = 1.5;      // [px per N] かたい側 134 N が 200px、やわらかい側 21 N が 32px
  const graphs = [], carts = [];
  IMP_KS.forEach((k, i) => {
    const y = ground.y + IMP_LANE_Y[i];
    const soft = (i === 0);
    const col = soft ? '#66bb6a' : '#ef5350';
    // 壁（固定）
    objects.push(new Body({ type:'box', x:IMP_WALL_X, y, w:30, h:140, isStatic:true, mass:0,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5 }));
    const cx = -450;
    const cart = _momCart(cx, 1, IMP_V0, 0, col, '台車 1kg', y);
    const plate = new Body({
      type:'circle', x:cx + MOM_CART_W / 2 + IMP_L0, y, radius:10, mass:IMP_PLATE,
      vx: toPx(IMP_V0), friction:0, frictionStatic:0, restitution:0,
      fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5, label:'押し板',
    });
    objects.push(plate);
    demoSpring({ bodyA:cart, anchorAx:MOM_CART_W / 2, anchorAy:0, bodyB:plate, anchorBx:0, anchorBy:0,
                 restLength:IMP_L0, stiffness:k, damping:2 * IMP_ZETA * Math.sqrt(k * 1), radius:8 });
    carts.push(cart);
    // 運動量（台車＋押し板＝1つの系）。★内訳は出さない（合計の変化＝壁からの力積だけを読む）
    graphs.push(momGraphNew([cart.id, plate.id], { comp:'x', showParts:false, showRef:true }));
    // いちばん縮んだ瞬間で止める（上の★）
    _momProgram(plate, { trigger:'hit', hitWhat:'body', action:'pause', times:1,
                         delay:(Math.PI / 2) * Math.sqrt(1 / k) },
                0.055, soft ? 0.60 : 0.66);
    demoLabel(cx - 60, y - 75, (soft ? 'やわらかいばね ' : 'かたいばね ') + k + ' N/m', col);
  });
  _momStackRight(graphs);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '力積（かたいばね・やわらかいばね）');
  demoNote (p.x, p.y + 54,
    '真上から見た図（重力なし・摩擦なし）。同じ 1 kg の台車を 3 m/s で壁にぶつける。\n'
  + '先に付けたばねの硬さだけが違う：上 50 N/m、下 2000 N/m。\n'
  + '\n'
  + '【手順】▶実行。ばねがいちばん縮んだ瞬間に、下・上の順で1回ずつ止まる（▶ で続き）\n'
  + '\n'
  + '【読みどころ】右の2枚（上の台車・下の台車）の運動量の変化は同じ\n'
  + '・下（かたい）：力は大きい（矢印 約 120 N）が、0.07 秒で終わる＝グラフが急に折れる\n'
  + '・上（やわらかい）：力は小さい（約 21 N）が、0.4 秒続く＝グラフがゆっくり下がる\n'
  + '・どちらも ＋3.6 → −2.8 kg·m/s。変化 ＝ 力 × 時間（力積）が同じだから\n'
  + '・グラフの傾きが力。同じ高さだけ下がるなら、時間をかけるほど力は小さい\n'
  + '　＝ エアバッグ・受け身・キャッチャーミットが衝撃をやわらげるしくみ');
}

// ── 衝撃振り子（弾丸の速さを測る）─────────────────────────────
//   ★撃ち込んで一体になる（完全非弾性）→ 振り上がる、の2段で解く題材。
//       衝突の間：運動量が保存（水平方向に外力が無い。吊り棒は鉛直で横向きの力を出さない）
//       振り上がる間：力学的エネルギーが保存（衝突では保存しない＝ここが要）
//     弾丸 0.5 kg・10 m/s、木片 2 kg：
//       一体の速さ V = 0.5×10/2.5 = 2.0 m/s、上がる高さ h = V²/2g = 0.204 m
//       運動エネルギー 25 J → 5 J（衝突で 80% が熱などへ）
//     逆にたどると、h を測れば v = (M+m)/m·√(2gh) で弾丸の速さが出る（これが実際の測り方）。
//   ★「一体になる」はくっつける仕掛けを使わず、形で作る：木片は左が開いたコの字で、
//     弾丸は溝に入って奥の壁に当たる（e=0）。振り上がって木片が減速する間は奥の壁が
//     弾丸を押し、戻るときは溝の床との静止摩擦（μ=1）で一緒に動く（傾きは最大 26°、
//     要る摩擦は tan で 0.44 g）。どれも系の中の力なので、運動量の話を崩さない。
//   ★弾丸は木片の手前 0.8 m から撃つ。遠くから撃つと飛ぶ間に重力で落ち、溝の床に
//     先に当たって奥の壁まで届かない（0.08 秒で 3 cm 落ちる。溝の高さは 30 cm）。
//   ★実測（2026-10-01、10秒）：当たるのは 6 tick 目。その 3 tick 後の運動量 4.97 kg·m/s・運動エネルギー
//     4.96 J（理論 5.00／5.00。差は振り上がり始めた重力のぶん）、振り上がった高さ 0.2034 m
//     （理論 0.204）。10 秒振らせても弾丸は溝の奥（木片の中心から 5.6px・6.9px）に留まったまま。
//   ★木片は回転を止める（fixedRotation）。吊り棒1本で吊るすので、回れると弾丸の当たる
//     高さで向きが変わり、溝の口が上を向いて弾丸がこぼれる。
const BP_M = 2, BP_m = 0.5, BP_v = 10;   // [kg] [kg] [m/s]
const BP_ROD = 200;                      // [px] 吊り棒（2 m）
const BP_W = 70, BP_H = 50, BP_SLOT = 30, BP_BACK = 14;   // [px] 木片の外寸・溝の高さ・奥の壁の厚み
// [px] 木片の静止位置（原点の高さ）。★重力の位置エネルギーの基準は原点を通る水平面
//   （physics/energy.js の★）。木片をそこに吊るすと、エネルギーグラフの重力が 0 から始まり、
//   「25 J → 5 J」「5 J が高さ h のぶんの位置エネルギーへ」が数のまま読める。
//   前は支点を原点の 4.3 m 上に置いていて、重力のぶんの 76 J が合計に下駄をはかせていた。
//   ★x は原点の縦の線から外す（目盛りの数字の列が吊り棒に重なる）
const BP_REST = { x: -250, y: 0 };
const BP_ZOOM = 0.9;                     // ★木片 0.7 m が画面で 63px。0.65 では 45px で溝が読めなかった
const BP_BULLET_R = 9;
function demoBallisticPendulum() {
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 16;
  updateGroundTerrain(false);    // ★地面は要らない（題材は宙に吊るした木片だけ）
  setDemoCam(0, BP_ZOOM);
  const ts = demoTextScale(BP_ZOOM);
  const bx = BP_REST.x, by = ground.y + BP_REST.y;   // 木片の中心（静止）
  const px = bx, py = by - BP_ROD;                    // 支点
  // コの字の木片（上の板・下の板・奥の壁を図形和で1つに）
  const t = (BP_H - BP_SLOT) / 2;
  const mat = { friction:1, frictionStatic:1, restitution:0, fillColor:'#a1887f', strokeColor:'#d7ccc8',
                strokeWidth:1.5 };
  const top  = new Body(Object.assign({ type:'box', x:bx, y:by - BP_SLOT / 2 - t / 2, w:BP_W, h:t, mass:1 }, mat));
  const bot  = new Body(Object.assign({ type:'box', x:bx, y:by + BP_SLOT / 2 + t / 2, w:BP_W, h:t, mass:1 }, mat));
  const back = new Body(Object.assign({ type:'box', x:bx + BP_W / 2 - BP_BACK / 2, y:by, w:BP_BACK, h:BP_H, mass:1 }, mat));
  const block = demoUnion(top, bot, back);
  block.setMass(BP_M);
  block.fixedRotation = true;          // ★上の★
  block.label = '木片 2kg';
  block.tracerEnabled = true; block.tracerColor = '#ffcc80'; block.tracerDuration = 12;
  const rod = new Joint({ type:'rod', bodyA:null, anchorAx:px, anchorAy:py, bodyB:block,
                          restLength:BP_ROD, layers:0 });
  setJointEnd(rod, 'B', block, bx, by - BP_H / 2, false);
  rod.restLength = BP_ROD - BP_H / 2;
  joints.push(rod);
  // 弾丸（溝の高さで、木片の手前 0.8 m から）
  const bullet = new Body({ type:'circle', x:bx - BP_W / 2 - 80, y:by, radius:BP_BULLET_R, mass:BP_m,
    vx: toPx(BP_v), fixedRotation:true, friction:1, frictionStatic:1, restitution:0,
    fillColor:'#ffd54f', strokeColor:'#fff8e1', strokeWidth:1.5, label:'弾丸 0.5kg' });
  objects.push(bullet);
  // 振り上がる高さの目安（理論 h = 0.204 m）。★木片の中心の高さで引く
  const hPx = toPx((BP_m * BP_v / (BP_M + BP_m)) ** 2 / (2 * G_EARTH));
  demoDashedPath(bx - 60, by - hPx, bx + 170, by - hPx, '#4fc3f7', 2, 8, 6);
  demoLabel(bx - 250, by - hPx - 12, 'h = 0.20 m（理論）', '#4fc3f7', DEMO_NOTE_SIZE * ts);
  // グラフ：運動量（px）と力学的エネルギー（運動＋重力）
  const ids = [block.id, bullet.id];
  const gm = momGraphNew(ids, { comp:'x', showParts:true, showRef:true });
  const ge = eneGraphNew(ids, { showKt:true, showKr:false, showUg:true, showUs:false,
                                showUgg:false, showUe:false, showMech:true });
  _momStackRight([gm, ge]);
  _momProgram(bullet, { trigger:'hit', hitWhat:'body', action:'pause', times:1 }, 0.055, 0.88);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '衝撃振り子（弾丸の速さを測る）', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '2 kg の木片を 2 m の棒で吊るす。0.5 kg の弾丸を 10 m/s で撃ち込むと、\n'
  + '溝の奥で止まり、木片と一体になって振り上がる。\n'
  + '\n'
  + '【手順】▶実行。弾丸が当たった瞬間に一度止まる（▶ で続き）\n'
  + '\n'
  + '【読みどころ】2段に分けて解く\n'
  + '① 当たる瞬間：運動量が保存（右うえ）。5 kg·m/s → 2.5 kg × 2.0 m/s\n'
  + '　（振れ始めると棒の張力が横向きの成分をもつ＝外力。だから合計はそのあと減る）\n'
  + '② 振り上がる間：力学的エネルギーが保存（右下）。½·2.5·2.0² ＝ 2.5·g·h\n'
  + '　→ h ＝ 0.20 m（水色の線まで上がる）\n'
  + '・エネルギーは①で 25 J → 5 J に減る（80% が熱へ）。運動量は減らない\n'
  + '・逆にたどれば、h を測るだけで弾丸の速さが分かる：v ＝ (M+m)/m·√(2gh)', DEMO_NOTE_SIZE * ts);
}

// ── ロケットの反動（3発）────────────────────────────────────
//   ★真上から見た図（重力0・摩擦0）。ロケットの後ろに、縮めたばねの発射台が3本並び、
//     それぞれに 0.5 kg の球が留めてある（ヒンジ）。1〜3 キーで留め具を外すと、ばねが
//     球を後ろへ押し出し、その反作用でロケットが前へ進む。＝分裂のデモを3回続けたもの。
//   ★ばねも球もロケットの一部（系の中）なので、何発撃っても合計の運動量は 0 のまま。
//     重心も最初の場所から動かない。「押すものが無い宇宙でもロケットは進める」の答え。
//   ★発射台は3本とも同じ（同じばね・同じ縮み）。それでも1発ごとにロケットの増える速さは
//     少しずつ大きくなる：撃つたびにロケット側が軽くなるので、同じ押し方でも速く動く。
//   ★実測（2026-10-01、1〜3 発を 1.5 秒おき）：ロケットの速さ 0.314 → 0.668 → 1.073 m/s
//     （増え方 0.314・0.354・0.406。比 1.13・1.29 は減衰を無視した理論 0.390・0.441・0.505 の比
//     1.13・1.29 と一致。絶対値が 2 割低いのは、ばねの減衰と押し板が持ち去るぶん）。
//     合計運動量 0.000000、重心のずれ 1e-11 px。
//     ☆2026-10-02 に留め具の腕（下の★）で留める作りへ組み替えたあとの値は RK_ARM_M の★。
//   ★留め具はヒンジ（リモコン〈外す・留め直す〉）。重心の求め方のデモと同じ部品。
//     留めるのは押し板と球の両方で、1台のリモコンで同時に外す。押し板と球の間は 1px 空ける。
//   ★押し板と球は胴の外にあるので、胴に直接ヒンジは打てない（ヒンジは画鋲：重なったものを
//     1点で留める。selection.js の pinJointsAt の★）。そこで胴の後ろの面から各段へ細い
//     「留め具の腕」を出し（胴と図形和で1つの物体）、押し板と球はその腕と重なる点でヒンジ留めする。
//     ロケットは押し板・球と別の衝突レイヤー（2）に置く＝腕を重ねても押し合わず、飛び出す球も
//     腕をすり抜ける。この宇宙の図でロケットが当たる相手はもともと何も無いので、動きは変わらない。
//     ★2026-10-02 のいきさつ：はじめは胴の外の点へヒンジを直接書いていて、手では組めなかった。
//       いったん胴を後ろへ伸ばして（発射筒）押し板と球を重ねる作りにしたあと、ユーザーの提案
//       （衝突しない部品 B を A に溶接し、B を留める）で、球が胴の外に並ぶ元の絵に戻した。
//       ★腕を別の物体にして溶接する形は採らなかった：溶接とヒンジの連なりがばねの力（42 N）で
//         たわみ、外す前から胴が揺れた（実測：外す前の胴の速さの最大 腕 0.05kg で 0.26 m/s、
//         0.5kg で 0.03、1.5kg でやっと 0.003。直す前は 4e-5）。重くすると運動量グラフの
//         「ロケット」の線が胴の一部の質量しか表さなくなる。図形和なら腕は胴そのもので、たわまない。
//       どの作りも手のツールだけで組める（図形和・衝突レイヤー・ヒンジ）。
//     ★球だけを留めて押し板で押しつけておく作りは使えない：押し板が「止まっているのに
//       速度 −1.68 m/s を持つ」状態に落ち着き（接触の位置補正が毎回押し戻すため）、
//       系の運動量の合計がその分だけずれた（実測：外す前から押し板2枚で −0.17 kg·m/s）。
//       押し板をヒンジで留めればばねの力は留め具が受け、接触には何の力もかからない。
//   ★留め具の窓は本文の下に横1列（ロケットの走る高さ RK_Y の★）。
//   ★発射台を縦に並べるので、押す力がロケットの重心からずれると回る。上下対称に
//     並べ（−32・0・＋32px）、ロケットの回転は止める（fixedRotation）。
const RK_M = 3, RK_BALL = 0.5;            // [kg]
const RK_W = 150, RK_H = 110;             // [px] ロケットの胴（留め具の腕を除いた箱）
const RK_DY = [-32, 0, 32];               // [px] 発射台の位置（胴の中心から）
const RK_K = 300, RK_L0 = 30, RK_X = 14;  // [N/m] [px] [px] 分裂のデモと同じばね
const RK_C = 0.65;                        // [N·s/m] 分裂のデモと同じ減衰
// [px] 胴の中心の高さ。★グラフの窓（右に縦2枚・下端は画面の 586px）より下を走らせる。
//   −200 では 1 m/s に達したロケットが 4 秒で窓の裏に入った。留め具の窓は本文のすぐ下へ回す
const RK_Y = 90;                         // ★60 では胴の上端が原点の線と目盛りの数字に掛かった
const RK_GAP = 1;                         // [px] 押し板と球のすきま（上の★）
function demoRocketRecoil() {
  _momSetup();
  world.forceVizScale = 3;
  const cx = -80, cy = ground.y + RK_Y;
  // ── ロケット＝胴の箱 ＋ 各段の留め具の腕（図形和で1つ。上の★）──
  //   ★横の腕は胴の後ろの面（2px 食い込ませる）から、押し板と球の中心を通って球の中心の 4px 先まで
  const bx = cx - RK_W / 2;                       // 胴の後ろの面
  const ballX = bx - (RK_L0 - RK_X) - 7 - 12 - RK_GAP;
  const armL = bx + 2, armR = ballX - 4;
  const rocket = demoUnion(new Body({ type:'box', x:cx, y:cy, w:RK_W, h:RK_H }),
    ...RK_DY.map(dy => new Body({ type:'box', x:(armL + armR) / 2, y:cy + dy, w:armL - armR, h:4 })));
  rocket.setMass(RK_M);
  Object.assign(rocket, { layers:0b0010,   // ★押し板・球（レイヤー1）と分ける（上の★）
    friction:0, frictionStatic:0, restitution:0, fixedRotation:true, showForces:true,
    fillColor:'#5c6bc0', strokeColor:'#c5cae9', strokeWidth:2, label:'ロケット 3kg' });
  const parts = [rocket], hinges = [];
  RK_DY.forEach((dy, i) => {
    const plateX = cx - RK_W / 2 - (RK_L0 - RK_X);
    const plate = new Body({ type:'circle', x:plateX, y:cy + dy, radius:7, mass:0.05,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1, label:'押し板' + (i + 1) });
    objects.push(plate);
    //   ★ばねの根元は胴の後ろの面。図形和で重心が腕のぶん後ろへずれるので、ローカル座標は世界の点から取る
    const root = getLocalAnchor(rocket, bx, cy + dy);
    demoSpring({ bodyA:rocket, anchorAx:root.x, anchorAy:root.y, bodyB:plate, anchorBx:0, anchorBy:0,
                 restLength:RK_L0, stiffness:RK_K, damping:RK_C, radius:6 });
    const ball = new Body({ type:'circle', x:plateX - 7 - 12 - RK_GAP, y:cy + dy, radius:12, mass:RK_BALL,
      friction:0, frictionStatic:0, restitution:0, fixedRotation:true,
      fillColor:['#ef5350', '#ffd54f', '#26c6da'][i], strokeColor:'#ffffff', strokeWidth:1.5,
      label:'球' + (i + 1) });
    ball.tracerEnabled = true; ball.tracerColor = ball.fillColor; ball.tracerDuration = 8;
    objects.push(ball);
    parts.push(plate, ball);
  });
  // 留め具は2つ（押し板と球）。1台のリモコンで同時に外す（下の rs）
  //   ★打つのは手のツールと同じ入口（demoPin）。押し板・球の中心は留め具の腕（ロケット）と重なっている
  RK_DY.forEach((dy, i) => {
    const plate = parts[1 + 2 * i], ball = parts[2 + 2 * i];
    hinges.push([plate, ball].map(b => demoPin('hinge', b.x, b.y, 'pair', { expect:[b, rocket] })));
  });
  rocket.tracerEnabled = true; rocket.tracerColor = '#9fa8da'; rocket.tracerDuration = 12;
  const ids = parts.map(b => b.id);
  const gm = momGraphNew(ids, { comp:'x', showParts:true, showRef:true });
  // ★下はロケットの速度。運動量（本体 3 kg だけ）にすると、まだ撃っていない球のぶんが
  //   入らず「球が持ち去ったぶんと同じ大きさ」が成り立たない。速度なら段の高さがそのまま読める
  const gr = velGraphNew(rocket, { showPos:false, showVel:true, showAcc:false,
                                   showX:true, showY:false, showMag:false, autoStart:true });
  _momStackRight([gm, gr]);
  comIds = ids.slice();
  // 留め具のリモコン（1〜3 キー）。★左下に横1列
  const rs = [];
  hinges.forEach((h, i) => {
    const r = addRemote('ghost', h[0], 'joint', h.map(j => j.id));
    if (!r) return;
    r.key = 'Digit' + (i + 1); r.collapsed = true;
    syncRemotePanel(r);
    rs.push(r);
  });
  let x = 56;
  for (const r of rs) {
    r.fx = x / canvas.width; r.fy = 0.43;
    placeRemotePanel(r); syncRemotePanel(r);
    x += (r.panel.offsetWidth || 170) + 6;
  }
  demoLabel(cx - 330, cy + 50, '発射台 ×3 →', '#ffd54f');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'ロケットの反動（3発）');
  demoNote (p.x, p.y + 54,
    '宇宙を真上から見た図（重力なし・何にも触れていない）。3 kg のロケットの後ろに、\n'
  + '縮めたばねの発射台が3本あり、0.5 kg の球が1つずつ留めてある。全部止まっている。\n'
  + '\n'
  + '【手順】▶実行 してから、1・2・3 キー（下の窓）で1発ずつ留め具を外す\n'
  + '\n'
  + '【読みどころ】押す相手が無くても、球を後ろへ押し出した反作用で前へ進む\n'
  + '・右うえ：全体の運動量の合計（黄）は 0 のまま（何発撃っても）。\n'
  + '　球は − へ、ロケット（青）は ＋ へ。1発ごとに同じ大きさだけ逆向きに分かれる\n'
  + '・右下：ロケットの速さは階段状に増える。0.31 → 0.67 → 1.07 m/s\n'
  + '　増え方は 0.31・0.35・0.41 と、あとの発ほど大きい（軽くなったロケットを押すから）\n'
  + '・白黒の丸は全体の重心。ロケットが進んでも、その場から動かない');
}

// ── 2次元の衝突（ビリヤード）────────────────────────────────
//   ★真上から見た図（重力0・摩擦0）。同じ質量の球を、中心をずらして当てる。
//     e = 1 なら2球は直角（90°）に分かれる：運動量 m·v⃗ = m·v⃗₁' + m·v⃗₂' と
//     エネルギー v² = v₁'² + v₂'² の両方を満たすのは、v⃗₁' ⊥ v⃗₂' のときだけ（三平方の定理）。
//   ★ずらしは半径ぶん（b = R）。当たる瞬間の中心を結ぶ線は進む向きから 30° 傾き、
//     的の球はその線の向きに 3cos30° = 2.60 m/s、手玉は 60° の向きに 3sin30° = 1.50 m/s。
//   ★運動量グラフを2枚（px・py）。py ははじめ 0 で、衝突のあと2球が上と下へ逆向きに
//     分け持つ（合計は 0 のまま）。成分ごとに保存する、が読める。
//   ★反発係数は手玉のつまみ（的の球は e=1 に固定。合成は積）。e < 1 では 90° より狭くなる。
//   ★実測（2026-10-01、200 tick）：e=1 で2つの向きの開きは 90.00°（手玉 +59.66°・1.516 m/s、
//     的 −30.34°・2.589 m/s。30° からの 0.34° は、接触を見つけた時点でわずかに重なっているぶん）。
//     e=0.5 で 66.87°。どちらも px 3.000000・py 0.000000。当たるのは 67 tick 目。
const BIL_R = 30, BIL_V = 3;
// [px] 手玉の走る高さ。★−240 では、衝突のあと 60° 上へ進む手玉が 2 秒で本文に届いた。
//   下げると、30° 下へ進む的の球はグラフの窓の下端（画面 586px）より下を抜けていく
const BIL_Y = -105;
function demoBilliards() {
  _momSetup();
  world.forceVizScale = 1;
  const y = ground.y + BIL_Y;
  const ball = (x, yy, v, col, label) => {
    const b = new Body({ type:'circle', x, y:yy, radius:BIL_R, mass:1, vx:toPx(v),
      friction:0, frictionStatic:0, restitution:1, fixedRotation:true, showForces:true,
      fillColor:col, strokeColor:'#ffffff', strokeWidth:1.5, label });
    b.tracerEnabled = true; b.tracerColor = col; b.tracerDuration = 10;
    objects.push(b);
    return b;
  };
  const a = ball(-650, y, BIL_V, '#eceff1', '手玉 1kg');
  const b = ball(-260, y + BIL_R, 0, '#ef5350', '的 1kg');      // ★半径ぶん下へずらす
  const gx = momGraphNew([a.id, b.id], { comp:'x', showParts:true, showRef:true });
  const gy = momGraphNew([a.id, b.id], { comp:'y', showParts:true, showRef:true });
  _momStackRight([gx, gy]);
  comIds = [a.id, b.id];
  _momRemote('prop', a, 'body', { prop:'restitution', lo:0, hi:1, collapsed:true }, 0.055, 0.84);
  _momProgram(a, { trigger:'hit', hitWhat:'body', action:'pause', times:1 }, 0.30, 0.84);
  demoLabel(-700, y - 75, '手玉 3 m/s →', '#eceff1');
  demoLabel(-300, y + BIL_R + 28, '的（半径ぶん下）', '#ef9a9a');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '2次元の衝突（ビリヤード）');
  demoNote (p.x, p.y + 54,
    '真上から見た図（重力なし・摩擦なし）。同じ 1 kg の球を、中心を半径ぶん\n'
  + 'ずらして当てる。反発係数は左下のつまみ（はじめ e = 1）。\n'
  + '\n'
  + '【手順】▶実行。当たった瞬間に一度止まる（▶ で続き）。e を変えるときは ↩ で戻してから\n'
  + '\n'
  + '【読みどころ】運動量は成分ごとに保存する\n'
  + '・右うえ（px）：合計は 3 kg·m/s のまま。右下（py）：合計は 0 のまま、\n'
  + '　2球が上と下へ同じ大きさで逆向きに分け持つ\n'
  + '・止まった画：力は2球の中心を結ぶ線の向き。的はその向きへ飛び出す\n'
  + '・e = 1 なら2つの道すじは直角（90°）に開く（的 約 2.6 m/s・手玉 約 1.5 m/s）\n'
  + '　＝ 運動量とエネルギーの両方が保存するのは、直角に分かれるときだけ\n'
  + '・e を下げると直角より狭くなる（e = 0.5 で 67°）\n'
  + '・重心（白黒の丸）はどの e でもまっすぐ進む');
}

// ── 台車の上を走る車（人と台車）──────────────────────────────
//   ★横から見た図。床は摩擦0（台車は自由に滑る）。台車の上をモーターで車輪を回す
//     おもちゃの車が走る。車を前へ押すのは「車輪と台車の床との摩擦」で、その反作用が
//     台車を後ろへ押す。＝ 台車の上を人が歩くのと同じ（人を押すのは足と床の摩擦）。
//   ★モーターのトルクは車体と車輪の間の内力、摩擦は車輪と台車の間の内力。
//     水平方向の外力（床の摩擦）は0なので、車＋台車の px は 0 のまま。
//     重力と床の垂直抗力は鉛直なので px には効かない（py は保存しない＝成分は px だけ見る）。
//   ★動かすのは方向キー（リモコン〈モーターを回す〉。→ 前・← 後ろ）。
//     放すと軸にブレーキがかかる（motorBrake）＝車は台車の上で止まる。そのとき台車も止まる。
//     「人が止まると台車も止まる」が運動量 0 のまま読める。
//   ★台車の両端には止め（図形和でひと続き）。車が端から落ちない。
//   ★実測（2026-10-01、→ を 1 秒押して放し、1.8 秒後に ← を 1 秒）：押している間 車 +0.815・
//     台車 −0.285 m/s（比 2.86 ＝ 4 kg / 1.4 kg）、放すと 2 tick で両方 0.000。← で同じ速さの逆、
//     放すと車は台車の上のはじめの位置（−0.1px）に戻って止まる。合計運動量の最大 2e-14、
//     重心の横のずれ 0.001px（縦は台車が床になじむ 0.6px）。
const CC_CART_W = 420, CC_CART_H = 20, CC_CART_M = 4;   // [px] [px] [kg]
const CC_CAR_W = 70, CC_CAR_H = 26, CC_CAR_M = 1;       // [px] [px] [kg]
const CC_WHEEL_R = 11, CC_WHEEL_M = 0.2;                 // [px] [kg]
const CC_ZOOM = 1.0;    // ★0.65 では車が画面で 45px しかなく、車輪の回るのが見えなかった
const CC_SPEED = 10;                                      // [rad/s] 車輪の回る速さ（台車に対して 1.1 m/s）。★25 では 1 秒で台車の端に着いた
function demoCartWalker() {
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 8;
  updateGroundTerrain(true);
  ground.friction = 0; ground.frictionStatic = 0;   // ★床は摩擦0（台車は自由に滑る）
  setDemoCam(0, CC_ZOOM);
  const ts = demoTextScale(CC_ZOOM);
  const gy = ground.y;
  const cy = gy - CC_CART_H / 2;
  const mat = { friction:1, frictionStatic:1, restitution:0, fillColor:'#8d6e63', strokeColor:'#d7ccc8',
                strokeWidth:1.5 };
  const base = new Body(Object.assign({ type:'box', x:0, y:cy, w:CC_CART_W, h:CC_CART_H, mass:1 }, mat));
  const stopL = new Body(Object.assign({ type:'box', x:-CC_CART_W / 2 + 6, y:cy - CC_CART_H / 2 - 15,
                                         w:12, h:30, mass:1 }, mat));
  const stopR = new Body(Object.assign({ type:'box', x: CC_CART_W / 2 - 6, y:cy - CC_CART_H / 2 - 15,
                                         w:12, h:30, mass:1 }, mat));
  const cart = demoUnion(base, stopL, stopR);
  cart.setMass(CC_CART_M);
  cart.fixedRotation = true;
  cart.label = '台車 4kg';
  // 車（車体＋車輪2つ）
  const topY = cy - CC_CART_H / 2;
  const wy = topY - CC_WHEEL_R;
  // ★車体の下面は車輪の中心より 4px 下まで下げ、軸の点を車体と車輪の両方に重ねる（軸は画鋲：
  //   重なった2つを1点で留める。手の軸ツールもクリック点に重なる2つをつなぐ）。以前は車体の
  //   下面が中心の 4px 上で、軸の点は車体の外＝手では組めなかった（2026-10-02 に直した）。
  //   ★重ねたぶん車体はレイヤー2に分ける（車輪と押し合わないように）。台車の止めに当たるのは
  //   車輪のほうで（車輪の前端＝車体の前端）、車体が止めに当たらなくなっても止まり方は同じ。
  const carY = wy - CC_CAR_H / 2 + 4;
  const car = new Body({ type:'box', x:0, y:carY, w:CC_CAR_W, h:CC_CAR_H, mass:CC_CAR_M,
    layers:0b0010,
    friction:0, frictionStatic:0, restitution:0, fixedRotation:true,
    fillColor:'#42a5f5', strokeColor:'#bbdefb', strokeWidth:1.5, label:'車 1kg' });
  objects.push(car);
  const axles = [], wheels = [];
  for (const dx of [-24, 24]) {
    const w = new Body({ type:'circle', x:dx, y:wy, radius:CC_WHEEL_R, mass:CC_WHEEL_M,
      friction:1, frictionStatic:1, restitution:0,
      fillColor:'#37474f', strokeColor:'#cfd8dc', strokeWidth:1.5,
      label:(dx < 0 ? '後輪' : '前輪') + ' 0.2kg' });
    objects.push(w);
    wheels.push(w);
    //   ★打つのは手のツールと同じ入口（demoPin）。spin:w ＝車輪が車体に対して ＋CC_SPEED で回る向き
    const j = demoPin('axle', w.x, w.y, 'pair', { expect:[car, w], spin:w,
      motorSpeed:CC_SPEED, motorTorque:50, motorBrake:true, opts:{ layers:0 } });
    axles.push(j);
  }
  car.tracerEnabled = true; car.tracerColor = '#90caf9'; car.tracerDuration = 10;
  const ids = [cart.id, car.id, ...wheels.map(w => w.id)];
  const gm = momGraphNew(ids, { comp:'x', showParts:true, showRef:true });
  _momStackRight([gm]);
  comIds = ids.slice();
  // 方向キーで回す（→ 前・← 後ろ）。★1台のリモコンで2つの軸をまとめて回す（remote.js の★）
  //   ★右向きに進むには車輪を時計回り（画面で）に回す。y が下向きなので角速度は正。
  const mk = (key, mode, fx) => {
    const r = addRemote('motor', axles[0], 'joint', axles.map(j => j.id));
    if (!r) return;
    r.key = key; r.mode = mode; r.collapsed = true;
    r.fx = fx; r.fy = 0.60;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  mk('ArrowRight', 'on', 0.055);
  mk('ArrowLeft', 'rev', 0.30);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '台車の上を走る車（人と台車）', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '摩擦の無い床に 4 kg の台車。その上に、モーターで車輪を回す 1.4 kg の車がのっている。\n'
  + '車を前へ押すのは車輪と台車の床との摩擦（人が歩くときの足の裏と同じ）。\n'
  + '\n'
  + '【手順】▶実行 してから → キー（前）・← キー（後ろ）を押す。放すと車輪が止まる\n'
  + '\n'
  + '【読みどころ】車が進むと台車は逆へ下がる\n'
  + '・右うえ：合計（黄）は 0 のまま。車と車輪（＋）と台車（青・−）が同じ大きさを分け持つ\n'
  + '・速さは質量に反比例：車 1.4 kg が右へ 0.82 m/s、台車 4 kg は左へ 0.29 m/s\n'
  + '・キーを放して車が止まると、台車もその場で止まる（合計 0 だから）\n'
  + '・白黒の丸は全体の重心。どう動かしても、その場から動かない\n'
  + '　＝ 中にいる人がどう歩いても、外から押されない限り全体の重心は動かない', DEMO_NOTE_SIZE * ts);
}

// ════════════════════════════════════════
//  力学 ▸ 円運動
// ════════════════════════════════════════
// ── 円運動（張力／垂直抗力）─────────────────────────────────
//   ★真上から見下ろした図（重力0・地面なし）。横から見た図にすると重力と垂直抗力が
//     加わり、向心力が「合力の一部」になってしまう。真上から見れば、円運動を保つ力
//     ちょうど1本だけが画面に出る＝「向きだけを変える力」を単独で見せられる。
//   ★同じ半径・同じ速さの2台を並べ、力の出どころだけを変える（糸が引く／壁が押す）。
//     出どころが違うのに矢印の長さと向きが同じになる、が読みどころなので、
//     半径と速さは2台で同じ定数を使う（作り分けの取り違えが起きようがない）。
//     ★③（モーターで回す棒）も同じ定数から組む。開いた時点は3台とも 5.00 m/s で並ぶ。
//   ★①②の力の矢印は必ず表示（showForces）。向心力は m v²/r = 1×5²/1.7 = 14.7 N。
//     ★矢印の長さは「円の半径の半分」に合わせる（CIR_F_FRAC）。矢印は画面 px で描かれる
//       ので、倍率は px/N を決め打ちせずカメラの倍率から出す。以前の 8 px/N だと 118px
//       ＝画面上の半径（170×0.65＝110px）とほぼ同じ長さになり、矢印の先が円の中心まで
//       届いて半径の線と見分けにくかった。半分（倍率 0.65 で 55px＝球2個ぶん強）なら
//       中心の手前で止まり、それでも十分見える。
//   ★③（モーターで回す棒）だけは矢印を出さない。読みどころが別だから：
//     ①②は「出どころの違う力が同じ1本になる」、③は「回す速さ ω を変えると v と T が
//     どう動くか」。定常で回っているあいだ、棒が球に及ぼす力は①の糸と同じ向心力1本に
//     なるが、つまみを動かしている最中だけは接線向きの力も出る（モーターが角速度を
//     変えているのだから当然）。それを①②と並べて出すと「力はいつも進む向きと直角」
//     という読みが濁る。
//     ★③はモーターが角速度を決めるので、球と棒の質量は運動に効かない。それでも球を
//       1kg にしてあるのは、①②と見くらべる相手として同じ札（1kg）が出ているほうが
//       よいから。実測：ω を 2.94／1.47／6／0 と切り替えて 10秒ずつ時間平均すると、
//       半径は 4つとも 170.0px（狙いどおり）、速さは 5.000／2.500／10.200／0.000 m/s
//       ＝ v=rω と小数第3位まで一致。角速度の実測は 2.936／1.468／5.990／0.000 で、
//       目標との差は 0.2% 以内（モーターが目標へ寄せるときの遅れぶん）。
//     ★つまみを動かしてから追いつくまでは 3〜5 tick（0.05〜0.08 秒）。実測：
//       2.94→6 が3、6→0 が5、0→2.94 が3 tick（トルク上限は既定の 288 N·m のまま）。
//   ★3台の置き場所は「x=0 の目盛りの線が装置に重ならない」で決めた。①②③を等間隔
//     500px で並べ、カメラを②の中心（x=260）に置くと、線は①の円の右端（画面 286px）と
//     ②の円筒の左端（365px）のあいだ、332px に落ちる。cam.x=0 のまま3台を ±500・0 に
//     並べると、線と数字の列が②の円筒をまっすぐ縦に貫く。
//   ★刻みは 32。糸（ロープ拘束）の位置補正がわずかに速さを削るため。実測（20秒後の速さ。
//     初速 5.00 m/s）：刻み4 … 3.83／16 … 4.61／32 … 4.79／64 … 4.79。32 で頭打ち。
//     壁の側は刻み16でも 5.00 のまま落ちない（接触は速度で解くので位置補正が要らない）。
//   ★壁は「円板に穴を開けた形」で作る。外周の円と内周の円を渡して detectArcs に円弧として
//     覚えさせる（js/physics/arc.js）。多角形のままだと継ぎ目ごとに法線が折れて速さが減る。
//     実測：この作りなら 10秒回しても半径 170.0〜170.5px・速さ 5.00 m/s のまま。
const CIR_R      = 170;  // [px] 球の中心が描く円の半径（1.7 m）。3台で共通
const CIR_V      = 5;    // [m/s] 速さ。3台で共通（③は開いた時点の速さ）
const CIR_BALL_R = 18;   // [px] 球の半径
const CIR_WALL_T = 22;   // [px] 円筒の壁の厚み
const CIR_CY     = -190; // [px] 3台の円の中心の高さ
const CIR_CX     = [-240, 260, 760];  // [px] ①糸／②円筒／③モーターの中心。★上の★で決めた並び
const CIR_ROD_W  = 10;   // [px] ③の棒の太さ
const CIR_ROD_M  = 0.5;  // [kg] ③の棒の質量。★モーターが角速度を決めるので運動には効かない
// [rad/s] ③のモーターの角速度。★開いた時点は①②と同じ速さ ＝ v/r = 5/1.7
const CIR_W0     = CIR_V / (CIR_R * PX2M);
// [rad/s] つまみの上げ幅。★下限は 0（止まっているところから上げられる。remote.js の★）。
//   remotePropTicks が範囲を 200 等分するので 0.03 rad/s 刻みになり、はじめの 2.94 も打てる。
//   上限 6 は開いた時点の倍より少し上＝「倍にすると速さも周期も倍と半分」が range に入る
const CIR_W_MAX  = 6;
// 開いた時点の①②の力の矢印の長さ ÷ 円の半径（どちらも画面上）。★上の★（半径の半分）
const CIR_F_FRAC = 0.5;
// 装置の上の見出し。★x は「装置の中心で揃える」。3台に増えていちばん右の札が画面の外へ
//   はみ出したので、決め打ちのずらし幅（-150px）をやめて字数から中央寄せを出す
//   （本文と同じ 23px の全角字＝ワールド 23px 幅で数えると、実測とほぼ合う）
function _cirLabel(cx, cy, text, color) {
  demoLabel(cx - text.length * DEMO_NOTE_SIZE / 2, cy, text, color);
}
// 円周上の点。ccw=false で逆向き（穴のループは外周と逆回りにする）
function _circleLoop(r, n, ccw) {
  const p = [];
  for (let i = 0; i < n; i++) {
    const a = (ccw ? 1 : -1) * 2 * Math.PI * i / n;
    p.push({ x: r * Math.cos(a), y: r * Math.sin(a) });
  }
  return p;
}
// 球1個。★上向き（-y）に置いて右向きの初速を与えると、時計回りに回る
//   ★力の矢印を出すかは呼ぶ側が決める（③だけ出さない。冒頭の★）
function _cirBall(cx, cy, color, showForces) {
  const b = new Body({
    type:'circle', x:cx, y:cy - CIR_R, radius:CIR_BALL_R, mass:1, vx: toPx(CIR_V),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5,
    showForces: showForces !== false, label:'1kg',
  });
  b.tracerEnabled = true; b.tracerColor = color; b.tracerDuration = 3;   // 1周 2.1秒ぶん残す
  objects.push(b);
  return b;
}
function demoCircularMotion() {
  resetDemoWorld();
  setDemoGravity(0);            // ★真上から見下ろした図
  world.sleeping = false;
  world.substeps = 32;          // ★糸の側が速さを保つのに要る（冒頭の★）
  updateGroundTerrain(false);
  // ── ① 糸の張力で回る ──
  const bx = CIR_CX[0];
  const ball1 = _cirBall(bx, CIR_CY, '#ffa726');
  joints.push(new Joint({ type:'rope', bodyA:null, anchorAx:bx, anchorAy:CIR_CY,
                          bodyB:ball1, anchorBx:0, anchorBy:0,
                          restLength:CIR_R, maxLength:CIR_R, linDensity:0.02,
                          // ★糸は灰色にする。緑のままだと張力の矢印（同じ緑）と重なって見分けられない
                          color:'#cfd8dc' }));
  // ── ② 円筒の内壁の垂直抗力で回る ──
  const wx = CIR_CX[1];
  const rIn = CIR_R + CIR_BALL_R, rOut = rIn + CIR_WALL_T;
  const outer = _circleLoop(rOut, 64, true), hole = _circleLoop(rIn, 64, false);
  objects.push(new Body({
    type:'polygon', x:wx, y:CIR_CY, isStatic:true, mass:0,
    verts:outer, holes:[hole],
    arcs: detectArcs(outer, [hole], [{ cx:0, cy:0, r:rOut }, { cx:0, cy:0, r:rIn }]),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2, label:'円筒',
  }));
  _cirBall(wx, CIR_CY, '#42a5f5');
  // ── ③ モーターで回す棒 ──
  //   ★中心の軸（モーター）→ 棒 → 先に溶接した球、の3つ。どれも左のツールバーにある
  //     部品だけで組める（箱・軸・円・溶接）。
  //   ★棒は球とレイヤーを分ける。棒の先は球の中に半径ぶん（18px）入っているので、
  //     同じレイヤーのままだと接触が立って溶接と押し合う。溶接でつないだ2つでも接触は
  //     素通りしない。
  const mx = CIR_CX[2];
  const rod = new Body({
    type:'box', x:mx, y:CIR_CY - CIR_R/2, w:CIR_R, h:CIR_ROD_W, angle:-Math.PI/2,
    mass:CIR_ROD_M, av:CIR_W0, layers:0b0010,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#90a4ae', strokeColor:'#cfd8dc', strokeWidth:1, label:'棒',
  });
  objects.push(rod);
  // モーター。★bodyA:null ＝ 軸は世界に固定した1点（①の糸の端と同じ作り）。
  //   トルクの上限は既定の 288 N·m のまま（つまみで ω を変えると数 tick で追いつく。上の★）
  const axle = new Joint({ type:'axle', bodyA:null, anchorAx:mx, anchorAy:CIR_CY,
                           bodyB:rod, anchorBx:-CIR_R/2, anchorBy:0,
                           motorSpeed:CIR_W0 });
  joints.push(axle);
  const ball3 = _cirBall(mx, CIR_CY, '#66bb6a', false);   // ★③だけ力の矢印を出さない
  ball3.av = CIR_W0;
  joints.push(new Joint({ type:'fixjoint', bodyA:rod, bodyB:ball3,
                          anchorAx:CIR_R/2, anchorAy:0, anchorBx:0, anchorBy:0 }));
  setDemoCam(CIR_CX[1], 0.65);
  // [px per N] 向心力 m v²/r が画面上で半径の CIR_F_FRAC 倍になる倍率（倍率 0.65 で 3.76）。
  //   ★カメラを決めたあとで出す（画面上の半径は cam.zoom で決まる。冒頭の★）
  const fCen = 1 * CIR_V * CIR_V / (CIR_R * PX2M);   // [N] 球は 1kg
  world.forceVizScale = CIR_F_FRAC * CIR_R * cam.zoom / fCen;
  const ly = CIR_CY - rOut - 30;
  _cirLabel(bx, ly, '① 糸でつないだ球（張力）',       '#ffa726');
  _cirLabel(wx, ly, '② 円筒の内側を回る球（垂直抗力）', '#42a5f5');
  _cirLabel(mx, ly, '③ モーターで回す棒',             '#66bb6a');
  // ③のつまみ。★窓は③の真下に置く。左下（addRemote の既定の積み場所）だと本文と①の
  //   あいだに出て、どの装置のつまみなのか分からなくなる。
  //   ★fx/fy は窓の左上を「キャンバスではなくアプリ領域」の割で測る（placeRemotePanel）。
  //     0.735/0.845 で③の円の真下・画面のいちばん下の帯に収まる
  //   ★畳んだ形（つまみ1本だけ）で開く。開いた形は高さ約 175px あり、画面の下端に
  //     押し当てても③の円の下半分を隠した（1280×800 で窓の上端 599px、円の下端 628px）。
  //     畳んでもつまみは動かせる（remote.js の collapsed の★）。設定欄は ⌃ で開ける
  const knob = addRemote('prop', axle, 'joint');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'motorSpeed'; knob.lo = 0; knob.hi = CIR_W_MAX;
    knob.fx = 0.735; knob.fy = 0.845; knob.collapsed = true;
    // ★畳んでから置き直す。先に置くと、開いた形の高さで下端に押し戻された位置のまま残る
    placeRemotePanel(knob); syncRemotePanel(knob); placeRemotePanel(knob);
  }
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '円運動（向心力）');
  // ★本文は11行まで。12行目を足すと最終行が①②③の見出しに掛かる（実測：11行なら
  //   本文の下端と見出しのあいだが画面 38px、12行だと 19px でぶつかって見える）。
  //   ③を足すときに①②の実測値の行（14.7 N・5.00 m/s ほか）をここから外したのは
  //   そのため。数値は上の★2つに残してある（本文には関係式と読みどころだけ置く）
  demoNote (p.x, p.y + 54,
    '真上から見下ろした図（重力は画面に現れない・摩擦なし）。3台とも 1 kg の球が、\n'
  + '半径 1.7 m の円を回っている。開いた時点はどれも秒速 5 m。\n'
  + '\n'
  + '【手順1】▶実行 を押して、①②の2本の矢印（力）を見くらべる\n'
  + '・① は糸が引く力（張力）だけ、② は壁が押す力（垂直抗力）だけが働いている\n'
  + '・出どころは違うのに、どちらの矢印もいつも円の中心を向き、長さも変わらない\n'
  + '・力が働き続けているのに速さが変わらないのは、力がいつも進む向きと直角だから。\n'
  + '　この力は向きだけを変え続けている ＝ 向心力\n'
  + '\n'
  + '【手順2】③ の下のつまみで、モーターの回る速さ ω を変える（③は力の矢印を出さない）\n'
  + '・半径 r は 1.7 m のまま。速さは v = rω、1周にかかる時間は T = 2π/ω。①②と見くらべる');
}

// ── 鉛直面内の円運動（半円筒）─────────────────────────────
//   ★横から見た図（重力あり）。斜面を滑り降りた球が、半円筒（円の右半分）の内側を
//     駆け上がる。中心より上では重力が中心を向く側に回るので、壁が押す力（垂直抗力）は
//     どんどん小さくなり、0 になった瞬間に面から離れる
//     ＝ 円運動を続けるのに要る力を、壁がもう出せなくなる点。
//   ★出発の高さだけが違う2台を並べる。低いほう（球の中心の落差 1.75 m）は途中で離れ、
//     高いほう（3.0 m）は一番上まで駆け上がる。理屈どおりの境目は落差 2.5 m。
//     実測は理屈と合っている：①は最下点 5.84 m/s（理論 5.86）で最下点から 119°
//     （理論 120°）の位置で離れ、②は最下点 7.65 m/s（理論 7.67）で 180°＝天辺まで
//     面に乗ったまま届く。
//   ★摩擦は 0（球・面とも）。転がりではなく「なめらかな面を滑る」教科書の設定にする。
//     摩擦を入れると運動エネルギーが回転にも分かれ、離れる点が理屈の位置とずれる。
//   ★コースは斜面から半円筒まで1枚の静的ポリゴンで作り、曲がった区間は detectArcs で
//     真円として解かせる（js/physics/arc.js）。別々の物体に分けると継ぎ目でエネルギーが
//     落ち、離れる位置が「出発の高さ」で決まらなくなる（エネルギーのデモの★と同じ理由）。
//   ★力の矢印の倍率は 2 px/N。最下点の垂直抗力は②で 68 N まで上がるので、既定の 1 では
//     上限 260px に張り付き、上へ行くほど短くなるという読みどころが潰れる。
const HC_R      = 118;  // [px] 半円筒の内壁の半径
const HC_BALL_R = 18;   // [px] 球の半径 → 球の中心が描く円は半径 100px（1.0 m）
const HC_WALL_T = 24;   // [px] コースの厚み
const HC_SLOPE  = 55;   // [deg] 斜面の角度
const HC_FIL_R  = 80;   // [px] 斜面と床をつなぐ円弧の半径
const HC_H      = 320;  // [px] 斜面のてっぺんの高さ（②の出発点 300px が乗る高さ）
const HC_FLAT   = 80;   // [px] 円筒の手前の平らな区間
const HC_ARC_N  = 40;   // 半円を何本の辺で描くか（当たりは真円なので見た目だけ）
const HC_DROP   = [175, 300];   // [px] 球の中心の落差（①途中で離れる／②一番上まで）
// コース1枚と球1個。ox は左右の置き場所、drop は球の中心の落差[px]
function _halfCylinderCourse(ox, drop, color, label) {
  const gy = ground.y;                       // 床の高さ（＝原点。位置エネルギーの基準）
  const th = HC_SLOPE * Math.PI / 180;
  const filW = HC_FIL_R * Math.sin(th), filH = HC_FIL_R * (1 - Math.cos(th));
  const xC = ox - HC_FLAT;                   // 円弧が床に接する点
  const xB = xC - filW, xA = xB - (HC_H - filH) / Math.tan(th);
  const cy = gy - HC_R;                      // 半円筒の中心（最下点が床に接する）
  const pts = [{ x:xA, y:gy - HC_H }, { x:xB, y:gy - filH }];
  for (let i = 1; i <= 12; i++) {            // 斜面と床をつなぐ円弧
    const p = th * (1 - i / 12);
    pts.push({ x: xC - HC_FIL_R * Math.sin(p), y: gy - HC_FIL_R + HC_FIL_R * Math.cos(p) });
  }
  pts.push({ x:ox, y:gy });                                  // 平らな区間 → 円筒の最下点
  for (let i = 1; i <= HC_ARC_N; i++) {                      // 内壁（φ=0 → 180°）
    const p = Math.PI * i / HC_ARC_N;
    pts.push({ x: ox + HC_R * Math.sin(p), y: cy + HC_R * Math.cos(p) });
  }
  const RO = HC_R + HC_WALL_T;
  pts.push({ x:ox, y:cy - RO });                             // 天辺で外側へ出る
  for (let i = HC_ARC_N - 1; i >= 0; i--) {                  // 外周（180° → 0）
    const p = Math.PI * i / HC_ARC_N;
    pts.push({ x: ox + RO * Math.sin(p), y: cy + RO * Math.cos(p) });
  }
  pts.push({ x:xA, y:gy + HC_WALL_T });                      // コースの裏側 → 左端へ
  objects.push(new Body({
    type:'polygon', x:0, y:0, isStatic:true, mass:0,
    verts: pts,
    arcs: detectArcs(pts, [], [{ cx:xC, cy:gy - HC_FIL_R, r:HC_FIL_R },
                               { cx:ox, cy, r:HC_R }, { cx:ox, cy, r:RO }]),
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2, label:'コース',
  }));
  // 球を斜面の上に置く。★面から半径ぶんだけ法線方向へ離した位置が中心
  const yc = gy - HC_BALL_R - drop;
  const ys = yc + HC_BALL_R * Math.cos(th);
  const xs = xA + (ys - (gy - HC_H)) / Math.tan(th);
  const ball = new Body({
    type:'circle', x: xs + HC_BALL_R * Math.sin(th), y: yc, radius:HC_BALL_R, mass:1,
    friction:0, frictionStatic:0, restitution:0, fixedRotation:true,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5, showForces:true, label,
  });
  ball.tracerEnabled = true; ball.tracerColor = color; ball.tracerDuration = 6;
  objects.push(ball);
  return { ball, xA, cy };
}
function demoHalfCylinder() {
  resetDemoWorld();
  world.substeps = 16;          // ★曲がった面を滑る間の損失を抑える（エネルギーのデモと同じ）
  world.sleeping = false;
  world.forceVizScale = 2;      // [px per N]（上の★）
  updateGroundTerrain(false);   // 床はコースの一部として作る（継ぎ目を作らない）
  const a = _halfCylinderCourse(-350, HC_DROP[0], '#ffa726', '球①');
  const b = _halfCylinderCourse( 320, HC_DROP[1], '#42a5f5', '球②');
  setDemoCam(0, 0.65);
  demoLabel(a.xA - 20, ground.y - HC_H - 46, '① 1.75 m から', '#ffa726');
  demoLabel(b.xA - 20, ground.y - HC_H - 46, '② 3.0 m から',  '#42a5f5');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '鉛直面内の円運動（半円筒）');
  demoNote (p.x, p.y + 54,
    'なめらかな面（摩擦なし）を 1 kg の球が滑る。半円筒の内側は半径 1.0 m の円で、\n'
  + '斜面を滑り降りた球がそのまま内壁を駆け上がる。①と②の違いは出発の高さだけ。\n'
  + '\n'
  + '【手順】▶実行 を押して、青い矢印（壁が押す力）の長さを追う\n'
  + '・上へ行くほど矢印は短くなる。円の中心と同じ高さを過ぎると重力が中心を向く側に\n'
  + '　回り、そのぶん壁が押す力は要らなくなる\n'
  + '・① は矢印が 0 になった瞬間に面から離れ、そこから放物線を描いて落ちる\n'
  + '・② は矢印が 0 にならず、一番上まで駆け上がってから飛び出す\n'
  + '・違いは速さだけ。速く回るほど曲がるのに大きな力が要るので、壁は押し続けられる');
}

// ════════════════════════════════════════
//  力学 ▸ 慣性力（見かけの力）
// ════════════════════════════════════════
//  ★この節の3本は「非慣性系から見ると現れる力」の話でひと続きになっている。
//    エレベータは慣性系のまま垂直抗力が変わるところまで（＝見かけの重さの正体）、
//    電車の振り子とコリオリは、そこへ視点の乗り換えを重ねたもの。
//    ★どれも見かけの力をエンジンに足していない（プロジェクトの約束）。慣性系で解いた
//      うえで、カメラを動く物体に接続して「見る側」を変えるだけにしてある。

// ── エレベーターの中の体重計（垂直抗力は重さと同じではない）───────────────
//   ★このデモの主張は「体重計が指すのは重力ではなく垂直抗力 N」。加速していると
//     N ≠ mg になり、その差がそのまま体重計の読みの違いになる。
//       上向きに加速中： N − mg = ma → N = m(g+a)
//       等速：           N = mg
//       上昇しながら減速（a が下向き）： N = m(g−|a|)
//   ★慣性力は出さない（この系は必ず慣性系で解く。ファイル冒頭とプロジェクトの約束）。
//     エレベータの中の人が「つり合っている」と言うために持ち出すのが慣性力で、
//     外から見れば、人は箱と一緒に加速しているだけ。矢印も重力と垂直抗力の2本しか出ない。
//   ★加速度は ±g/2 = ±4.9 m/s²。実物のエレベータは 1 m/s² ほどで N の差が 10% しかなく、
//     矢印の長さで読めない。g/2 なら 75 kg / 50 kg / 25 kg と1.5倍・0.5倍になり、
//     「体重計の読み」として覚えやすい値になる（本文に実物の値も書いてある）。
//   ★1台をリモコンで動かす。前は3台を並べて a>0 / a=0 / a<0 を同時に見せていたが、
//     「同じかごが押し方で 75kg・50kg・25kg を指す」ほうが、体重計の読みが動き方で
//     決まることの見え方として強い。3台だと「別のかご＝別のもの」と読めてしまう。
//   ★動力は2つに分ける。かごの重さとつり合う〈支える動力〉（天井・常に働く）と、
//     〈加速用の動力〉（床・リモコン2つで ±）。押していない間は前者だけが残って a = 0 に
//     なるので、「何も押さない＝等速」が最初の姿として成り立つ。1つの動力で ±g/2 の
//     3状態を作ろうとすると、押していない間の大きさ（Mg）と押している間の大きさ
//     （1.5Mg / 0.5Mg）を1つの数で表せない。
//   ★向きの逆転はリモコンをもう1つ置いて〈逆向きに効かせる〉にする（remote.js の★。
//     1つの窓に2つのボタンを置かない）。同じ床に2つ付いていて、押されているほうが勝つ。
//   ★カメラをかごに接続する（電車の振り子と同じ作り）。画面が「かごの中の人の目」に
//     なるので、人は動かず地面と方眼だけが流れる＝「中の人には自分は静止して見える」が
//     そのまま絵になる。説明文は画面に貼る札にする（ワールドに置くと一緒に流れて消える）。
const ELV_W = 300, ELV_H = 340, ELV_T = 18;    // [px] かごの外寸と梁の厚み
const ELV_CY = 340;         // [px] かごの中心の高さ（地面から）。★「地面（シャフトの底）が
                            //   画面に入る」がこの値の上限（既定の倍率 0.55 で、かごの中心の
                            //   190画面px 下＝345px まで）。下がるほど ↓ を先に押したときの
                            //   余裕が減るので、入るぎりぎりを取る（3.4m ＝ 押しっぱなしで 1.2 秒）
const ELV_PERSON = 50;      // [kg] 人。体重計は 50 kg を指すはず（静止時）
const ELV_A = G_EARTH / 2;  // [m/s²] 加速度の大きさ（±g/2）
function demoElevatorScale() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;      // ★眠ると垂直抗力の矢印が消える
  world.forceVizScale = 0.16;  // [画面px per N] 重力 490 N が 78px、垂直抗力 735 N が 118px
  updateGroundTerrain(true);
  // ★倍率 0.50（既定の 0.55 より引く）。カメラをかごに接続すると画面の中身がかごで決まり、
  //   かごの天井から地面（シャフトの底）まで 5.0m ある。0.55 では地面が下の目盛り帯に
  //   隠れた。かごを下げて詰める手もあるが、それだと ↓ を先に押したときすぐ着地する
  //   （3.4m ＝ 1.2 秒ぶんの余裕を残したい）。引いて両方を入れる。
  setDemoCam(0, 0.50);
  const beam = (x, y, w, h, mass, label) => {
    const b = new Body({
        fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
      type:'box', x, y, w, h, mass,
      friction:0.5, frictionStatic:0.6, restitution:0,
      fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5, label });
    objects.push(b);
    return b;
  };
  const cx = 0, cy = gy - ELV_CY;                        // かごの中心
  const off = ELV_W/2 - ELV_T/2, offY = ELV_H/2 - ELV_T/2;
  const floor   = beam(cx, cy + offY, ELV_W, ELV_T, 2,   'かごの床');
  const ceiling = beam(cx, cy - offY, ELV_W, ELV_T, 2,   'かごの天井');
  // ★壁は床・天井と同じ高さまで伸ばして角で重ね、レイヤーを分ける（電車のデモの★と同じ）
  const wallL   = beam(cx - off, cy, ELV_T, ELV_H, 1.5, '壁');
  const wallR   = beam(cx + off, cy, ELV_T, ELV_H, 1.5, '壁');
  wallL.layers = wallR.layers = 0b0010;
  // ★溶接のアンカーは「2本が重なる角」に置く（電車のデモの★。中心どうしだと枠が潰れる）
  for (const [a, ax, ay, b, bx, by] of [
        [floor,   -off, 0, wallL, 0,  offY],
        [wallL,   0, -offY, ceiling, -off, 0],
        [ceiling, off, 0, wallR, 0, -offY],
        [wallR,   0,  offY, floor, off, 0]]) {
    //   ★打つのは手のツールと同じ入口（demoPin）。角は2本が重なっている点
    const w = getWorldAnchor(a, ax, ay);
    demoPin('fixjoint', w.x, w.y, 'pair', { expect:[a, b] });
  }
  // 体重計の皿と、その上に立つ人。★皿は「目盛りの付いた台」の代わりで、物理としては
  //   ただの板。人にかかる垂直抗力（青い矢印）がそのまま体重計の読みになる
  const floorTop = cy + offY - ELV_T/2;
  const plate = beam(cx, floorTop - 8, 150, 16, 1, '体重計');
  plate.fillColor = '#eceff1'; plate.strokeColor = '#b0bec5';
  const person = new Body({
    type:'box', x:cx, y:floorTop - 16 - 55, w:60, h:110, mass:ELV_PERSON,
    friction:0.5, frictionStatic:0.6, restitution:0,
    showForces:true, label:'人 50kg',
    fillColor:'#ffa726', strokeColor:'#ffe0b2', strokeWidth:2 });
  objects.push(person);
  // 動力はかご全体（枠＋皿＋人）の質量から決める。上向きが正なので、内部の y は逆向き
  const total = objects.reduce((s, o) => s + o.mass, 0);
  // [N] 支える動力（重さとつり合う。常に働く）
  ceiling.thrusters.push(new Thruster({ force: total * G_EARTH, dir: -Math.PI/2 }, ceiling));
  // [N] 加速用（リモコンで ± に切り替える）
  const lift = new Thruster({ force: total * ELV_A, dir: -Math.PI/2 }, floor);
  floor.thrusters.push(lift);
  // ── 上げ下げのリモコン2つ（同じ動力を、正転と逆転で）─────────────
  //   ★窓は横に並べる。縦に積むと2つ目が本文（17行）に掛かる。
  for (const [key, mode, fx] of [['ArrowUp', 'on', 0.035], ['ArrowDown', 'rev', 0.215]]) {
    const r = addRemote('thruster', lift, 'thruster');
    if (!r) continue;
    r.key = key; r.mode = mode; r.fx = fx; r.fy = 0.60;
    placeRemotePanel(r); syncRemotePanel(r);
  }
  // ── ケーブルを切る（X）：支える動力を〈押している間だけ止める〉──────────────
  //   ★新しい力は足さない。支える動力を止めるだけで、かご・体重計・人はそろって自由落下し、
  //     体重計を押す力（垂直抗力）が 0 になる＝無重量状態。〈止める〉は remote.js の 'off'
  //     （押している間だけ止める）で、放せば支えが戻り、その時の速さのまま等速で動く。
  //   ★実測：押した次の tick から落ちている間ずっと N = 0.00 N（押す前 490.3 N）。
  //   ★そのまま押すと、かごの底から地面まで 1.7 m しかなく 0.59 秒で着地する。
  //     ↑ で 1 秒上げてから押すと、投げ上げと同じく上がってから落ちるので約 1.5 秒続く
  //     （本文の【もう一手】）。ELV_CY を上げて落差を稼がないのは、その上限の★のため。
  const cut = addRemote('thruster', ceiling.thrusters[0], 'thruster');
  if (cut) {
    // ★窓はかごの右・グラフの窓の下に、畳んだ形で置く。↑ ↓ の隣（fx 0.395）に並べると
    //   かごの左半分を隠し、開いた形のままだと右上のグラフの窓に掛かる
    cut.key = 'KeyX'; cut.mode = 'off'; cut.collapsed = true; cut.fx = 0.645; cut.fy = 0.70;
    placeRemotePanel(cut); syncRemotePanel(cut); placeRemotePanel(cut);
  }
  demoWarmForces(30);          // ★止めたまま垂直抗力の矢印を出す（demo-kit の★）。
                               //   押していない間はつり合っているので、回しても動かない
  // ★グラフは人に付ける。押し方で加速度Yが +4.9 / 0 / −4.9 と切り替わるのが数で読め、
  //   青い矢印の伸び縮みと並べて見られる。成分は Y だけ（運動は上下だけ）。
  moveDemoGraphTop(velGraphNew(person, { showPos:true, showVel:true, showAcc:true,
                                         showX:false, showY:true, showMag:false }));
  // ★カメラはかごに接続する（★。接続先は天井——追従は接続先の中心へ視点を寄せるので、
  //   床に付けると視点が下がって画面の上半分が空だけになる。電車の振り子と同じ）
  attachCamera(ceiling, 'world');
  // ★視点を少し下げて、本文の下に かご が来る場所を空ける。ここは かご が回らない
  //   （cam.angle が 0 のまま）ので、ワールドのずらしがそのまま画面のずらしになる。
  //   ★下げすぎない：地面（シャフトの底）が下の目盛り帯に隠れる。−40 で 25px 覗く
  sceneCamera.offY = -40;
  demoTitlePinned('エレベーターの中の体重計');
  // ★本文は15行まで。これより長いと最後の行が かご の天井（画面 381px）に掛かる
  demoNotePinned(
    '50 kg の人が体重計に乗ってかごの中に立っている。矢印の色： 重力＝赤　垂直抗力＝青\n'
  + 'カメラをかごに付けてあるので、いまの画面は「かごの中の人の目」（動くと地面が流れる）\n'
  + '\n'
  + '【手順】▶実行 を押し、リモコン（左下の ↑ / ↓、右下の X キー）でかごを動かす\n'
  + '・何も押さない： a = 0 → N = mg = 490 N ＝ 50.0 kg（支える動力が重さとつり合う）\n'
  + '・↑ を押す： a = +4.90 m/s²（上向き）→ N = m(g+a) = 735 N ＝ 体重計は 75.0 kg\n'
  + '・↓ を押す： a = −4.90 m/s²（下向き）→ N = m(g−|a|) = 245 N ＝ 体重計は 25.0 kg\n'
  + '・X を押す（ケーブルが切れる）： a = −g → N = 0 ＝ 体重計は 0 kg（無重量状態）\n'
  + '・赤（重力 mg）はどれも同じ長さ。伸び縮みするのは青（垂直抗力 N）だけで、体重計が\n'
  + '　　指すのはこちら： N = m(g + a)。慣性力は1本も描いていない（人に働く力はこの2本だけ）\n'
  + '・グラフ：人の加速度Yが押し方で切り替わる。速度Yは押している間だけ傾く\n'
  + '\n'
  + '【もう一手】↑ で上昇させてから ↓ に持ち替えると「上昇しながら減速」。a が同じなら\n'
  + '　　体重計も 25.0 kg のまま。X は ↑ で 1 秒上げてから押すと約 1.5 秒浮ける\n'
  + '※実物のエレベータは 1 m/s² ほど（振れは 10%）。ここでは矢印で読めるよう g/2 にした');
}

// ── 加速する電車内の振り子（慣性力）───────────────────────────
//   ★慣性力そのものは矢印に出せない、というより出してはいけない。この系は慣性系（画面に
//     固定した座標）で解いていて、球に本当に働いているのは重力と棒の張力の2本だけ。
//     その合力は 0 ではなく ma で、実際に球はそのぶん加速している。ここへ「慣性力 −ma」を
//     足すと合力 0 の絵になり、球が加速している事実と正面から食い違う。
//     ＝ 慣性力は「電車と一緒に動く人が見たときにだけ現れる見かけの力」で、
//        画面（慣性系）の中には存在しない。説明の本文でその線引きを書く。
//   ★止まっている電車・鉛直に垂れた振り子から始め、リモコン（X）を押している間だけ
//     加速する。〈押すと効く〉はリモコンの既定の形で、他のデモと同じ読み方で通じる。
//     ★代償：加速を「途中から」与えるので、振り子は 30° で静止せずに振れる。減衰が
//       無いので永遠に続く（実測：X を押し続けて 0.03°〜59.48° を往復、中点 29.75°、
//       周期 2.361 s。球の加速度Xは σ3.25 で振れ、4周期の平均は 5.660 m/s²
//       ＝理論値 5.662）。**振れの中心が つり合いの角度**
//       という読み方に変えて本文に書いた。0° と 60° の折り返しが読めるので、
//       その真ん中として 30° を取れる（振れ幅がつり合いの角度の2倍になるのは、
//       つり合いの向きを「見かけの重力」と見れば、そこから 30° ずらして手を放すのと
//       同じだから）。空気抵抗で落ち着かせる手も考えたが、この engine の抗力は
//       ワールド速度に掛かる＝走るほど強くなるので、角度が時間とともにずれる。採らない。
//   ★加速度は 30° になる値（g·tan30° = 5.66 m/s²）にした。実物の電車は 1 m/s² 程度で、
//     それだと 5.8°＝画面では読めない。この誇張は説明の本文に明記する。
//   ★車体は「床・天井・左右の壁」の4本の梁を溶接した枠。中が見えるので振り子が
//     電車の中にあることが一目で分かる（1枚の箱にすると球が中に入れられない）。
//   ★ガイド（レール）は使わない。溶接だけで組んでも十分に硬い（実測：3秒回して天井の
//     沈みは 0.55px、棒の傾きは 30.01°±0.10°、球の加速度は 5.664 m/s² ＝理論値 5.662 と一致）。
//     4本ともガイドに載せると精度は上がる（傾き 30.00°±0.004°）が、ガイドは1本ごとに
//     画面を横切る破線と両向き矢印を描くので、4本ぶんの線が題材の上に重なる。
//     0.1° のために絵を壊す取引になるので、床を地面に載せるだけにした。
//   ★動力は床に付ける。力の大きさは車体＋球の総質量から出す（質量を1つ変えても
//     加速度が 5.66 m/s² のまま保たれる＝角度が 30° からずれない）。
//   ★鉛直の目印は引かない。前後の壁がそのまま鉛直の基準になり、しかも電車と一緒に動く。
//     お絵描きの線を出発点に置いてみたが、注釈は電車について行かないので、走り出すと
//     振り子から離れていくばかりで角度の読みに使えなかった。
const TRN_W = 460, TRN_H = 340, TRN_T = 16;   // [px] 車体の外寸と梁の太さ
const TRN_ROD = 170, TRN_BALL_R = 22;         // [px] 棒の長さと球の半径
const TRN_DEG = 30;                           // [°]  つり合いの傾き（＝加速度を決める）
const TRN_X0  = -500;                         // [px] 出発点
function demoTrainPendulum() {
  resetDemoWorld();
  updateGroundTerrain(true);    // ★レールは世界の地面（床を地面に載せて走らせる＝下の★）。
                                //   明示しないと、地面を消したデモの直後に開いたとき電車ごと
                                //   落ち続ける（実測：地面なしで開くと 3 秒で 44m 落下した）
  world.sleeping = false;
  world.forceVizScale = 12;     // [px per N] 重力 9.8N が 118px
  const th = TRN_DEG * Math.PI / 180;
  const accel = G_EARTH * Math.tan(th);        // [m/s²] tanθ = a/g
  const cx = TRN_X0, cy = ground.y - TRN_H / 2;
  const beam = (x, y, w, h, mass, label) => {
    const b = new Body({
        fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
      type:'box', x, y, w, h, mass,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5, label,
    });
    objects.push(b);
    return b;
  };
  const off = TRN_W / 2 - TRN_T / 2, offY = TRN_H / 2 - TRN_T / 2;
  const floor   = beam(cx, cy + offY, TRN_W, TRN_T, 2,   '床');
  const ceiling = beam(cx, cy - offY, TRN_W, TRN_T, 2,   '天井');
  // ★壁は床・天井と同じ高さまで伸ばし、四隅で床・天井と重ねる。溶接は画鋲と同じで、
  //   重なった2つを1点で留めるもの（手の溶接ツールもクリック点に重なる2つをつなぐ）。
  //   以前は壁を床と天井のあいだに収めて端で接していただけで、角の溶接点は壁の外（8px）
  //   にあり、手では組めなかった（2026-10-02 に直した）。
  //   ★重ねたぶん、壁はレイヤー2に分ける。同じレイヤーだと溶接した相手とも押し合う。
  //     壁に当たるものは無い（球は 60° 振れても壁まで 45px 残る）ので、分けても動きは同じ。
  const wallL   = beam(cx - off, cy, TRN_T, TRN_H, 1.5, '後ろの壁');
  const wallR   = beam(cx + off, cy, TRN_T, TRN_H, 1.5, '前の壁');
  wallL.layers = wallR.layers = 0b0010;
  // ★溶接のアンカーは「2本が重なる角」に置く。両方 (0,0)（＝互いの中心）にすると、
  //   溶接は中心どうしを重ねようとして枠が1点へ潰れる（実際にそうなった）。
  for (const [a, ax, ay, b, bx, by] of [
        [floor,   -off, 0, wallL, 0,  offY],   // 左下の角
        [wallL,   0, -offY, ceiling, -off, 0], // 左上の角
        [ceiling, off, 0, wallR, 0, -offY],    // 右上の角
        [wallR,   0,  offY, floor, off, 0]]) { // 右下の角（枠を閉じる）
    //   ★打つのは手のツールと同じ入口（demoPin）。角は2本が重なっている点
    const w = getWorldAnchor(a, ax, ay);
    demoPin('fixjoint', w.x, w.y, 'pair', { expect:[a, b] });
  }
  // 天井の下面のまん中が吊り点。球は鉛直に垂らして止めておく（★。加速はリモコンで与える）
  const pivY = cy - offY + TRN_T / 2;
  const ball = new Body({
      fixedRotation:true,   // ★質点として扱う。何にも触れていないので、冒頭の★の例外にあたらない
    type:'circle', x:cx, y:pivY + TRN_ROD,
    radius:TRN_BALL_R, mass:1,
    friction:0, frictionStatic:0, restitution:0,
    showForces:true,                            // ★読ませたいのはこの2本だけ
    fillColor:'#ffd54f', strokeColor:'#fff8e1', strokeWidth:1.5, label:'おもり',
  });
  objects.push(ball);
  joints.push(new Joint({ type:'rod', bodyA:ceiling, anchorAx:0, anchorAy:TRN_T / 2,
                          bodyB:ball, anchorBx:0, anchorBy:0,
                          // ★棒は車体をすり抜けさせる（layers:0）。天井の下面が吊り点なので、
                          //   衝突を残すと棒の付け根が天井と当たり判定を持ってしまう。
                          restLength:TRN_ROD, maxLength:TRN_ROD, layers:0 }));
  // 動力は総質量から決める（★）。ここまでに置いた物体がすべて一緒に加速する
  const total = objects.reduce((s, o) => s + o.mass, 0);
  const drive = new Thruster({ force: total * accel, dir: 0 }, floor);   // [N] 右向き
  floor.thrusters.push(drive);
  // ── 加速のリモコン ────────────────────────────────────
  //   ★〈押している間だけ効かせる〉。押していない間は等速（最初は静止）で、押すと
  //     加速が始まり、放せばまた等速に戻る＝慣性力が現れたり消えたりを何度でも往復できる。
  //   ★前は「床を選んで右パネルの動力を消す」と書いていた。編集ツール＝編集の道具を
  //     手順に要求していたうえ、一度消すと戻せない（戻るを押すしかない）。
  const rem = addRemote('thruster', drive, 'thruster');
  if (rem) {
    rem.key = 'KeyX'; rem.mode = 'on';
    rem.fx = 0.035; rem.fy = 0.645;   // ★説明文（14行）の下。かぶると【もう一手】の行が読めない
    placeRemotePanel(rem); syncRemotePanel(rem);
  }
  // ★止めたまま張力の矢印も出す（demo-kit の★）。開いた姿はつり合っているので、回しても
  //   動かない。★リモコンを置いたあとに回すこと。先に回すと動力（45N）が効いた状態の
  //   矢印が残り、鉛直に垂れた絵に「斜めの張力」が付いて食い違う。
  demoWarmForces(30);
  setDemoCam(0, 0.65);
  // ★グラフはおもりに付ける。「電車の中では止まって見えるのに、実際は加速している」を
  //   数で見せる一手で、慣性力が見かけの力でしかないことの裏づけになる。
  //   成分は X だけ（運動は水平方向だけ。Y を出しても 0 の線が並ぶ）。
  moveDemoGraphTop(velGraphNew(ball, { showPos:true, showVel:true, showAcc:true,
                                       showX:true, showY:false, showMag:false }));
  // ★カメラを電車に接続する。これで画面は「電車の中の人の目」になり、おもりは
  //   傾いたまま画面に貼り付いて、地面と方眼だけが後ろへ流れる＝慣性力の話がそのまま絵になる。
  //   ★向きは 'world'（常に y 軸正）。電車は回らないので 'body' でも結果は同じだが、
  //     この題材で回転を持ち出す理由がない。
  //   ★接続先は天井。追従は接続した物体の中心へ視点を寄せるので、床に付けると
  //     視点が地面すれすれまで下がって、上半分が空だけになる（天井なら元の構図に近い）。
  attachCamera(ceiling, 'world');
  // ★視点を少し下げて、説明文の場所を空ける。追従は接続先の中心へ視点を寄せるので、
  //   そのままだと車体の上端が画面 363px に来て、本文の最後の3行が車体に掛かった。
  //   ここは電車が回らない（cam.angle が 0 のまま）ので、ワールドのずらしがそのまま
  //   画面のずらしになる。回るカメラでこれをやると、ずれが画面上で振り回されるので注意。
  sceneCamera.offY = -110;
  // ★説明文は「画面に貼る」札にする。ワールドに置くと地面と一緒に後ろへ流れ、
  //   走り出して 2 秒で読めなくなる（実測：本文の左端が 2 秒で画面の外）。
  demoTitlePinned('加速する電車内の振り子（慣性力）');
  demoNotePinned(
    '水平なレールに止まっている電車（床・天井・前後の壁を溶接した枠。摩擦なし）。天井から\n'
  + '1.7 m の棒で 1 kg のおもりを吊ってある。カメラを電車に付けてあるので、いまの画面は\n'
  + '「電車の中の人の目」（走り出すと地面が後ろへ流れる）\n'
  + '\n'
  + '【手順】▶実行 を押し、左下のリモコン（X キー）を押している間だけ電車が加速する\n'
  + '・押さないあいだは鉛直に垂れたまま（静止／等速＝地面の上と同じ）。押すと後ろへ傾く\n'
  + '・押し続けると 0° と 60° のあいだを往復する。その真ん中の 30° がつり合いの角度で、\n'
  + '　　tan30° = 5.66 ÷ 9.8。加速度と重力加速度の比が、そのまま傾きを決める\n'
  + '　　（前後の壁が鉛直の目印。壁は電車と一緒に動くので、走っている間も比べられる）\n'
  + '・矢印は重力（下・9.8 N）と棒の張力（斜め上）の2本だけ。合力は 0 ではなく、\n'
  + '　　おもりを加速させている力そのもの（ma）\n'
  + '・電車の中の人には、おもりは 30° のまわりを振れて見える。その人が「つり合っている」と\n'
  + '　　言うために持ち出すのが慣性力 −ma（後ろ向き）。慣性系で見ればそんな力は無い\n'
  + '・グラフ：押しているあいだ、おもりの速度Xは右上がり。加速度Xは 5.66 のまわりを振れる\n'
  + '・実物の電車の加速は 1 m/s² ほどで、傾きは 5.8°。ここでは読めるように強くしてある\n'
  + '\n'
  // ★ここは3行のまま。4行にすると最後の行が電車の天井まで下りてきて重なった
  + '【なぜ止まらない】現実の振り子は空気抵抗で 30° に落ち着くが、ここには減衰が無いので\n'
  + '　　振れ続ける。振れ幅がつり合いの角度のちょうど2倍（0°〜60°）になるのは、加速を\n'
  + '　　「つり合いの向きから 30° ずらして手を放した」のと同じ状態から始めているため');
}

// ── 回転する円板の上の運動（コリオリの力）──────────────────────────
//   ★このデモの主張は「曲げているのは力ではなく視点」。だからエンジンには見かけの力を
//     1つも足していない。球に働く力はゼロ（摩擦なし・重力なし）で、慣性系では正真正銘の
//     等速直線運動。曲がって見えるのは、カメラを円板に固定して見ているからだけ。
//     ★見かけの力をエンジンへ入れる作りにすると、この一点が崩れてコリオリの力が
//       “本物の力” に見える。入れないことがこのデモの中身そのものなので、動かさないこと。
//   ★カメラを外すと同じ運動が直線に戻る。それを本文で案内して、1つのデモで両方の系を
//     見せる（目録を2行に割らない）。★軌跡は貯めた点をそのまま両方の系へ描き分けるので、
//     走らせている途中で外しても、いま引かれている曲線がその場で直線に化ける
//     （実行し直す必要はない。js/app/camera.js の姿勢の記録の★）。
//   ★数値は「縁に着くころ、円板がちょうど 90° 回っている」で決めた：
//     半径 2.6 m・球 1.0 m/s → 2.62 秒で縁。ω=0.6 rad/s なら 0.6×2.62=1.57 rad=90°。
//     実測でも 90°。画面が1周するのに 10.5 秒で、目で追える速さ（ω を 0.8 まで上げると
//     7.9 秒になり、画面が回りすぎて軌跡を読む前に酔う）。
//   ★円板は「球が上を滑っている床」で、ぶつける相手ではない。だから
//     衝突レイヤーを球と分ける（円板はレイヤー2、球は既定のレイヤー1）。
//     ★layers:0（ゴースト）にはしない。0 の物体は黄色い破線で縁取りされる仕様で
//       （js/render/body.js:115。「なぜ当たらないのか」を画面から読めるようにするため）、
//       円板が破線で縁取られて軌跡より先に目へ入る。レイヤーを分ければ
//       印は小さな色ドット1つで済み、当たらない理由も同じように読める。
//   ★円板の大きさは「説明の本文が円板に掛からない」で決まった。カメラを付けると追従が
//     視点を円板の中心へ寄せる＝円板は必ず画面のまん中に出るので、左うえの本文が長いほど
//     食い込む（半径 2.6 m・倍率 0.75 のときは本文の下半分が円板の下に潜って読めなかった）。
//     半径 1.96 m・倍率 0.62 で、円板の上端は画面 246px、本文の最終行は 223px。
//   ★縁に届くまでの時間は ω だけで決まる（t = R/v で、90° の条件 ωR/v = π/2 を入れると
//     t = π/2ω = 2.62 秒）。だから円板を小さくしても「2.6 秒で 90°」は変わらない。
//     大きさを変えるときは v = ω·R/(π/2) を守ること。
const COR_R = 196;          // [px] 円板の半径（1.96 m）
const COR_OMEGA = -0.6;     // [rad/s] 円板の角速度。★負＝画面では反時計回り。
                            //   こうすると球は「進む向きに対して右」へそれる。球は画面の上へ転がり出す
                            //   （下の★）ので、到達点は円板の右端。いちばん上がっても中心から 0.36R で、
                            //   左うえの説明文には届かない。＋0.6 だと左へそれる（到達点は左端）。
const COR_V = 0.75;         // [m/s] 球の速さ ＝ |ω|·R/(π/2)。縁に着くとき円板はちょうど 90°
function demoCoriolis() {
  resetDemoWorld();
  setDemoGravity(0);            // ★真上から見下ろした図（重力は画面に現れない）
  world.sleeping = false;
  updateGroundTerrain(false);
  const disc = new Body({
    type:'circle', x:0, y:0, radius:COR_R, mass:60, layers:0b0010, angle:-Math.PI/2,   // ★球（既定のレイヤー1）と分ける＝当たらない
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#37474f', strokeColor:'#78909c', strokeWidth:2, label:'円板',
  });
  objects.push(disc);
  joints.push(new Joint({ type:'axle', bodyA:null, anchorAx:0, anchorAy:0,
                          bodyB:disc, anchorBx:0, anchorBy:0,
                          motorSpeed:COR_OMEGA, motorTorque:1e6 }));
  // ★目印の線は、円に描かれる向きの線（render/body.js の「向きを示す基準線」）をそのまま使う。
  //   線は物体の局所 +x に引かれ、円板と一緒に回る。
  //   ★円板は角度 −90° で置き、線を画面の上へ向ける。カメラ（'body'）の青い矢印は
  //     「画面の上に保っている向き」を指すので、付けた瞬間の上＝線の向きになり、矢印と線が重なる
  //     （2026-10-02、ユーザーの指示）。球もこの向き（画面の上）へ転がす。★以前は中心から縁へのスポーク（箱）を円板に溶接して目印にして
  //   いたが、円に線が入るようになったので外した（溶接の印も出なくなり、軌跡が先に目に入る）。
  //   ★円板の角度と球の初速の向きは必ず揃えること。ずらすと線が球の進む向きからずれる。
  // 目印の線に沿ってまっすぐ転がす球。働く力は無い＝慣性系では等速直線運動
  const ball = new Body({
    type:'circle', x:0, y:0, radius:16, mass:1,
    vx: 0, vy: -toPx(COR_V),     // ★画面の上＝円板の線の向き（上の★）
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#ffd54f', strokeColor:'#fff8e1', strokeWidth:1.5, label:'球',
  });
  ball.tracerEnabled  = true;
  ball.tracerColor    = '#ffd54f';
  ball.tracerDuration = 60;
  objects.push(ball);
  const zoom = 0.62;
  setDemoCam(0, zoom);
  // ★カメラを円板に付けると、追従が毎フレーム視点を円板の中心へ寄せる。本文の置き場所も
  //   同じ基準にしないと、開いた直後に文字だけ画面の外へ滑っていく。
  cam.y = 0;
  attachCamera(disc, 'body');   // 円板と一緒に画面ごと回す＝円板に乗った人の視点
  const p = demoTextTopLeft();
  const s = demoTextScale(zoom);
  demoTitle(p.x, p.y, '回転する円板とコリオリの力', DEMO_TITLE_SIZE * s);
  // ★本文は10行まで（上の★）。最終行の下端が画面 242px、円板の上端が 246px でぎりぎり。
  //   11行目を足すと文字が円板の下に潜って読めなくなる。
  demoNote (p.x, p.y + 54 * s,
    '真上から見下ろした図（重力も摩擦も無し）。円板が 0.6 rad/s で回っている。\n'
  + 'カメラを円板に固定してあるので、いまの画面は「円板に乗った人の目」。\n'
  + '\n'
  + '【手順】▶実行 を押して、目印の線に沿ってまっすぐ転がした球の軌跡を見る\n'
  + '・球は線から外れていく（進む向きに対して右へ）。線は円板に描いた印\n'
  + '・縁に届くのは 2.6 秒後。そのとき円板は 90°＝4分の1周ぶん回っている\n'
  + '・円板の上の人は、この曲がりを「コリオリの力」と呼んで説明する\n'
  + '\n'
  + '【もう一手】上の カメラ で「カメラを外す」を押すと、いま引かれている\n'
  + '軌跡がその場でまっすぐな線に変わる。球に働く力は 0 のまま＝曲げていたのは視点',
    DEMO_NOTE_SIZE * s);
}

// ════════════════════════════════════════
//  力学 ▸ 単振動
// ════════════════════════════════════════
// ── 単振動と円運動の射影 ─────────────────────────────────
//   ★「等速円運動を真横から見ると単振動」を、レーザーで結んで見せる。単振動する物体に
//     レーザーを載せ、円運動のほうへ真横に撃つ。光の線はいつも円運動の球に当たり続ける
//     ＝ 2つの物体の高さ（y）がいつも等しい、が目で見える形になる。
//   ★単振動は鉛直ばね振り子。天井から吊ったばねに 1kg を下げ、つりあいの位置から
//     振幅ぶん持ち上げて静かに放す。重力はつりあいの位置を mg/k だけ下へずらすだけで、
//     そのまわりの動きは水平ばね振り子とまったく同じ ω=√(k/m) の単振動になる。
//     ★ばねが押す側へ回らないことを確かめてある：つりあいの伸び mg/k = 155px に対して
//       振幅は 130px。いちばん上がった瞬間でも 25px 伸びたまま。実物の吊りばねは押せない
//       ので、ここが逆転すると画面の中だけで起きる別の運動になってしまう。
//   ★円運動は「棒＋モーター」で作る。棒を軸（axle）で中心に留め、モーターに一定の
//     角速度 ω を与える。
//     ★拘束だけで回すのは選ばなかった：棒（rod）も糸（rope）も位置補正がわずかに速さを
//       削る。実測（重力0・20秒・初速 3.27 m/s）＝ 刻み16 で 3.07（−6%）、32 で 3.16、
//       64 で 3.21、128 まで上げても 3.24。位相がずれるとレーザーが球から外れる。
//       モーターなら刻み16 のままで 3.26〜3.27 に収まる（実測）。この作りでの実測：
//       20秒まわして円の半径 130.0px のまま、おもりと球の高さのずれは最大 2.5px
//       （球の半径 20px）＝ レーザーは外れない。ばねの伸びも最小 25px で押す側へ回らない。
//     ★棒はレイヤー0（ゴースト）にする。物にぶつからないだけでなくレーザーも透過する
//       ので（js/optics/laser.js:177）、光は棒に遮られず必ず球に当たる。
//   ★2つの周期を合わせるのは k と ω の選び方だけ：ばねは k = mω²、モーターは ω そのもの。
//     数値は合わせ込みではなく、この関係から決まっている。
const PRJ_T      = 2.5;   // [s]  周期（2つとも共通）
const PRJ_A      = 130;   // [px] 円の半径＝単振動の振幅（1.3 m）
const PRJ_MASS   = 1;     // [kg] おもりと球
const PRJ_BALL_R = 20;    // [px] おもり・球の半径
// ★左右と高さは、左うえの説明文と右うえのグラフの窓を避けて決めてある：
//   本文の下端は天井の 28px 上、円のいちばん右は窓の左端より内側に収まる。
const PRJ_SHM_X  = -450;  // [px] ばね振り子の位置
const PRJ_CIR_X  = 60;    // [px] 円の中心の左右の位置
const PRJ_CEIL_Y = -460;  // [px] 天井（地面からの高さ）
const PRJ_NAT_L  = 120;   // [px] ばねの自然長
const PRJ_ARM_T  = 10;    // [px] 棒の太さ
function demoShmProjection() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 16;
  updateGroundTerrain(true);   // 横から見た図（重力は既定のまま働く）
  const w = 2 * Math.PI / PRJ_T;              // [rad/s] 角振動数
  const k = PRJ_MASS * w * w;                 // [N/m]  ばね定数（ω=√(k/m) から決まる）
  const ext  = toPx(PRJ_MASS * G_EARTH / k);  // [px]   つりあいの伸び mg/k
  const ceil = gy + PRJ_CEIL_Y;
  const eqY  = ceil + PRJ_NAT_L + ext;        // つりあいの位置＝円の中心の高さ
  const slip = { friction:0, frictionStatic:0, restitution:0 };
  const anchor = o => new Body(Object.assign({ isStatic:true, mass:0,
    fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5 }, slip, o));
  // ★天井は置かない。ばねの上端は背景に留めるだけ（bodyA:null）。天井の帯は幅が広く、
  //   左うえの説明文と同じ高さの帯を横切るので、文字を避ける置き場がなくなる。
  //   吊るし元が要るのは見た目の話で、背景に留めた端には支点の印が描かれる。
  // ── ① 鉛直ばね振り子（単振動）──
  //   つりあいの位置から振幅ぶん上げた点で静かに放す（初速0）
  const bob = new Body(Object.assign({
    type:'circle', x:PRJ_SHM_X, y:eqY - PRJ_A, radius:PRJ_BALL_R, mass:PRJ_MASS,
    fixedRotation:true, fillColor:'#ffa726', strokeColor:'#ffffff', strokeWidth:1.5,
    label:'おもり 1kg' }, slip));
  objects.push(bob);
  demoSpring({ anchorAx:PRJ_SHM_X, anchorAy:ceil, bodyB:bob,
               restLength:PRJ_NAT_L, stiffness:k, damping:0 });
  // ── ② 棒＋モーターで回す等速円運動 ──
  //   棒は中心から球までの1本。中心を軸で留め、球は棒の先へピン（hinge）で付ける。
  //   ★球はピン留めなので自転しない（fixedRotation）。棒だけはモーターで回すので回転する。
  objects.push(anchor({ type:'circle', x:PRJ_CIR_X, y:eqY, radius:14, label:'軸（固定）' }));
  const arm = new Body(Object.assign({
    type:'box', x:PRJ_CIR_X, y:eqY - PRJ_A / 2, w:PRJ_A, h:PRJ_ARM_T, angle:-Math.PI / 2,
    mass:0.2, layers:0,                       // ★ゴースト＝ぶつからず、レーザーも透過する
    fillColor:'#90a4ae', strokeColor:'#cfd8dc', strokeWidth:1.5, label:'棒' }, slip));
  const ball = new Body(Object.assign({
    type:'circle', x:PRJ_CIR_X, y:eqY - PRJ_A, radius:PRJ_BALL_R, mass:PRJ_MASS,
    fixedRotation:true, fillColor:'#42a5f5', strokeColor:'#ffffff', strokeWidth:1.5,
    label:'等速円運動 1kg' }, slip));
  // 出発の瞬間から等速で回っているように、棒も球も初速を入れておく（v = ω×r）
  arm.av = w; arm.vx = w * PRJ_A / 2;
  ball.vx = w * PRJ_A;
  objects.push(arm, ball);
  joints.push(new Joint({ type:'axle', bodyA:null, anchorAx:PRJ_CIR_X, anchorAy:eqY,
                          bodyB:arm, anchorBx:-PRJ_A / 2, anchorBy:0,
                          motorSpeed:w, motorTorque:2000 }));
  joints.push(new Joint({ type:'hinge', bodyA:arm, bodyB:ball,
                          anchorAx:PRJ_A / 2, anchorAy:0, anchorBx:0, anchorBy:0 }));
  ball.tracerEnabled = true; ball.tracerColor = '#42a5f5'; ball.tracerDuration = 3;
  // ── レーザー（おもりに載せ、円のほうへ真横に撃つ）──
  //   ★物体に載せると本体と一緒に動く（Laser の body/localX/localY/angle）。角度 0 は右向き。
  lasers.push(new Laser({ body:bob, localX:PRJ_BALL_R, localY:0, angle:0, wavelength:532 }));
  setDemoCam(0, 0.65);
  // 札は地面の帯の上に置く（★装置の下は球が最も下がる位置まで使う。左右と上は本文と窓）
  demoLabel(PRJ_SHM_X - 230, gy + 46, '① 鉛直ばね振り子（単振動）',     '#ffa726');
  demoLabel(PRJ_CIR_X - 170, gy + 46, '② 棒とモーターで回す等速円運動', '#42a5f5');
  moveDemoGraphTop(velGraphNew(bob, { showPos:true, showVel:true, showAcc:true,
                                      showX:false, showY:true, showMag:false }));
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '単振動と円運動の射影');
  demoNote (p.x, p.y + 54,
    '① 天井から吊ったばねに 1kg を下げた鉛直ばね振り子（1.3 m 上げて放す）\n'
  + '② 棒の先の球をモーターで回す等速円運動（半径 1.3 m・周期 2.5 秒）\n'
  + '①②は周期も振れ幅も同じ。おもりのレーザーが②へ真横に光を撃っている\n'
  + '\n'
  + '【手順】▶実行 を押して、レーザーの当たる先を見る\n'
  + '・光の線はいつも②の球に当たり続ける ＝ 2つの物体の高さがいつも同じ\n'
  + '・つまり単振動は「等速円運動を真横から見たもの（射影）」\n'
  + '・重力はつりあいの位置を 1.55 m 下へずらすだけ。そのまわりの振れ方は\n'
  + '　水平に置いたばね振り子と同じで、周期も振幅も重力で変わらない\n'
  + '・グラフ：変位が最大のとき速度は 0、加速度は逆向きに最大。速度が最大に\n'
  + '　なるのは変位が 0 を通るとき ＝ 円運動を真横から見れば当たり前のこと');
}

// ── 2本のばねにつながれた物体の運動 ────────────────────────
//   ★両側から同じばねで引く（押す）。片方が伸びれば片方は縮み、どちらも中央へ戻す向きに
//     働くので、戻す力は2本ぶん＝ばね定数の和になる。だから周期は1本のときより短い。
//   ★摩擦0の床の上（横から見た図）。重力は垂直抗力とつり合うので、運動は左右だけ。
//   ★ばねの減衰は 0。入れると振幅が減っていき、「単振動は同じ振れ幅を保つ」が崩れる。
//   ★台車の質量をつまみ（リモコン〈物理量を変える〉）で変えられる。T = 2π√(m/2k) の
//     「質量が4倍なら周期は2倍」を、同じ台車・同じばねのままグラフの波の間隔で読ませる。
//     ばね定数のほうは変えない：リモコンが触れるのは軸のモーターまでで、ばねのジョイントは
//     対象外（remote.js の remoteKnobs）。質量の側だけで T∝√m は言い切れる。
//     ★範囲は 0.25〜4 kg。両端と開いた時点の 1 kg で周期が 1:2:4 倍に並ぶ。
//       remotePropTicks は質量の可動域を 200 等分した線形にするので、1 kg もちょうど打てる。
//     ★台車の札は「台車」にする。「1kg」のままだと、つまみを回したあと札が嘘になる。
//     ★動いている途中で回すと、速さを保ったまま重さだけが変わるので振れ幅も変わる
//       （運動エネルギーが m に比例して変わる）。周期を比べるときはリセットしてから回すよう
//       本文で案内する（止めたまま回せる。remote.js の _remoteStartSim の★）。
//       実測：中央を通る瞬間に 1→4 kg にすると振幅は 1.5→（理論 3.0 m）のところ 2.8 m で
//       台車が壁に当たる。
//     ★実測（乱数固定・24秒＝5〜23周期の平均）：0.25／1／4 kg で周期 0.9935／1.9869／
//       3.9738 秒＝理論 2π√(m/2k) と小数第4位まで一致。振幅は 1.500 m のまま。
const TSP_K    = 5;     // [N/m] ばね1本ぶん（2本で 10 N/m ⇒ 周期 2.0 秒）
const TSP_MASS = 1;     // [kg] 開いた時点の質量
const TSP_M_LO = 0.25;  // [kg] つまみの下限（周期 1.0 秒）
const TSP_M_HI = 4;     // [kg] つまみの上限（周期 4.0 秒）
const TSP_A    = 150;   // [px] 振幅（1.5 m）
const TSP_ANCH = 320;   // [px] ばねの取り付け位置（つりあいの位置から ±）
const TSP_HALF = 40;    // [px] 台車の半幅
// [px] つりあいの位置。★左へ寄せる：右うえのグラフの窓（画面 x≈263px から右）に
//   右の壁とばねが隠れてしまうため（実測：中央に置くと右の壁が窓の裏に入った）
const TSP_CX   = -100;
function demoTwoSprings() {
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 16;
  // ★力の矢印を出す。倍率は 8 px/N。この題材でいちばん大きい弾性力は
  //   振幅いっぱいのときの 2k·A = 10 N/m × 1.5 m = 15 N ＝ 120px で、台車（幅80px）より
  //   長く出る。重力と垂直抗力の 9.81 N も 78px で、打ち消し合っているのが読める。
  //   ★つまみで 4 kg にすると縦の2本（39 N）は描画の上限 260px で頭打ちになる。読みどころの
  //     横の弾性力は質量によらない（最大 15 N のまま）ので、倍率は 1 kg に合わせたままにする。
  world.forceVizScale = 8;
  updateGroundTerrain(true);
  const gy = ground.y;
  const cart = new Body({
    type:'box', x:TSP_CX + TSP_A, y:gy - 25, w:TSP_HALF * 2, h:50, mass:TSP_MASS,
    friction:0, frictionStatic:0, restitution:0, showForces:true,
    fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5, label:'台車',
  });
  objects.push(cart);
  for (const s of [-1, 1]) {
    objects.push(new Body({ type:'box', x:TSP_CX + s * (TSP_ANCH + 20), y:gy - 55, w:40, h:110, isStatic:true, mass:0,
                            friction:0, frictionStatic:0,
                            fillColor:'#37474f', strokeColor:'#90a4ae', strokeWidth:2, label:'壁' }));
    demoSpring({ anchorAx:TSP_CX + s * TSP_ANCH, anchorAy:gy - 25,
                 bodyB:cart, anchorBx:s * TSP_HALF, anchorBy:0,
                 // 中央にいるとき自然長＝どちらのばねも伸びも縮みもしていない
                 restLength:TSP_ANCH - TSP_HALF, stiffness:TSP_K, damping:0, radius:10 });
  }
  setDemoCam(0, 0.65);
  demoLabel(TSP_CX - 140, gy - 190, '中央がつりあいの位置', '#eceff1');
  moveDemoGraphTop(velGraphNew(cart, { showPos:true, showVel:true, showAcc:true,
                                       showX:true, showY:false, showMag:false }));
  // 質量のつまみ。★畳んだ形で台車の下に置く（窓の位置は下の実測で決めた）
  const knob = addRemote('prop', cart, 'body');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'mass'; knob.lo = TSP_M_LO; knob.hi = TSP_M_HI;
    knob.collapsed = true; knob.fx = 0.30; knob.fy = 0.86;
    placeRemotePanel(knob); syncRemotePanel(knob); placeRemotePanel(knob);
  }
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '2本のばねにつながれた物体');
  demoNote (p.x, p.y + 54,
    'なめらかな床（摩擦なし）の上の台車（はじめは 1 kg）を、左右から同じばね（5 N/m）で\n'
  + 'つないである。真ん中がつりあいの位置で、そこから 1.5 m ずらしたところから放す。\n'
  + '\n'
  + '【手順】▶実行 を押して、台車とグラフを見る\n'
  + '・右へずれると、右のばねは縮んで押し返し、左のばねは伸びて引き戻す\n'
  + '　＝ 2本とも中央へ戻す向きに働く（戻す力はばね定数の和で決まる）\n'
  + '・行き過ぎては戻るのくり返し。振れ幅は減らない（摩擦もばねの減衰も 0 だから）\n'
  + '・グラフ：加速度はいつも変位と逆向きで、変位に比例して大きくなる\n'
  + '　＝ これが単振動の正体。速度は真ん中を通るときに最大になる\n'
  + '\n'
  + '【もう一手】下のつまみで台車の質量を変え、グラフの波の間隔（周期）を見くらべる\n'
  + '・周期 T = 2π√(m/2k)。1 kg で 2.0 秒、4 kg で 4.0 秒、0.25 kg で 1.0 秒\n'
  + '　＝ 質量が4倍なら周期は2倍（重いほど動かしにくく、ゆっくり往復する）\n'
  + '・比べるときは リセット してから回す（動いている途中で回すと振れ幅も変わる）');
}

// ── ばね振り子（向きが変わっても周期は同じ）──────────────────
//   ★同じばね・同じおもりを、横・斜め45°・縦の3通りに置く。重力はつりあいの位置を
//     ずらすだけで、そこからのずれに対する戻す力は同じ ⇒ 周期は向きによらない。
//   ★見せ方は「3つが同時に折り返す」。3つとも、自分のつりあいの位置から同じだけ
//     ずらして放す。つりあいの位置は向きによって違う（縦は自然長より mg/k だけ下、
//     斜めは斜面方向に mg·sin45°/k）ので、そこだけは向きごとに計算して置く。
//   ★3台ともレールに乗せ、ばねの向きの1方向にしか動かないよう固定する。床の上の横の台や
//     吊るしただけの縦の台も、ドラッグや速度ツールで横へずらされると振り子のように揺れ出し、
//     「向きだけの違い」が崩れるため。
//     ★斜めを「斜面の上の物体」で作らないこと：摩擦と垂直抗力の誤差が入り、
//       「向きだけの違い」にならなくなる。
const SPD_K    = 17.5;  // [N/m] 3台とも共通（1kg で周期 1.5 秒）
const SPD_MASS = 1;     // [kg]
const SPD_AMP  = 100;   // [px] つりあいの位置からのずれ（3台とも共通）
const SPD_STEP = 50;    // [px] 目盛りの刻み（＝振幅の半分。いちばん外が放す位置）
const SPD_REST = 170;   // [px] ばねの自然長（3台とも共通）
const SPD_R    = 22;    // [px] おもりの半径
// 1台ぶん。dirDeg＝ばねが伸びる向き（0=右／45=右下／90=下）
function _springPendulumOne(ax, ay, dirDeg, color, label) {
  const th = dirDeg * Math.PI / 180;
  const ux = Math.cos(th), uy = Math.sin(th);            // ばねの向き（内部座標。y は下が正）
  // つりあいの位置：自然長 ＋ 重力のばね方向成分ぶんの伸び（横向きなら 0）
  const sag = SPD_MASS * G_EARTH * uy / SPD_K * PPM;     // [px]
  const d0  = SPD_REST + sag;
  const bob = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x: ax + ux * (d0 + SPD_AMP), y: ay + uy * (d0 + SPD_AMP), radius:SPD_R, mass:SPD_MASS,
    friction:0, frictionStatic:0, restitution:0,
    guideEnabled: true, guideAngle: th,                  // ★ばねの向きに固定（上の★）
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5, label,
  });
  objects.push(bob);
  objects.push(new Body({ type:'box', x:ax, y:ay, w:34, h:34, isStatic:true, mass:0,
                          fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5 }));
  demoSpring({ anchorAx:ax, anchorAy:ay, bodyB:bob,
               restLength:SPD_REST, stiffness:SPD_K, damping:0 });
  // つりあいの位置を中心とする等間隔の目盛り（注釈なので物理には一切関与しない）。
  //   ★刻みは振幅の半分。いちばん外の線がちょうど放す位置に来るので、3台が折り返す
  //     ところと真ん中を通るところが、同じ番号の線で読める。
  //   ★中央だけ太く長くする。全部同じだと「どれがつりあいの位置か」が消える。
  for (let k = -2; k <= 2; k++) {
    const c = ax + ux * (d0 + k * SPD_STEP), cy = ay + uy * (d0 + k * SPD_STEP);
    const h = k === 0 ? 34 : 24;
    demoPath([{ x: c - uy * h, y: cy + ux * h }, { x: c + uy * h, y: cy - ux * h }],
             k === 0 ? '#eceff1' : '#b0bec5', k === 0 ? 4 : 2.5);
  }
  return bob;
}
function demoSpringPendulumOrientation() {
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 16;
  updateGroundTerrain(true);    // ①は床の上に置く（向きはレールで固定。上の★）
  const y0 = -430;
  _springPendulumOne(-600, ground.y - SPD_R,  0, '#ffa726', '横');
  _springPendulumOne(-120, y0,               45, '#66bb6a', '斜め45°');
  _springPendulumOne( 330, y0,               90, '#42a5f5', '縦');
  setDemoCam(0, 0.65);
  demoLabel(-600, ground.y - 90, '① 横',     '#ffa726');
  demoLabel(-120, y0 - 60,       '② 斜め45°', '#66bb6a');
  demoLabel( 330, y0 - 60,       '③ 縦',     '#42a5f5');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'ばね振り子（向きと周期）');
  demoNote (p.x, p.y + 54,
    '同じばね・同じおもり（1 kg）を、横・斜め45°・縦の3通りに置いたもの。\n'
  + '3台とも、自分のつりあいの位置（太い灰色の線）から同じだけずらして放す。\n'
  + '目盛りは3台とも同じ間隔で、いちばん外の線が放す位置。\n'
  + '\n'
  + '【手順】▶実行 を押して、3台が折り返す瞬間を見くらべる\n'
  + '・3台はいつも同時に折り返す ＝ 周期は向きによらない\n'
  + '・どの瞬間も、3台は自分の目盛りの同じところにいる\n'
  + '・重力はつりあいの位置をずらすだけ（縦の印がいちばん下にあるのはそのため）。\n'
  + '　そこからのずれに対して戻ってくる力は、向きが変わっても同じだから\n'
  + '・周期を変えられるのは、ばねの強さとおもりの重さだけ。重力の向きは効かない');
}

// ── 単振り子（重さによらない周期／円運動の射影）─────────────
//   ★2つのことを1画面で見せる。左の2台は「おもりの重さが4倍でも同じ動き」、右の1台は
//     「振り子の左右の動きは、等速円運動を横から見たもの」（レーザーで結ぶ）。
//   ★おもりは質点、腕は質量0の連結棒（rod）＝教科書の単振り子。棒は当たり判定を切る
//     （layers:0。2重振り子の★と同じ理由）。
//   ★円運動の球は「棒＋モーター」で作る。棒を軸（axle）で円の中心に留め、モーターに
//     単振り子と同じ角速度 ω=√(g/L) を与える。
//     ★棒だけ（rod）で回すことはできない：重力があるので下で速く上で遅い、ただの振り子に
//       なってしまう。モーターなら重力があっても一定の角速度で回り続ける
//       （実測：重力あり・刻み16 で半径 64.7px のまま、速さの振れは ±1.4%）。
//     ★トルク上限 2000 を上げないこと。上げると悪くなる（実測・30 秒、球が理想の等速
//       円運動からずれる最大量）：2000→9.1px／10000→40.3px／50000→73.1px。
//       中身を位相で追うと、1周の中の揺れはどちらも 11.56°で同じ＝トルク不足ではない。
//       違うのは出だしに付く一定の位相で、2000 は -8.1°〜+3.5°と0をまたぐのに対し
//       50000 は +24.9°〜+36.5°＝強いモーターが最初の数 tick で棒を掴んで先へ送ってしまう。
//     ★以前は「自然長 0 のばね」で作っていた（重力はつりあいを g/ω² 下げるだけなので、
//       支点を円の中心より L 上に置けば等速円運動になる）。モーターにしたので、
//       軸はそのまま円の中心に置けばよい。
//     ★棒はレイヤー0（ゴースト）。物にぶつからず、レーザーも透過する（射影デモの★）。
//   ★振れ角は①②が 15°、③だけ 6.2°。単振り子が単振動になるのは小さい角度の近似で、
//     ずれを決めるのは振れ角だけ（周期のずれ ≒ θ²/16）。腕の長さは効かない。
//     実測（30 秒。光と球のずれは包絡線の最大値。ある瞬間の値は振れの中で上下するので読めない）：
//       ・15°のまま腕を伸ばす … 250px:+0.404%/15.2px → 400px:+0.413%/19.4px
//                              → 600px:+0.420%/23.5px → 900px:+0.423%/29.3px
//         周期のずれは長さによらず 0.4% で一定。そのうえ光と球のずれは √L で増える
//         （振れ幅 L·sinθ が伸びるため）。＝長くするだけでは狙いと逆に悪くなる。
//       ・横のふれ幅 64.7px を保ったまま伸ばす（＝角度が小さくなる）…
//         250px/15°:+0.404%/15.2px → 400px/9.3°:+0.159%/5.1px
//         → 600px/6.2°:+0.071%/2.3px → 900px/4.1°:+0.032%/1.2px
//     ★そこで③だけ 6 m にした。画面上の振れ幅は①②と同じ 64.7px のままなので
//       「振れが小さすぎて見えない」にはならない。組み直したあとのデモの実測（30 秒）：
//         光と球の中心のずれ 7.4px（組み直す前は 14.4px。球の半径は 16px）
//         内訳 … 振り子が理想の cos からずれる量 2.3px ／ 球の側 9.1px
//         おもりと球のすき間は最小 69.4px（振れているおもりに球は当たらない）
//       ★残りのずれはもう振り子の近似ではなく球の側が主。ここを削るには上のモーターの
//         位相を直すしかなく、トルクでは動かない（1つ上の★）。16px に対して 7.4px なら
//         レーザーは球に当たり続けるので、これ以上は追わない。
//     ★①②を 15°のまま残すのは、そちらの読みどころが「重さによらない」で、
//       近似のずれは 2 台に同じだけ乗る＝重なり具合に一切効かないため。
//     ★3台とも「横へ同じだけずらして放す」で揃えてある（角度ではなく、ふれ幅で揃える）。
//       ③の角度は PEN_AMP から asin で出すので、腕の長さを変えても揃ったままになる。
const PEN_L     = 250;   // [px] ①②の腕の長さ（2.5 m）
const PEN_DEG   = 15;    // [°]  ①②の放す角度
// [px] ①②の支点の高さ。★説明文（10行）の下端が -518px なので、そこより下に置く。
//   -560 では棒の上 42px が本文の最後の2行に掛かっていた
const PEN_PIV_Y = -470;
const PEN_CIR_Y = 40;    // [px] 円の中心の高さ（★③の腕を伸ばしたぶん下げた。下の PEN3_PIV_Y の★）
// [px] 横のふれ幅。3台とも共通で、これが円運動の半径にもなる
const PEN_AMP   = PEN_L * Math.sin(PEN_DEG * Math.PI / 180);
// ③（レーザーつき）だけは腕を長くして、そのぶん放す角度を小さくする。★理由は下の★
const PEN3_L     = 600;                             // [px] ③の腕の長さ（6 m）
const PEN3_TH    = Math.asin(PEN_AMP / PEN3_L);     // [rad] ③の放す角度（6.2°）
// [px] ③の支点の高さ。腕が長いぶん上へ逃がす。★おもりの下端（-114）と円運動の球の
//   上端（-41）の間に 73px 空く高さ。ここを詰めると振れているおもりに球が当たる。
//   ★これ以上は上げない：-800 にすると支点が画面の上端から 68px ＝ 上の操作ヒントの帯
//     （高さ 55px）のすぐ下に入り、窓が低いと帯に隠れる。足りないぶんは円の中心を下げる
const PEN3_PIV_Y = -730;
// 単振り子1台。r はおもりの半径（重さの違いを見た目でも出す）。L/pivY/th は③用（既定は①②）
function _simplePendulum(px, mass, r, color, label, L, pivY, th) {
  if (L === undefined)    L    = PEN_L;
  if (pivY === undefined) pivY = PEN_PIV_Y;
  if (th === undefined)   th   = PEN_DEG * Math.PI / 180;
  const bob = new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x: px + L * Math.sin(th), y: pivY + L * Math.cos(th),
    radius:r, mass, friction:0, frictionStatic:0, restitution:0,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5, label,
  });
  objects.push(bob);
  joints.push(new Joint({ type:'rod', bodyA:null, anchorAx:px, anchorAy:pivY,
                          bodyB:bob, restLength:L, layers:0 }));
  return bob;
}
function demoSimplePendulum() {
  resetDemoWorld();
  world.sleeping = false;
  world.substeps = 16;
  updateGroundTerrain(false);
  // ── 左：おもりの重さだけが違う2台 ──
  _simplePendulum(-620, 1, 20, '#ffa726', '1kg');
  _simplePendulum(-380, 4, 32, '#ef5350', '4kg');
  // ── 右：レーザーを載せた1台と、その下で等速円運動する球 ──
  const bobR = 20;
  const bob = _simplePendulum(320, 1, bobR, '#66bb6a', '1kg', PEN3_L, PEN3_PIV_Y, PEN3_TH);
  lasers.push(new Laser({ body:bob, localX:0, localY:bobR, angle:Math.PI/2, wavelength:532 }));
  const w = Math.sqrt(G_EARTH / (PEN3_L * PX2M));     // [rad/s] ③の角振動数 √(g/L)
  const A = PEN_AMP;                                  // [px] 振れの左右の大きさ＝円の半径
  // 軸受け → 棒 → 球 の順に積む（あとから push したものが手前に描かれる）
  objects.push(new Body({ type:'circle', x:320, y:PEN_CIR_Y, radius:11, isStatic:true, mass:0,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'軸（固定）' }));
  const arm = new Body({
    type:'box', x:320 + A / 2, y:PEN_CIR_Y, w:A, h:8, mass:0.2, layers:0,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#90a4ae', strokeColor:'#cfd8dc', strokeWidth:1.5, label:'棒' });
  const ball = new Body({
    type:'circle', x:320 + A, y:PEN_CIR_Y, radius:16, mass:1, fixedRotation:true,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#42a5f5', strokeColor:'#ffffff', strokeWidth:1.5, label:'円運動',
  });
  // 出発の瞬間から等速で回っているように初速を入れる（v = ω×r）
  arm.av = w; arm.vy = w * A / 2;
  ball.vy = w * A;
  objects.push(arm, ball);
  ball.tracerEnabled = true; ball.tracerColor = '#42a5f5'; ball.tracerDuration = 4;
  joints.push(new Joint({ type:'axle', bodyA:null, anchorAx:320, anchorAy:PEN_CIR_Y,
                          bodyB:arm, anchorBx:-A / 2, anchorBy:0,
                          motorSpeed:w, motorTorque:2000 }));
  joints.push(new Joint({ type:'hinge', bodyA:arm, bodyB:ball,
                          anchorAx:A / 2, anchorAy:0, anchorBx:0, anchorBy:0 }));
  setDemoCam(0, 0.65);
  // 札はおもりの下に置く（★支点の上は説明文が占めていて、真横は棒とレーザーが通る）
  demoLabel(-700, PEN_PIV_Y  + PEN_L  + 60, '① 1kg と ② 4kg（長さは同じ）', '#eceff1');
  // ★③の札はおもりと円の間のすき間へ。ここより右はレーザーが通り、左は縦軸の目盛りが出る
  demoLabel(  40, PEN_CIR_Y - PEN_AMP - 60, '③ レーザーつき',              '#66bb6a');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '単振り子');
  demoNote (p.x, p.y + 54,
    '振り子が3台。左の2台は長さ 2.5 m で、おもりの重さだけが違う（1 kg と 4 kg）。\n'
  + '右の1台は長さ 6 m で、レーザーを載せて真下へ光を撃っている。\n'
  + '3台とも、横へ同じだけずらして静かに放す（長い1台はそのぶん振れ角が小さい）。\n'
  + '\n'
  + '【手順】▶実行 を押して、まず左の2台を見る\n'
  + '・重さが4倍でも2台はぴったり重なったまま振れ続ける ＝ 周期はおもりの重さによらない\n'
  + '　（重いほど強く引かれるが、そのぶん動かしにくいので、ちょうど打ち消し合う）\n'
  + '・つぎに右の1台と、その下で棒の先の球が回るのを見る（棒はモーターが一定の速さで回す）\n'
  + '・レーザーはいつも下の球に当たり続ける ＝ 振り子の左右の動きは円運動を横から見たもの\n'
  + '※振り子が単振動になるのは振れ角が小さいときの話。右の1台が長いのはそのため');
}

// ── 2重振り子（カオス）───────────────────────────────────
//   ★単振り子の隣に置く題材。単振動は「同じように始めれば同じように動く」が土台に
//     あるので、腕をもう1本つないだ途端にそれが成り立たなくなる、を並べて見せる。
//   ★2台の違いは上の腕の初期角度 3°だけ。他（腕の長さ・おもりの質量・支点の高さ）は
//     同じ定数を同じ関数に通して作る＝作り分けの取り違えが起きようがない。
//   ★おもりは質点、腕は質量のない剛体棒＝教科書の2重振り子そのもの。連結棒（rod）は
//     2点の距離だけを固定する拘束なので、おもりの中心につなぐと回転のトルクが一切
//     入らない（＝おもりの自転は運動に関与しない。質点2つと同じ）。
//   ★摩擦も空気抵抗も入れない（drag は既定0）。減衰があると違いが育つ前に止まる。
//   ★軌跡は下のおもりだけに付ける。上のおもりは支点からの距離が一定＝ただの円周を
//     なぞるので、描いても円が2つ重なるだけで、下のおもりの軌跡を読みにくくする。
//   ★初期角度の差は 1°ではなく 3°にした。下のおもりの離れが「おもり1個ぶん(36px)」／
//     「腕の半分(65px)」になるまでの時間は実測で
//         0.3° … 13.1 / 13.2 秒（置いた瞬間のずれ 0.7px）
//         1°   … 10.9 / 11.9 秒（2.3px）
//         3°   …  7.4 / 10.7 秒（6.8px）   ← これを採る
//         5°   …  4.0 /  7.5 秒（11.3px）
//     3°でも置いた瞬間のずれは 6.8px＝おもりの半径 18px より小さく、画面（倍率0.65）では
//     4px しかない＝「ほとんど同じに見える」は保てる。5°まで開くと待ち時間は半分になるが、
//     並べた時点でずれが見て取れてしまい、題材の「同じに見えるのに」が弱くなる。
const DP_ARM      = 130;   // [px] 腕の長さ。上下とも 1.3 m
const DP_MASS     = 1;     // [kg] おもり。上下とも同じ
const DP_BOB_R    = 18;    // [px] おもりの半径
const DP_PIVOT_Y  = -370;  // [px] 支点の高さ（地面から上へ）。下のおもりの届く範囲は
                           //      支点から半径 260px なので、上は説明文の下端、
                           //      下は地面の 110px 上で止まる（どちらにも触れない）
const DP_TILT_DEG = 3;     // [°]  右の振り子だけ、上の腕をこの角度だけ下げて始める
// ★この題材だけ細かい刻みで回す（既定の 4 では2台がいつまでも同じ動きをする）。
//   連結棒の拘束は1歩ごとにわずかにエネルギーを削るので、刻みが粗いと「違いが育つ」
//   より先に振り子が失速し、2台がそろって同じ小さな揺れへ落ちてしまう。
//   実測（左の振り子。腕を真上まで持ち上げるのに要る 38.2J を 100% として、30秒後・
//   60秒後に系から抜けたぶん／腕の半分だけ離れて見えるまでの時間／1tick の負荷）：
//       substeps  4 … −62% −81%・60秒たっても離れない・0.13 ms
//                 8 … −54% −81%・15.9 秒            ・0.21 ms
//                16 … −25% −42%・11.6 秒            ・0.35 ms
//                32 … −19% −39%・10.8 秒            ・0.67 ms
//                64 … −10% −18%・10.7 秒            ・1.17 ms   ← これを採る
//               128 … − 6% −11%・10.7 秒            ・2.13 ms
//   64 と 128 で離れる時刻が一致する＝この刻みで軌道はもう変わらない。これ以上細かく
//   しても減るのは数値誤差ぶんの目減りだけなので、1フレーム 16.7ms の枠と釣り合う 64 にする。
const DP_SUBSTEPS = 64;
// 支点 (px,py) に1台ぶんを組む。tiltDeg は上の腕の初期の傾き [°]
function _demoDoublePendulumOne(px, py, tiltDeg, color) {
  // 支点の目印。★当たり判定は切る（layers:0）。下のおもりは支点の真上まで届くので、
  //   ぶつかる物を置くと2台で当たり方が変わり、そもそも比べものにならなくなる。
  //   拘束そのものは世界に固定した座標（bodyA:null）が持っていて、この箱は絵でしかない
  objects.push(new Body({ type:'box', x:px, y:py, w:38, h:16, isStatic:true, layers:0,
                          fillColor:'#455a64', strokeColor:'#90a4ae', strokeWidth:1.5 }));
  const th = tiltDeg * Math.PI / 180;      // ★内部の y は下向きが正＝正の角度は「下へ傾ける」
  const bob = (x, y) => new Body({
      fixedRotation:true,   // ★回転オフ（力学デモ共通。ファイル冒頭の★）
    type:'circle', x, y, radius:DP_BOB_R, mass:DP_MASS,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:color, strokeColor:'#ffffff', strokeWidth:1.5,
  });
  const b1 = bob(px + DP_ARM * Math.cos(th), py + DP_ARM * Math.sin(th));
  const b2 = bob(b1.x + DP_ARM, b1.y);     // 傾けるのは上の腕だけ。下の腕は水平から始める
  objects.push(b1, b2);
  // ★腕（連結棒）の当たり判定は切る（layers:0）。連結棒は太さを持つ棒として他の物体と
  //   ぶつかるので、既定のままだと下のおもりが上の腕に衝突する。実物の2重振り子が
  //   2本の腕を板の手前と奥へずらして留めてあるのと同じ理由で、ここも通り抜けさせる。
  //   （実測：切る前は 11.75 秒に下のおもりが上の腕へぶつかって速さ 391→45 px/s、
  //     系の力学的エネルギーが 1 tick で 7.3 J 失われていた。反発 0 なのでまるごと熱に
  //     なり、そこから先は「2台の違い」ではなく衝突の有無が動きを決めてしまう）
  joints.push(new Joint({ type:'rod', bodyA:null, anchorAx:px, anchorAy:py,
                          bodyB:b1, restLength:DP_ARM, layers:0 }));
  joints.push(new Joint({ type:'rod', bodyA:b1, bodyB:b2, restLength:DP_ARM, layers:0 }));
  b2.tracerEnabled  = true;
  b2.tracerColor    = color;
  b2.tracerDuration = 10;   // ★10秒ぶん残す。2台が離れ始めるのが10秒あたりなので、
                            //   これだけ残せば「別々になったあと」の形が丸ごと画面に出る
  return { b1, b2 };
}
function demoDoublePendulum() {
  resetDemoWorld();
  world.substeps = DP_SUBSTEPS;
  updateGroundTerrain(true);
  const py = ground.y + DP_PIVOT_Y;
  _demoDoublePendulumOne(-360, py, 0,           '#4fc3f7');
  _demoDoublePendulumOne( 360, py, DP_TILT_DEG, '#ffa726');
  setDemoCam(0, 0.65);
  // 札は振れる範囲（支点から半径 260px）の外＝地面のすぐ上に置く。
  // 支点の上や横は下のおもりが通る場所なので、置くと軌跡が文字の上を走る
  demoLabel(-470, ground.y - 60, '① 上の腕は水平',     '#4fc3f7');
  demoLabel( 250, ground.y - 60, '② 上の腕だけ 3°下げ', '#ffa726');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '2重振り子（カオス）');
  demoNote (p.x, p.y + 54,
    '腕の長さ 1.3 m・おもり 1 kg を2本つないだ振り子が2台。どちらも腕を水平にして\n'
  + 'そっと放す。2台の違いは、上の腕の初期角度が 3°（おもりの位置で 7cm）だけ違うこと。\n'
  + '\n'
  + '【手順】▶実行 を押して、下のおもりの軌跡（青と橙）を見くらべる\n'
  + '・はじめの5秒ほどは、2台は重なったまま同じように動く\n'
  + '・10 秒あたりから離れはじめ、そのあとは似ても似つかない動きになる\n'
  + '　＝ わずかな初期条件の違いが、時間とともに増幅される（カオス）\n'
  + '・腕が1本の単振り子ならこうはならない。腕を1本足しただけで、\n'
  + '　「同じように始めれば同じように動く」が使えなくなる');
}

// ── 共振（強制振動）────────────────────────────────────
//   ★このデモの主張は「揺すり方の速さが物体の固有振動数に近いときだけ、振幅が大きく育つ」。
//     同じ強さで揺すっているのに、振幅が 6 倍違う3台を並べる。
//   ★揺する仕掛けはモーターとクランク。回る円板の中心から 0.15 m ずれた点にばねの端を
//     留めてあるので、ばねの上端は毎秒 ω ラジアンで上下する（横のずれは 0.15 m しかなく、
//     ばねの長さ 3.5 m に対して 0.1% しか効かない ＝ 実質「上端を正弦波で揺する」）。
//     ★モーター・ばね・ガイドはどれも左のツールバーにある部品で、手で組み直せる。
//   ★固有角振動数は ω₀ = √(k/m) = √(25/1) = 5.0 rad/s（周期 1.26 秒）。
//     揺する速さは ω = 0.5ω₀ / 1.0ω₀ / 2.0ω₀ の3つ。理論の振幅比（伝達率）は
//       |Y/Y₀| = √((1+(2ζr)²) / ((1−r²)² + (2ζr)²))   r = ω/ω₀、ζ = c/(2√(mk)) = 0.08
//       r=0.5 → 1.33 倍（0.20 m）　r=1 → 6.3 倍（0.94 m）　r=2 → 0.35 倍（0.05 m）
//     ★実測（20 秒めから 300tick のあいだの最大と最小の差の半分。乱数は使っていない）：
//       0.200 m / 0.937 m / 0.050 m。理論値と 0.3% 以内で一致する。
//       モーターの角速度も指令どおり（2.50 / 5.00 / 10.00 rad/s）。
//   ★減衰 c = 0.8 N·s/m（ζ=0.08）は「育ちきるまで待てる速さ」で決めた。ζ=0.05 だと
//     振幅は 1.5 m まで伸びるが、育つのに 12 秒かかる（時定数 2m/c）。0.08 なら 8 秒で、
//     しかも振幅の比は 6 倍のまま読める。
const RES_K = 25;         // [N/m] ばね定数
const RES_M = 1;          // [kg]  おもり
// ★0.29 は「これまで実際に効いていた減衰」。以前は demo-kit が c を ζ に直して渡しており、
//   そのときの質量の見積もり（おもり 1kg）が、ソルバの換算質量（クランク側の腕まで入って
//   0.135 kg）と違ったため、書いてある 0.8 ではなく 0.29 が効いていた。c をそのまま渡す
//   ようになったので、数のほうを実効値へ合わせる（0.8 のままだと共振の山が
//   507.8px → 189.8px ＝ 37% に潰れ、このデモの見どころが消える。実測）。
//   ζ は換算質量に対して 0.29/(2√(25×0.135)) = 0.079 で、上の★の 0.08 と変わらない。
const RES_C = 0.29;       // [N·s/m] ばねの減衰（換算質量に対して ζ = 0.08）
const RES_CRANK = 15;     // [px] クランクの偏心（＝揺すり幅 0.15 m）
const RES_DISK = 40;      // [px] 円板の半径
const RES_W0 = Math.sqrt(RES_K / RES_M);        // [rad/s] 固有角振動数 5.0
const RES_SHOTS = [
  { r: 0.5, head:'① ゆっくり揺する',     note:'ω = 2.5 rad/s ＝ 0.5 ω₀\n振幅 0.20 m（揺すり幅の 1.3 倍）\nおもりは上端と同じ向きに動く' },
  { r: 1.0, head:'② 固有振動数で揺する', note:'ω = 5.0 rad/s ＝ ω₀\n振幅 0.94 m（揺すり幅の 6.3 倍）\n＝ 共振。位相は 90° 遅れる', hot:true },
  { r: 2.0, head:'③ 速く揺する',         note:'ω = 10 rad/s ＝ 2 ω₀\n振幅 0.05 m（揺すり幅の 0.35 倍）\nおもりはほとんど動かない' },
];
function demoResonance() {
  const gy = ground.y;
  resetDemoWorld();
  world.sleeping = false;      // ★揺すられ続ける題材。眠らせない
  world.substeps = 8;          // ★ばねが硬め（k=25, ω₀=5）なので刻みを倍にする
  updateGroundTerrain(true);
  // ★3台は画面の右 2/3 へ寄せる。左うえは説明の本文の場所で、支柱の高さ（画面 179px）が
  //   ちょうど本文の下端と並ぶため、重ねると支柱が文字の上に乗る
  setDemoCam(158, 0.5);
  // ★円板は支柱の下面から 10px 離す。触れさせると、回っている円板と静止した梁のあいだに
  //   接触が立ち続けて、モーターがそれと押し合う（摩擦0でも法線力のちらつきが残る）
  const SUP_Y = gy - 800, DISK_Y = gy - 740, MASS_Y = gy - 400;
  RES_SHOTS.forEach((s, i) => {
    const cx = i * 500;
    // 支柱（天井）。固定
    objects.push(new Body({ type:'box', x:cx, y:SUP_Y, w:160, h:20, isStatic:true, mass:0,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'支柱（固定）' }));
    // 支柱の腕。支柱の下面から円板の中心の 6px 下まで下ろした細い棒（固定・衝突レイヤーなし）。
    //   ★軸（画鋲）は円板の中心に打つが、円板は支柱の 10px 下に浮かせてある（上の★）ので、
    //     支柱そのものには打てない。腕を下ろして中心で円板と重ね、そこを軸で留める。
    //   ★衝突レイヤーなし（layers:0）にする。ばねは取り付けた相手（円板）以外のすべてに当たる
    //     が、衝突レイヤーなしの物体だけは素通りする（slinky.js の _slinkyBroadphase）。レイヤー
    //     ありにすると、クランクが真上に来るたびにばねが中心を通って腕に当たる。
    //   ★2026-10-02 のいきさつ：はじめは支柱の外の点へ軸を直接書いていた（手では組めない）。
    //     いったん円板を背景に留めたが、ユーザーの提案（衝突しない部品を介して留める）で
    //     支柱が円板を支える元の絵に戻した。支柱も腕も固定物なので、溶接もたわみも無い。
    //   ★円板より先に置く＝円板の奥に描く（見えるのは支柱と円板のあいだの 10px だけ）
    const strut = new Body({ type:'box', x:cx, y:(SUP_Y + 10 + DISK_Y + 6) / 2, w:10, h:DISK_Y + 6 - (SUP_Y + 10),
      isStatic:true, mass:0, layers:0, friction:0, frictionStatic:0, restitution:0,
      fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'支柱の腕' });
    objects.push(strut);
    // クランクの円板。★回る当人なので回転は止めない（射影デモの棒と同じ例外）
    const disk = new Body({ type:'circle', x:cx, y:DISK_Y, radius:RES_DISK, mass:0.2,
      friction:0, frictionStatic:0, restitution:0,
      fillColor:'#ffca28', strokeColor:'#ffe082', strokeWidth:2, label:'クランク' });
    objects.push(disk);
    // ★軸は円板の中心で、円板と支柱の腕をつなぐ（上の★）。打つのは手のツールと同じ入口（demoPin）。
    //   spin:disk ＝円板が腕に対して ＋の向きに回る
    demoPin('axle', cx, DISK_Y, 'pair', { expect:[disk, strut], spin:disk, motorSpeed: s.r * RES_W0 });
    // おもり。★鉛直のガイドに載せて1自由度にする（クランクの横ぶれを運動に混ぜないため）
    const mass = new Body({ type:'box', x:cx, y:MASS_Y, w:64, h:64, mass:RES_M,
      fixedRotation:true, friction:0, frictionStatic:0, restitution:0,
      guideEnabled:true, guideAngle:Math.PI/2,
      fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:2, label:'おもり 1kg' });
    objects.push(mass);
    // ばね。★自然長は「静止して吊り合う長さ − mg/k」。こうすると開いた瞬間は
    //   つり合いの位置にいて、揺すられたぶんだけが振幅になる（初期の落下が混ざらない）
    const dist = Math.hypot(RES_CRANK, MASS_Y - DISK_Y);
    demoSpring({ bodyA:disk, bodyB:mass, anchorAx:RES_CRANK, anchorAy:0, anchorBx:0, anchorBy:0,
                 restLength: dist - toPx(RES_M * G_EARTH / RES_K),
                 stiffness:RES_K, damping:RES_C, color:'#4dd0e1' });
    // 立て札はおもりの下。★支柱の下（ばねの横）に置くと、幅 300px の札が円板（cx±40）に
    //   重なる。おもりが振れ切る位置（共振の台で cx, gy-306）より下なら、どの台でも当たらない
    annotations.push(new Annotation({ type:'text', x:cx - 150, y:gy - 230, text:s.head,
                                      size:22, bold:true, color: s.hot ? '#ff8a65' : '#4fc3f7' }));
    annotations.push(new Annotation({ type:'text', x:cx - 150, y:gy - 196, text:s.note,
                                      size:19, color:'#cfd8dc' }));
  });
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '共振（強制振動）');
  demoNote (p.x, p.y + 54,
    '同じばね（k = 25 N/m）と同じおもり（1 kg）を\n'
  + '3台。モーターで回るクランクが、ばねの上端を\n'
  + '同じ幅（0.15 m）で上下に揺する。違うのは\n'
  + '揺する速さ ω だけ。\n'
  + '\n'
  + '【手順】▶実行 を押して、10 秒ほど待つ\n'
  + '・②だけ振幅がどんどん育ち、他の2台の何倍にもなる\n'
  + '・固有角振動数 ω₀ = √(k/m) = 5.0 rad/s（周期 1.26 秒）\n'
  + '　　揺する速さがこれに近いときだけ大きく振れる ＝ 共振\n'
  + '・①（遅い）は上端と同じ向きに、ゆっくり付いていく\n'
  + '・③（速い）は揺すりに付いていけず、ほぼ止まって見える\n'
  + '\n'
  + '【もう一手】おもりを選んで質量を 4 kg にすると ω₀ が\n'
  + '　半分（2.5 rad/s）になり、共振する台が②から①へ移る');
}

// ════════════════════════════════════════
//  力学 ▸ 万有引力
// ════════════════════════════════════════
// ── 第1宇宙速度・第2宇宙速度 ──────────────────────────────
//   ★中心に固定した星と、その表面のすぐ上から真横へ打ち出す探査機10機。位置は10機とも
//     まったく同じで、違うのは打ち出す速さだけ。＝「落ちる／回る／帰ってこない」を
//     分けているのが速さ1つであることが、そのまま画面に出る。
//   ★働く力は万有引力だけ。一様な重力（world.gravY）は 0 にし、地面も消す。
//   ★星は静的物体にする。applyGravitation が組を飛ばすのは「両方とも静的」のときだけ
//     なので、静的でも引力の源にはなり、自分は動かない（js/physics/gravitation.js:25）。
//   ★数値は「表面の重力と第1宇宙速度が、どちらも読める値になる」ように選んだ：
//       星 900000 kg・半径 3.0 m ＋ 万有引力定数 100 → 表面の重力 9.99 m/s²（地球とほぼ同じ）
//       打ち出す点は中心から 3.6 m（表面の 0.6 m 上）→ 第1宇宙速度 4.999 m/s ＝ ちょうど 5.00
//       第2宇宙速度 = √2 × 5.00 = 7.07 m/s、円軌道の周期 4.53 秒
//   ★星と探査機の質量比が 90万倍なのは見た目のためではない。applyGravitation は総当たりで、
//     探査機どうしも引き合う。10機は重なった1点から出発するので、そこが最も効いてしまう。
//     星の引力は G·M、探査機どうしは G·m で決まるので、M/m を上げるほど後者だけが薄まる
//     （G·M を保ったまま G を下げ M を上げる）。M/m = 90万での効き方：出発点の探査機どうしの
//     加速度は 1.56 px/s² で星の引力 694 px/s² の 0.23%。実測でも、円軌道の1機を単独で回した
//     ときとの差は1周して 2.5px（軌道半径 360px の 0.7%）で、軌道の形は変わらない。
//     太陽と地球の質量比 33万倍と同じ桁でもある。
//   ★衝突が要るのは「落ちる1機」だけ。10機が重なって出発するので、残り9機はレイヤー0
//     （ゴースト）にして互いに押し合わないようにする。落ちる1機だけを既定のレイヤーに
//     すれば、星とはぶつかり、他の探査機とはすれ違う。レイヤーは4枚しかない
//     （LAYER_ALL = 0b1111）ので、機ごとに1枚ずつ配る形は取れない。
//     ★残り9機が星に触れないことは軌道で保証されている：円軌道と楕円5機のいちばん低い点は
//       打ち出した 3.6 m そのもの（表面 3.0 m より外）、逃げる3機は離れる一方。
const ORB_STAR_M = 900000;   // [kg] 星
const ORB_STAR_R = 300;      // [px] 星の半径（3.0 m）
const ORB_R0     = 360;      // [px] 打ち出す点（中心から 3.6 m ＝ 表面の 0.6 m 上）
const ORB_G      = 100;      // 実効万有引力定数 G_sim（冒頭の★）
const ORB_BALL_R = 11;       // [px] 探査機。10機ぶん重なるので小さめ
// 打ち出す速さ（第1宇宙速度の何倍か）と色。
//   ★色は速さの順に赤→黄→緑→水色→青→紫と回す。軌跡の色の並びがそのまま速さの並びに
//     なるので、どれが速いほうかを凡例と照らさずに読める。
//   ★第1宇宙速度と第2宇宙速度の2本だけは、隣と色が近くならないように離してある
//     （黄と濃い青）。この2本が題材の主役で、残りは「その間」と「その先」だから。
//   ★楕円の5機は 5.50 から 0.25 m/s ずつの等間隔にする。等間隔に速くしているのに
//     いちばん遠い点は 5.5 → 7.1 → 9.3 → 12.8 → 19.4 m と加速度的に伸びる（実測）
//     ＝ 第2宇宙速度に近づくほど楕円が発散していくことが、刻みを揃えてはじめて読める。
//     ★6.25 と 6.50 の2機は遠い点が画面の外へ出る（一周は実測 15.4 秒・25.7 秒）。
//       これは隠さず本文に書く。「画面に収まる速さ」で切ると、まさにこの発散が消える。
const ORB_SHOTS = [
  { k: 0.70,       color:'#ef5350', label:'3.50 m/s（落ちる）' },
  { k: 1.00,       color:'#ffd54f', label:'5.00 m/s（第1宇宙速度）' },
  { k: 1.10,       color:'#d4e157', label:'5.50 m/s（楕円軌道）' },
  { k: 1.15,       color:'#9ccc65', label:'5.75 m/s（楕円軌道）' },
  { k: 1.20,       color:'#43a047', label:'6.00 m/s（楕円軌道）' },
  { k: 1.25,       color:'#26a69a', label:'6.25 m/s（楕円軌道）' },
  { k: 1.30,       color:'#26c6da', label:'6.50 m/s（楕円軌道）' },
  { k: Math.SQRT2, color:'#2979ff', label:'7.07 m/s（第2宇宙速度）' },
  { k: 1.55,       color:'#7e57c2', label:'7.75 m/s' },
  { k: 1.70,       color:'#ba68c8', label:'8.50 m/s' },
];
// 半径 r[px] での円軌道の速さ[px/s]。★ソフトニング ε²（world.gravSoften）込みで
//   a = G·M/(r²+ε²) と v²/r を等しく置いただけ。ここで解いておけば、星の質量や
//   打ち出す高さを変えた人が「円軌道が円でなくなった」に気づかないまま進めない。
function orbitSpeedAt(r) {
  return Math.sqrt(r * ORB_G * ORB_STAR_M / (r * r + gravSoften2()));
}
function demoOrbitSpeeds() {
  resetDemoWorld();
  setDemoGravity(0);             // ★一様な重力は無し（働くのは万有引力だけ）
  world.gravitation  = true;
  world.gravStrength = ORB_G;
  world.sleeping     = false;    // 遠いところでは遅くなるので、眠って止まらないように
  // ★刻みは既定の 4 のまま。上げても円軌道は良くならない（実測：5周まわしたときの
  //   半径のずれの最大が 刻み4 … 0.40%／8 … 0.28%／16 … 0.23%／32 … 0.21%。
  //   5周後の半径はどれも 359.9px で、ふくらみも縮みもしない）。
  updateGroundTerrain(false);
  setDemoCam(0, 0.50);
  // ★星は画面の中心から右上へずらす。cam から取るので、窓の大きさが変わっても位置関係は崩れない。
  //   右へ … 左うえは説明の場所。中央に置くと星が本文に掛かる（本文の右端との間が 90px）。
  //   上へ … 楕円のいちばん遠い点は打ち出した点の真反対＝星の真下に来る。星を中央に置くと
  //          遠い点 927px（6.00 m/s）が画面の下から出てしまう。上げると下に 968px 取れる。
  const sx = cam.x + 480, sy = cam.y - 150;
  // ★星の表面には摩擦を持たせ、探査機は回転を止める（fixedRotation）。どちらも
  //   「落ちた1機がちゃんと止まる」ために要る。摩擦0のままだと着地後も表面を滑り続け
  //   （実測：60秒後も 4.05 m/s で滑走）、摩擦だけ足すと今度は円い探査機が星の表面を
  //   転がり出して、やはり止まらない（実測：2.70 m/s のまま 60秒。転がり抵抗は無いので
  //   永久に転がる）。どちらの場合も「落ちた」のか「低いところを回っている」のか
  //   画面で区別がつかない。回転を止めれば摩擦は滑り摩擦として効き、着地から 1.7 秒で
  //   完全に止まる（実測。以後30秒まで r=311px・|v|=0.00 のまま。円軌道の 359.9px も変わらず）。
  //   ★探査機の自転はこの題材の外（見たいのは重心の道すじだけ）。
  //   ★摩擦は接触でしか効かない（背景摩擦は world.bgFriction が別に持つ）ので、
  //     飛んでいる9機の軌道には影響しない。
  const surf = { friction:0.6, frictionStatic:0.8, restitution:0 };
  objects.push(new Body(Object.assign({
    type:'circle', x:sx, y:sy, radius:ORB_STAR_R, mass:ORB_STAR_M, isStatic:true,
    fillColor:'#ffb300', strokeColor:'#ffe082', strokeWidth:2, label:'星（固定・90万kg）',
  }, surf)));
  const v1 = orbitSpeedAt(ORB_R0);
  const probes = [];
  ORB_SHOTS.forEach((s, i) => {
    const b = new Body(Object.assign({
      type:'circle', x:sx, y:sy - ORB_R0, radius:ORB_BALL_R, mass:1,
      vx: s.k * v1,                        // ★星の真上に置いてあるので、真横＝接線の向き
      fixedRotation:true,                  // ★転がらせない（すぐ上の★）
      layers: i === 0 ? undefined : 0,     // ★落ちる1機だけ星とぶつかる（冒頭の★）
      fillColor:s.color, strokeColor:'#ffffff', strokeWidth:1,
      label:s.label,
    }, surf));                             // ★10機は速さ以外まったく同じ（摩擦も揃える）
    b.tracerEnabled  = true;
    b.tracerColor    = s.color;
    b.tracerDuration = 45;                 // ★いちばん外の楕円（6.50 m/s）の一周 25.7 秒より長く
    objects.push(b);
    probes.push(b);
  });
  // ── 速度のグラフ（楕円の1機だけ）────────────────────────────
  //   ★出すのは「黄（円軌道）の2つ外側」＝ 5.75 m/s の1機だけ。窓は1つ＝1物体なので、
  //     10機ぶん出すと画面が埋まる。楕円を1本えらぶなら、円軌道との違いが読めて、
  //     しかも軌道が画面に収まっているものがよい。
  //   ★出すのは速さ（大きさ）だけ。この題材で読みたいのは「近いところで速く、遠いところで
  //     遅い」の1点で、x 成分・y 成分は軌道の向きの話になって邪魔になる。
  //     変位と加速度の段も出さない（変位は軌跡そのものが見せている）。
  //   ★何番目かは ORB_SHOTS の並びから引く（円軌道の 2つ外側）。速さを1行足した人が
  //     窓の相手を直し忘れると、黙って別の機のグラフが出ることになる。
  //   ★窓は左下へ寄せる。星を画面の右上へ置いてある（下の★）ので、既定の右下では
  //     楕円のいちばん遠い点の側（星の真下）が窓に隠れる。左うえは本文の場所なので、
  //     空いているのは本文の下＝左下。
  const iCircle = ORB_SHOTS.findIndex(s => s.k === 1.00);
  moveDemoGraphLeft(
    velGraphNew(probes[iCircle + 2], { showPos:false, showVel:true, showAcc:false,
                                       showX:false, showY:false, showMag:true }));
  // 打ち出す点と向き。★軌跡はここから右へ出ていくので、印は打ち出す点の「上」に置く
  demoArrow(sx + 30, sy - ORB_R0 - 78, 130, 1, '#90a4ae');
  demoLabel(sx - 330, sy - ORB_R0 - 90, '10機ともここから同時に', '#90a4ae');
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '第1宇宙速度・第2宇宙速度');
  demoNote (p.x, p.y + 54,
    '中心の星は固定（90万 kg・半径 3.0 m、表面の重力は 9.99 m/s² ＝ 地球とほぼ同じ）。\n'
  + 'その表面の 0.6 m 上から、探査機 1kg を10機、まったく同じ点から真横へ同時に打ち出す。\n'
  + '違うのは速さだけ（働く力は万有引力だけ。一様な重力も地面もない）。\n'
  + '\n'
  + '【手順】▶実行 を押して、10本の軌跡を見くらべる\n'
  + '・赤 3.50 m/s … 回りきれずに落ちて、星の表面に着く\n'
  + '・黄 5.00 m/s … 円軌道。高さが変わらないまま回り続ける ＝ 第1宇宙速度\n'
  + '・黄緑〜水色 5.50／5.75／6.00／6.25／6.50 m/s … どれも楕円軌道。打ち出した点がいちばん低い\n'
  + '　　0.25 m/s ずつしか速くしていないのに、いちばん遠い点は中心から\n'
  + '　　5.5 → 7.1 → 9.3 → 12.8 → 19.4 m と伸びる（一周も 6.2 → 25.7 秒へ延びる）\n'
  + '　　外側の2機は画面の外まで出てから戻ってくる ＝ 待っていれば必ず帰ってくる\n'
  + '・青 7.07 m/s … 5.00 の √2 倍 ＝ 第2宇宙速度。ここで遠い点が無限へ飛び、もう戻らない\n'
  + '・青紫 7.75 ／ 紫 8.50 m/s … さらに速い。同じ「戻らない」でも、より真っすぐ遠ざかる\n'
  + '・速さが足りなければ落ち、足りれば回り、√2 倍を超えると帰ってこない');
}

// ── 連星（2つの星は重心のまわりを回る）──────────────────────
//   ★見せたいのは1点だけ：「重い星のまわりを軽い星が回っている」のではなく、
//     2つとも共通の1点（重心）のまわりを回っている、ということ。だから
//     ・どちらの星も静的にしない（片方を固定した瞬間に題材が消える）
//     ・質量比は 3:1。1:1 だと対称すぎて「重心のまわり」も「たがいのまわり」も
//       同じ図に見えるし、100:1 だと重い星の円が小さすぎて止まって見える。
//       3:1 なら重い星も半径 1.2 m の円をはっきり描く。
//       ★その「止まって見える」側は捨てたのではなく、別のデモに分けてある
//         （demoBinaryStarWobble。比を 15:1 まで上げて重心を星の内部へ入れる）。
//   ★重心が止まっているのは、はじめの運動量の合計を 0 に置いたから。
//     applyGravitation は組ごとに大きさの等しい逆向きの力積を与える（js/physics/
//     gravitation.js:33-36）ので合計の運動量は厳密に保存し、重心は動かない。
//     ＝ 重心の印が2つの円の中心に留まり続けることが、そのまま重心の証拠になる。
//     ★以前はここにペンツールの ✕ を注釈として置いていた。置いた印は「ここが重心の
//       はず」と人が宣言したものでしかなく、動かないのは当たり前（注釈は物理に一切
//       参加しない）。表示メニューの「選択系の重心を表示」は Σmr/Σm を毎フレーム解き
//       直した結果なので、それが動かないこと自体が読みどころになる＝主張が証拠に変わる。
//     実測：60秒（5.7周）まわしても、重心のずれ 0px・合計の運動量 0（どちらも
//     浮動小数の丸めでも厳密に 0 のまま。vB がちょうど 3·vA になるため）。
//   ★数値は「重心の式が画面の値でそのまま検算できる」ように選んだ：
//       星A 3.0×10⁵ kg・星B 1.0×10⁵ kg、間隔 4.8 m、G_sim = 100
//       → 重心までの距離 1.2 m と 3.6 m（比 1:3 ＝ 質量の比の逆）
//         速さ 0.72 m/s と 2.16 m/s（比も 1:3）→ 運動量の大きさが等しい
//         周期はどちらも 10.45 秒（実測。同じ点のまわりを回るので当然どちらも同じ）
//     実測の軌道半径は 120.02px / 360.07px（標準偏差はどちらも 0.09%）＝ 円のまま
//     ☆2026-09-27 に万有引力を位置の前後へ半分ずつにしたあと（gravitation.js の★）：
//       120.017px / 360.052px・標準偏差 0.010%、周期 10.453 秒。重心と運動量は 0 のまま
//   ★ソフトニング ε は既定の 8px のまま。間隔 480px に対して力の減りは 0.03% で、
//     この題材（重心の位置）には効かない。下げるのは太陽系のような縮尺模型だけ。
const BIN_MA = 300000;   // [kg] 星A（重いほう）
const BIN_MB = 100000;   // [kg] 星B
const BIN_D  = 480;      // [px] 2つの星の間隔（4.8 m）
const BIN_G  = 100;      // 実効万有引力定数 G_sim
const BIN_NOTE_SIZE  = 37;   // [px] 本文（既定 23px の 1.6 倍。下の★）
const BIN_TITLE_SIZE = 48;   // [px] 見出し（既定 30px の 1.6 倍）
function demoBinaryStar() {
  resetDemoWorld();
  setDemoGravity(0);             // ★一様な重力は無し（働くのは2つの星の間の万有引力だけ）
  world.gravitation  = true;
  world.gravStrength = BIN_G;
  world.sleeping     = false;    // 重い星は 0.72 m/s と遅いので、眠って止まらないように
  updateGroundTerrain(false);
  setDemoCam(0, 0.50);
  // ★重心は画面の右へ置く。本文を 1.6 倍にしたので左半分は本文で埋まる（幅 1102px、
  //   高さ 770px＝16行×37px×行送り1.3。重心の印の説明で2行増えた）。
  //   星Bの円（半径 3.6 m ＝ 360px）はその右へ逃がす。グラフの窓は
  //   開かないので右下も空いており、円の全体が縦にも収まる。
  const M  = BIN_MA + BIN_MB;
  const rA = BIN_D * BIN_MB / M;               // 重心から星Aまで [px]（120px ＝ 1.2 m）
  const rB = BIN_D * BIN_MA / M;               // 　　　　　星Bまで [px]（360px ＝ 3.6 m）
  const cx = cam.x + 640, cy = cam.y + 60;     // 重心の位置
  // 円軌道の速さ。★F = G·mA·mB/(d²+ε²) を、それぞれの円運動 m v²/r につり合わせる。
  //   ここで解いておけば、質量や間隔を変えた人が「円軌道が円でなくなった」に
  //   気づかないまま進めない（第1宇宙速度のデモの orbitSpeedAt と同じ考え）。
  const F  = BIN_G * BIN_MA * BIN_MB / (BIN_D * BIN_D + gravSoften2());
  const vA = Math.sqrt(F * rA / BIN_MA);       // 72.2 px/s ＝ 0.72 m/s
  const vB = Math.sqrt(F * rB / BIN_MB);       // 216.5 px/s ＝ 2.16 m/s（vA の3倍）
  // ★向きは逆にする（mA·vA = mB·vB なので合計の運動量はちょうど 0）。
  //   ここが 0 でないと重心が流れていき、ペンで書いた ✕ から離れていく。
  const mk = (x, vy, m, r, color, stroke, label) => {
    const b = new Body({ type:'circle', x, y:cy, radius:r, mass:m, vy,
                         fixedRotation:true,          // ★自転はこの題材の外（見たいのは重心の道すじ）
                         fillColor:color, strokeColor:stroke, strokeWidth:2, label });
    b.tracerEnabled  = true;
    b.tracerColor    = color;
    b.tracerDuration = 12;                     // ★一周 10.4 秒より少し長く（円が閉じて見える）
    objects.push(b);
    return b;
  };
  const starA = mk(cx - rA,  vA, BIN_MA, 58, '#ffb300', '#ffe082', '星A 30万kg');
  const starB = mk(cx + rB, -vB, BIN_MB, 40, '#4fc3f7', '#b3e5fc', '星B 10万kg');
  // ── 重心の印（表示メニューの「選択系の重心を表示」）──────────────
  //   ★系は星A と星B の2つ。印も札もこの機能が自分で描くので、デモ側で置くものは無い
  //     （render/vectors.js の drawCenterOfMass。塗り分けた丸＋「重心」の札）。
  //   ★手で作れる部品だけで組む約束のとおり、これは表示メニューから誰でも出せる。
  //     2つの星を選んで「選択系の重心を表示」を押せば、この画面がそのまま再現できる。
  comIds = [starA.id, starB.id];
  // ★本文は既定（23px）の 1.6 倍。この題材は円2つしか置かないので画面が余り、
  //   既定のままだと画面上 10.4px でいかにも小さい。37px なら 16.6px になる。
  //   ★そのぶん本文は幅も高さも 1.6 倍に伸びるので、1行を 30 文字ほどに詰め、
  //     系の置き場所を右へずらしてある（上の cx）。実測の本文の幅は 1091px で、
  //     左端 cam.x−1060 から右端は cam.x+31。星Bの円の左端 cam.x+240 との間が 209px。
  //   ★見出しは短くする。48px では 19 文字で画面の 460px を使い、右上のツールヒントの
  //     帯（画面の 420px から右）の裏に末尾が隠れた（実測）。13 文字なら 303px で収まる。
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '連星 ― 重心のまわりを回る', BIN_TITLE_SIZE);
  demoNote (p.x, p.y + 86,
    '星A（30万 kg）と星B（10万 kg）が、たがいの引力だけで動く。\n'
  + '質量の比は 3:1。外から力は加わらない。\n'
  + '\n'
  + '【手順】▶実行 を押して、2本の軌跡を見くらべる\n'
  + '・白黒に塗り分けた丸が重心の位置\n'
  + '・重い星A も止まっていない。印のまわりを半径 1.2 m で回る\n'
  + '・星B は「星Aのまわり」ではなく、同じ印を中心に半径 3.6 m\n'
  + '・2つの円の中心はどちらも印 ＝ 重心。周期も同じ 10.4 秒\n'
  + '\n'
  + '【なぜ印がそこから動かないか】\n'
  + '・重心までの距離の比 1.2 : 3.6 = 1 : 3 ＝ 質量の比の逆\n'
  + '　30万 × 1.2 = 10万 × 3.6\n'
  + '・速さの比も 1 : 3。2つの運動量は大きさが等しく向きが逆で、\n'
  + '　合計はいつも 0 ＝ だから重心は動かない\n'
  + '・印は2つの星の位置と質量から毎回計算し直している。\n'
  + '　置いた目印ではないので、動かないこと自体が読みどころ', BIN_NOTE_SIZE);
}

// ── 連星②（重心が重い星の内部にある＝星は首を振るだけ）──────────
//   ★これは demoBinaryStar の続き。あちらは「重心はどこか」（3:1 で検算できる図）で、
//     こちらは「質量比を上げていくと重心が重い星に飲み込まれ、その星は回っているのに
//     止まって見える」。読みどころが違うので分けてある。同じ画面には入らない：
//     極端な比では軽い星の軌道半径がほぼ間隔いっぱい（rB → d）まで広がり、
//     2つの系を並べると幅 2250px 要る（画面は 1996px）。
//   ★間隔・実効万有引力定数は demoBinaryStar と同じ（480px・G_sim 100）。変えたのは
//     質量比だけ（3:1 → 15:1）。「同じ装置で比だけ変えた」が読めるようにするため。
//   ★★この図の星は、間隔にくらべてうんと大きく描いてある（星Aの半径は間隔の 1/8）。
//     本物の太陽は間隔の 1/1000 以下しかないので、実際に重心が中に入るには質量比が
//     もっと極端でないといけない（太陽と木星は 1047:1 でも重心は太陽の中心から
//     半径の 1.07 倍＝表面のすぐ外。土星なら 0.59 倍、地球なら 0.0006 倍で内側）。
//     ＝ 結論（重心は星の中に入りうる／だから太陽は止まって見える）は本物どおりだが、
//     そこへ至る道すじは「星を大きく描く」で代用している。本文にそのまま書く。
//   ★質量比 15:1 は、画面から逆に決まる。星Aの首振りの円が画面上で何 px になるかは
//     質量比だけで決まっていて、間隔にもカメラの倍率にもよらない：
//       rA/rB = 1/q で、rB は「画面に収まる最大の円」＝ 225 画面px で頭打ちだから、
//       星Aの円はいつも 225/q 画面px。＝ 間隔を詰めて寄っても、大きくはならない。
//     この題材は2つを同時に満たす必要があり、q はその間に挟まれる：
//       ① ✕ が星Aの円盤の中に十分入っている（比を下げると表面ぎわへ出る）
//       ② それでも星Aの首振りが円だと読める（比を上げると点にしか見えない）
//     星Aの半径 60px に対して rA = 480/(1+q) は
//       q=8  … rA/RA 0.89（表面ぎわ。「内部」に見えない）
//       q=15 … 0.50、画面上 15px の円  ← これ。円の半径がちょうど星の半径の半分
//       q=30 … 0.26、画面上 7.7px（ただの点で、回っていることが読めない）
//   ★45万:3万 は「重心までの距離が丸い数になる」ように選んだ組。rA=0.30 m・rB=4.50 m で、
//     45万×0.30 = 3万×4.50 が画面の目盛りのまま検算できる（demoBinaryStar と同じ流儀）。
//   ★星Aの半径をちょうど 2·rA にしてあるので、星Aの軌跡の円は円盤に内接する（軌跡の
//     いちばん遠い側は、その瞬間の円盤のふちに接する）。＝「星が動く範囲は自分の体の中に
//     収まっている」が図でそのまま見える。半径を大きくすると軌跡が円盤の内側へ引っ込み、
//     「半分」の検算もできなくなるので、この 2 倍は動かさない。
//   ★実測（60秒＝6.3周）：星Aの軌道半径 30.006px（標準偏差 0.10%）、星B 450.08px（同 0.10%）
//     ☆2026-09-27 に万有引力を半分ずつにしたあと（gravitation.js の★）：30.004px / 450.062px、
//       標準偏差 0.010%、周期 9.540 秒。以下の段は直す前の値
//     ＝どちらも円のまま。重心のずれ 0px・合計の運動量 0（浮動小数の丸めでも厳密に 0。
//     mA·vA も mB·vB も √(F·d·mA·mB/M) の同じ式に帰着するため）。周期 9.541 秒で、
//     5周ぶんのばらつきは 0.0000 秒。星Aの vx の振幅は 0.198 m/s。
//     重心が星Aの円盤の内部にあった tick は 3600/3600 ＝ 100%。
//   ★星Aの軌跡の色だけは星の色に合わせない。軌跡は自分の円盤の上に重なって描かれる
//     （js/render/body.js:245 が形の後）ので、同色だと消える。
const BW_MA = 450000;   // [kg] 星A（重いほう）
const BW_MB = 30000;    // [kg] 星B（質量比ちょうど 15:1）
const BW_D  = 480;      // [px] 2つの星の間隔（4.8 m。demoBinaryStar と同じ）
const BW_G  = 100;      // 実効万有引力定数 G_sim（同上）
const BW_RA = 60;       // [px] 星Aを描く半径。★上の★の ①②を挟んで決めた
const BW_RB = 24;       // [px] 星Bを描く半径
const BW_NOTE_SIZE  = 30;   // [px] 本文（既定 23px の 1.3 倍。下の★）
const BW_TITLE_SIZE = 40;
function demoBinaryStarWobble() {
  resetDemoWorld();
  setDemoGravity(0);             // ★一様な重力は無し（働くのは2つの星の間の万有引力だけ）
  world.gravitation  = true;
  world.gravStrength = BW_G;
  world.sleeping     = false;    // ★星Aは 0.20 m/s しかない。眠らせると首振りが止まる
  updateGroundTerrain(false);
  setDemoCam(0, 0.50);
  const M  = BW_MA + BW_MB;
  const rA = BW_D * BW_MB / M;                 // 重心から星Aまで [px]（30px ＝ 0.30 m）
  const rB = BW_D * BW_MA / M;                 // 　　　　　星Bまで [px]（450px ＝ 4.50 m）
  // ★系は画面の右へ寄せる。星Bの円が半径 450px あるので、左に残るのは本文のぶんだけ
  //   （系は cam.x+460 を中心に ±474px。本文の右端 cam.x−174 との間が 160px 空く）。
  const cx = cam.x + 460, cy = cam.y + 60;
  // 円軌道の速さ（demoBinaryStar と同じ解き方。F = G·mA·mB/(d²+ε²) を m v²/r につり合わせる）
  const F  = BW_G * BW_MA * BW_MB / (BW_D * BW_D + gravSoften2());
  const vA = Math.sqrt(F * rA / BW_MA);        // 19.8 px/s ＝ 0.20 m/s
  const vB = Math.sqrt(F * rB / BW_MB);        // 296.4 px/s ＝ 2.96 m/s（vA の 15 倍）
  const mk = (x, vy, m, r, color, stroke, trace, label) => {
    const b = new Body({ type:'circle', x, y:cy, radius:r, mass:m, vy,
                         fixedRotation:true,          // ★自転はこの題材の外
                         fillColor:color, strokeColor:stroke, strokeWidth:2, label });
    b.tracerEnabled  = true;
    b.tracerColor    = trace;
    b.tracerDuration = 11;                     // ★一周 9.5 秒より少し長く（円が閉じて見える）
    objects.push(b);
    return b;
  };
  const starA = mk(cx - rA,  vA, BW_MA, BW_RA, '#ffb300', '#ffe082', '#4e342e', '星A 45万kg');
  const starB = mk(cx + rB, -vB, BW_MB, BW_RB, '#4fc3f7', '#b3e5fc', '#4fc3f7', '星B 3万kg');
  // ── 重心の印（表示メニューの「選択系の重心を表示」。demoBinaryStar と同じ）────
  //   ★以前はペンツールの ✕ を置き、札は円盤の外へ出して破線でつないでいた。表示メニュー
  //     の印は札を自分のすぐ横に書くので、その引き出し線はもう要らない（黒い縁取りが
  //     付くので、星A の #ffb300 の上に重なっても読める）。
  //   ★印は画面px で固定の大きさなので、この題材でいちばん小さい円——星Aの首振り
  //     （半径 30 ワールドpx ＝ 倍率 0.50 で画面 15px）——の中に収まる必要がある。
  //     実測：印の半径は画面 9px で、首振りの円の内側に留まり、円としてまだ読める。
  comIds = [starA.id, starB.id];
  // ── 星Aの左右の速さ（＝視線速度）────────────────────────
  //   ★出すのは x 成分だけ。「止まって見えるのに速さは振れている」がこの窓の役目で、
  //     大きさ（|v|）だと円軌道なので一定の直線になり、何も読めない。y 成分は同じ波の
  //     位相ちがいで、1本あれば足りる。変位・加速度の段も出さない。
  //   ★窓は左下。系が画面の右を占めているので、空いているのは本文の下だけ。
  moveDemoGraphBottom(moveDemoGraphLeft(sizeDemoGraph(
    velGraphNew(starA, { showPos:false, showVel:true, showAcc:false,
                         showX:true, showY:false, showMag:false, autoStart:true }),
    400, 250)));
  // ★本文は既定（23px）の 1.3 倍。demoBinaryStar は 1.6 倍だが、こちらは題材が
  //   画面の右半分を丸ごと使う（星Bの円は直径 900px）ので、そこまで大きくできない。
  //   1行 26 文字までに収めること（30px×26 ＝ 780px で、系の左端まで 160px 残る）。
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '連星 ― 重い星は首を振る', BW_TITLE_SIZE);
  demoNote (p.x, p.y + 72,
    '星A（45万 kg）と星B（3万 kg）。質量の比は 15:1。\n'
  + '間隔も引力も「連星」のデモと同じで、比だけを変えた。\n'
  + '\n'
  + '【手順】▶実行 を押して、星Aから目を離さない\n'
  // ★重心の印がどう見えるか（白黒に塗り分けた丸）はここには書かない。印は自分のすぐ横に
  //   「重心」と札を出すし、目録で先に並ぶ「連星」のデモが姿を説明している。ここへ足すと
  //   行が増えるか行が伸びるかのどちらかになり、下の2つの枠のどちらかを割る：
  //     ・行数 … 21 行でちょうど左下のグラフの窓の上端に収まる（実測：窓の上端は
  //       画面 476px、21行目が 468px、22行目なら 487px）。最後の ※ 行は「星を大きく
  //       描いてある」と断る行なので、窓の裏に入ってはいけない。
  //     ・行の幅 … いちばん長い行は 793px（30px×26文字の目安どおり）。下の行を
  //       785px に収めてあるので、本文の幅は変わっていない。
  + '・星B は大きな円を描く。星A は止まって見える\n'
  + '・でも星Aも重心の印のまわりを回っている。円の半径は\n'
  + '　自分の半径のちょうど半分。首を振るだけに見える\n'
  + '\n'
  + '【なぜ重心が星の中に入るか】\n'
  + '・重心までの距離の比は、質量の比の逆 ＝ 1 : 15\n'
  + '　45万 × 0.30 m ＝ 3万 × 4.50 m\n'
  + '・比が大きいほど重心は重いほうへ寄り、やがて星の内部\n'
  + '　へ入る。太陽をほとんど止めて描けるのもこのため\n'
  + '\n'
  + '【左下のグラフ】星Aの左右の速さ\n'
  + '・止まって見えるのに、速さは振れ続けている。周期は\n'
  + '　星Bの一周と同じ。実際の星ではこの振れを測って、\n'
  + '　見えない相手（惑星）を見つけている\n'
  + '\n'
  + '※星は間隔にくらべてうんと大きく描いてある。本物の\n'
  + '　星で重心が中に入るには、比はもっと極端になる', BW_NOTE_SIZE);
}

// ── 太陽系（水星〜木星）と木星の4つの衛星 ────────────────────
//   ★この図で「実際の比のまま」なのは、惑星の公転半径・公転周期・離心率の3つ。
//     ここは作り物にしない：ケプラーの第1〜第3法則がそのまま読めることが題材だから。
//     置くのは位置と初速だけで、あとは万有引力に任せる（周期を書き込んだりはしない）。
//   ★逆に、実際と違うところは3つある。隠さず本文に並べて書く：
//     ① 星の大きさ … 実比だと太陽が 0.6px、地球が 0.005px で何も見えない。
//        大小の順（水星＜火星＜金星＜地球＜木星）だけ保ち、比は捨てた。
//     ② 木星の質量 … 太陽の 1/50（実際は 1/1050 ＝ 21倍の水増し）。
//     ③ 衛星の公転半径 … 実際の26倍。
//     ②と③は必ず対で要る。衛星が太陽に引きはがされない範囲（ヒル半径）は
//     r_H = a·(m/3M)^(1/3) で、実際の木星の質量なら 1 AU = 120px の縮尺で 44px しかなく、
//     安定に回れるのはその 1/3 ほどまで。ところが実際の衛星の公転半径は
//     この縮尺では 0.34〜1.5px（木星の絵より内側）で、そもそも見えない。
//     木星を21倍重くするとヒル半径が 118px へ広がり、26倍に離した衛星（8.8〜39px）が
//     その 0.33 倍の内側に収まる。＝ 見えるようにするための水増しではなく、
//     「見える距離まで離した衛星を、それでも木星につなぎ止める」ための水増し。
//   ★26倍という値は、上と下の両方から挟まれて決まっている。実測（300秒＝木星4周）で
//     水増し率を振ると、カリストの公転半径の振れと、カリスト/イオ の周期比はこうなる：
//       30倍 … 27.4〜63.2px（置いた 45.3px から±40%）・平均が +4.9% 外へ流れる・比 9.77
//       26倍 … 35.3〜42.3px（置いた 39.3px から ±8%）・平均 −0.3%・比 9.38  ← これ
//       22倍 … 31.5〜33.9px 安定だが、内側のイオが 7.4px まで縮んで ε が効き、比 9.08
//       18倍 … 26.6〜27.9px 安定、比 9.19
//     上限は太陽（離しすぎると引きはがされかけて楕円が暴れる）、下限は引力のぼかし ε
//     （近づけすぎると内側の衛星だけ周期が伸びる）。実際の比は 9.43 なので 26倍が最も近い。
//   ★26倍が4つの衛星で共通なのが大事。距離を一律 k 倍すると周期は一律 k^1.5 倍になるので、
//     衛星どうしの周期の比は実際のまま残る（実測 1 : 1.98 : 3.99 : 9.38。
//     実際の イオ:エウロパ:ガニメデ:カリスト = 1 : 2.01 : 4.04 : 9.43）。
//     ＝ 木星系でもケプラーの第3法則が成り立つことは、水増ししても読める。
//   ★引力のぼかし ε は 8px → 1px へ下げる（world.gravSoften）。既定のままだと
//     いちばん内側のイオ（半径 8.8px）で引力が 45% も減り、上の 1:2:4:9.4 が
//     大きく化ける。理由は js/physics/gravitation.js の★。
//   ★太陽は固定する。木星を21倍重くしてあるので、動かすと太陽の首振りまで21倍に
//     出てしまい、「太陽も重心のまわりを回る」を実際の20倍の大きさで見せることになる。
//     連星のデモ（demoBinaryStar）は水増しなしでその話をしているので、ここでは出さない。
//     「重心が星の内部にあるほど比が大きいとき、その星はどう見えるか」も
//     demoBinaryStarWobble が受け持つ。
//   ★水増しした木星は、内側の惑星も実際より強く揺さぶる。効くのはいちばん近い火星で、
//     実測（150秒＝火星13周）の公転半径の振れは 158.7〜207.7px。対照として木星を
//     実際の質量に戻すと 165.1〜203.2px（置いた楕円は 165.7〜199.9px）。
//     ＝ 離心率でいうと 0.09（置いた値）→ 0.10（実際の木星）→ 0.13（水増しした木星）。
//     隠さず本文に書く。水星・金星・地球はこの差が見た目に出ない（実測 0.005 未満）。
//   ★惑星を1つずつ太陽と2体だけで回すと、置いたとおりの楕円が保たれる
//     （実測：水星 e=0.2050／金星 0.0067／地球 0.0166。置いた値は 0.2056／0.0068／0.0167、
//      刻み16と48で同じ）。＝ 上の振れは積分の誤差ではなく、惑星どうしの引力そのもの。
//     ☆2026-09-27 に万有引力を位置の前後へ半分ずつにした（gravitation.js の★）。150秒の
//       最小・最大距離から出す離心率で比べると新旧の差は 0.0006 以下、火星の振れ
//       158.7〜207.7px は同じ。上の4桁の値の測り方は再現していない。
const SOL_AU     = 120;      // [px] 1 AU ＝ 1.20 m
const SOL_G      = 100;      // 実効万有引力定数 G_sim
const SOL_MSUN   = 20000;    // [kg] 太陽
const SOL_JUP_K  = 21;       // 木星の質量の水増し（太陽比 1/1050 → 1/50）
const SOL_MOON_K = 26;       // 衛星の公転半径の水増し（上の★で挟んで決めた値）
// 名前, 軌道長半径[AU], 離心率, 質量（太陽比）, 描く半径[px], 色, 置く向き[°]
//   ★向きはばらばらにする。そろえると軌道の楕円がどれも同じ向きを向き、
//     「太陽が焦点にある」が「太陽が左にずれている」に見えてしまう。
//   ★描く半径は木星の 6.0px が頭打ちで、そこから下へ配った値。いちばん内側のイオの
//     公転半径が 8.8px しかないので、木星をこれより大きく描くとイオが木星の絵の中へ入る。
//     大小の順（水星＜火星＜金星＜地球＜木星）だけは実際どおりに保つ。
const SOL_PLANETS = [
  { name:'水星', a:0.3871, e:0.2056, m:1.660e-7, r:2.8, color:'#b0a999', th:255 },
  { name:'金星', a:0.7233, e:0.0068, m:2.447e-6, r:4.6, color:'#e8c98a', th:140 },
  { name:'地球', a:1.0000, e:0.0167, m:3.003e-6, r:5.0, color:'#4fa3e0', th: 60 },
  { name:'火星', a:1.5237, e:0.0934, m:3.227e-7, r:3.6, color:'#d1603d', th:200 },
  { name:'木星', a:5.2044, e:0.0489, m:9.550e-4, r:6.0, color:'#d8a878', th: 25 },
];
// ガリレオ衛星。名前, 公転半径[AU]（実際の値）, 質量（木星比）, 描く半径[px], 色, 置く向き[°]
const SOL_MOONS = [
  { name:'イオ',     a:0.002819, m:4.706e-5, r:1.3, color:'#f4e04d', th:  0 },
  { name:'エウロパ', a:0.004486, m:2.529e-5, r:1.3, color:'#e0e6e8', th: 90 },
  { name:'ガニメデ', a:0.007155, m:7.808e-5, r:1.6, color:'#a9927d', th:180 },
  { name:'カリスト', a:0.012585, m:5.669e-5, r:1.4, color:'#8d7c6f', th:270 },
];
// 半径 r[px] の円軌道の速さ[px/s]。★ソフトニング ε 込み（orbitSpeedAt と同じ形）
function solCircSpeed(GM, r) { return Math.sqrt(GM * r / (r * r + gravSoften2())); }
// 周期[s]。★ε は無視している（衛星でも ε/r ≦ 0.1 で、周期のずれは 0.5% 未満）
function solPeriod(GM, r) { return 2 * Math.PI * Math.sqrt(r * r * r / GM); }
function demoSolarSystem() {
  resetDemoWorld();
  setDemoGravity(0);             // ★一様な重力は無し（働くのは万有引力だけ）
  world.gravitation  = true;
  world.gravStrength = SOL_G;
  world.gravSoften   = 1;        // [px] 冒頭の★（既定の 8px では衛星の周期が化ける）
  world.sleeping     = false;    // 外側は遅いので、眠って止まらないように
  // ★刻みを 4 → 16 に上げる。いちばん内側のイオは 1周 1.0 秒＝ 6.2 rad/s あり、
  //   刻み4（1歩 1/240 秒）では1歩で 1.5° 進む。実測、60秒（59周）まわしたときの
  //   公転半径のずれは 刻み4 … 1.9%／8 … 0.5%／16 … 0.13%。惑星だけなら 4 で足りるが、
  //   衛星まで入れると足りない（イオだけが外へふくらんでいく）。
  world.substeps     = 16;
  // ★力の矢印の倍率。この題材の引力は mN の桁（実測・1周ぶん：火星 0.00178〜0.00306 N・
  //   地球 0.048〜0.081 N・木星 11.2〜18.8 N）で、既定の 1 px/N では矢印が 2px に
  //   届かず1本も出ない。＝「力ベクトルを表示」を入れても何も起きない状態だった。
  //   ★1200 px/N は「いちばん弱い火星が、遠日点でも消えない」下限から決めた。
  //     火星の最小 0.00178 N × 1200 = 2.14px ＞ しきい値 2px（実測・70秒＝火星6周）。
  //     ここを下げると、公転の途中で火星の矢印だけが点いたり消えたりする。
  //   ★これでも全部を長さで比べることはできない。この系の引力は最弱（火星 0.0019 N）と
  //     最強（木星 18.8 N）で 1万倍あり、矢印が使える幅は 12〜260px ＝ 22 倍しかない。
  //     惑星を1つ選んで、近日点で伸び遠日点で縮むのを追う読み方が向く
  //     （倍率は 20000 px/N まで上げられる。火星なら 6000 前後）。
  world.forceVizScale = 1200;
  updateGroundTerrain(false);
  setDemoCam(0, 0.42);
  // ★太陽は画面の中央より右下へ置く。左うえは説明の場所で、木星の軌道（半径 6.5 m）が
  //   そこへ掛かる。右下へ寄せると、本文の下端の高さで木星の軌道が本文の右端をかわす。
  const sx = cam.x + 320, sy = cam.y + 190;
  const GM = SOL_G * SOL_MSUN;
  objects.push(new Body({ type:'circle', x:sx, y:sy, radius:20, mass:SOL_MSUN,
    isStatic:true, layers:0,       // ★静的でも引力の源にはなる（gravitation.js:25）
    fillColor:'#ffd54f', strokeColor:'#ffecb3', strokeWidth:2, label:'太陽（固定）' }));
  let jupiter = null;
  for (const p of SOL_PLANETS) {
    const a  = p.a * SOL_AU;                       // 軌道長半径 [px]
    const rA = a * (1 + p.e);                      // 遠日点までの距離 [px]
    const th = p.th * Math.PI / 180;
    // ★遠日点に置き、そこでの速さを与える（vis-viva）。近日点で速く遠日点で遅い
    //   ＝ ケプラーの第2法則が、こちらで何もしなくても軌跡の粗密に出る。
    const v  = Math.sqrt(GM / a * (1 - p.e) / (1 + p.e));
    const b = new Body({ type:'circle',
      x: sx + rA * Math.cos(th), y: sy + rA * Math.sin(th),
      vx: -v * Math.sin(th),     vy:  v * Math.cos(th),
      radius:p.r, mass:p.m * SOL_MSUN, layers:0,   // ★ぶつかることはないので全部すり抜け
      fillColor:p.color, strokeColor:'#ffffff', strokeWidth:1, label:p.name });
    b.tracerEnabled  = true;
    b.tracerColor    = p.color;
    b.tracerDuration = solPeriod(GM, a) * 1.08;    // ★自分の1周ぶん＋少し（軌道が閉じて見える）
    objects.push(b);
    if (p.name === '木星') jupiter = { body:b, m:p.m * SOL_MSUN * SOL_JUP_K };
  }
  // ★木星だけ、置いたあとで質量を水増しする。公転のほうは実際の質量で決めた初速の
  //   ままでよい（太陽が固定なので、公転の周期と形に惑星自身の質量は効かない）。
  jupiter.body.mass = jupiter.m;
  jupiter.body.label = '木星（質量は太陽の1/50）';
  const GMJ = SOL_G * jupiter.m;
  for (const s of SOL_MOONS) {
    const r  = s.a * SOL_AU * SOL_MOON_K;          // 水増しした公転半径 [px]
    const th = s.th * Math.PI / 180;
    const v  = solCircSpeed(GMJ, r);
    // ★速度は「木星の速度 ＋ 木星のまわりを回る速度」。足し忘れると衛星だけが
    //   置き去りになり、木星が先へ行ってしまう（衛星は太陽を回る別の天体になる）。
    objects.push(new Body({ type:'circle',
      x: jupiter.body.x + r * Math.cos(th), y: jupiter.body.y + r * Math.sin(th),
      vx: jupiter.body.vx - v * Math.sin(th), vy: jupiter.body.vy + v * Math.cos(th),
      radius:s.r, mass:s.m * jupiter.m, layers:0,
      fillColor:s.color, strokeColor:'#ffffff', strokeWidth:1, label:s.name }));
    // ★衛星に軌跡は付けない。太陽から見ると木星の道すじに小さな輪が重なった線になり、
    //   木星系（半径 45px）の中では読めない団子になる。
  }
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '太陽系（水星〜木星）と木星の4つの衛星');
  const note =
    '太陽を固定し、5つの惑星を万有引力だけで回す。公転半径・公転周期・\n'
  + '軌道のつぶれ具合（離心率）は、どれも実際の比のまま置いてある。\n'
  + '1 AU（太陽と地球の距離）＝ 1.20 m、地球の1年 ＝ 5.8 秒。\n'
  + '\n'
  + '【手順】▶実行 を押して、5本の軌跡を見くらべる\n'
  + '・内側ほど速い。1周は 水星1.4／金星3.6／地球5.8／火星11.0／木星69 秒\n'
  + '　　半径が 1.52 倍（火星）なら周期は 1.52^1.5 = 1.88 倍 ＝ 第3法則\n'
  + '・水星と火星の軌跡は楕円（離心率 0.21 と 0.09）で、太陽はその楕円の\n'
  + '　中心ではなく焦点にいる ＝ 第1法則。内側は小さいので、太陽のあたりを\n'
  + '　ホイールで拡大すると、輪の中心が太陽からずれているのが見える\n'
  + '・木星のまわりを4つのガリレオ衛星が回る。木星系は木星の公転半径の\n'
  + '　6% しかないので、ホイールで木星を拡大して見る\n'
  + '　　1周は イオ0.83／エウロパ1.65／ガニメデ3.33／カリスト7.8 秒\n'
  + '\n'
  + '【この図が実際と違うところ】\n'
  + '・星の大きさ … 誇張。大小の順だけ本当で、比は実際どおりではない\n'
  + '・木星の質量 … 太陽の 1/50（実際は 1/1050）。そのぶん内側も強く揺さぶり、\n'
  + '　いちばん近い火星の楕円が実際よりゆっくり形を変える（離心率 0.09 → 0.13）\n'
  + '・衛星の公転半径 … 実際の26倍。この縮尺だと本当は 0.3〜1.5px しかなく、\n'
  + '　木星の絵より内側に入ってしまう。離した衛星をそれでもつなぎ止めるために、\n'
  + '　木星を重くしてある（この2つは対で必要）。26倍は4つとも同じなので、\n'
  + '　衛星どうしの周期の比 1 : 2.0 : 4.0 : 9.4 は実際のまま残る';
  demoNote(p.x, p.y + 54, note);
  // ── 凡例 ────────────────────────────────────────────
  //   ★物体の label（'地球' など）は画面には出ない。パネルとグラフの凡例の文字で、
  //     描画は物体の色だけ（js/render/body.js に label を描く処理は無い）。
  //     グラフを開かないこのデモでは、名前を出す口がここしかない。
  //   ★軌道の輪に名前を添えるのではなく凡例にしたのは、内側の3本の間隔が
  //     40px と 33px しかなく、23px の文字を置くと輪の上に乗るため。
  //   ★置く高さは本文の実測（demoNoteBelow）から取る。決め打ちにすると、
  //     あとから本文に1行足した人が凡例と重ねてしまう。
  //   ★行の頭の短い線は、その惑星の軌跡と同じ色・同じ太さ。名前と輪を色で結ぶ。
  const ly = demoNoteBelow(p.y + 54, note);
  SOL_PLANETS.forEach((pl, i) => {
    const y = ly + i * 32;
    annotations.push(new Annotation({ type:'path', x:p.x, y:y + 13, width:3,
                                      color:pl.color, pts:[{x:0,y:0},{x:34,y:0}] }));
    const T = solPeriod(GM, pl.a * SOL_AU);
    demoLabel(p.x + 48, y, `${pl.name}　${pl.a.toFixed(2)} AU　1周 ` +
                           `${T < 20 ? T.toFixed(1) : T.toFixed(0)} 秒`, pl.color);
  });
}

// ── 楕円軌道のエネルギー ────────────────────────────────────
//   ★固定した星のまわりを楕円軌道で回る探査機の力学的エネルギー。近い点では速く（運動が大きく）、
//     遠い点では遅い（万有引力の位置エネルギーが大きい）が、合計は一周のあいだずっと一定。
//     位置エネルギーは無限遠を 0 とするので、つねに負（グラフの 0 より下）。
//   ★星・打ち出し点・G は「第1宇宙速度・第2宇宙速度」と同じ（ORB_*）。速さは第1宇宙速度の
//     1.20 倍の 6.00 m/s。いちばん遠い点は r₀k²/(2−k²) = 9.26 m（同デモの★の実測 9.3 m）。
//     ★1.15 倍（遠い点 7.1 m）では離心率 0.32 でほぼ円に見え、楕円だと読めなかった（実測の画面）。
//     実測（2026-10-01、60 秒＝5.5 周）：合計 −7.005〜−7.003 J（ぶれ 0.03%）、中心からの距離
//     3.60〜9.25 m、運動 2.72〜17.99 J（近い点と遠い点で 6.6 倍）、周期 10.80 s。
//   ★星は固定なので系の外の「動かない相手」として位置エネルギーに入る（energy.js の
//     energyParticipantOK）。グラフの系は探査機1機だけでよい。
//   ★配置：本文は左うえ、グラフは左した、軌道は右側（近い点が左・遠い点が右の横長）。
//     倍率 0.40 に引くので、文字は demoTextScale で基準の見かけの大きさに戻す。
const OE_K    = 1.20;            // 第1宇宙速度に対する倍率
const OE_ZOOM = 0.40;
function demoOrbitEnergy() {
  resetDemoWorld();
  setDemoGravity(0);             // ★一様な重力は無し（働くのは万有引力だけ）
  world.gravitation  = true;
  world.gravStrength = ORB_G;
  world.sleeping     = false;
  updateGroundTerrain(false);
  setDemoCam(0, OE_ZOOM);
  const ts = demoTextScale(OE_ZOOM);
  // ★星の位置は画面の中心から（右へ 2.5 m・下へ 1.1 m）。軌道の上端が上の操作ヒントの帯より下、
  //   下端が画面の下端より上、近い点がグラフの窓（左した）より右に来る位置（実測の画面）。
  const sx = cam.x + 250, sy = cam.y + 110;
  objects.push(new Body({
    type:'circle', x:sx, y:sy, radius:ORB_STAR_R, mass:ORB_STAR_M, isStatic:true,
    friction:0.6, frictionStatic:0.8, restitution:0,
    fillColor:'#ffb300', strokeColor:'#ffe082', strokeWidth:2, label:'星（固定・90万kg）' }));
  const v = OE_K * orbitSpeedAt(ORB_R0);
  const probe = new Body({
    type:'circle', x:sx - ORB_R0, y:sy, radius:ORB_BALL_R * 1.6, mass:1,
    vy: -v,                                   // ★星の左から真上へ＝接線の向き（画面の上向き）
    fixedRotation:true, friction:0, frictionStatic:0, restitution:0,
    fillColor:'#9ccc65', strokeColor:'#ffffff', strokeWidth:1, label:'探査機 1kg' });
  probe.tracerEnabled  = true;
  probe.tracerColor    = '#9ccc65';
  probe.tracerDuration = 30;
  objects.push(probe);
  const rApo = ORB_R0 * OE_K * OE_K / (2 - OE_K * OE_K);   // [px]
  demoLabel(sx - ORB_R0 - 420, sy - 120, '近い点（速い）', '#9ccc65', DEMO_NOTE_SIZE * ts);
  demoLabel(sx + rApo - 400,   sy + 90,  '遠い点（遅い）', '#9ccc65', DEMO_NOTE_SIZE * ts);
  const g = eneGraphNew([probe.id], {
    showKt:true, showUgg:true, showMech:true,
    showKr:false, showUg:false, showUs:false, showUe:false });
  sizeDemoGraph(g, 380, 330); moveDemoGraphLeft(g); moveDemoGraphBottom(g);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '楕円軌道のエネルギー', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '星は固定（90万 kg）。探査機 1kg を、星の左 3.6 m から\n'
  + '真上へ 6.00 m/s で打ち出す（第1宇宙速度の 1.2 倍）。\n'
  + '\n'
  + '【手順】▶実行 を押して、左したのグラフを見る\n'
  + '・運動（青）：近い点で大きく、遠い点で小さい\n'
  + '・万有引力の位置（水色）：いつも負。遠いほど 0 に近い\n'
  + '・合計（黄）は一周のあいだずっと平ら ＝ 保存する\n'
  + '・近づくと速くなるのは、位置エネルギーが運動に移るから', DEMO_NOTE_SIZE * ts);
}
